const TP_ASSET_V = 'tp83';
window._tpExtraReady = false;
window._tpExtraPromise = null;
function _tpExtraSrc() { return '/app-extra.js?v=' + TP_ASSET_V; }
function _tpEnsureExtra() {
  if (window._tpExtraReady) return Promise.resolve();
  if (window._tpExtraPromise) return window._tpExtraPromise;
  window._tpExtraPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = _tpExtraSrc();
    s.async = false;
    s.onload = () => { window._tpExtraReady = true; resolve(); };
    s.onerror = () => reject(new Error('بارگذاری ماژول تکمیلی ناموفق بود'));
    document.head.appendChild(s);
  });
  return window._tpExtraPromise;
}
function _tpLazy(name) {
  const stub = function () {
    const args = arguments;
    const ctx = this;
    return _tpEnsureExtra().then(() => {
      const impl = window[name];
      if (impl === stub) throw new Error('تابع ' + name + ' در ماژول تکمیلی نیست');
      return impl.apply(ctx, args);
    });
  };
  window[name] = stub;
}
