function _teamAccessSession() {
  try { return JSON.parse(localStorage.getItem(TEAM_ACCESS_SESSION_KEY) || 'null'); }
  catch(e) { return null; }
}
function _normalizeTeamPermissions(permissions) {
  const list = Array.isArray(permissions) ? [...new Set(permissions.filter(Boolean))] : [];
  const hasTodoDetail = list.some(key => TODO_TEAM_PERMISSIONS.some(permission => permission.key === key));
  if (hasTodoDetail && !list.includes('todolist')) list.unshift('todolist');
  return list;
}
function _teamSessionStorageKey(session) {
  const s = session || _teamAccessSession();
  if (!s) return _userDBKey();
  const owner = s.ownerUserId || s.ownerEmail || 'pending';
  const account = s.accountId || 'default';
  return 'tp_team_' + String(owner).replace(/[^a-zA-Z0-9_-]/g, '_') + '_v3_' + String(account).replace(/[^a-zA-Z0-9_-]/g, '_');
}
function _isTeamGuest() { return !!_teamAccessSession(); }
function _teamCan(page) {
  const s = _teamAccessSession();
  if (!s) return true;
  const permissions = _normalizeTeamPermissions(s.permissions);
  if (['settings','tutorial'].includes(page)) return true;
  if (page === 'students' && permissions.includes('sessions')) return true;
  if (page === 'payments' && ['reminders','families'].some(p => permissions.includes(p))) return true;
  if (page === 'transactions' && permissions.includes('dashboard')) return true;
  return permissions.includes(page);
}
function _teamPerm(key) {
  const s = _teamAccessSession();
  if (!s) return true;
  return _normalizeTeamPermissions(s.permissions).includes(key);
}
function _teamEmail() {
  return String(_teamAccessSession()?.email || _sbUser?.email || '').trim().toLowerCase();
}
function _todoCurrentTeamMember() {
  const email = _teamEmail();
  if (!email) return null;
  return (_db.team_members || []).find(m =>
    String(m.email || '').trim().toLowerCase() === email &&
    m.status !== 'حذف‌شده'
  ) || null;
}
function _todoSharedWith(t) {
  if (Array.isArray(t?.shared_with)) return t.shared_with.map(String);
  if (Array.isArray(t?.sharedWith)) return t.sharedWith.map(String);
  return [];
}
function _todoIsOwnAssigned(t) {
  const session = _teamAccessSession();
  const ownStaff = _todoSessionStaff();
  const email = _teamEmail();

  const ownStaffId = String(
    ownStaff?.id ||
    session?.staffId ||
    session?.staff_id ||
    ''
  );

  const taskStaffId = String(
    t?.assignee_id ||
    t?.staff_id ||
    ''
  );

  if (ownStaffId && taskStaffId === ownStaffId) return true;

  const taskEmail = String(t?.assignee_email || '')
    .trim()
    .toLowerCase();

  if (email && taskEmail === email) return true;

  return false;
}
function _todoCanView(t) {
  if (!_todoBelongsToActiveAccount(t)) return false;
  if (!_isTeamGuest()) return true;
  const email = _teamEmail();
  if (_teamPerm('todo_view_team') || _teamPerm('todo_manage_staff')) return true;
  if (_teamPerm('todo_view_assigned') && _todoIsOwnAssigned(t)) return true;
  if (_teamPerm('todo_view_shared') && _todoSharedWith(t).map(x => x.toLowerCase()).includes(email)) return true;
  if (_teamPerm('todo_view_clients') && String(t?.category || '') === 'clients') return true;
  return false;
}
function _todoCanComplete(t) {
  if (!_isTeamGuest()) return true;
  return _todoIsOwnAssigned(t) && (
    _teamPerm('todo_complete_own') ||
    _teamPerm('todo_edit_manager') ||
    _teamPerm('todo_manage_staff')
  );
}
function _todoCanReport(t) {
  if (!_isTeamGuest()) return true;
  return _teamPerm('todo_report_own') && _todoIsOwnAssigned(t);
}
function _todoCanEdit(t) {
  if (!_isTeamGuest()) return true;
  if (_teamPerm('todo_edit_manager') || _teamPerm('todo_manage_staff')) return true;
  return _todoIsOwnAssigned(t) && (_teamPerm('todo_create_self') || _teamPerm('todo_complete_own'));
}
function _todoCanDelete(t) {
  if (!_isTeamGuest()) return true;
  return _teamPerm('todo_delete') || _teamPerm('todo_manage_staff') || _teamPerm('todo_edit_manager') || (_todoIsOwnAssigned(t) && _teamPerm('todo_create_self'));
}
function _todoHasActivePersonnel() {
  return (_db.staff || []).some(s => staffIsPersonnel(s) && s.is_active !== false && s.is_active !== 0);
}
function _todoCanOpenStaffTasksTab() {
  if (!_isTeamGuest()) return _todoHasActivePersonnel();
  if ((_db.todos || []).some(t => _todoIsOwnAssigned(t))) return false;
  return _teamPerm('todo_manage_staff');
}
function _todoSessionStaff() {
  const session = _teamAccessSession();
  const staffId = session?.staffId || session?.staff_id || '';

  if (staffId) {
    const byId = (_db.staff || []).find(
      s => staffIsPersonnel(s) &&
      String(s.id) === String(staffId)
    );
    if (byId) return byId;
  }

  const member = _todoCurrentTeamMember();
  const memberStaffId = member?.staff_id || member?.staffId || '';
  if (memberStaffId) {
    const byMemberId = (_db.staff || []).find(
      s => staffIsPersonnel(s) &&
      String(s.id) === String(memberStaffId)
    );
    if (byMemberId) return byMemberId;
  }

  const email = _teamEmail();
  if (!email) return null;

  const byEmail = (_db.staff || []).find(
    s => staffIsPersonnel(s) &&
    String(s.email || '').trim().toLowerCase() === email
  ) || null;

  // Migration: قدیمی‌ترین دعوت‌نامه‌ها فقط ایمیل داشتند؛ به محض شناسایی، staffId را
  // داخل Session ذخیره کن تا از این پس اتصال پایدار و مستقل از ایمیل باشد.
  if (byEmail && session && !staffId) {
    try {
      localStorage.setItem(TEAM_ACCESS_SESSION_KEY, JSON.stringify({ ...session, staffId: String(byEmail.id) }));
    } catch(e) {}
  }

  return byEmail;
}
function _todoCanCreateForStaff(staffId) {
  if (!_isTeamGuest()) return true;
  const ownStaff = _todoSessionStaff();
  const ownId = ownStaff ? String(ownStaff.id) : '';
  if (staffId && ownId && String(staffId) !== ownId) return _teamPerm('todo_create_others') || _teamPerm('todo_manage_staff');
  return _teamPerm('todo_create_self') || _teamPerm('todo_manage_staff');
}
function _teamDefaultPage() {
  const s = _teamAccessSession();
  const first = _normalizeTeamPermissions(s?.permissions).find(p => _SAFE_RESTORE_PAGES.includes(p));
  return first || 'settings';
}
function _applyTeamAccessToNav() {
  const s = _teamAccessSession();
  document.querySelectorAll('.nav-item[data-page], .bn-item[data-page]').forEach(el => {
    const page = el.dataset.page;
    if ((page === 'reminders' || page === 'sessions' || page === 'families') && el.classList.contains('nav-item')) {
      el.style.display = 'none';
      return;
    }
    el.style.display = (!s || _teamCan(page)) ? '' : 'none';
  });
  const accountBtn = document.getElementById('account-btn');
  if (accountBtn && s) {
    const nameEl = document.getElementById('account-name-display');
    if (nameEl) nameEl.textContent = 'هم‌تیمی';
    accountBtn.title = 'دسترسی هم‌تیمی';
  }
}
function _teamAccessDeniedHtml(page) {
  const label = TEAM_ACCESS_SECTIONS.find(x => x.key === page)?.label || 'این بخش';
  return `<div class="detail-section" style="max-width:560px;margin:40px auto;text-align:center">
    <div style="font-size:34px;margin-bottom:10px">🔒</div>
    <h3 style="margin-bottom:8px">به ${label} دسترسی نداری</h3>
    <p style="font-size:13px;color:var(--text2);line-height:1.9">صاحب حساب برای ایمیل شما دسترسی این بخش را فعال نکرده است.</p>
    <button class="btn btn-primary" style="margin-top:14px" onclick="currentPage=_teamDefaultPage();renderPage()">رفتن به بخش‌های مجاز</button>
  </div>`;
}
function _teamEncodeInvite(data) {
  return btoa(unescape(encodeURIComponent(JSON.stringify(data))));
}
function _teamDecodeInvite(token) {
  const rawToken = String(token || '').trim();
  const packed = rawToken.includes('~') ? rawToken.split('~').pop() : rawToken;
  const normalized = packed.replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '='.repeat((4 - normalized.length % 4) % 4);
  const data = JSON.parse(decodeURIComponent(escape(atob(padded))));
  if (data && data.v === 3) {
    return {
      inviteId: data.i,
      email: '',
      ownerName: '',
      ownerEmail: '',
      ownerUserId: data.u || '',
      accountId: data.a || 'default',
      staffId: '',
      roleKey: 'staff_basic',
      permissions: [],
      instructionFolders: [],
      compact: true
    };
  }
  if (data && data.v === 2) {
    return {
      inviteId: data.i,
      email: data.e,
      ownerName: data.n || '',
      ownerEmail: data.o || '',
      ownerUserId: data.u || '',
      accountId: data.a || 'default',
      staffId: data.s || '',
      roleKey: data.r || 'staff_basic',
      permissions: [],
      instructionFolders: [],
      compact: true
    };
  }
  return data;
}
function _acceptTeamInviteToken(token) {
  const payload = _teamDecodeInvite(token);
  if (!payload || !payload.inviteId || (!payload.email && !payload.ownerUserId)) {
    throw new Error('دعوت‌نامه معتبر نیست');
  }
  const inviteEmail = String(payload.email || _sbUser?.email || '').trim().toLowerCase();
  if (!inviteEmail) throw new Error('برای پذیرش دعوت ابتدا وارد حساب خود شوید');
  const permissions = _normalizeTeamPermissions(payload.permissions);
  localStorage.setItem(TEAM_ACCESS_SESSION_KEY, JSON.stringify({
    inviteId: payload.inviteId,
    email: inviteEmail,
    ownerName: payload.ownerName || '',
    ownerEmail: payload.ownerEmail || '',
    ownerUserId: payload.ownerUserId || '',
    accountId: payload.accountId || '',
    ownerDbKey: payload.ownerDbKey || '',
    staffId: payload.staffId || payload.staff_id || '',
    roleKey: payload.roleKey || payload.role_key || payload.team_role || 'staff_basic',
    permissions,
    instructionFolders: payload.instructionFolders || payload.instruction_folders || [],
    acceptedAt: new Date().toISOString(),
  }));
  if (payload.accountId) _setCurrentAccountId(payload.accountId);
  if (payload.ownerDbKey) window._activeDBKey = payload.ownerDbKey;
  localStorage.removeItem(TEAM_PENDING_INVITE_KEY);
  currentPage = permissions.find(p => _SAFE_RESTORE_PAGES.includes(p)) || 'todolist';
  location.hash = currentPage;
}
async function _ensureTeamAccessOwner() {
  const session = _teamAccessSession();
  if (!session) return null;

  const invitedEmail = String(session.email || '').trim().toLowerCase();
  const currentEmail = String(_sbUser?.email || '').trim().toLowerCase();
  if (invitedEmail && currentEmail && invitedEmail !== currentEmail) {
    localStorage.removeItem(TEAM_ACCESS_SESSION_KEY);
    showToast('این لینک دعوت برای ایمیل دیگری ساخته شده است', 'error');
    return null;
  }

  if (!session.ownerEmail && !session.ownerUserId) {
    showToast('لینک هم‌تیمی قدیمی است؛ صاحب حساب لینک دعوت را دوباره کپی کند', 'error');
    window._activeDBKey = _teamSessionStorageKey(session);
    return session;
  }

  try {
    const res = await _apiFetch('/api/auth/team-invite/resolve', {
      method: 'POST',
      body: JSON.stringify({
        ownerUserId: session.ownerUserId || '',
        ownerEmail: session.ownerEmail || '',
        inviteId: session.inviteId,
        email: session.email || '',
        staffId: session.staffId || session.staff_id || '',
        roleKey: session.roleKey || session.role_key || session.team_role || 'staff_basic',
        accountId: session.accountId || 'default',
        permissions: _normalizeTeamPermissions(session.permissions),
        instructionFolders: session.instructionFolders || []
      })
    });
    if (!res.ok) throw new Error('resolve failed');
    const resolved = await res.json();
    const next = {
      ...session,
      ownerUserId: resolved.ownerUserId || session.ownerUserId || '',
      ownerName: resolved.ownerName || session.ownerName || '',
      ownerEmail: resolved.ownerEmail || session.ownerEmail || '',
      accountId: resolved.accountId || session.accountId || 'default',
      staffId: resolved.staffId || resolved.staff_id || session.staffId || '',
      roleKey: resolved.roleKey || resolved.role_key || resolved.team_role || session.roleKey || 'staff_basic',
      permissions: _normalizeTeamPermissions(resolved.permissions?.length ? resolved.permissions : session.permissions),
      instructionFolders: resolved.instructionFolders || session.instructionFolders || []
    };
    localStorage.setItem(TEAM_ACCESS_SESSION_KEY, JSON.stringify(next));
    window._activeDBKey = _teamSessionStorageKey(next);
    return next;
  } catch(e) {
    if (!session.ownerUserId) {
      showToast('اتصال هم‌تیمی کامل نشد؛ لینک دعوت را دوباره از صاحب حساب بگیر', 'error');
    }
    window._activeDBKey = _teamSessionStorageKey(session);
    return session;
  }
}
// وقتی داده از سرور به‌روزرسانی می‌شود (هر ۵ ثانیه)، دسترسی‌های کش‌شده هم‌تیمی را
// از روی team_members تازه‌سینک‌شده بازسازی می‌کند تا تغییرات مدیر فوراً اعمال شود
// (بدون نیاز به خروج و ورود دوباره یا ساخت لینک دعوت جدید).
function _teamSyncSessionPermissions() {
  const session = _teamAccessSession();
  if (!session) return false;
  const staffId = String(session.staffId || session.staff_id || '');
  const email = String(session.email || '').trim().toLowerCase();
  const member = (_db.team_members || []).find(m =>
    (staffId && String(m.staff_id || '') === staffId) ||
    (!staffId && String(m.email || '').trim().toLowerCase() === email)
  );
  if (!member) return false;

  const newPerms = _normalizeTeamPermissions(member.permissions);
  const newRole = member.role_key || member.team_role || member.roleKey || session.roleKey || 'staff_basic';
  const newFolders = (member.instruction_folders || []).map(Number).filter(Boolean);
  const oldPerms = _normalizeTeamPermissions(session.permissions);
  const oldRole = session.roleKey || session.role_key || session.team_role || 'staff_basic';
  const oldFolders = _teamInstructionFolderIds(session);

  const sortedEq = (a, b) => JSON.stringify([...a].sort()) === JSON.stringify([...b].sort());
  if (newRole === oldRole && sortedEq(newPerms, oldPerms) && sortedEq(newFolders, oldFolders)) return false;

  const next = { ...session, roleKey: newRole, permissions: newPerms, instructionFolders: newFolders };
  localStorage.setItem(TEAM_ACCESS_SESSION_KEY, JSON.stringify(next));
  _applyTeamAccessToNav();
  // اگر صفحه فعلی دیگر مجاز نیست، کاربر را به یک صفحهٔ مجاز هدایت کن
  if (!_teamCan(currentPage)) {
    currentPage = _teamDefaultPage();
    location.hash = currentPage;
  }
  showToast('دسترسی‌های شما توسط مدیر به‌روزرسانی شد ✓', 'success');
  return true;
}
function _leaveTeamAccess() {
  // مهم: قبل از هر چیز جلوی sync رو بگیر. وگرنه location.reload() رویداد
  // pagehide رو صدا می‌زنه که _syncToServer() رو اجرا می‌کنه؛ در اون لحظه
  // TEAM_ACCESS_SESSION_KEY پاک شده (پس accId = خودِ کاربر) ولی _db هنوز
  // داده‌ی کامل کارفرماست — یعنی داده‌ی کارفرما جای داده‌ی خودِ کاربر روی
  // سرور نوشته می‌شه و حساب پرسنل رو خراب می‌کنه.
  window._leavingTeamAccess = true;
  clearInterval(window._syncInterval);
  clearInterval(window._pollInterval);
  clearTimeout(window._pollInterval);
  window._serverPollGeneration = (window._serverPollGeneration || 0) + 1;
  clearTimeout(window._serverSyncTimer);
  localStorage.removeItem(TEAM_ACCESS_SESSION_KEY);
  showToast('دسترسی هم‌تیمی خارج شد ✓', 'success');
  setTimeout(() => location.reload(), 600);
}
function _teamActiveDBKey() {
  const s = _teamAccessSession();
  return s ? _teamSessionStorageKey(s) : _userDBKey();
}
function _teamInstructionFolderIds(source) {
  const raw = source || _teamAccessSession() || {};
  const ids = raw.instructionFolders || raw.instruction_folders || [];
  return Array.isArray(ids) ? ids.map(Number).filter(Boolean) : [];
}
function _instrAncestors(id) {
  const flat = _db?.instructions || [];
  const out = [];
  let current = flat.find(n => +n.id === +id);
  let guard = 0;
  while (current && current.parent_id && guard++ < 40) {
    const parent = flat.find(n => +n.id === +current.parent_id);
    if (!parent) break;
    out.push(parent.id);
    current = parent;
  }
  return out;
}
function _instrDescendants(id) {
  const flat = _db?.instructions || [];
  const out = [];
  const walk = (pid) => {
    flat.filter(n => +n.parent_id === +pid).forEach(n => {
      out.push(n.id);
      if (n.type === 'category' || n.type === 'kcategory') walk(n.id);
    });
  };
  walk(+id);
  return out;
}
function _teamCanInstructionNode(id) {
  const session = _teamAccessSession();
  if (!session) return true;
  if (!_teamCan('instructions')) return false;
  const allowed = _teamInstructionFolderIds(session);
  if (!allowed.length) return true;
  const node = (_db?.instructions || []).find(n => +n.id === +id);
  if (!node) return false;
  const ancestors = _instrAncestors(id);
  if (allowed.includes(+id) || ancestors.some(a => allowed.includes(+a))) return true;
  if (node.type === 'category' || node.type === 'kcategory') {
    const descendants = _instrDescendants(id);
    return descendants.some(d => allowed.includes(+d));
  }
  return false;
}
function _teamCanCreateInstruction(parentId) {
  const session = _teamAccessSession();
  if (!session) return true;
  if (!_teamCan('instructions')) return false;
  const allowed = _teamInstructionFolderIds(session);
  if (!allowed.length) return true;
  return parentId && _teamCanInstructionNode(parentId);
}
// Apply the correct sidebar/bottom-nav highlight IMMEDIATELY, synchronously,
// right as the script parses — before any auth/network/init() work runs.
// This is what prevents the "flash of wrong menu item" on refresh: we never
// let the browser paint the default HTML state before correcting it.
function _menuPageFor(page) {
  if (page === 'sessions' || page === 'customerlist' || page === 'archive') return 'students';
  if (page === 'reminders' || page === 'families') return 'payments';
  if (page === 'transactions') return 'dashboard';
  return page;
}
(function _syncInitialActiveMenuSync() {
  const menuPage = _menuPageFor(currentPage);
  document.querySelectorAll('.nav-item[data-page]').forEach(x => {
    x.classList.toggle('active', x.dataset.page === menuPage);
  });
  document.querySelectorAll('.bn-item[data-page]').forEach(x => {
    x.classList.toggle('active', x.dataset.page === menuPage);
  });
})();
let openSessionGroups = new Set();

// ── Helpers ──────────────────────────────────────────────────────────────────
function fa(n) { return String(n).replace(/[0-9]/g, d => '۰۱۲۳۴۵۶۷۸۹'[+d]); }
function fmt(n) { return fa(Number(n || 0).toLocaleString('en')); }
function avatar(name, idx) {
  const c = COLORS[idx % COLORS.length];
  const initial = escapeHtml(String(name || '').charAt(0) || '؟');
  return `<div class="avatar" style="background:${c}22;color:${c}">${initial}</div>`;
}
function pkgTag(pkg) {
  return `<span class="tag" style="background:${pkg.type_color}22;color:${pkg.type_color}">${escapeHtml(pkg.type_label)}</span>`;
}
function showToast(msg, type = '') {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.className = 'toast show' + (type ? ' ' + type : '');
  clearTimeout(t._t);
  t._t = setTimeout(() => t.classList.remove('show'), 2800);
}
function balanceHtml(balance, isSupplier) {
  if (isSupplier) {
    if (balance > 0) return `<span class="amount amount-debt">${fmt(balance)} ت (ما بدهکار)</span>`;
    if (balance < 0) return `<span class="amount balance-credit">${fmt(-balance)} ت (ما طلبکار)</span>`;
    return `<span class="amount amount-paid">تسویه</span>`;
  }
  if (balance > 0) return `<span class="amount amount-debt">${fmt(balance)} ت</span>`;
  if (balance < 0) return `<span class="amount balance-credit">${fmt(-balance)} ت طلب</span>`;
  return `<span class="amount amount-paid">تسویه</span>`;
}
function familyBalanceHtml(balance) {
  if (balance > 0) return `<span class="amount amount-debt">${fmt(balance)} ت بدهی</span>`;
  if (balance < 0) return `<span class="amount balance-credit">${fmt(-balance)} ت اعتبار</span>`;
  return `<span class="amount amount-paid">تسویه</span>`;
}
function mstuStatusLine(balance) {
  let color, label, amt = '';
  if (balance > 0)      { color = 'var(--red)';   label = 'بدهکار'; amt = fmt(balance) + ' تومان'; }
  else if (balance < 0) { color = 'var(--blue)';  label = 'طلبکار'; amt = fmt(-balance) + ' تومان'; }
  else                  { color = 'var(--green)'; label = 'تسویه'; }
  return `<div class="mstu-status-line" style="color:${color}">
    <span class="dot" style="background:${color}"></span>
    <span>${label}</span>
    ${amt ? `<span class="amt">${amt}</span>` : ''}
  </div>`;
}
function statusHtml(balance, isSupplier) {
  if (isSupplier) {
    if (balance > 0) return `<span class="status status-debt">🏭 ما بدهکاریم</span>`;
    if (balance < 0) return `<span class="status" style="color:var(--blue)"><span style="width:7px;height:7px;border-radius:50%;background:var(--blue);display:inline-block;margin-left:5px"></span>ما طلبکاریم</span>`;
    return `<span class="status status-ok">تسویه</span>`;
  }
  if (balance > 0) return `<span class="status status-debt">بدهکار</span>`;
  if (balance < 0) return `<span class="status" style="color:var(--blue)"><span style="width:7px;height:7px;border-radius:50%;background:var(--blue);display:inline-block;margin-left:5px"></span>طلبکار</span>`;
  return `<span class="status status-ok">تسویه</span>`;
}
function escapeHtml(str) {
  if (str == null || str === false) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
function escapeAttr(str) {
  return escapeHtml(JSON.stringify(str == null ? '' : String(str)));
}
function excerpt(str, len=70) {
  if (!str) return '';
  const clean = str.trim();
  return clean.length > len ? clean.slice(0,len) + '…' : clean;
}

// ── Rich text: **bold** and ==highlight== + simple sticker emojis ────────────
function _cleanPlaceholderAnswer(value) {
  const text = String(value || '').trim();
  // Legacy templates used dotted/dashed lines as a visual writing area. They
  // are placeholders, not user-entered answers, so never show them in inputs.
  if (text.length >= 3 && /^[-.…·_ـ\s]+$/.test(text)) return '';
  return String(value || '');
}

function _renderChecklist(text, checked, interactive, noteId, field, itemIndex, textareaId) {
  const bs = 'margin-top:3px;width:18px;height:18px;flex-shrink:0;accent-color:var(--accent2)';
  const chk = checked ? 'checked ' : '';
  const ts = checked ? 'text-decoration:line-through;color:var(--text3)' : '';
  const answerMatch = String(text || '').match(/^(.+?[:：])\s*(.*)$/);
  if (answerMatch && interactive && (noteId != null || textareaId)) {
    const answerHandler = "oninput='_updateChecklistAnswer(" + (noteId == null ? 'null' : noteId) + ',' + JSON.stringify(field || '') + ',this,' + itemIndex + ',' + JSON.stringify(textareaId || '') + ")'";
    return '<div class="interactive-form-field" style="display:grid;grid-template-columns:minmax(110px,auto) minmax(150px,1fr);align-items:center;gap:10px;margin:4px 0;min-height:52px;padding:7px 10px;border-radius:9px;background:var(--bg3);border:1px solid var(--border)">' +
      '<label style="font-weight:600" for="checklist-answer-' + (noteId == null ? 'draft' : noteId) + '-' + field + '-' + itemIndex + '">' + answerMatch[1] + '</label>' +
      '<input id="checklist-answer-' + (noteId == null ? 'draft' : noteId) + '-' + field + '-' + itemIndex + '" type="text" value="' + _cleanPlaceholderAnswer(answerMatch[2]) + '" ' + answerHandler + ' placeholder="اینجا وارد کنید…" aria-label="مقدار ' + answerMatch[1] + '" ' +
        'style="width:100%;min-width:0;height:40px;padding:7px 10px;border:1px solid var(--border2);border-radius:8px;background:var(--bg2);color:var(--text);font-family:var(--font);font-size:13px">' +
      '</div>';
  }
  if (answerMatch) {
    return '<div style="display:flex;gap:10px;margin:4px 0;padding:8px"><strong>' + answerMatch[1] + '</strong><span>' + (answerMatch[2] || '—') + '</span></div>';
  }
  if (interactive && (noteId != null || textareaId)) {
    const handler = "onchange='_toggleChecklistItem(" + (noteId == null ? 'null' : noteId) + ',' + JSON.stringify(field || '') + ',this,' + itemIndex + ',' + JSON.stringify(textareaId || '') + ")'";
    return '<label class="interactive-checklist-item" style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;margin:2px 0;min-height:44px;padding:10px 6px;border-radius:8px;transition:background .15s" onmouseenter="this.style.background=\'rgba(124,106,247,.07)\'" onmouseleave="this.style.background=\'transparent\'"><input type="checkbox" ' + chk + handler + ' style="' + bs + ';cursor:pointer"><span style="' + ts + '">' + text + '</span></label>';
  }
  return '<label style="display:flex;align-items:flex-start;gap:10px;margin:2px 0;min-height:40px;padding:8px 4px"><input type="checkbox" ' + chk + 'disabled style="' + bs + '"><span style="' + ts + '">' + text + '</span></label>';
}

// پاک‌سازی لایه‌های تودرتوی نشانه‌ی رنگ که در نسخه‌ی قدیمی applyTextColor ذخیره می‌شدند
function _cleanupColorMarkers(str) {
  if (!str) return str;
  let s = str, prev;
  do {
    prev = s;
    s = s.replace(/\{\{c:(#[0-9a-fA-F]{3,8})\}\}\{\{c:#[0-9a-fA-F]{3,8}\}\}([\s\S]*?)\{\{\/c\}\}\{\{\/c\}\}/g, '{{c:$1}}$2{{/c}}');
  } while (s !== prev);
  return s;
}

function renderRich(str, opts) {
  if (!str) return '';
  const interactive = !!(opts && opts.interactive);
  const noteId = (opts && opts.noteId != null) ? opts.noteId : null;
  const field = (opts && opts.field) ? opts.field : '';
  const textareaId = (opts && opts.textareaId) ? opts.textareaId : '';
  let checklistIndex = 0;
  let s = escapeHtml(str);
  // پاک‌سازی لایه‌های تودرتوی رنگ که با نسخه‌ی قبلیِ باگ‌دار ذخیره شده بودند
  // (مثل {{c:x}}{{c:y}}متن{{/c}}{{/c}}) — رنگ بیرونی (آخرین رنگ انتخاب‌شده) نگه داشته می‌شود.
  s = _cleanupColorMarkers(s);
  // نشانه‌گذاری رنگ متن {{c:#hex}}...{{/c}} → span رنگی واقعی
  s = s.replace(/\{\{c:(#[0-9a-fA-F]{3,8})\}\}([\s\S]*?)\{\{\/c\}\}/g, '<span style="color:$1">$2</span>');
  // سازگاری با یادداشت‌های قدیمی که HTML خام رنگ در آن‌ها ذخیره و توسط escapeHtml خراب شده بود
  s = s.replace(/&lt;span style="color:(#[0-9a-fA-F]{3,8})"&gt;([\s\S]*?)&lt;\/span&gt;/g, '<span style="color:$1">$2</span>');
  // کد باید قبل از سایر قواعد Markdown کنار گذاشته شود تا محتوای داخلش فرمت نشود.
  const codeBlocks = [];
  s = s.replace(/```(?:[^\n]*)\n?([\s\S]*?)```/g, function(_, code) {
    const token = '\uE000CODE' + codeBlocks.length + '\uE001';
    codeBlocks.push('<pre style="direction:ltr;text-align:left;overflow-x:auto;margin:10px 0;padding:12px;border:1px solid var(--border2);border-radius:9px;background:var(--bg3);font-family:monospace;font-size:12px;line-height:1.7;white-space:pre-wrap"><code>' + code.replace(/^\n|\n$/g,'') + '</code></pre>');
    return token;
  });
  const inlineCodes = [];
  s = s.replace(/`([^`\n]+)`/g, function(_, code) {
    const token = '\uE002INLINE' + inlineCodes.length + '\uE003';
    inlineCodes.push('<code style="direction:ltr;display:inline-block;padding:1px 6px;border-radius:5px;background:var(--bg3);color:var(--accent2);font-family:monospace;font-size:.92em">' + code + '</code>');
    return token;
  });
  // ':' alone is ambiguous (it is also used by headings such as "نکته:").
  // A plain-text field therefore needs the dotted writing line below it. The
  // line remains in raw Markdown as the field marker but is hidden in preview.
  const plainFields = [];
  let plainFieldIndex = 0;
  s = s.replace(/^(?:\s*\{\{field\}\}\s*([^:\n]{1,80}[:：])\s*(.*?)|[ \t]*([^:\n]{1,80}[:：])[ \t]*([^\n]*?)[ \t]*\n(?:[ \t]*\n)*[ \t]*[.…·_ـ-]{3,}[ \t]*)$/gm, function(_, markedLabel, markedAnswer, legacyLabel, legacyAnswer) {
    const label = markedLabel || legacyLabel;
    const answer = markedLabel ? markedAnswer : legacyAnswer;
    const index = plainFieldIndex++;
    const token = '\uE004FIELD' + plainFields.length + '\uE005';
    const displayAnswer = _cleanPlaceholderAnswer(answer).replace(/\s*⏎\s*/g, '\n');
    if (interactive && (noteId != null || textareaId)) {
      const handler = "oninput='_updatePlainFieldAnswer(" + (noteId == null ? 'null' : noteId) + ',' + JSON.stringify(field || '') + ',this,' + index + ',' + JSON.stringify(textareaId || '') + ")'";
      plainFields.push('<div class="interactive-form-field interactive-form-textarea" style="margin:12px 0;padding:10px;border:1px solid var(--border);border-radius:10px;background:var(--bg3)">' +
        '<label for="plain-answer-' + (noteId == null ? 'draft' : noteId) + '-' + field + '-' + index + '" style="display:block;margin-bottom:7px;font-weight:700;color:var(--text)">' + label + '</label>' +
        '<textarea id="plain-answer-' + (noteId == null ? 'draft' : noteId) + '-' + field + '-' + index + '" rows="3" ' + handler + ' placeholder="توضیحات را اینجا وارد کنید…" ' +
          'style="display:block;width:100%;min-height:88px;padding:10px 12px;border:1px solid var(--border2);border-radius:9px;background:var(--bg2);color:var(--text);font-family:var(--font);font-size:13px;line-height:1.8;resize:vertical">' + displayAnswer + '</textarea></div>');
    } else {
      plainFields.push('<div style="margin:8px 0"><strong>' + label + '</strong> ' + (displayAnswer || '—').replace(/\n/g,'<br>') + '</div>');
    }
    return token;
  });
  s = s.replace(/==(.+?)==/g, '<mark>$1</mark>');
  s = s.replace(/~~(.+?)~~/g, '<del>$1</del>');
  s = s.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  s = s.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<i>$2</i>');
  s = s.replace(/&lt;u&gt;([\s\S]*?)&lt;\/u&gt;/g, '<u>$1</u>');
  // Markdown images must be handled before ordinary links; otherwise the
  // `[alt](url)` part becomes a link and the leading `!` is left as text.
  s = s.replace(/!\[([^\]\n]*)\]\((https?:\/\/[^\s)]+)\)/g,
    '<figure style="margin:14px 0;text-align:center">' +
      '<img src="$2" alt="$1" loading="lazy" referrerpolicy="no-referrer" ' +
        'style="display:block;max-width:100%;height:auto;max-height:70vh;margin:0 auto;border-radius:10px;border:1px solid var(--border2);object-fit:contain;background:var(--bg3)" ' +
        'onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'block\'">' +
      '<figcaption style="display:none;padding:12px;border:1px dashed var(--border2);border-radius:9px;color:var(--text3);font-size:12px">تصویر بارگذاری نشد' +
        '$1' +
      '</figcaption>' +
    '</figure>');
  s = s.replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" style="color:var(--accent2);text-decoration:underline">$1</a>');
  s = s.replace(/^\s*(#{1,6})\s+(.+)$/gm, function(_, hashes, title) {
    const level = hashes.length;
    const sizes = ['','1.75em','1.5em','1.3em','1.15em','1.05em','1em'];
    return '<h' + level + ' style="font-size:' + sizes[level] + ';line-height:1.55;margin:18px 0 8px;font-weight:800;color:var(--text)">' + title + '</h' + level + '>';
  });
  s = s.replace(/^\s*&gt;\s?(.+)$/gm, '<blockquote style="margin:8px 0;padding:7px 12px;border-right:3px solid var(--accent);background:rgba(124,106,247,.07);color:var(--text2)">$1</blockquote>');
  s = s.replace(/^\s*---\s*$/gm, '<hr style="border:none;border-top:1px solid var(--border2);width:100%;margin:14px 0">');
  s = s.replace(/^(\d+)\. (.+)$/gm, '<span style="display:flex;gap:6px;margin:2px 0"><span style="color:var(--accent2);font-weight:600;flex-shrink:0">$1.</span><span>$2</span></span>');
  // Task-list syntax is accepted both with and without a Markdown list marker:
  // [ ] item, - [ ] item, * [x] item, + [X] item.
  s = s.replace(/^\s*(?:[-+*]\s+)?\[([ xX])\]\s+(.+)$/gm, function(_,state,t){
    return _renderChecklist(t,state.toLowerCase()==='x',interactive,noteId,field,checklistIndex++,textareaId);
  });
  s = s.replace(/^\s*[-+]\s+(.+)$/gm, '<span style="display:flex;gap:8px;margin:2px 0"><span style="color:var(--accent2);font-weight:800">•</span><span>$1</span></span>');
  s = s.replace(/((?:^\|.+\|\n?)+)/gm, function(tb) {
    const rows = tb.trim().split('\n').filter(function(r){ return r.trim().startsWith('|'); });
    if (rows.length < 2) return tb;
    let html = '<div style="overflow-x:auto;margin:8px 0"><table style="width:100%;border-collapse:collapse;font-size:13px">';
    rows.forEach(function(row,i){
      if (/^\|[-| ]+\|$/.test(row.trim())) return;
      const cells = row.replace(/^\|/,'').replace(/\|$/,'').split('|');
      const tag = i===0?'th':'td';
      const cs = 'padding:6px 10px;border:1px solid var(--border2);text-align:right;'+(i===0?'background:var(--bg3);font-weight:600':'background:var(--bg2)');
      html += '<tr>'+cells.map(function(c){ return '<'+tag+' style="'+cs+'">'+c.trim()+'</'+tag+'>'; }).join('')+'</tr>';
    });
    html += '</table></div>';
    return html;
  });
  s = s.replace(/\n/g, '<br>');
  s = s.replace(/\uE002INLINE(\d+)\uE003/g, function(_, i){ return inlineCodes[+i] || ''; });
  s = s.replace(/\uE000CODE(\d+)\uE001/g, function(_, i){ return codeBlocks[+i] || ''; });
  s = s.replace(/\uE004FIELD(\d+)\uE005/g, function(_, i){ return plainFields[+i] || ''; });
  return s;
}

async function _toggleChecklistItem(noteId, field, checkbox, itemIndex, textareaId) {
  const textarea = textareaId ? document.getElementById(textareaId) : null;
  const note = noteId == null ? null : (_db.instructions||[]).find(function(n){ return n.id === +noteId; });
  if (!textarea && !note) return;
  const source = textarea ? textarea.value : (note[field] || '');
  let seen = -1;
  const updated = source.replace(/^(\s*(?:[-+*]\s+)?)\[([ xX])\](\s+.+)$/gm, function(line, prefix, state, rest) {
    seen += 1;
    if (seen !== Number(itemIndex)) return line;
    return prefix + (checkbox.checked ? '[x]' : '[ ]') + rest;
  });
  if (textarea) {
    textarea.value = updated;
    textarea.dispatchEvent(new Event('input', { bubbles:true }));
  } else {
    note[field] = updated;
    _save();
    showToast(checkbox.checked ? 'انجام شد ✓' : 'به حالت انجام‌نشده برگشت', 'success');
  }
  const label = checkbox.closest('label');
  const textEl = checkbox.parentElement?.querySelector('[data-checklist-label]') || checkbox.nextElementSibling;
  if (textEl) textEl.style.cssText = checkbox.checked ? 'text-decoration:line-through;color:var(--text3)' : '';
  if (label) label.setAttribute('aria-label', checkbox.checked ? 'انجام‌شده' : 'انجام‌نشده');
}

function _updateChecklistAnswer(noteId, field, input, itemIndex, textareaId) {
  const textarea = textareaId ? document.getElementById(textareaId) : null;
  const note = noteId == null ? null : (_db.instructions||[]).find(function(n){ return n.id === +noteId; });
  if (!textarea && !note) return;
  const source = textarea ? textarea.value : (note[field] || '');
  let seen = -1;
  const cleanAnswer = String(input.value || '').replace(/[\r\n]+/g, ' ').trimStart();
  const updated = source.replace(/^(\s*(?:[-+*]\s+)?)\[([ xX])\](\s+)(.+)$/gm, function(line, prefix, state, spacing, rest) {
    seen += 1;
    if (seen !== Number(itemIndex)) return line;
    const parts = rest.match(/^(.*?[:：])\s*(.*)$/);
    if (!parts) return line;
    return prefix + '[' + state + ']' + spacing + parts[1] + (cleanAnswer ? ' ' + cleanAnswer : '');
  });
  if (textarea) {
    textarea.value = updated;
    textarea.dispatchEvent(new Event('input', { bubbles:true }));
    return;
  }
  note[field] = updated;
  clearTimeout(input._checklistSaveTimer);
  input._checklistSaveTimer = setTimeout(function() {
    _save();
    input.style.borderColor = 'var(--green)';
    setTimeout(function(){ input.style.borderColor = 'var(--border2)'; }, 700);
  }, 450);
}

function _updatePlainFieldAnswer(noteId, field, input, itemIndex, textareaId) {
  const textarea = textareaId ? document.getElementById(textareaId) : null;
  const note = noteId == null ? null : (_db.instructions||[]).find(function(n){ return n.id === +noteId; });
  if (!textarea && !note) return;
  const source = textarea ? textarea.value : (note[field] || '');
  let seen = -1;
  const cleanAnswer = String(input.value || '').replace(/\r/g, '').trimStart().replace(/\n+/g, ' ⏎ ');
  const updated = source.replace(/^(?:\s*\{\{field\}\}\s*([^:\n]{1,80}[:：])\s*(.*?)|[ \t]*([^:\n]{1,80}[:：])[ \t]*([^\n]*?)[ \t]*\n(?:[ \t]*\n)*[ \t]*[.…·_ـ-]{3,}[ \t]*)$/gm, function(line, markedLabel, markedAnswer, legacyLabel) {
    seen += 1;
    if (seen !== Number(itemIndex)) return line;
    const label = markedLabel || legacyLabel;
    return label + (cleanAnswer ? ' ' + cleanAnswer : '') + '\n........................';
  });
  if (textarea) {
    textarea.value = updated;
    textarea.dispatchEvent(new Event('input', { bubbles:true }));
    return;
  }
  note[field] = updated;
  clearTimeout(input._plainFieldSaveTimer);
  input._plainFieldSaveTimer = setTimeout(function() {
    _save();
    input.style.borderColor = 'var(--green)';
    setTimeout(function(){ input.style.borderColor = 'var(--border2)'; }, 700);
  }, 450);
}

// ── Global error guard: never let a stray error silently freeze the UI ──────
function _isBrowserExtensionNoise(msg) {
  msg = String(msg || '');
  return msg.includes('Could not establish connection') ||
    msg.includes('Receiving end does not exist') ||
    msg.includes('Extension context invalidated');
}
window.addEventListener('error', (e) => {
  const msg = String((e && (e.message || (e.error && e.error.message))) || '');
  if (_isBrowserExtensionNoise(msg)) {
    e.preventDefault();
    return;
  }
  console.error('App error:', e.error || e.message);
  showToast('خطایی رخ داد — اگر چیزی کار نکرد، لطفاً دوباره تلاش کن', 'error');
});
window.addEventListener('unhandledrejection', (e) => {
  const msg = e.reason?.message || String(e.reason || '');
  const isExt = _isBrowserExtensionNoise(msg);
  // نادیده گرفتن خطاهای مربوط به extension مرورگر (preventDefault stops Chrome's Uncaught log)
  if (isExt) {
    e.preventDefault();
    return;
  }
  console.error('Unhandled promise rejection:', e.reason);
  showToast('خطایی رخ داد — اگر چیزی کار نکرد، لطفاً دوباره تلاش کن', 'error');
});

// ── Navigation ────────────────────────────────────────────────────────────────
// ── Electron: inject missing window.api.instructions if not present ──────────
(function() {
  if (typeof window.api === 'undefined') return; // no electron
  if (window.api.instructions) return; // already exists
  // We are in Electron but preload.js doesn't have instructions
  // Use localStorage via _db as fallback (data will save to electron's localStorage)
  function _eTree(flat, pid) {
    return (flat||[]).filter(function(n){return (n.parent_id||null)===(pid||null);})
      .map(function(n){return Object.assign({},n,{items:_eTree(flat,n.id)});});
  }
  window.api.instructions = {
    getAll: async function() {
      if (!_db) await _loadPrimaryDatabase();
      if (!_db.instructions) _db.instructions = [];
      return _eTree(_db.instructions, null);
    },
    getChildren: async function(pid) {
      if (!_db) await _loadPrimaryDatabase();
      var tree = _eTree(_db.instructions||[], null);
      if (!pid) return tree;
      var node = tree.find(function(n){return n.id==pid;});
      return node ? (node.items||[]) : [];
    },
    add: async function(p) {
      if (!_db) await _loadPrimaryDatabase();
      if (typeof _teamCanCreateInstruction === 'function' && !_teamCanCreateInstruction(p.parent_id || null)) return Promise.resolve({ok:false,error:'به این پوشه دسترسی نداری'});
      if (!_db.instructions) _db.instructions = [];
      if (!_db._nextId) _db._nextId = {};
      if (!_db._nextId.instructions) _db._nextId.instructions = 1;
      var id = _db._nextId.instructions++;
      _db.instructions.push({id:id, parent_id:p.parent_id||null, title:p.title||'',
        icon:p.icon||'folder', color:p.color||'#7c6af7', type:p.type||'category',
        content:p.content||'', attachments:[], created_at:new Date().toISOString()});
      _save();
      return Promise.resolve({ok:true, id:id});
    },
    update: function(p) {
      if (typeof _teamCanInstructionNode === 'function' && !_teamCanInstructionNode(p.id)) return Promise.resolve({ok:false,error:'به این مورد دسترسی نداری'});
      if (!_db || !_db.instructions) return Promise.resolve({ok:false});
      var idx = _db.instructions.findIndex(function(x){return x.id==p.id;});
      if (idx >= 0) { _db.instructions[idx] = Object.assign({}, _db.instructions[idx], p); _save(); }
      return Promise.resolve({ok:true});
    },
    delete: function(id) {
      if (typeof _teamCanInstructionNode === 'function' && !_teamCanInstructionNode(id)) return Promise.resolve({ok:false,error:'به این مورد دسترسی نداری'});
      if (!_db || !_db.instructions) return Promise.resolve({ok:false});
      var del = new Set();
      function col(x) { del.add(x); (_db.instructions||[]).filter(function(n){return n.parent_id==x;}).forEach(function(n){col(n.id);}); }
      col(id);
      _db.instructions = _db.instructions.filter(function(n){return !del.has(n.id);});
      _save();
      return Promise.resolve({ok:true});
    },
    getNode: function(id) {
      if (!_db || !_db.instructions) return Promise.resolve(null);
      return Promise.resolve(_db.instructions.find(function(x){return x.id==id;})||null);
    },
  };
})();

function bindNavItems() {
  document.querySelectorAll('.nav-item[data-page]').forEach(el => {
    el.onclick = (e) => {
      e.preventDefault();
      document.querySelectorAll('.nav-item').forEach(x => x.classList.remove('active'));
      el.classList.add('active');
      currentPage = el.dataset.page;
      if (currentPage === 'students') { _studentsTab = 'sessions'; _keySessionsExpanded = false; }
      if (currentPage === 'todolist') _todoActiveTab = 'mine';
      updatePageTitle();
      renderPage();
    };
  });
}
bindNavItems();

// Browser Back/Forward support: jump to whichever page the hash now points to.
window.addEventListener('hashchange', () => {
  const page = (location.hash || '').replace('#', '').trim();
  if (page && page !== currentPage && _SAFE_RESTORE_PAGES.includes(page)) {
    if (page === 'students' || page === 'sessions') { _studentsTab = 'sessions'; _keySessionsExpanded = false; }
    currentPage = page;
    if (currentPage === 'todolist') _todoActiveTab = 'mine';
    updatePageTitle();
    renderPage();
  }
});

function updatePageTitle() {
  document.body.classList.toggle('knowledge-page', currentPage === 'instructions');
  document.body.classList.toggle('primary-mobile-page', ['goals','habits','todolist'].includes(currentPage));
  const titles = {
    students: 'امور مشتریان',
    payments: 'حساب مشتریان',
    purchases: 'تاریخچه کل فروش ها',
    sessions: 'امور مشتریان',
    families: 'حساب مشتریان',
    reminders: 'حساب مشتریان',
    customerlist: `لیست ${META.entityPlural || 'شاگردان'}`,
    archive: `بایگانی ${META.entityPlural || 'شاگردان'}`,
    staff: 'حساب پرسنل و اعضا',
    instructions: 'مرکز دانش',
    todolist: 'لیست کارها',
    calendar: 'تقویم',
    tutorial: 'آموزش‌ها',
    admin_panel: '👑 پنل مدیریت',
    dashboard: 'داشبورد مالی',
    transactions: 'تراکنش‌های مالی',
    settings: 'تنظیمات',
    goals: '🎯 اهداف',
    habits: '🔥 عادت‌ها',
  };
  document.getElementById('page-title').textContent = titles[currentPage];
}

// Keeps sidebar / bottom-nav highlight in sync with currentPage, no matter
// which code path changed the page (click, back/forward, refresh restore).
function setActiveMenu(page) {
  const menuPage = _menuPageFor(page);
  document.querySelectorAll('.nav-item[data-page]').forEach(x => {
    x.classList.toggle('active', x.dataset.page === menuPage);
  });
  document.querySelectorAll('.bn-item[data-page]').forEach(x => {
    x.classList.toggle('active', x.dataset.page === menuPage);
  });
}

function updateSidebarGreeting() {
  try {
    const helloEl = document.getElementById('sg-hello');
    const statsEl = document.getElementById('sg-stats');
    if (!helloEl || !statsEl) return;
    if (typeof _todosInit === 'function') _todosInit();
    if (typeof _habitsInit === 'function') _habitsInit();

    const today = (typeof _todayJalaliStr === 'function') ? _todayJalaliStr() : '';
    const sessionsToday = (_db.sessions || []).filter(s => s.date_jalali === today).length;
    const tasksPending = (_db.todos || []).filter(t => !t.done && !t.archived).length;
    const activeHabits = (_db.habits || []).filter(h => !h.archived);
    const doneTodaySet = new Set((_db.habit_logs || []).filter(l => l.date === today && l.done).map(l => l.habit_id));
    const habitsOverdue = activeHabits.filter(h => !doneTodaySet.has(h.id)).length;

    const firstName = (_sbUser?.name || (_sbUser?.email ? _sbUser.email.split('@')[0] : '') || '').trim();
    helloEl.textContent = firstName ? `سلام ${firstName} 👋` : 'سلام 👋';

    const chip = (n, label) => `<span class="sg-chip"><b>${fa(n)}</b> ${label}</span>`;
    statsEl.innerHTML = [
      chip(sessionsToday, 'جلسه امروز'),
      chip(tasksPending, 'کار'),
      habitsOverdue > 0 ? chip(habitsOverdue, 'عادت عقب‌افتاده') : '',
    ].join('');
  } catch (e) { /* داشبورد کوچک سایدبار حیاتی نیست؛ خطا نباید ناوبری را بشکند */ }
}

function applyMetaToUI() {
  const appLang = _getAppLanguage();
  document.documentElement.lang = appLang === 'en' ? 'en' : 'fa';
  document.documentElement.dir = appLang === 'en' ? 'ltr' : 'rtl';
  _applyAppTranslation(appLang);
  document.getElementById('app-title').textContent = META.appTitle || 'TeamPulse';
  document.getElementById('app-subtitle').textContent = `مدیریت ${META.entityPlural || 'شاگردان'}`;
  document.getElementById('logo-icon').textContent = (META.appTitle || 'س').charAt(0);
  document.getElementById('nav-label-students').textContent = 'امور مشتریان';
  document.getElementById('nav-label-sessions').textContent = META.sessionPlural || 'جلسات';
  const customerListLabel = document.getElementById('nav-label-customerlist');
  if (customerListLabel) customerListLabel.textContent = `لیست ${META.entityPlural || 'شاگردان'}`;
  const archiveLabel = document.getElementById('nav-label-archive');
  if (archiveLabel) archiveLabel.textContent = `بایگانی ${META.entityPlural || 'شاگردان'}`;
  document.title = (META.appTitle || 'TeamPulse');
  updatePageTitle();
  _applyTeamAccessToNav();
}

function _setGoogleTranslateCookie(targetLang) {
  const value = targetLang === 'en' ? '/fa/en' : '/fa/fa';
  const expires = targetLang === 'en'
    ? ';expires=Fri, 31 Dec 9999 23:59:59 GMT'
    : ';expires=Thu, 01 Jan 1970 00:00:00 GMT';
  document.cookie = `googtrans=${value};path=/${expires}`;
  if (location.hostname) {
    document.cookie = `googtrans=${value};domain=${location.hostname};path=/${expires}`;
  }
}

function _applyAppTranslation(targetLang) {
  if (!document.body) {
    setTimeout(() => _applyAppTranslation(targetLang), 100);
    return;
  }
  if (!document.getElementById('app-translation-style')) {
    const style = document.createElement('style');
    style.id = 'app-translation-style';
    style.textContent = '.goog-te-banner-frame,.skiptranslate{display:none!important}body{top:0!important}#google_translate_element{display:none!important}';
    document.head.appendChild(style);
  }
  if (targetLang !== 'en') {
    _setGoogleTranslateCookie('fa');
    _selectGoogleTranslateLanguage('fa');
    document.body?.classList.remove('app-translated');
    return;
  }
  _setGoogleTranslateCookie('en');
  document.body?.classList.add('app-translated');

  if (!document.getElementById('google_translate_element')) {
    const holder = document.createElement('div');
    holder.id = 'google_translate_element';
    holder.style.cssText = 'position:absolute;left:-9999px;top:-9999px;width:1px;height:1px;overflow:hidden';
    document.body.appendChild(holder);
  }

  window.googleTranslateElementInit = function() {
    if (window.google?.translate?.TranslateElement) {
      new google.translate.TranslateElement({
        pageLanguage: 'fa',
        includedLanguages: 'en,fa',
        autoDisplay: false,
      }, 'google_translate_element');
      setTimeout(() => _selectGoogleTranslateLanguage('en'), 400);
    }
  };

  if (!document.getElementById('google-translate-script')) {
    const script = document.createElement('script');
    script.id = 'google-translate-script';
    script.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
    script.onerror = () => showToast('ترجمه خودکار در دسترس نیست؛ اتصال یا دسترسی به Google Translate را بررسی کن', 'error');
    document.head.appendChild(script);
  } else {
    setTimeout(() => _selectGoogleTranslateLanguage('en'), 150);
  }
}

function _selectGoogleTranslateLanguage(lang) {
  const combo = document.querySelector('.goog-te-combo');
  if (!combo) return;
  combo.value = lang;
  combo.dispatchEvent(new Event('change'));
}

async function renderPage() {
  document.body.classList.toggle('knowledge-page', currentPage === 'instructions');
  document.body.classList.toggle('primary-mobile-page', ['goals','habits','todolist'].includes(currentPage));
  if (currentPage === 'sessions') {
    currentPage = 'students';
    _studentsTab = 'sessions';
    _keySessionsExpanded = false;
    updatePageTitle();
  }
  if (currentPage === 'reminders') {
    currentPage = 'payments';
    _paymentsTab = 'reminders';
    updatePageTitle();
  }
  if (currentPage === 'families') {
    currentPage = 'payments';
    _paymentsTab = 'families';
    updatePageTitle();
  }
  _applyTeamAccessToNav();
  if (!_teamCan(currentPage)) {
    const fallback = _teamDefaultPage();
    if (fallback && fallback !== currentPage && _teamCan(fallback)) {
      currentPage = fallback;
      updatePageTitle();
      setActiveMenu(currentPage);
      if (_SAFE_RESTORE_PAGES.includes(currentPage)) history.replaceState(null, '', '#' + currentPage);
    } else {
      updateTopbarActions('');
      setContent(_teamAccessDeniedHtml(currentPage));
      return;
    }
  }
  // Reset topbar hamburger to its default state; the knowledge-center page
  // will swap it back to a back-arrow if we're still inside a folder there.
  if (typeof _instrSetHeaderNav === 'function' && currentPage !== 'instructions') {
    _instrSetHeaderNav(false);
  }
  // Save current page for refresh restore
  if (currentPage && currentPage !== 'students' || currentPage === 'students') {
    localStorage.setItem('tp_last_page', currentPage);
  }
  // Keep sidebar highlight + URL hash in sync with the page being rendered,
  // regardless of which handler triggered the navigation.
  setActiveMenu(currentPage);
  updateSidebarGreeting();
  if (_SAFE_RESTORE_PAGES.includes(currentPage) && location.hash.replace('#', '') !== currentPage) {
    history.replaceState(null, '', '#' + currentPage);
  }
  try {
    if (currentPage === 'students')  {
      if (_studentsTab === 'sessions') await renderSessions();
      else await renderStudents();
    }
    else if (currentPage === 'payments')  await renderPayments();
    else if (currentPage === 'families')  await renderFamilies();
    else if (currentPage === 'reminders')  await renderReminders();
    else if (currentPage === 'customerlist')  await renderCustomerList();
    else if (currentPage === 'archive')  await renderArchive();
    else if (currentPage === 'staff')  await renderStaff();
    else if (currentPage === 'instructions')  await renderInstructions();
    else if (currentPage === 'todolist')      await renderTodoList();
    else if (currentPage === 'calendar')       await renderCalendar();
    else if (currentPage === 'tutorial')      await renderTutorial();
    else if (currentPage === 'admin_panel')   await renderAdminPanel();
    else if (currentPage === 'settings')  await renderSettings();
    else if (currentPage === 'goals')     await renderGoals();
    else if (currentPage === 'habits')    await renderHabits();
    else if (currentPage === 'dashboard') await renderDashboard();
    else if (currentPage === 'transactions') await renderFinancialTransactions();
    else await renderStudents();
  } catch(e) {
    console.error('[TeamPulse] renderPage error:', e);
    setContent(`<div style="text-align:center;padding:40px;color:var(--red)">
      <div style="font-size:32px;margin-bottom:12px">⚠️</div>
      <div style="font-weight:700;margin-bottom:8px">خطا در بارگذاری صفحه</div>
      <div style="font-size:12px;color:var(--text3);margin-bottom:16px">${escapeHtml(e.message)}</div>
      <button class="btn btn-primary" onclick="renderPage()">تلاش مجدد</button>
    </div>`);
  }
}

// ════════════════════════════════════════════════════════════════════════════
// STUDENTS PAGE
// ════════════════════════════════════════════════════════════════════════════
let stuChip = 'all';
let stuChipsExpanded = false;
function setStuChip(val) {
  stuChip = val;
  const cur = document.querySelector('#topbar-actions .table-search input') ||
              document.querySelector('#content .table-search input');
  renderStudents(cur ? cur.value : '');
}
function toggleStuChipsExpanded() {
  stuChipsExpanded = !stuChipsExpanded;
  const cur = document.querySelector('#topbar-actions .table-search input') ||
              document.querySelector('#content .table-search input');
  renderStudents(cur ? cur.value : '');
}
function goStudentSection(page) {
  if (page === 'sessions' || page === 'students') {
    _studentsTab = page;
    currentPage = 'students';
    localStorage.setItem('tp_last_page', 'students');
    if (location.hash !== '#students') location.hash = 'students';
  } else {
    currentPage = page;
    localStorage.setItem('tp_last_page', page);
    if (location.hash !== '#' + page) location.hash = page;
  }
  if (typeof setActiveMenu === 'function') setActiveMenu(currentPage);
  updatePageTitle();
  renderPage();
}
function studentSectionNav(active) {
  const plural = META.entityPlural || 'شاگردان';
  const items = [
    { page: 'sessions', label: META.sessionPlural || 'جلسات', cls: 'students-tab-sessions' },
    { page: 'students', label: 'پرونده‌ها' },
    { page: 'customerlist', label: 'فهرست' },
    { page: 'archive', label: 'بایگانی' },
  ].filter(item => typeof _teamCan !== 'function' || _teamCan(item.page));
  return `<div class="students-section-nav" aria-label="بخش‌های ${plural}">
    ${items.map(item => `<button class="${[active === item.page ? 'active' : '', item.cls || ''].filter(Boolean).join(' ')}" onclick="goStudentSection('${item.page}')">${escapeHtml(item.label)}</button>`).join('')}
  </div>`;
}

function renderCaseFormsSection(search = '') {
  const allForms = Array.isArray(_db.case_forms) ? _db.case_forms : [];
  const query = String(search || '').trim().toLowerCase();
  const forms = query ? allForms.filter(form => [form.title, form.description, form.content].some(value => String(value || '').toLowerCase().includes(query))) : allForms;
  if (!allForms.length) return `
    <div class="table-card" style="margin-bottom:16px">
      <div class="table-header"><div class="title-wrap"><span class="title">فرم‌های پرونده</span><span class="subtitle">فرم آماده‌ای ساخته نشده است</span></div></div>
      <div class="empty" style="padding:22px"><span>▣</span>با دکمه «افزودن فرم» یک فرم بسازید یا متن فرم آماده را وارد کنید</div>
    </div>`;
  if (!forms.length) return `
    <div class="table-card" style="margin-bottom:16px">
      <div class="table-header"><div class="title-wrap"><span class="title">فرم‌های پرونده</span><span class="subtitle">نتیجه‌ای برای جستجو پیدا نشد</span></div></div>
      <div class="empty" style="padding:22px"><span>🔎</span>فرمی با عبارت «${escapeHtml(search)}» پیدا نشد</div>
    </div>`;
  return `
    <div class="table-card" style="margin-bottom:16px">
      <div class="table-header"><div class="title-wrap"><span class="title">فرم‌های پرونده</span><span class="subtitle">${query ? `${fa(forms.length)} نتیجه از ${fa(allForms.length)} فرم` : `${fa(forms.length)} فرم ساخته‌شده`}</span></div></div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px;padding:14px">
        ${forms.map(form => {
          const menuId = 'case-form-menu-' + form.id;
          const fieldCount = (String(form.content||'').match(/^(?:\s*[-+*]\s+)?\[[ xX]\]/gm)||[]).length +
            (String(form.content||'').match(/^[^:\n]{1,80}[:：][ \t]*\n(?:[ \t]*\n)*[ \t]*[.…·_ـ-]{3,}/gm)||[]).length;
          return `<div style="position:relative;padding:14px;border:1px solid var(--border);border-radius:11px;background:var(--bg2);min-height:112px;cursor:pointer" onclick="openCaseFormDetail(${form.id})">
            <div style="display:flex;align-items:flex-start;gap:10px">
              <div style="width:38px;height:38px;border-radius:10px;background:rgba(124,106,247,.14);color:var(--accent2);display:grid;place-items:center;font-size:20px;flex-shrink:0">▣</div>
              <div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:700;color:var(--text);line-height:1.7">${escapeHtml(form.title)}</div><div style="font-size:10px;color:var(--text3);margin-top:5px">${fa(fieldCount)} مورد · ویرایش ${DateService.disp(form.updated_at || form.created_at || '') || 'اکنون'}</div></div>
              <div class="row-menu" onclick="event.stopPropagation()"><button class="row-menu-btn" aria-label="عملیات فرم" onclick="toggleRowMenu(event,'${menuId}')">⋮</button><div class="row-menu-panel" id="${menuId}"><div class="row-menu-item" onclick="openCaseFormDetail(${form.id})">مشاهده</div><div class="row-menu-item" onclick="openCaseFormBuilder(${form.id})">ویرایش</div><div class="row-menu-divider"></div><div class="row-menu-item" onclick="printCaseForm(${form.id})">🖨️ پرینت</div><div class="row-menu-item" onclick="downloadCaseFormWord(${form.id})">📝 دانلود Word</div><div class="row-menu-divider"></div><div class="row-menu-item danger" onclick="deleteCaseForm(${form.id})">حذف</div></div></div>
            </div>
            ${form.description ? `<div style="font-size:11px;color:var(--text2);margin-top:10px;line-height:1.7">${escapeHtml(form.description)}</div>` : ''}
          </div>`;
        }).join('')}
      </div>
    </div>`;
}

function _caseFormSetMode(mode) {
  const imported = document.getElementById('case-form-import-panel');
  const manual = document.getElementById('case-form-manual-panel');
  if (imported) imported.style.display = mode === 'import' ? 'block' : 'none';
  if (manual) manual.style.display = mode === 'manual' ? 'block' : 'none';
  document.querySelectorAll('.case-form-mode').forEach(btn => {
    const active = btn.dataset.mode === mode;
    btn.style.background = active ? 'var(--accent)' : 'var(--bg3)';
    btn.style.color = active ? 'white' : 'var(--text2)';
  });
}

function _caseFormRowHtml(type = 'field', label = '') {
  return `<div class="case-form-builder-row" style="display:grid;grid-template-columns:140px 1fr 40px;gap:8px;align-items:center;margin-bottom:8px">
    <select class="form-select case-form-row-type" aria-label="نوع ردیف"><option value="field" ${type==='field'?'selected':''}>فیلد کوتاه</option><option value="textarea" ${type==='textarea'?'selected':''}>توضیح چندخطی</option><option value="check" ${type==='check'?'selected':''}>چک‌باکس</option><option value="heading" ${type==='heading'?'selected':''}>عنوان بخش</option><option value="text" ${type==='text'?'selected':''}>متن راهنما</option></select>
    <input class="form-input case-form-row-label" value="${escapeHtml(label)}" placeholder="عنوان یا متن ردیف" aria-label="عنوان ردیف">
    <button type="button" class="btn btn-ghost" title="حذف ردیف" aria-label="حذف ردیف" onclick="this.closest('.case-form-builder-row').remove()" style="padding:7px;min-width:40px;color:var(--red)">×</button>
  </div>`;
}

function addCaseFormBuilderRow(type = 'field', label = '') {
  document.getElementById('case-form-builder-rows')?.insertAdjacentHTML('beforeend', _caseFormRowHtml(type, label));
}

function _updateCaseFormImportPreview(textarea) {
  const preview = document.getElementById('case-form-import-preview');
  if (!preview) return;
  // An interactive preview field updates the hidden source textarea itself.
  // Do not rebuild the preview during that keystroke, otherwise Android loses focus.
  if (preview.contains(document.activeElement)) return;
  const content = textarea?.value || '';
  preview.innerHTML = content.trim()
    ? renderRich(content,{interactive:true,textareaId:'case-form-import'})
    : '<div style="min-height:280px;display:grid;place-items:center;text-align:center;color:var(--text3);font-size:12px;line-height:1.9">متن فرم را در کادر مقابل Paste کنید<br>پیش‌نمایش کامل فرم اینجا نمایش داده می‌شود</div>';
}

function openCaseFormBuilder(id = null) {
  const form = id == null ? null : (_db.case_forms || []).find(item => +item.id === +id);
  const initialRows = form ? '' : _caseFormRowHtml('field','نام و نام خانوادگی') + _caseFormRowHtml('field','شماره تماس') + _caseFormRowHtml('textarea','توضیحات');
  openModal(form ? 'ویرایش فرم پرونده' : 'افزودن فرم پرونده', `
    <div class="form-group full"><label class="form-label">عنوان فرم</label><input class="form-input" id="case-form-title" value="${escapeHtml(form?.title||'')}" placeholder="مثلاً: فرم پذیرش اولیه"></div>
    <div class="form-group full" style="margin-top:8px"><label class="form-label">توضیح کوتاه (اختیاری)</label><input class="form-input" id="case-form-description" value="${escapeHtml(form?.description||'')}" placeholder="کاربرد این فرم"></div>
    <div style="display:flex;gap:6px;margin:14px 0" role="tablist" aria-label="روش ایجاد فرم"><button type="button" class="case-form-mode" data-mode="import" onclick="_caseFormSetMode('import')" style="flex:1;padding:9px;border:0;border-radius:8px;background:var(--accent);color:white;font-family:var(--font);font-weight:700;cursor:pointer">وارد کردن فرم</button><button type="button" class="case-form-mode" data-mode="manual" onclick="_caseFormSetMode('manual')" style="flex:1;padding:9px;border:0;border-radius:8px;background:var(--bg3);color:var(--text2);font-family:var(--font);font-weight:700;cursor:pointer">ساخت فرم</button></div>
    <div id="case-form-import-panel">
      <div class="case-form-import-workspace">
        <div class="case-form-import-pane"><label class="form-label" for="case-form-import">متن فرم را از هرجا کپی و اینجا Paste کنید</label><textarea class="form-textarea" id="case-form-import" rows="16" oninput="_updateCaseFormImportPreview(this)" placeholder="# عنوان بخش&#10;- [ ] مورد قابل انجام&#10;- [ ] نام مشتری:&#10;توضیحات مشتری:&#10;........................">${escapeHtml(form?.content||'')}</textarea><div style="font-size:10px;color:var(--text3);line-height:1.8;margin-top:5px">موارد بدون «:» چک‌باکس می‌شوند؛ موارد دارای «:» ورودی نوشتاری خواهند داشت.</div></div>
        <div class="case-form-import-pane"><div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px"><label class="form-label" style="margin:0">پیش‌نمایش فرم کامل</label><span style="font-size:10px;color:var(--green)">زنده و قابل آزمایش</span></div><div class="case-form-live-preview" id="case-form-import-preview" aria-live="polite"></div></div>
      </div>
    </div>
    <div id="case-form-manual-panel" style="display:none"><div id="case-form-builder-rows">${initialRows}</div><button type="button" class="btn btn-ghost btn-sm" onclick="addCaseFormBuilderRow()">+ افزودن ردیف</button></div>
  `, [
    { label: form ? 'ذخیره تغییرات' : 'ایجاد فرم', cls:'btn-primary', action:`saveCaseForm(${form?.id || 'null'})` },
    { label:'انصراف', cls:'btn-ghost', action:'closeModal()' },
  ], { fullPage:true, overlayClass:'case-form-builder-modal' });
  setTimeout(() => {
    _updateCaseFormImportPreview(document.getElementById('case-form-import'));
    const body = document.querySelector('.case-form-builder-modal .modal-body');
    body?.addEventListener('focusin', event => {
      if (window.innerWidth > 640 || !event.target.matches('input,textarea,select')) return;
      setTimeout(() => event.target.scrollIntoView({block:'center',behavior:'smooth'}),260);
    });
  },0);
}

function _caseFormManualContent() {
  return [...document.querySelectorAll('.case-form-builder-row')].map(row => {
    const type = row.querySelector('.case-form-row-type')?.value;
    const label = row.querySelector('.case-form-row-label')?.value.trim();
    if (!label) return '';
    if (type === 'heading') return '## ' + label;
    if (type === 'check') return '[ ] ' + label;
    if (type === 'field') return '[ ] ' + label.replace(/[:：]\s*$/,'') + ':';
    if (type === 'textarea') return label.replace(/[:：]\s*$/,'') + ':\n........................';
    return label;
  }).filter(Boolean).join('\n\n');
}

function saveCaseForm(id) {
  const title = document.getElementById('case-form-title')?.value.trim();
  if (!title) { showToast('عنوان فرم را وارد کنید','error'); return; }
  const importVisible = document.getElementById('case-form-import-panel')?.style.display !== 'none';
  const rawContent = importVisible ? (document.getElementById('case-form-import')?.value || '') : _caseFormManualContent();
  if (!rawContent.trim()) { showToast('حداقل یک مورد برای فرم وارد کنید','error'); return; }
  // Imported forms are stored verbatim. Manual forms are stored as generated structured Markdown.
  const content = importVisible ? rawContent : rawContent.trim();
  const creation_mode = importVisible ? 'import' : 'manual';
  _db.case_forms = Array.isArray(_db.case_forms) ? _db.case_forms : [];
  const existing = id == null ? null : _db.case_forms.find(item => +item.id === +id);
  const now = formatJalali(...todayJalali());
  if (existing) Object.assign(existing,{title,description:document.getElementById('case-form-description')?.value.trim()||'',content,creation_mode,updated_at:now});
  else _db.case_forms.unshift({id:genEvalId(),title,description:document.getElementById('case-form-description')?.value.trim()||'',content,creation_mode,created_at:now,updated_at:now});
  _save(); closeModal(); showToast(existing?'فرم ویرایش شد ✓':'فرم ساخته شد ✓','success'); renderStudents();
}

function openCaseFormDetail(id) {
  const form = (_db.case_forms || []).find(item => +item.id === +id);
  if (!form) return;
  openModal(escapeHtml(form.title), `<div class="detail-section">${form.description?`<p style="font-size:12px;color:var(--text2);margin-bottom:12px">${escapeHtml(form.description)}</p>`:''}<div style="font-size:13px;line-height:1.9">${renderRich(form.content)}</div></div>`, [
    {label:'ویرایش',cls:'btn-primary',action:`closeModal();openCaseFormBuilder(${id})`},
    {label:'کپی',cls:'btn-ghost',action:`copyCaseForm(${id})`},
    {label:'بستن',cls:'btn-ghost',action:'closeModal()'},
  ]);
}

function copyCaseForm(id) {
  const form = (_db.case_forms || []).find(item => +item.id === +id);
  if (!form) return;
  copyToClipboard(('# ' + form.title + '\n\n' + form.content).trim(), 'فرم کپی شد ✓');
}

function _caseFormDocumentHtml(form, autoPrint = false) {
  const title = escapeHtml(form.title || 'فرم پرونده');
  // جایگزینی رنگ‌های متغیر با رنگ‌های ثابت باعث می‌شود فایل .doc در Word هم
  // مستقل از پوستهٔ تیرهٔ برنامه خوانا باشد.
  const content = renderRich(form.content || '')
    .replaceAll('var(--text)', '#1f2937')
    .replaceAll('var(--text2)', '#4b5563')
    .replaceAll('var(--text3)', '#6b7280')
    .replaceAll('var(--accent2)', '#5b45d6')
    .replaceAll('var(--border)', '#d1d5db')
    .replaceAll('var(--border2)', '#e5e7eb')
    .replaceAll('var(--bg2)', '#ffffff')
    .replaceAll('var(--bg3)', '#f8fafc');
  const printScript = autoPrint ? '<' + 'script>window.onload=()=>{window.focus();setTimeout(()=>window.print(),300);</' + 'script>' : '';
  return `<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>
    *{box-sizing:border-box} body{direction:rtl;font-family:Tahoma,Arial,sans-serif;color:#1f2937;background:#fff;max-width:860px;margin:0 auto;padding:34px 40px;font-size:13px;line-height:2}
    h1{font-size:21px;margin:0 0 5px;color:#111827} h2,h3,h4,h5,h6{color:#111827} .meta{font-size:11px;color:#6b7280;margin-bottom:24px;padding-bottom:12px;border-bottom:1px solid #e5e7eb}
    table{width:100%;border-collapse:collapse;margin:14px 0} th,td{padding:8px 10px;border:1px solid #d1d5db;text-align:right;vertical-align:top} th{background:#f3f4f6;font-weight:700}
    input,textarea{border:1px solid #9ca3af;border-radius:4px;min-height:26px;background:#fff} mark{background:#fef3c7;padding:1px 3px}@page{size:A4;margin:16mm}@media print{body{max-width:none;padding:0}.meta{margin-bottom:16px}}
  </style></head><body><h1>${title}</h1>${form.description ? `<div class="meta">${escapeHtml(form.description)}</div>` : '<div class="meta">فرم پرونده · TeamPulse</div>'}<main>${content}</main>${printScript}</body></html>`;
}

function _caseFormFilename(form) {
  return String(form?.title || 'فرم-پرونده').trim().replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, '-').slice(0, 70) || 'فرم-پرونده';
}

function printCaseForm(id) {
  const form = (_db.case_forms || []).find(item => +item.id === +id);
  if (!form) return;
  const popup = window.open('', '_blank', 'width=960,height=760');
  if (!popup) { showToast('مرورگر اجازه بازکردن پنجره پرینت را نداد', 'error'); return; }
  popup.document.open();
  popup.document.write(_caseFormDocumentHtml(form, true));
  popup.document.close();
}

function downloadCaseFormWord(id) {
  const form = (_db.case_forms || []).find(item => +item.id === +id);
  if (!form) return;
  const blob = new Blob(['\ufeff' + _caseFormDocumentHtml(form)], { type: 'application/msword;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = _caseFormFilename(form) + '.doc';
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1500);
  showToast('فایل Word آماده دانلود شد ✓', 'success');
}

function deleteCaseForm(id) {
  if (!confirm('این فرم حذف شود؟')) return;
  _db.case_forms = (_db.case_forms || []).filter(item => +item.id !== +id);
  _save(); showToast('فرم حذف شد','error'); renderStudents();
}

async function renderStudents(search = '') {
  updateTopbarActions(`
    <div class="table-search stu-topbar-search">
      <span class="search-toggle-icon" style="color:var(--text3)">🔍</span>
      <input placeholder="جستجوی مشتری یا فرم..." aria-label="جستجوی مشتری یا فرم پرونده" oninput="renderStudents(this.value)" value="${escapeHtml(search)}">
    </div>
    <div style="display:flex;align-items:stretch;border:1px solid var(--border2);border-radius:12px;overflow:hidden;background:var(--bg2);flex-shrink:0">
      <button class="btn btn-primary" onclick="openCaseFormBuilder()" style="border-radius:0;border:none;box-shadow:none"><span class="btn-icon">+</span><span> افزودن فرم</span></button>
      <button class="btn btn-ghost" onclick="openStudentModal()" style="border-radius:0;border:0;border-right:1px solid var(--border2)"><span class="btn-icon">+</span><span> افزودن ${META.entitySingular || 'شاگرد'}</span></button>
    </div>
  `);

  allStudents = await window.api.students.getAll();
  FAMILIES = await window.api.families.getAll();
  { const _sb = document.getElementById('student-badge'); _sb.textContent = fa(allStudents.length); _sb.style.display = allStudents.length ? '' : 'none'; }

  let filtered = search
    ? allStudents.filter(s => (s.name + s.lname).includes(search))
    : allStudents;

  if (stuChip === 'debt') filtered = filtered.filter(s => s.balance > 0);
  else if (stuChip === 'paid') filtered = filtered.filter(s => s.balance <= 0);
  else if (stuChip && stuChip !== 'all') filtered = filtered.filter(s => (s.packages || []).some(p => p.type_label === stuChip));

  const totalDebt = allStudents.reduce((a, s) => a + Math.max(0, s.balance), 0);
  const totalPaid = allStudents.reduce((a, s) => a + s.totalPaid, 0);

  // Top package types present (for filter chips)
  const typeCounts = {};
  allStudents.forEach(s => (s.packages || []).forEach(p => { typeCounts[p.type_label] = (typeCounts[p.type_label] || 0) + 1; }));
  const topTypes = Object.entries(typeCounts).sort((a, b) => b[1] - a[1]).slice(0, 4).map(e => e[0]);

  let html = `
  ${studentSectionNav('students')}
  ${renderCaseFormsSection(search)}
  <div class="stats-row stu-stats-row">
    <div class="stat-card s-accent">
      <div class="stat-label">کل ${META.entityPlural || 'شاگردان'}</div>
      <div class="stat-value">${fa(allStudents.length)}</div>
      <div class="stat-sub">نفر ثبت‌شده</div>
    </div>
    <div class="stat-card s-green">
      <div class="stat-label">کل دریافتی</div>
      <div class="stat-value">${fmt(totalPaid)}</div>
      <div class="stat-sub">تومان</div>
    </div>
    <div class="stat-card s-red">
      <div class="stat-label">کل مانده بدهی</div>
      <div class="stat-value">${fmt(totalDebt)}</div>
      <div class="stat-sub">تومان</div>
    </div>
    <div class="stat-card">
      <div class="stat-label">کل ${META.sessionPlural || 'جلسات'}</div>
      <div class="stat-value">${fa(allStudents.reduce((a,s) => a + s.sessionCount, 0))}</div>
      <div class="stat-sub">برگزارشده</div>
    </div>
  </div>

  <div class="table-card">
    <div class="stu-tools-row">
      <div class="chip-bar">
        <button class="chip ${stuChip==='all'?'active':''}" onclick="setStuChip('all')">همه</button>
        <button class="chip ${stuChip==='debt'?'active':''}" onclick="setStuChip('debt')">🔴 بدهکار</button>
        <button class="chip ${stuChip==='paid'?'active':''}" onclick="setStuChip('paid')">🟢 تسویه</button>
        ${topTypes.length ? (stuChipsExpanded
          ? topTypes.map(t => `<button class="chip ${stuChip===t?'active':''}" onclick="setStuChip(${escapeAttr(t)})">${escapeHtml(t)}</button>`).join('')
            + `<button class="chip chip-more" onclick="toggleStuChipsExpanded()" title="بستن فیلترهای بیشتر">−</button>`
          : `<button class="chip chip-more" onclick="toggleStuChipsExpanded()" title="فیلترهای بیشتر">+</button>`
        ) : ''}
      </div>
    </div>

    <div class="stu-table-wrap">
    <table>
      <thead>
        <tr>
          <th>نام</th>
          <th>پکیج‌ها</th>
          <th>قرارداد کل</th>
          <th>پرداخت‌شده</th>
          <th>کیف پول</th>
          <th>مانده حساب</th>
          <th>وضعیت</th>
          <th>عملیات</th>
        </tr>
      </thead>
      <tbody>`;

  if (filtered.length === 0) {
    html += `<tr><td colspan="8"><div class="empty"><span>👤</span>${META.entitySingular || 'شاگردی'} یافت نشد</div></td></tr>`;
  } else {
    filtered.forEach((s, i) => {
      const fam = FAMILIES.find(f => f.id === s.family_id);
      const tableMenuId = `stu-table-menu-${s.id}`;
      html += `<tr>
        <td>
          <div class="name-cell">
            ${avatar(s.name, i)}
            <div>
              <div style="font-weight:500">${escapeHtml(s.name)} ${escapeHtml(s.lname)} ${fam ? `<span class="family-badge">👨‍👩‍👧 ${escapeHtml(fam.name)}</span>` : ''}</div>
              <div class="name-cell-sub">${DateService.disp(s.date_jalali) || '—'}</div>
            </div>
          </div>
        </td>
        <td>${(s.packages || []).map(pkgTag).join('') || '<span style="color:var(--text3)">—</span>'}</td>
        <td><span class="amount amount-neutral">${fmt(s.totalAmount)}</span></td>
        <td><span class="amount amount-paid">${fmt(s.totalPaid)}</span></td>
        <td>${s.wallet > 0 ? `<span class="wallet-badge">👛 ${fmt(s.wallet)}</span>` : '<span class="wallet-badge empty">—</span>'}</td>
        <td>${balanceHtml(s.balance)}</td>
        <td>${statusHtml(s.balance)}</td>
        <td>
          <div class="stu-table-actions">
            <div class="row-menu">
              <button class="row-menu-btn" onclick="toggleRowMenu(event,'${tableMenuId}')" aria-label="عملیات">⋮</button>
              <div class="row-menu-panel" id="${tableMenuId}">
                <div class="row-menu-item" onclick="openStudentDetail(${s.id})">📋 جزئیات</div>
                <div class="row-menu-item" onclick="openAddPayment(${s.id})">💳 پرداخت</div>
                <div class="row-menu-item" onclick="openNewPurchase(${s.id})">🛍 خرید</div>
                <div class="row-menu-item" onclick="openStudentModal(${s.id})">✏️ ویرایش</div>
                <div class="row-menu-divider"></div>
                <div class="row-menu-item danger" onclick="deleteStudent(${s.id})">🗑 حذف</div>
              </div>
            </div>
          </div>
        </td>
      </tr>`;
    });
  }

  html += `</tbody></table></div>`;

  // ── Compact mobile card list (shown only on narrow screens; see CSS) ──
  html += `<div class="mstu-list">`;
  if (filtered.length === 0) {
    html += `<div class="empty"><span>👤</span>${META.entitySingular || 'شاگردی'} یافت نشد</div>`;
  } else {
    filtered.forEach((s, i) => {
      const fam = FAMILIES.find(f => f.id === s.family_id);
      const pkgs = s.packages || [];
      const visiblePkgs = pkgs.slice(0, 2);
      const extra = pkgs.length - visiblePkgs.length;
      const menuId = `stu-menu-${s.id}`;
      html += `
      <div class="mstu-card student-record-row" onclick="openStudentDetail(${s.id})">
        <div class="mstu-top">
          ${avatar(s.name, i)}
          <div class="mstu-name-wrap">
            <div class="mstu-name">${escapeHtml(s.name)} ${escapeHtml(s.lname)}</div>
            ${fam ? `<div class="mstu-family">👨‍👩‍👧 ${escapeHtml(fam.name)}</div>` : ''}
          </div>
          <div class="row-menu">
            <button class="row-menu-btn" onclick="toggleRowMenu(event,'${menuId}')">⋮</button>
            <div class="row-menu-panel" id="${menuId}">
              <div class="row-menu-item" onclick="openStudentDetail(${s.id})">📋 جزئیات</div>
              <div class="row-menu-item" onclick="openAddPayment(${s.id})">💳 پرداخت</div>
              <div class="row-menu-item" onclick="openNewPurchase(${s.id})">🛍 خرید</div>
              <div class="row-menu-item" onclick="openStudentModal(${s.id})">✏️ ویرایش</div>
              <div class="row-menu-divider"></div>
              <div class="row-menu-item danger" onclick="deleteStudent(${s.id})">🗑 حذف</div>
            </div>
          </div>
        </div>
        ${mstuStatusLine(s.balance)}
        <div class="mstu-pkgs">
          ${visiblePkgs.map(pkgTag).join('')}
          ${extra > 0 ? `<span class="tag" style="background:var(--bg4);color:var(--text3)">+${fa(extra)}</span>` : ''}
          ${pkgs.length === 0 ? '<span style="color:var(--text3);font-size:11px">بدون پکیج</span>' : ''}
        </div>
      </div>`;
    });
  }
  html += `</div>`;

  html += `</div>`; // .table-card
  setContent(html);

  // Restore focus to search box (it's in topbar, so look there first)
  const si = document.querySelector('#topbar-actions .table-search input') ||
             document.querySelector('#content .table-search input');
  if (si && search) {
    si.focus();
    si.setSelectionRange(search.length, search.length);
  }
}

// ── Student Detail Modal ──────────────────────────────────────────────────────
async function openStudentDetail(id) {
  const s = allStudents.find(x => x.id === id);
  if (!s) return;
  const payments = await window.api.payments.getByStudent(id);
  const walletHistory = await window.api.wallet.history(id);
  const fam = FAMILIES.find(f => f.id === s.family_id);
  const studentPackages = await window.api.packages.getByStudent(id);

  const purchaseRows = studentPackages.length
    ? studentPackages.map(p => `
      <div class="detail-row" id="pkg-row-${p.id}">
        <span class="detail-key">
          <span class="tag" style="background:${p.pkg_color}22;color:${p.pkg_color};font-size:10px">${escapeHtml(p.type_label)}</span>
          ${p.start_date ? ` · شروع: ${p.start_date}` : ''}
          ${p.payment_due_date ? ` · سررسید پرداخت: ${p.payment_due_date}` : ''}
          ${!p.is_chargeable ? ` · <small style="color:var(--amber)">هنوز وارد بدهی نشده</small>` : ''}
          ${p.staff_name ? ` · <small style="color:var(--accent2)">مجری: ${escapeHtml(p.staff_name)}</small>` : ''}
          ${p.note ? ` <small style="color:var(--text3)">— ${escapeHtml(p.note)}</small>` : ''}
        </span>
        <span class="detail-val" style="display:flex;align-items:center;gap:6px">
          ${fmt(p.total_amount)} تومان
          <button class="btn btn-ghost btn-sm" onclick="openEditPackage(${p.id})">✏️</button>
          <button class="btn btn-danger btn-sm" onclick="deletePackage(${p.id})">🗑</button>
        </span>
      </div>`).join('')
    : '<div class="detail-row"><span class="detail-key" style="color:var(--text3)">خریدی ثبت نشده</span></div>';

  const pkgRows = (s.packages || []).map(p => `
    <div class="detail-row">
      <span class="detail-key">${escapeHtml(p.type_label)}${p.initial_cost ? ` <small style="color:var(--text3)">(+${fmt(p.initial_cost)} بدهی قبلی)</small>` : ''}</span>
      <span class="detail-val">${fmt(p.grand_total)} تومان${!p.is_chargeable?' · آینده':''}</span>
    </div>`).join('');

  const payRows = payments.length
    ? payments.map(p => `
      <div class="detail-row">
        <span class="detail-key">${DateService.disp(p.date_jalali)} — ${escapeHtml(p.pkg_label)}${p.account_label ? ` <small style="color:var(--accent2)">· ${escapeHtml(p.account_label)}</small>`:''}${p.note ? ` <small style="color:var(--text3)">(${escapeHtml(p.note)})</small>`:''}</span>
        <span class="detail-val amount-paid">
          ${fmt(p.amount)} ${escapeHtml(p.currency || 'تومان')}
          <button class="btn btn-ghost btn-sm" style="margin-right:4px" onclick="openEditPayment(${p.id})">✏️</button>
          <button class="btn btn-danger btn-sm" onclick="deletePayment(${p.id}, 'students')">🗑</button>
        </span>
      </div>`).join('')
    : '<div class="detail-row"><span class="detail-key" style="color:var(--text3)">هنوز پرداختی ثبت نشده</span></div>';

  const walletRows = walletHistory.length
    ? walletHistory.slice(0,5).map(w => `
      <div class="detail-row">
        <span class="detail-key">${DateService.disp(w.date_jalali) || '—'} ${w.note ? '— ' + w.note : ''}</span>
        <span class="detail-val" style="color:${w.delta>=0?'var(--green)':'var(--red)'}">${w.delta>=0?'+':''}${fmt(w.delta)} ت</span>
      </div>`).join('')
    : '';

  let familySection = '';
  if (fam) {
    familySection = `
    <div class="detail-section">
      <h3>👨‍👩‍👧 حساب مشترک: ${escapeHtml(fam.name)}</h3>
      ${fam.members.map(m => `
        <div class="detail-row">
          <span class="detail-key">${escapeHtml(m.name)} ${escapeHtml(m.lname)}${m.id===s.id?' (این فرد)':''}</span>
          <span class="detail-val">${balanceHtml(m.balance)}</span>
        </div>`).join('')}
      <div class="detail-row" style="border-top:1px solid var(--border2);margin-top:4px">
        <span class="detail-key" style="font-weight:700">مانده مشترک خانواده</span>
        <span class="detail-val" style="font-weight:700">${familyBalanceHtml(fam.totalBalance)}</span>
      </div>
    </div>`;
  }

  openModal(`جزئیات: ${escapeHtml(s.name)} ${escapeHtml(s.lname)}`, `
    <div class="detail-section">
      <h3>اطلاعات ${META.entitySingular || 'شاگرد'}</h3>
      <div class="detail-row"><span class="detail-key">نام</span><span class="detail-val">${escapeHtml(s.name)} ${escapeHtml(s.lname)}</span></div>
      <div class="detail-row"><span class="detail-key">تاریخ رزرو/ثبت‌نام</span><span class="detail-val">${DateService.disp(s.date_jalali) || '—'}</span></div>
      <div class="detail-row"><span class="detail-key">تلفن</span><span class="detail-val">${escapeHtml(s.phone || '—')}</span></div>
      <div class="detail-row"><span class="detail-key">دسته‌بندی مشتری</span><span class="detail-val">${escapeHtml(s.customer_category || '—')}</span></div>
      <div class="detail-row"><span class="detail-key">نام مجموعه</span><span class="detail-val">${escapeHtml(s.organization_name || '—')}</span></div>
      <div class="detail-row"><span class="detail-key">آدرس</span><span class="detail-val">${escapeHtml(s.address || '—')}</span></div>
      <div class="detail-row"><span class="detail-key">یادداشت</span><span class="detail-val">${escapeHtml(s.note || '—')}</span></div>
    </div>
    <div class="detail-section">
      <h3>پکیج‌ها و مبالغ</h3>
      ${pkgRows || '<div class="detail-row"><span style="color:var(--text3)">پکیجی ثبت نشده</span></div>'}
      <div class="detail-row" style="margin-top:6px;border-top:1px solid var(--border2)">
        <span class="detail-key">پرداخت‌شده کل (تومان)</span>
        <span class="detail-val amount-paid">${fmt(s.totalPaid)} تومان</span>
      </div>
      <div class="detail-row">
        <span class="detail-key">مانده حساب (با کیف پول)</span>
        <span class="detail-val">${balanceHtml(s.balance)}</span>
      </div>
    </div>
    ${familySection}
    <div class="detail-section">
      <h3>👛 کیف پول — موجودی: <span style="color:var(--green)">${fmt(s.wallet)} تومان</span></h3>
      <div class="wallet-actions">
        <button class="btn btn-ghost btn-sm" onclick="closeModal();openWalletAdjust(${id}, 1)">+ افزایش موجودی</button>
        <button class="btn btn-ghost btn-sm" onclick="closeModal();openWalletAdjust(${id}, -1)">- برداشت / استفاده</button>
      </div>
      ${walletRows ? '<div style="margin-top:8px">' + walletRows + '</div>' : ''}
    </div>
    <div class="detail-section">
      <h3>🛒 تاریخچه خریدها <button class="btn btn-ghost btn-sm" style="margin-right:8px" onclick="closeModal();openNewPurchase(${id})">+ خرید جدید</button></h3>
      ${purchaseRows}
    </div>
    <div class="detail-section">
      <h3>تاریخچه دریافت‌ها</h3>
      ${payRows}
    </div>
  `, [
    { label: '✏️ ویرایش', cls: 'btn-ghost', action: `closeModal();openStudentModal(${id})` },
    { label: '💳 افزودن پرداخت', cls: 'btn-primary', action: `closeModal();openAddPayment(${id})` },
    { label: `📅 ثبت ${META.sessionSingular || 'جلسه'}`, cls: 'btn-ghost', action: `closeModal();openAddSessionGeneral(${id})` },
    { label: '⏰ یادآوری پرداخت', cls: 'btn-ghost', action: `closeModal();openAddReminder(${id})` },
    { label: '🗑 حذف', cls: 'btn-danger', action: `closeModal();deleteStudent(${id})` },
  ]);
}


// نگاشت شغل به نوع پکیج پیش‌فرض
function _packageTypesList() {
  return (_db?.package_types?.length ? _db.package_types : PKG_TYPES) || [];
}

function _getDefaultPkgTypeId() {
  const jobId = META.jobId || '';
  const jobPkgMap = {
    beauty:   'customer',   // آرایشگاه → مشتری
    cooking:  'customer',   // آشپزی → مشتری
    shop:     'customer',   // فروشگاه → مشتری
    medical:  'visitor',    // پزشک → مراجعه‌کننده
    therapy:  'visitor',    // روانشناس → مراجعه‌کننده
    tutoring: 'coaching',   // معلم → کوچینگ
    music:    'coaching',   // موسیقی → کوچینگ
    coach:    'coaching',   // مربی → کوچینگ
    business: 'coaching',   // مشاور → کوچینگ
  };
  const pkgKey = jobPkgMap[jobId] || 'coaching';
  const types = _packageTypesList();
  const pt = types.find(p => p.key === pkgKey) || types[0];
  return pt ? pt.id : 1;
}

// ── New Purchase (add another package to an existing student) ────────────────
function purchaseTypeOptionsHtml(selectedId = null) {
  const selected = selectedId == null ? '' : String(selectedId);
  return _packageTypesList().map(pt => `<option value="${pt.id}" ${String(pt.id)===selected?'selected':''}>${escapeHtml(pt.label)}</option>`).join('') +
    '<option value="__new_type__">+ ساخت خدمت جدید</option>';
}

function newPurchaseServiceFieldsHtml(prefix) {
  return `
    <div class="form-group full" id="${prefix}-new-service-fields" style="display:none">
      <label class="form-label">خدمت جدید</label>
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
        <input class="form-input" id="${prefix}-new-service-label" placeholder="مثلاً ادمین اینستاگرام" style="flex:1;min-width:220px">
        <input type="color" class="color-input" id="${prefix}-new-service-color" value="#7c6af7">
      </div>
    </div>`;
}

function staffMatchesService(staff, typeId) {
  const pt = _packageTypesList().find(x => String(x.id) === String(typeId));
  const serviceKey = _serviceLabelKey(pt?.label);
  if (!serviceKey) return false;
  return (staff?.roles || []).some(r => {
    const role = _db.staff_roles.find(x => String(x.id) === String(r.role_id));
    return _serviceLabelKey(role?.label) === serviceKey;
  });
}

function purchaseStaffOptionsHtml(typeId = '', selectedStaffId = '') {
  const rows = (_db.staff || []).filter(s => staffIsPersonnel(s) && s.is_active !== false && s.is_active !== 0);
  const sorted = rows.slice().sort((a,b) => Number(staffMatchesService(b,typeId)) - Number(staffMatchesService(a,typeId)));
  return '<option value="">— انتخاب نشده —</option>' + sorted.map(s => {
    const matched = staffMatchesService(s,typeId);
    const name = `${escapeHtml(s.name||'')} ${escapeHtml(s.lname||'')}`.trim();
    return `<option value="${s.id}" ${String(s.id)===String(selectedStaffId)?'selected':''}>${escapeHtml(name || 'پرسنل')} ${matched ? '— هماهنگ با خدمت' : ''}</option>`;
  }).join('');
}

function onPurchaseTypeChange(prefix) {
  const typeVal = document.getElementById(prefix + '-type')?.value || '';
  const fields = document.getElementById(prefix + '-new-service-fields');
  if (fields) fields.style.display = typeVal === '__new_type__' ? 'block' : 'none';
  const staffSel = document.getElementById(prefix + '-staff');
  if (staffSel && typeVal !== '__new_type__') {
    const selected = staffSel.value;
    staffSel.innerHTML = purchaseStaffOptionsHtml(typeVal, selected);
  }
}

async function resolvePurchaseTypeId(prefix) {
  const typeVal = document.getElementById(prefix + '-type')?.value;
  if (typeVal !== '__new_type__') return +typeVal;
  const label = document.getElementById(prefix + '-new-service-label')?.value.trim();
  const color = document.getElementById(prefix + '-new-service-color')?.value || '#7c6af7';
  if (!label) {
    showToast('نام خدمت جدید را وارد کنید', 'error');
    return 0;
  }
  const item = await window.api.packageTypes.add({ label, color });
  PKG_TYPES = await window.api.packageTypes.getAll();
  return +item.id || +(PKG_TYPES.find(x => _serviceLabelKey(x.label) === _serviceLabelKey(label))?.id || 0);
}

function openNewPurchase(studentId, preset = {}) {
  const s = allStudents.find(x => x.id === studentId);
  if (!s) return;
  const defaultPkgId = preset.type_id || _getDefaultPkgTypeId();
  const amount = Number(preset.amount || 0);
  const initial = Number(preset.initial_cost || 0);
  const current = Number(preset.current_payment || 0);
  const repeat = Number(preset.repeat_months || 0);
  const date = preset.date || formatJalali(...todayJalali());
  const paymentDueDate = preset.payment_due_date || date;
  const note = preset.note || '';
  const reminderId = preset.reminder_id ? Number(preset.reminder_id) : 0;
  const typeOptions = purchaseTypeOptionsHtml(defaultPkgId);

  openModal(`🛍 ثبت خرید جدید — ${escapeHtml(s.name)} ${escapeHtml(s.lname)}`, `
    <div class="form-grid">
      <div class="form-group full">
        <label class="form-label">پکیج / خدمت *</label>
        <select class="form-select" id="np-type" onchange="onPurchaseTypeChange('np')">${typeOptions}</select>
      </div>
      ${newPurchaseServiceFieldsHtml('np')}
      <div class="form-group full">
        <label class="form-label">مجری خدمت / پرسنل</label>
        <select class="form-select" id="np-staff">${purchaseStaffOptionsHtml(defaultPkgId, preset.staff_id || '')}</select>
      </div>
      <div class="form-group">
        <label class="form-label">مبلغ کل / دوره‌ای (تومان)</label>
        <input class="form-input amount-input" id="np-amount" type="number" placeholder="0" value="${amount || ''}">
      </div>
      <div class="form-group">
        <label class="form-label">بدهی قبلی (تومان)</label>
        <input class="form-input amount-input" id="np-initial" type="number" placeholder="0" value="${initial || ''}">
      </div>
      <div class="form-group">
        <label class="form-label">پرداختی حال حاضر (تومان)</label>
        <input class="form-input amount-input" id="np-current" type="number" placeholder="0" value="${current || ''}">
      </div>
      <div class="form-group">
        <label class="form-label">تاریخ شروع خدمت (شمسی)</label>
        <input class="form-input jdate" id="np-date" value="${escapeHtml(date)}">
      </div>
      <div class="form-group">
        <label class="form-label">سررسید اولین پرداخت (شمسی)</label>
        <input class="form-input jdate" id="np-payment-due" value="${escapeHtml(paymentDueDate)}">
      </div>
      <div class="form-group full">
        <label class="form-label">🔁 تکرار / یادآوری تجدید</label>
        <select class="form-select" id="np-repeat">
          <option value="0" ${repeat===0?'selected':''}>بدون تکرار</option>
          <option value="1" ${repeat===1?'selected':''}>هر ۱ ماه</option>
          <option value="3" ${repeat===3?'selected':''}>هر ۳ ماه</option>
          <option value="6" ${repeat===6?'selected':''}>هر ۶ ماه</option>
          <option value="12" ${repeat===12?'selected':''}>هر ۱۲ ماه</option>
        </select>
      </div>
      <div class="form-group full">
        <label class="form-label">توضیحات خرید</label>
        <input class="form-input" id="np-note" placeholder="توضیح یا یادداشت درباره این خرید..." value="${escapeHtml(note)}">
      </div>
    </div>
  `, [
    { label: 'ثبت خرید', cls: 'btn-primary', action: `saveNewPurchase(${studentId}, ${reminderId})` },
    { label: 'انصراف', cls: 'btn-ghost', action: 'closeModal()' },
  ]);
  initDatePickers();
  onPurchaseTypeChange('np');
}

async function saveNewPurchase(studentId, reminderId = 0) {
  if (window._savingNewPurchase) return;
  window._savingNewPurchase = true;
  try {
  const type_id = await resolvePurchaseTypeId('np');
  const date = document.getElementById('np-date')?.value;
  const paymentDueDate = document.getElementById('np-payment-due')?.value || date;
  const repeat_months = +(document.getElementById('np-repeat')?.value || 0);
  if (!type_id) return;
  if (reminderId && repeat_months > 0 && !_nextFuturePaymentReminderDate(paymentDueDate, repeat_months)) {
    showToast('تاریخ سررسید معتبر نیست؛ تاریخ را اصلاح کنید', 'error');
    return;
  }
  const res = await window.api.packages.add({
    student_id: studentId,
    type_id,
    staff_id: document.getElementById('np-staff')?.value || null,
    total_amount: +(document.getElementById('np-amount')?.value || 0),
    initial_cost: +(document.getElementById('np-initial')?.value || 0),
    current_payment: +(document.getElementById('np-current')?.value || 0),
    repeat_months,
    note: document.getElementById('np-note')?.value || '',
    date,
    payment_due_date: paymentDueDate,
    skip_reminder: !!reminderId,
  });
  if (reminderId) {
    const completed = await window.api.reminders.completePurchase({ id: reminderId, package_id: res?.id, repeat_months, payment_due_date: paymentDueDate });
    if (!completed?.ok) {
      closeModal();
      showToast(completed?.error || 'خرید ثبت شد اما انتقال یادآوری انجام نشد؛ یادآوری را ویرایش کنید', 'error');
      await refreshReminderSurface();
      return;
    }
  }
  closeModal();
  showToast(repeat_months > 0 ? 'خرید ثبت شد و یادآوری دوره بعد ساخته شد ✓' : 'خرید جدید ثبت شد ✓', 'success');
  if (currentPage === 'reminders') await renderReminders();
  else if (currentPage === 'payments' && _paymentsTab === 'reminders') await renderPayments();
  else if (currentPage === 'payments') await renderPayments();
  else await renderStudents();
  } finally {
    window._savingNewPurchase = false;
  }
}

// ── Wallet adjust modal ────────────────────────────────────────────────────────
function openWalletAdjust(studentId, sign) {
  const s = allStudents.find(x => x.id === studentId);
  const title = sign > 0 ? 'افزایش موجودی کیف پول' : 'برداشت از کیف پول';
  openModal(`${title} — ${escapeHtml(s.name)} ${escapeHtml(s.lname)}`, `
    <div class="form-grid">
      <div class="form-group">
        <label class="form-label">مبلغ (تومان) *</label>
        <input class="form-input amount-input" id="f-wallet-amount" type="number" placeholder="0">
      </div>
      <div class="form-group">
        <label class="form-label">تاریخ (شمسی)</label>
        <input class="form-input jdate" id="f-wallet-date" placeholder="انتخاب تاریخ" value="${formatJalali(...todayJalali())}">
      </div>
      <div class="form-group full">
        <label class="form-label">یادداشت</label>
        <input class="form-input" id="f-wallet-note" placeholder="مثلاً: پرداخت اضافه برای دوره بعد">
      </div>
    </div>
    <p style="font-size:11px;color:var(--text3);margin-top:6px">موجودی فعلی: ${fmt(s.wallet)} تومان</p>
  `, [
    { label: 'ثبت', cls: 'btn-primary', action: `saveWalletAdjust(${studentId}, ${sign})` },
    { label: 'انصراف', cls: 'btn-ghost', action: 'closeModal()' },
  ]);
  initDatePickers();
}

async function saveWalletAdjust(studentId, sign) {
  const amount = +(document.getElementById('f-wallet-amount')?.value || 0);
  if (!amount || amount <= 0) { showToast('مبلغ را وارد کنید', 'error'); return; }
  await window.api.wallet.adjust({
    student_id: studentId,
    delta: sign * amount,
    date: document.getElementById('f-wallet-date')?.value || '',
    note: document.getElementById('f-wallet-note')?.value || '',
  });
  closeModal();
  showToast(sign > 0 ? 'به کیف پول اضافه شد ✓' : 'از کیف پول کسر شد ✓', 'success');
  await renderStudents();
}

// ── Add/Edit Student Modal ────────────────────────────────────────────────────
function openStudentModal(id = null) {
  const editing = id !== null;
  const s = editing ? allStudents.find(x => x.id === id) : null;
  refreshFamiliesAndOpenStudentModal(editing, s, id);
}

