function updateGeneralPaymentPkgs() {
  const sid = +document.getElementById('gp-student')?.value;
  const s = allStudents.find(x => x.id === sid);
  const sel = document.getElementById('gp-pkg');
  const opts = paymentPackageOptionsHtml(s?.packages || []);
  sel.innerHTML = opts || '<option value="">— پکیجی ثبت نشده —</option>';
  toggleQuickNewPackage('gp');
  const info = document.getElementById('gp-pkg-info');
  const pkgLabels = uniquePaymentPackageOptions(s?.packages || []).map(p=>p.type_label).join('، ') || '—';
  if (info) info.innerHTML = `<p style="font-size:11px;color:var(--text3)">خدمات فعال: ${pkgLabels} — مانده فعلی: ${balanceHtml(s?.balance||0)}</p>`;
}

async function saveGeneralPayment() {
  const studentId = +document.getElementById('gp-student')?.value;
  const pkgId = document.getElementById('gp-pkg')?.value;
  const amount = +(document.getElementById('gp-amount')?.value || 0);
  const date = document.getElementById('gp-date')?.value;
  if (!pkgId) { showToast('پکیج را انتخاب کنید', 'error'); return; }
  if (!amount || amount <= 0) { showToast('مبلغ دریافتی را وارد کنید', 'error'); return; }
  if (!date) { showToast('تاریخ را وارد کنید', 'error'); return; }

  let packageId = pkgId === '__general__' ? null : +pkgId;
  if (pkgId === '__new__') {
    const newTotal = +(document.getElementById('gp-new-total')?.value || 0) || amount;
    const res = await window.api.packages.add({
      student_id: studentId,
      type_id: +(document.getElementById('gp-new-type')?.value || 0),
      total_amount: newTotal,
      initial_cost: 0,
      current_payment: 0,
      repeat_months: 0,
      note: document.getElementById('gp-note')?.value || '',
      date,
    });
    packageId = +res?.id;
  }

  await window.api.payments.add({
    package_id: packageId,
    student_id: studentId,
    amount,
    currency: document.getElementById('gp-currency')?.value || 'تومان',
    date,
    method: document.getElementById('gp-method')?.value,
    account_id: document.getElementById('gp-account')?.value || null,
    note: document.getElementById('gp-note')?.value,
  });
  closeModal();
  showToast('پرداخت ثبت شد ✓', 'success');
  await renderPayments();
}

// ════════════════════════════════════════════════════════════════════════════
// PAYMENTS PAGE
// ════════════════════════════════════════════════════════════════════════════
let _paymentsTab = 'purchases';

function accountCustomerTabsHtml(tab, search = '') {
  return `
    <div class="payments-toolbar account-tabs-toolbar">
      <div class="payments-segmented" role="tablist" aria-label="حساب مشتریان">
        <button class="${tab==='purchases'?'active':''}" role="tab" aria-selected="${tab==='purchases'}" onclick="_paymentsTab='purchases';currentPage='payments';renderPayments()">🛒 فروش</button>
        <button class="${tab==='payments'?'active':''}" role="tab" aria-selected="${tab==='payments'}" onclick="_paymentsTab='payments';currentPage='payments';renderPayments()">💳 دریافت</button>
        <button class="${tab==='reminders'?'active':''}" role="tab" aria-selected="${tab==='reminders'}" onclick="_paymentsTab='reminders';currentPage='payments';renderPayments()">🔔 یادآوری</button>
        <button class="${tab==='families'?'active':''}" role="tab" aria-selected="${tab==='families'}" onclick="_paymentsTab='families';currentPage='payments';renderPayments()">👥 حساب مشترک</button>
      </div>
    </div>`;
}

function accountCustomerTopbarHtml(tab, search = '') {
  if (tab === 'families') {
    return `<button class="btn btn-primary" onclick="openNewFamily()"><span class="btn-icon">+</span><span> افزودن گروه جدید</span></button>`;
  }
  if (!['purchases', 'payments', 'reminders'].includes(tab)) return '';
  const searchPlaceholder = tab === 'reminders' ? 'جستجوی یادآوری...' : 'جستجو با نام...';
  return `<div class="table-search">
    <svg width="14" height="14" viewBox="0 0 20 20" fill="none"><circle cx="9" cy="9" r="6" stroke="currentColor" stroke-width="2"/><path d="M15 15l3 3" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
    <input placeholder="${searchPlaceholder}" oninput="renderPayments(this.value)" value="${escapeHtml(search)}">
  </div>`;
}

function updateReminderBadges(count) {
  const text = fa(count || 0);
  ['reminder-badge', 'payments-reminder-badge', 'bn-reminder-badge'].forEach(id => {
    const badge = document.getElementById(id);
    if (!badge) return;
    badge.style.display = count ? 'inline-block' : 'none';
    badge.textContent = text;
  });
}

async function refreshReminderSurface(search = '') {
  if (currentPage === 'payments' && _paymentsTab === 'reminders') await renderPayments(search);
  else if (currentPage === 'reminders') await renderReminders(search);
}

async function renderPayments(search = '') {
  const tab = _paymentsTab;

  updateTopbarActions(accountCustomerTopbarHtml(tab, search));

  allStudents = await window.api.students.getAll();
  try {
    const remindersForBadge = await window.api.reminders.getAll();
    updateReminderBadges(remindersForBadge.filter(r => !r.done).length);
  } catch(e) {}
  const q = search.trim().toLowerCase();

  if (tab === 'families') {
    await renderFamilies(true);
    return;
  }

  if (tab === 'purchases') {
    let packages = await window.api.packages.getAll();
    if (q) packages = packages.filter(p => `${p.name} ${p.lname}`.toLowerCase().includes(q));

    let html = `${accountCustomerTabsHtml(tab, search)}<div class="table-card tbl-responsive customer-sales-table">
      <div class="table-header"><span class="title">🛒 تاریخچه کل فروش ها (${fa(packages.length)} مورد)</span><button class="btn btn-primary btn-sm payment-header-add" title="افزودن خرید" onclick="openGeneralPurchaseModal()">+</button></div>
      <table>
        <thead><tr><th>${META.entitySingular||'شاگرد'}</th><th>نوع خرید</th><th>مجری</th><th>مبلغ کل</th><th>شروع / سررسید پرداخت</th><th>تکرار</th><th>توضیحات</th><th>عملیات</th></tr></thead>
        <tbody>`;
    if (packages.length === 0) {
      html += `<tr><td colspan="8"><div class="empty"><span>🛒</span>خریدی ثبت نشده</div></td></tr>`;
    } else {
      packages.forEach(p => {
        const saleMenuId = `sale-menu-${p.id}`;
        html += `<tr>
          <td data-label="مشتری" style="font-weight:500">${escapeHtml(p.name)} ${escapeHtml(p.lname)}</td>
          <td><span class="tag" style="background:${p.pkg_color}22;color:${p.pkg_color}">${escapeHtml(p.type_label)}</span></td>
          <td style="font-size:11px;color:var(--text2)">${escapeHtml(p.staff_name||'—')}</td>
          <td><span class="amount amount-paid">${fmt(p.total_amount)} تومان</span></td>
          <td style="color:var(--text2)">
            <div>شروع: ${DateService.disp(p.start_date)||'—'}</div>
            <div style="font-size:10px;color:${_isPackageChargeable(p)?'var(--green)':'var(--amber)'};margin-top:2px">سررسید پرداخت: ${DateService.disp(p.payment_due_date||p.start_date)||'—'}${_isPackageChargeable(p)?'':' · آینده'}</div>
          </td>
          <td style="font-size:11px;color:var(--text2)">${p.repeat_months>0?`هر ${fa(p.repeat_months)} ماه`:'یک‌بار'}</td>
          <td style="font-size:11px;color:var(--text3)">${escapeHtml(p.note||'')}</td>
          <td data-label="عملیات">
            <div class="row-menu">
              <button class="row-menu-btn" type="button" aria-label="عملیات فروش ${escapeHtml(`${p.name} ${p.lname}`.trim())}" aria-haspopup="menu" onclick="toggleRowMenu(event,'${saleMenuId}')">⋮</button>
              <div class="row-menu-panel" id="${saleMenuId}" role="menu">
                <div class="row-menu-item" role="menuitem" onclick="openEditPackage(${p.id})">✏️ ویرایش فروش</div>
                <div class="row-menu-divider"></div>
                <div class="row-menu-item danger" role="menuitem" onclick="deletePackage(${p.id})">🗑 حذف فروش</div>
              </div>
            </div>
          </td>
        </tr>`;
      });
    }
    html += `</tbody></table></div>`;
    setContent(html);

  } else if (tab === 'payments') {
    const allPayments = await window.api.payments.getAll();
    let payments = allPayments;
    if (q) payments = payments.filter(p => `${p.name} ${p.lname}`.toLowerCase().includes(q));

    let html = `${accountCustomerTabsHtml(tab, search)}<div class="table-card tbl-responsive customer-payments-table">
      <div class="table-header"><span class="title">💳 تاریخچه دریافت‌ها (${fa(payments.length)} مورد)</span><button class="btn btn-primary btn-sm payment-header-add" title="افزودن دریافت" onclick="openGeneralPaymentModal()">+</button></div>
      <table>
        <thead><tr><th>${META.entitySingular||'شاگرد'}</th><th>پکیج</th><th>مبلغ</th><th>تاریخ</th><th>واریز به حساب</th><th>مانده حساب</th><th>یادداشت</th><th>عملیات</th></tr></thead>
        <tbody>`;
    if (payments.length === 0) {
      html += `<tr><td colspan="8"><div class="empty"><span>💳</span>پرداختی ثبت نشده</div></td></tr>`;
    } else {
      payments.forEach(p => {
        const student = allStudents.find(s => s.id === p.student_id);
        html += `<tr>
          <td data-label="مشتری" style="font-weight:500"><button class="btn btn-ghost btn-sm" style="padding:0;border:0;background:none" onclick="openStudentDetail(${p.student_id})">${escapeHtml(p.name)} ${escapeHtml(p.lname)}</button></td>
          <td data-label="پکیج"><span class="tag" style="background:${p.pkg_color}22;color:${p.pkg_color}">${escapeHtml(p.pkg_label)}</span></td>
          <td data-label="مبلغ"><span class="amount amount-paid">${fmt(p.amount)} ${escapeHtml(p.currency||'تومان')}</span></td>
          <td data-label="تاریخ" style="color:var(--text2)">${DateService.disp(p.date_jalali)}</td>
          <td data-label="واریز به حساب" style="font-size:11px;color:${p.account_label?'var(--accent2)':'var(--text3)'}">${escapeHtml(p.account_label||'ثبت نشده')}</td>
          <td data-label="مانده حساب">${student ? balanceHtml(student.balance) : '—'}</td>
          <td data-label="یادداشت" style="color:var(--text3);font-size:11px">${escapeHtml(p.note||'')}${p.method?` (${escapeHtml(p.method)})`:''}</td>
          <td data-label="عملیات">
            <div class="row-menu">
              <button class="row-menu-btn" type="button" aria-label="عملیات دریافت ${escapeHtml(`${p.name} ${p.lname}`.trim())}" aria-haspopup="menu" onclick="toggleRowMenu(event,'payment-menu-${p.id}')">⋮</button>
              <div class="row-menu-panel" id="payment-menu-${p.id}" role="menu">
                <div class="row-menu-item" role="menuitem" onclick="openEditPayment(${p.id})">✏️ ویرایش دریافت</div>
                <div class="row-menu-divider"></div>
                <div class="row-menu-item danger" role="menuitem" onclick="deletePayment(${p.id}, 'payments')">🗑 حذف دریافت</div>
              </div>
            </div>
          </td>
        </tr>`;
      });
    }
    html += `</tbody></table></div>`;
    setContent(html);
  } else {
    await renderReminders(search, true, accountCustomerTabsHtml(tab, search));
  }

  if (search) {
    requestAnimationFrame(() => {
      const sp = document.querySelector('#topbar-actions .table-search input') ||
                 document.querySelector('.table-search input');
      if (sp) { sp.focus(); try { sp.setSelectionRange(search.length, search.length); } catch(e){} }
    });
  }
}

// ════════════════════════════════════════════════════════════════════════════
// SESSIONS PAGE
// ════════════════════════════════════════════════════════════════════════════
async function renderSessions(search = '') {
  const prevScroll = document.getElementById('sessions-board')?.scrollLeft || 0;
  updateTopbarActions(`
    <div class="table-search stu-topbar-search" style="margin-left:8px">
      <span class="search-toggle-icon" style="color:var(--text3)">🔍</span>
      <input placeholder="جستجوی ${META.entitySingular||'شاگرد'}..." oninput="renderSessions(this.value)" value="${escapeHtml(search)}">
    </div>
    <div style="display:flex;align-items:stretch;border:1px solid var(--border2);border-radius:12px;overflow:hidden;background:var(--bg2);flex-shrink:0">
      <button class="btn btn-primary" onclick="openAddSessionGeneral()" style="border-radius:0;border:none;box-shadow:none">+ ثبت ${META.sessionSingular || 'جلسه'}</button>
      <button class="btn btn-ghost" onclick="openStudentModal()" style="border-radius:0;border:0;border-right:1px solid var(--border2)">+ افزودن ${META.entitySingular || 'شاگرد'}</button>
    </div>
  `);
  allStudents = await window.api.students.getAll();
  const groups = await window.api.sessions.getAll();
  const keyOnes = await window.api.sessions.keyOnes();

  let html = studentSectionNav('sessions');

  // ── Board: students as vertical columns, in stable user-defined order ────
  const savedOrder = await window.api.sessions.getOrder();
  let groupsSorted;
  if (savedOrder && savedOrder.length) {
    const byId = new Map(groups.map(g => [g.student_id, g]));
    groupsSorted = savedOrder.map(id => byId.get(id)).filter(Boolean);
    groups.forEach(g => { if (!savedOrder.includes(g.student_id)) groupsSorted.push(g); });
  } else {
    groupsSorted = groups.slice();
  }

  if (search) {
    groupsSorted = groupsSorted.filter(g => (g.name + g.lname).includes(search));
  }

  if (groupsSorted.length === 0) {
    setContent(html + `<div class="empty"><span>🔍</span>چیزی پیدا نشد</div>`);
    return;
  }

  // Compute open followup counts per student
  const followupCounts = {};
  groupsSorted.forEach(g => {
    let openCount = 0;
    g.sessions.forEach(s => { (s.followups||[]).forEach(f => { if (!f.done) openCount++; }); });
    followupCounts[g.student_id] = openCount;
  });

  html += `<div class="sessions-board" id="sessions-board">`;
  groupsSorted.forEach(g => {
    const openFU = followupCounts[g.student_id] || 0;
    html += `
    <div class="session-column" draggable="true" data-student-id="${g.student_id}">
      <div class="session-column-header">
        <span class="scn-name" style="cursor:move" title="برای تغییر ترتیب، بکش و رها کن">⠿ ${escapeHtml(g.name)} ${escapeHtml(g.lname)}</span>
        <span class="scn-count">(${fa(g.sessions.length)})</span>
        ${openFU > 0 ? `<span title="اقدامات باز" onclick="openStudentFollowups(${g.student_id}, ${escapeAttr((g.name) + ' ' + (g.lname))})" style="cursor:pointer;background:rgba(251,191,36,.15);color:var(--amber);border-radius:20px;padding:2px 8px;font-size:11px;font-weight:700">📌 ${fa(openFU)}</span>` : ''}
        <button class="archive-btn" title="انتقال به بایگانی" onclick="archiveStudent(${g.student_id}, ${escapeAttr((g.name) + ' ' + (g.lname))})">📦 بایگانی این ${META.entitySingular||'شاگرد'}</button>
        <button class="topics-btn" onclick="openTopics(${g.student_id}, ${escapeAttr((g.name) + ' ' + (g.lname))})">📌 موضوعات مهم</button>
        <button class="key-events-btn" onclick="openKeyEvents(${g.student_id}, ${escapeAttr((g.name) + ' ' + (g.lname))})">🌟 رویدادهای مهم</button>
        <button class="summary-btn" onclick="openSessionsSummary(${g.student_id}, ${escapeAttr((g.name) + ' ' + (g.lname))})">📋 خلاصه کل ${META.sessionPlural||'جلسات'}</button>
        <button class="eval-btn" onclick="openEvaluation(${g.student_id}, ${escapeAttr((g.name) + ' ' + (g.lname))})">📊 ارزیابی عملکرد</button>
        <button class="session-column-add" onclick="openAddSessionGeneral(${g.student_id})">+ افزودن ${META.sessionSingular||'جلسه'}</button>
      </div>
      <div class="session-column-body">
        ${g.sessions.length === 0
          ? `<div class="empty" style="padding:14px;font-size:11px"><span>📅</span>هنوز ${META.sessionSingular||'جلسه'}‌ای ثبت نشده</div>`
          : g.sessions.map(s => `
          <div class="session-card ${s.importance==='key' ? 'key' : ''}" onclick="openSessionDetail(${s.id})">
            <div class="sc-date">${s.importance==='key' ? '⭐ ' : ''}${DateService.disp(s.date_jalali)} <span style="color:var(--text3);font-weight:400">(${jalaliWeekdayName(s.date_jalali)})</span></div>
            <div class="sc-title">${escapeHtml(s.title) || '(بدون عنوان)'}</div>
            ${s.note ? `<div class="sc-excerpt">${renderRich(excerpt(s.note, 60))}</div>` : ''}
          </div>`).join('')}
      </div>
    </div>`;
  });
  html += `</div>`;

  // ── Key sessions summary — horizontal scroll AFTER board ──────────────
  if (!search && keyOnes.length > 0) {
    html += `
    <div class="detail-section key-sessions-panel" id="key-sessions-panel" style="border-color:var(--amber);margin-top:24px;background:linear-gradient(135deg,var(--bg2) 0%,rgba(251,191,36,.05) 100%)">
      <button class="key-sessions-toggle" onclick="toggleKeySessionsPanel()" aria-expanded="${_keySessionsExpanded ? 'true' : 'false'}">
        <span>⭐ نکات مهم و کلیدی</span>
        <span class="key-sessions-count">${fa(keyOnes.length)} مورد</span>
        <span class="key-sessions-arrow">${_keySessionsExpanded ? '−' : '+'}</span>
      </button>
      <div class="key-sessions-row" id="key-sessions-row" style="${_keySessionsExpanded ? '' : 'display:none'}">
        ${_keySessionsExpanded ? keyOnes.map(s => `
          <div class="key-session-card" onclick="openSessionDetail(${s.id})">
            <div class="ks-top">
              <span class="ks-name">${escapeHtml(s.name)} ${escapeHtml(s.lname)}</span>
              <span class="ks-date">${DateService.disp(s.date_jalali)}</span>
            </div>
            <div class="ks-title">${escapeHtml(s.title) || '(بدون عنوان)'}</div>
            <div class="ks-excerpt">${renderRich(excerpt(s.note))}</div>
          </div>`).join('') : ''}
      </div>
    </div>`;
  }

  setContent(html || `<div class="empty"><span>📅</span>${META.entitySingular||'شاگردی'} ثبت نشده</div>`);
  if (!search) initSessionsDragDrop();

  const board = document.getElementById('sessions-board');
  if (board) board.scrollLeft = prevScroll;
  if (!search && !_keySessionsExpanded) {
    requestAnimationFrame(() => {
      const contentEl = document.getElementById('content');
      if (contentEl) contentEl.scrollTop = 0;
    });
  }

  if (search) {
    requestAnimationFrame(() => {
      const si = document.querySelector('#topbar-actions .table-search input') ||
                 document.querySelector('.table-search input');
      if (si) { si.focus(); try { si.setSelectionRange(search.length, search.length); } catch(e){} }
    });
  }
}

function toggleKeySessionsPanel() {
  _keySessionsExpanded = !_keySessionsExpanded;
  renderSessions().then(() => {
    if (!_keySessionsExpanded) return;
    requestAnimationFrame(() => {
      const panel = document.getElementById('key-sessions-panel');
      if (!panel) return;
      panel.setAttribute('tabindex', '-1');
      panel.focus({ preventScroll: true });
      panel.scrollIntoView({ behavior: 'smooth', block: 'start', inline: 'nearest' });
    });
  });
}

function initSessionsDragDrop() {
  const board = document.getElementById('sessions-board');
  if (!board) return;
  let dragEl = null;

  board.querySelectorAll('.session-column').forEach(col => {
    col.addEventListener('dragstart', () => {
      dragEl = col;
      col.style.opacity = '0.4';
    });
    col.addEventListener('dragend', () => {
      col.style.opacity = '';
      saveSessionsOrder();
    });
    col.addEventListener('dragover', (e) => {
      e.preventDefault();
      if (!dragEl || dragEl === col) return;
      const rect = col.getBoundingClientRect();
      const before = (e.clientX - rect.left) < rect.width / 2;
      board.insertBefore(dragEl, before ? col : col.nextSibling);
    });
  });
}

async function saveSessionsOrder() {
  const board = document.getElementById('sessions-board');
  if (!board) return;
  const order = [...board.querySelectorAll('.session-column')].map(el => +el.dataset.studentId);
  await window.api.sessions.setOrder(order);
}

function toggleSessionGroup(studentId) {
  if (openSessionGroups.has(studentId)) openSessionGroups.delete(studentId);
  else openSessionGroups.add(studentId);
  document.getElementById(`sg-${studentId}`)?.classList.toggle('collapsed');
}

async function deleteSession(sessionId) {
  if (!confirm(`این ${META.sessionSingular||'جلسه'} حذف شود؟`)) return;
  await window.api.sessions.delete(sessionId);
  showToast('حذف شد', 'error');
  await renderSessions();
}

function _parseSessionCaseForm(content) {
  const lines = String(content || '').replace(/\r/g, '').split('\n');
  const items = [];
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i].trim();
    if (!raw) continue;
    const heading = raw.match(/^#{1,6}\s+(.+)$/);
    if (heading) { items.push({ type:'heading', label:heading[1].trim() }); continue; }
    const check = raw.match(/^(?:[-+*]\s+)?\[[ xX]\]\s+(.+)$/);
    if (check) {
      const label = check[1].trim();
      if (/[:：]\s*$/.test(label)) items.push({ type:'text', label:label.replace(/[:：]\s*$/,'').trim() });
      else items.push({ type:'check', label });
      continue;
    }
    const field = raw.match(/^([^:：]{1,100})[:：]\s*(.*)$/);
    if (field) {
      const label = field[1].trim();
      const answer = field[2].trim();
      const next = String(lines[i + 1] || '').trim();
      if (!answer && /^[.…·_ـ-]{3,}$/.test(next)) { items.push({ type:'textarea', label }); i++; continue; }
      if (!answer && !next) { items.push({ type:'text', label }); continue; }
      if (!answer && next && !/^#{1,6}\s+/.test(next) && !/^(?:[-+*]\s+)?\[[ xX]\]/.test(next)) {
        items.push({ type:'guide', label:`${label}: ${next}` }); i++; continue;
      }
      if (!answer) { items.push({ type:'text', label }); continue; }
      items.push({ type:'guide', label:`${label}: ${answer}` });
      continue;
    }
    if (/^[.…·_ـ-]{3,}$/.test(raw)) continue;
    items.push({ type:'guide', label:raw.replace(/^[-+*]\s+/, '') });
  }
  return items.map((item, index) => ({ ...item, key:index + 1 }));
}

function _sessionCaseFormOptions(selectedId) {
  return `<option value="">— بدون فرم —</option>` + (_db.case_forms || []).map(form =>
    `<option value="${form.id}" ${+selectedId===+form.id?'selected':''}>${escapeHtml(form.title)}</option>`
  ).join('');
}

function _sessionCaseFormFieldsHtml(formId, responses = [], sessionId = null) {
  const form = (_db.case_forms || []).find(item => +item.id === +formId);
  if (!form) return '';
  const saved = new Map((responses || []).map(item => [String(item.key), item]));
  return `<div style="padding:12px;border:1px solid var(--border);border-radius:10px;background:var(--bg2)">
    <div style="font-size:12px;font-weight:700;color:var(--text);margin-bottom:10px">${escapeHtml(form.title)}</div>
    ${_parseSessionCaseForm(form.content).map(item => {
      const value = saved.get(String(item.key));
      if (item.type === 'heading') return `<h4 style="font-size:13px;color:var(--text);margin:16px 0 8px">${escapeHtml(item.label)}</h4>`;
      if (item.type === 'guide') return `<div style="font-size:11px;color:var(--text2);line-height:1.8;margin:7px 0">${escapeHtml(item.label)}</div>`;
      if (item.type === 'check') return `<label style="display:flex;align-items:center;gap:9px;padding:9px 10px;margin:6px 0;background:var(--bg3);border:1px solid var(--border);border-radius:8px;cursor:pointer"><input class="session-case-response" data-key="${item.key}" data-type="check" data-label="${escapeHtml(item.label)}" type="checkbox" ${value?.checked?'checked':''} ${sessionId?`onchange="_saveSessionCaseResponse(${sessionId},this)"`:''} style="width:18px;height:18px;accent-color:var(--accent2);cursor:pointer;flex-shrink:0"><span style="font-size:12px;color:var(--text);${value?.checked?'text-decoration:line-through;color:var(--text3)':''}">${escapeHtml(item.label)}</span></label>`;
      const textarea = item.type === 'textarea';
      return `<div class="form-group full" style="margin:9px 0"><label class="form-label">${escapeHtml(item.label)}</label>${textarea
        ? `<textarea class="form-textarea session-case-response" data-key="${item.key}" data-type="textarea" data-label="${escapeHtml(item.label)}" rows="3" placeholder="اینجا بنویسید..." ${sessionId?`oninput="_saveSessionCaseResponse(${sessionId},this)"`:''}>${escapeHtml(value?.value||'')}</textarea>`
        : `<input class="form-input session-case-response" data-key="${item.key}" data-type="text" data-label="${escapeHtml(item.label)}" value="${escapeHtml(value?.value||'')}" placeholder="اینجا بنویسید..." ${sessionId?`oninput="_saveSessionCaseResponse(${sessionId},this)"`:''}>`}</div>`;
    }).join('')}
  </div>`;
}

function _onSessionCaseFormChange(select) {
  const container = document.getElementById('session-case-form-fields');
  if (container) container.innerHTML = select.value ? _sessionCaseFormFieldsHtml(+select.value) : '';
}

function _collectSessionCaseForm() {
  const select = document.getElementById('f-ses-case-form');
  const formId = +(select?.value || 0);
  const form = (_db.case_forms || []).find(item => +item.id === formId);
  const responses = [...document.querySelectorAll('.session-case-response')].map(control => ({
    key:+control.dataset.key,
    type:control.dataset.type,
    label:control.dataset.label || '',
    ...(control.type === 'checkbox' ? { checked:control.checked } : { value:control.value })
  }));
  return { case_form_id:formId || null, case_form_title:form?.title || '', case_form_responses:responses };
}

function _sessionCaseFormReadOnlyHtml(session) {
  if (!session.case_form_id) return '';
  return `<div class="detail-section"><h3>فرم جلسه</h3>${_sessionCaseFormFieldsHtml(session.case_form_id,session.case_form_responses||[],session.id)}</div>`;
}

function _saveSessionCaseResponse(sessionId, control) {
  const session = (_db.sessions || []).find(item => +item.id === +sessionId);
  if (!session) return;
  session.case_form_responses = session.case_form_responses || [];
  const key = +control.dataset.key;
  let response = session.case_form_responses.find(item => +item.key === key);
  if (!response) {
    response = { key, type:control.dataset.type, label:control.dataset.label || '' };
    session.case_form_responses.push(response);
  }
  if (control.type === 'checkbox') {
    response.checked = control.checked;
    const label = control.nextElementSibling;
    if (label) label.style.cssText = control.checked ? 'font-size:12px;text-decoration:line-through;color:var(--text3)' : 'font-size:12px;color:var(--text)';
  } else response.value = control.value;
  clearTimeout(control._sessionFormSaveTimer);
  control._sessionFormSaveTimer = setTimeout(() => _save(), 400);
}

function _interactiveSessionNoteHtml(session) {
  const note = String(session.note || '');
  if (!note) return '<span style="color:var(--text3)">—</span>';
  const sourceId = `session-note-source-${session.id}`;
  return `<textarea id="${sourceId}" aria-hidden="true" tabindex="-1" style="display:none" oninput="_saveInteractiveSessionNote(${session.id},this.value)">${escapeHtml(note)}</textarea>
    <div style="font-size:13px;color:var(--text);line-height:1.9">${renderRich(note,{interactive:true,textareaId:sourceId})}</div>`;
}

function _saveInteractiveSessionNote(sessionId, value) {
  const session = (_db.sessions || []).find(item => +item.id === +sessionId);
  if (!session) return;
  session.note = value;
  clearTimeout(window._interactiveSessionNoteSaveTimer);
  window._interactiveSessionNoteSaveTimer = setTimeout(() => {
    _save();
    showToast('پاسخ فرم ذخیره شد ✓', 'success');
  }, 450);
}

async function openSessionDetail(sessionId) {
  const groups = await window.api.sessions.getAll();
  let session = null, student = null;
  for (const g of groups) {
    const found = g.sessions.find(s => s.id === sessionId);
    if (found) { session = found; student = g; break; }
  }
  if (!session) return;

  openModal(`${escapeHtml(student.name)} ${escapeHtml(student.lname)} — ${DateService.disp(session.date_jalali)}`, `
    <div class="detail-section">
      ${session.importance==='key' ? '<p style="color:var(--amber);font-weight:700;margin-bottom:8px">⭐ نکته مهم و کلیدی</p>' : ''}
      <div class="detail-row"><span class="detail-key">عنوان</span><span class="detail-val">${escapeHtml(session.title) || '—'}</span></div>
      <div class="detail-row"><span class="detail-key">تاریخ</span><span class="detail-val">${DateService.disp(session.date_jalali)} (${jalaliWeekdayName(session.date_jalali)})</span></div>
      <div class="detail-row"><span class="detail-key">اهمیت</span><span class="detail-val">${session.importance==='key' ? 'مهم و کلیدی' : 'معمولی'}</span></div>
    </div>
    <div class="detail-section">
      <h3>توضیحات کامل</h3>
      ${_interactiveSessionNoteHtml(session)}
    </div>
    ${session.extra_note ? `
    <div class="detail-section">
      <h3>توضیحات تکمیلی</h3>
      <p style="font-size:13px;color:var(--text);line-height:1.9">${renderRich(session.extra_note)}</p>
    </div>` : ''}
    ${_sessionCaseFormReadOnlyHtml(session)}
    ${(session.followups && session.followups.length > 0) ? `
    <div class="detail-section">
      <h3>📌 اقدامات تا جلسه بعد</h3>
      <div>
        ${session.followups.map(f => `
          <label style="display:flex;align-items:center;gap:8px;padding:6px 0;cursor:pointer;border-bottom:1px solid var(--border)">
            <input type="checkbox" ${f.done?'checked':''} onchange="toggleFollowupFromDetail(${sessionId}, ${f.id}, this)" style="width:16px;height:16px;accent-color:var(--accent2);cursor:pointer;flex-shrink:0">
            <span style="${f.done?'text-decoration:line-through;color:var(--text3)':'color:var(--text)'};font-size:13px;flex:1">${escapeHtml(f.text)}</span>
            ${f.done?'<span style="font-size:11px;color:var(--green)">✓ انجام شد</span>':''}
          </label>`).join('')}
      </div>
    </div>` : ''}
    ${session.achievements ? `
    <div class="detail-section">
      <h3>🌱 پیشرفت‌ها و دستاوردهای مشاهده‌شده</h3>
      <p style="font-size:13px;color:var(--text);line-height:1.9">${renderRich(session.achievements)}</p>
      ${_achievementPeriodBadge(session)}
    </div>` : ''}
    <div class="detail-section">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
        <h3>📎 پیوست‌ها</h3>
        <button class="btn btn-ghost btn-sm" onclick="_triggerAttach('session',${sessionId})">+ افزودن فایل</button>
      </div>
      ${(session.attachments||[]).length === 0
        ? '<p style="font-size:12px;color:var(--text3)">هنوز پیوستی اضافه نشده</p>'
        : renderSessionAttachments(sessionId, session.attachments||[])}
    </div>
  `, [
    { label: '✏️ ویرایش', cls: 'btn-primary', action: `closeModal();openEditSession(${sessionId})`, style: 'min-width:160px;font-size:14px;padding:12px 28px;box-shadow:0 4px 16px rgba(124,106,247,.45)' },
    { label: 'بستن', cls: 'btn-ghost', action: 'closeModal()', style: 'opacity:.85;font-size:11px;padding:7px 12px;box-shadow:none' },
    { label: '🗑 حذف', cls: 'btn-danger', action: `closeModal();deleteSession(${sessionId})`, style: 'margin-left:auto' },
  ], { fullPage: true, overlayClass: 'session-form-detail-modal' });
  setTimeout(() => _bindInteractiveSessionMobileFocus(), 0);
}

function _bindInteractiveSessionMobileFocus() {
  const body = document.querySelector('.session-form-detail-modal .modal-body');
  if (!body || body.dataset.mobileFocusBound === '1') return;
  body.dataset.mobileFocusBound = '1';
  body.addEventListener('focusin', event => {
    if (!event.target.matches('input,textarea,select')) return;
    setTimeout(() => event.target.scrollIntoView({ block:'center', behavior:'smooth' }), 260);
  });
}

async function openStudentFollowups(studentId, displayName) {
  const openFU = await window.api.sessions.getOpenFollowups(studentId);
  const itemsHtml = openFU.length === 0
    ? '<div style="text-align:center;padding:20px;color:var(--text3);font-size:12px">همه اقدامات انجام شده‌اند 🎉</div>'
    : openFU.map(f => `
      <label style="display:flex;align-items:center;gap:8px;padding:8px 10px;background:var(--bg3);border-radius:8px;margin-bottom:6px;cursor:pointer">
        <input type="checkbox" onchange="toggleFollowupAndRefresh(${studentId}, ${escapeAttr(displayName)}, ${f.session_id}, ${f.id}, this)" style="width:17px;height:17px;accent-color:var(--green);cursor:pointer;flex-shrink:0">
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;color:var(--text)">${escapeHtml(f.text)}</div>
          <div style="font-size:10px;color:var(--text3);margin-top:2px">از جلسه ${f.session_date}</div>
        </div>
      </label>`).join('');

  openModal(`📌 اقدامات باز — ${escapeHtml(displayName)}`, `
    <div style="margin-bottom:10px;font-size:12px;color:var(--text2)">
      ${fa(openFU.length)} مورد هنوز انجام نشده
    </div>
    <div>${itemsHtml}</div>
  `, [
    { label: 'بستن', cls: 'btn-primary', action: 'closeModal()' },
  ]);
}

async function toggleFollowupAndRefresh(studentId, displayName, sessionId, itemId, checkbox) {
  await window.api.sessions.toggleFollowup({ session_id: sessionId, item_id: itemId });
  showToast('✅ انجام شد', 'success');
  // after a short delay refresh the list
  setTimeout(() => openStudentFollowups(studentId, displayName), 300);
}

async function toggleFollowupFromDetail(sessionId, itemId, checkbox) {
  await window.api.sessions.toggleFollowup({ session_id: sessionId, item_id: itemId });
  const label = checkbox.nextElementSibling;
  if (label) label.style.cssText = checkbox.checked ? 'text-decoration:line-through;color:var(--text3);font-size:13px;flex:1' : 'color:var(--text);font-size:13px;flex:1';
  showToast(checkbox.checked ? '✅ انجام شد' : 'بازگشت به باز', 'success');
}

async function _buildPreSessionSummary(studentId, excludeSessionId = null) {
  if (!studentId) return '';
  const openFU = await window.api.sessions.getOpenFollowups(studentId);
  const recentAch = await window.api.sessions.getRecentAchievements(studentId);
  const groups = await window.api.sessions.getAll();
  const g = groups.find(x => x.student_id === studentId);
  const gSessions = g ? g.sessions.filter(s => s.id !== excludeSessionId) : [];
  const lastSession = gSessions.length ? gSessions[0] : null;
  if (!openFU.length && !recentAch.length && !lastSession) return '';

  const _sec = (icon, label, badge, badgeColor, contentHtml) => `
    <div style="padding:10px 14px 12px">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
        <span style="font-size:14px">${icon}</span>
        <span style="font-size:12px;font-weight:600;color:var(--text);flex:1">${label}</span>
        ${badge ? `<span style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px;background:${badgeColor}22;color:${badgeColor}">${badge}</span>` : ''}
      </div>
      ${contentHtml}
    </div>`;

  let sections = '';

  if (lastSession) {
    const lastNote = lastSession.note ? `<div style="font-size:11px;color:var(--text2);line-height:1.7;margin-top:6px;background:var(--bg3);border-radius:6px;padding:8px 10px">${escapeHtml(excerpt(lastSession.note, 200))}</div>` : '<div style="font-size:11px;color:var(--text3)">یادداشتی ثبت نشده</div>';
    sections += _sec('📄', `جلسه قبل — ${DateService.disp(lastSession.date_jalali)}`, lastSession.title ? excerpt(lastSession.title,20) : '', 'var(--text3)', lastNote);
  }

  if (openFU.length > 0) {
    const fuContent = openFU.slice(0,5).map(f =>
      `<div style="display:flex;align-items:center;gap:6px;font-size:11px;color:var(--text2);padding:4px 0;border-bottom:1px solid var(--border)"><span style="color:var(--text3);flex-shrink:0">☐</span><span>${escapeHtml(f.text)}</span></div>`
    ).join('') + (openFU.length > 5 ? `<div style="font-size:10px;color:var(--text3);margin-top:4px">و ${fa(openFU.length-5)} مورد دیگر...</div>` : '');
    sections += _sec('📌', 'اقدامات باز', `${fa(openFU.length)} مورد`, 'var(--amber)', fuContent);
  }

  if (recentAch.length > 0) {
    const achContent = recentAch.slice(0,3).map(a =>
      `<div style="display:flex;align-items:flex-start;gap:6px;font-size:11px;color:var(--text2);padding:4px 0;border-bottom:1px solid var(--border)"><span style="color:var(--green);flex-shrink:0">✔</span><span>${escapeHtml(excerpt(a.text, 80))}</span></div>`
    ).join('');
    sections += _sec('🌱', 'آخرین دستاوردها', `${fa(recentAch.length)} مورد`, 'var(--green)', achContent);
  }

  return `<div class="ses-presummary-box" id="ses-presummary-box">
    <button type="button" class="ses-presummary-toggle" onclick="_togglePreSummaryBox()">
      <span style="font-size:11px;font-weight:700;color:var(--accent2)">📋 خلاصه قبل از جلسه</span>
      <span class="ses-presummary-arrow" id="ses-presummary-arrow">▶</span>
    </button>
    <div class="ses-presummary-body" id="ses-presummary-body" style="display:none">
      ${sections}
    </div>
  </div>`;
}

function _togglePreSummaryBox() {
  const body = document.getElementById('ses-presummary-body');
  const arrow = document.getElementById('ses-presummary-arrow');
  if (!body) return;
  const open = body.style.display !== 'none';
  body.style.display = open ? 'none' : 'block';
  if (arrow) arrow.style.transform = open ? '' : 'rotate(90deg)';
}

async function openAddSessionGeneral(presetStudentId = null) {
  if (!allStudents.length) { showToast(`ابتدا ${META.entitySingular||'شاگرد'} اضافه کنید`, 'error'); return; }
  _resetSessionTimer();
  const initStudentId = presetStudentId || allStudents[0]?.id || null;
  const opts = allStudents.map(s => `<option value="${s.id}" ${s.id===initStudentId?'selected':''}>${escapeHtml(s.name)} ${escapeHtml(s.lname)}</option>`).join('');
  const initStudent = allStudents.find(s => s.id === initStudentId);
  const preSummary = initStudentId ? await _buildPreSessionSummary(initStudentId) : '';

  const title = `ثبت ${META.sessionSingular || 'جلسه'}${initStudent ? `<div id="ses-modal-subtitle" style="font-size:11px;font-weight:500;color:var(--text3);margin-top:2px">${META.entitySingular||'شاگرد'}: ${escapeHtml(initStudent.name)} ${escapeHtml(initStudent.lname)}</div>` : '<div id="ses-modal-subtitle" style="font-size:11px;font-weight:500;color:var(--text3);margin-top:2px"></div>'}`;

  openModal(title, `
    <!-- ── خلاصه قبل از جلسه (Accordion) ─────────────────────────────── -->
    <div id="ses-presummary-container">${preSummary}</div>

    <!-- ── نوار اطلاعات جلسه: شاگرد/تاریخ/اهمیت (Context، نه محتوای اصلی) ── -->
    <div class="ses-meta-bar">
      <button type="button" class="ses-meta-toggle" onclick="_toggleSesMeta()">
        <span class="ses-meta-summary" id="ses-meta-summary"></span>
      </button>
      <div class="ses-meta-body" id="ses-meta-body">
        <div class="meta-row" id="meta-student-static-row" style="${presetStudentId ? '' : 'display:none'}">
          <span class="meta-icon">👤</span>
          <span class="meta-student-static" id="ses-meta-student-static">${initStudent ? escapeHtml(initStudent.name + ' ' + initStudent.lname) : ''}</span>
          <button type="button" class="meta-change-link" onclick="_toggleSesStudentEdit()">✏️ تغییر</button>
        </div>
        <div class="meta-row" id="meta-student-select-row" style="${presetStudentId ? 'display:none' : 'display:flex'}">
          <span class="meta-icon">👤</span>
          <select class="form-select" id="f-ses-student" onchange="_onSesStudentChangeRebuildPeriods(this)">${opts}</select>
        </div>
        <div class="meta-row">
          <span class="meta-icon">📅</span>
          <input class="form-input jdate" id="f-ses-date" value="${formatJalali(...todayJalali())}" oninput="_updateSesPeriodBadge();_updateSesMetaSummary()" onchange="_updateSesPeriodBadge();_updateSesMetaSummary()">
        </div>
        <div class="meta-row">
          <span class="meta-icon">🏷️</span>
          <div class="seg-sm" id="f-ses-importance-seg">
            <button type="button" data-val="normal" class="active" onclick="_setImportanceSeg('normal')">🟢 معمولی</button>
            <button type="button" data-val="key" onclick="_setImportanceSeg('key')">⭐ مهم</button>
          </div>
          <input type="hidden" id="f-ses-importance" value="normal">
        </div>
      </div>
    </div>

    <div class="form-grid">

      <!-- ── اطلاعات اصلی ──────────────────────────────────────────────── -->
      <div class="form-group full">
        <div class="ses-title-head">
          <label class="form-label ses-title-label">📝 عنوان جلسه</label>
          <button type="button" class="ses-timer" id="ses-form-timer" onclick="_toggleSessionTimer()" aria-label="شروع تایمر جلسه" title="شروع یا توقف تایمر جلسه">
            <span class="ses-timer-icon" id="ses-timer-icon">▶</span>
            <span class="ses-timer-time" id="ses-timer-time">00:00</span>
          </button>
        </div>
        <input class="form-input ses-title-input" id="f-ses-title" placeholder="مثلاً: بررسی اهداف سه‌ماهه" style="padding:13px 14px">
      </div>

      <!-- ── محتوای جلسه ──────────────────────────────────────────────── -->
      <div class="form-group full session-note-wrap">
        <label class="form-label">توضیحات جلسه</label>
        ${richToolbar('f-ses-note')}
        <textarea class="form-textarea" id="f-ses-note" rows="4" placeholder="خلاصه جلسه، موضوع بحث، نکات گفته‌شده..." onpaste="pasteRichClipboard(event, 'f-ses-note')"></textarea>
      </div>

      <!-- ── پیگیری‌ها ─────────────────────────────────────────────────── -->
      <div class="form-group full" style="border-top:1px solid var(--border);padding-top:14px;margin-top:4px">
        <label class="form-label">📌 اقدامات تا جلسه بعد</label>
        <div id="ses-followup-list" style="margin-bottom:6px"></div>
        <div style="display:flex;gap:6px">
          <input class="form-input" id="f-ses-followup-input" placeholder="مثلاً: تماس با مشتری جدید..." style="flex:1" onkeydown="if(event.key==='Enter'){event.preventDefault();_addSesFollowupItem()}">
          <button type="button" class="btn btn-ghost" onclick="_addSesFollowupItem()">+ افزودن</button>
        </div>
      </div>

      <div class="form-group full">
        <label class="form-label">🌱 پیشرفت‌ها و دستاوردها</label>
        <textarea class="form-textarea" id="f-ses-achievements" rows="3" placeholder="پیشرفت‌های مشاهده‌شده، موفقیت‌ها، تغییرات مثبت..." data-no-voice></textarea>
        <div id="f-ses-period-badge" style="margin-top:8px;font-size:11px;color:var(--text3);line-height:1.8"></div>
        <div id="ses-ach-tags"></div>
      </div>

      <!-- ── تنظیمات بیشتر (Accordion) ────────────────────────────────── -->
      <div class="form-group full" style="border-top:1px solid var(--border);padding-top:4px;margin-top:4px">
        <button type="button" onclick="_toggleAdvSes()" id="f-ses-adv-btn"
          style="display:flex;align-items:center;gap:6px;padding:8px 0;background:none;border:none;cursor:pointer;font-family:var(--font);color:var(--text3);font-size:12px;width:100%">
          <span id="f-ses-adv-arrow" style="transition:transform .2s;font-size:10px">▶</span>
          <span>⋮ تنظیمات بیشتر</span>
        </button>
        <div id="f-ses-adv-body" style="display:none;padding-top:8px">
          <div class="form-group full" style="margin:0 0 12px">
            <button type="button" onclick="_toggleExtraNote()"
              style="display:flex;align-items:center;gap:7px;padding:9px 12px;width:100%;background:var(--bg3);border:1px solid var(--border);border-radius:8px;cursor:pointer;font-family:var(--font);color:var(--text2);font-size:12px;transition:all .15s">
              <span id="f-ses-extra-arrow" style="font-size:10px;transition:transform .2s">▶</span>
              <span style="font-weight:600">یادداشت‌های خصوصی</span>
              <span style="color:var(--text3);font-size:11px">(اختیاری)</span>
            </button>
            <div id="f-ses-extra-body" style="display:none;margin-top:6px">
              ${richToolbar('f-ses-extra')}
              <textarea class="form-textarea" id="f-ses-extra" rows="3" placeholder="نکات تکمیلی، یادداشت‌های اضافه..."></textarea>
            </div>
          </div>
          <div class="form-group full" style="flex-direction:row;align-items:center;gap:8px;padding:2px 0 12px;flex-wrap:nowrap;margin-top:0">
            <input type="checkbox" id="f-ses-add-topic" style="width:17px;height:17px;cursor:pointer;flex-shrink:0;margin:0">
            <label for="f-ses-add-topic" style="font-size:12px;cursor:pointer;margin:0">📌 این جلسه به‌عنوان "موضوع مهم" هم ثبت شود</label>
          </div>
          <div class="form-group full" style="margin-top:0">
            <label class="form-label">📎 پیوست‌ها</label>
            <div id="ses-attach-preview" style="margin-bottom:8px"></div>
            <button type="button" class="btn btn-ghost btn-sm" onclick="_pickSessionFiles()">📎 افزودن فایل یا عکس</button>
            <div id="ses-attach-count" style="font-size:11px;color:var(--text3);margin-top:4px"></div>
          </div>
          <div class="form-group full" style="margin:0 0 12px;padding:12px;background:var(--bg3);border:1px solid var(--border);border-radius:9px">
            <label class="form-label" for="f-ses-case-form">فرم پرونده در این جلسه</label>
            <select class="form-select" id="f-ses-case-form" onchange="_onSessionCaseFormChange(this)">${_sessionCaseFormOptions(null)}</select>
            <div id="session-case-form-fields" style="margin-top:10px"></div>
          </div>
      </div>
      </div>

    </div>
  `, [
    { label: 'ثبت جلسه', cls: 'btn-primary', action: `saveSessionGeneral()` },
    { label: 'انصراف', cls: 'btn-ghost', action: 'closeModal()' },
  ], { fullPage: true, overlayClass: 'session-editor-modal' });
  initDatePickers();
  window._pendingSessionAttachments = [];
  window._pendingFollowups = [];
  if (window.innerWidth > 768) setTimeout(() => document.getElementById('f-ses-title')?.focus(), 50);
  setTimeout(() => {
    const sid = initStudentId || +document.getElementById('f-ses-student')?.value;
    if (sid) _renderAchievementTagPicker(_primaryEvalFormId(sid), []);
    _updateSesPeriodBadge();
    _updateSesMetaSummary();
    _bindSessionTextareaVisibilityGuard();
  }, 0);
}

function _setImportanceSeg(val) {
  document.getElementById('f-ses-importance').value = val;
  const btns = document.querySelectorAll('#f-ses-importance-seg button');
  btns.forEach(b => b.classList.toggle('active', b.dataset.val === val));
  _updateSesMetaSummary();
}

function _toggleSesMeta() {
  const body = document.getElementById('ses-meta-body');
  const arrow = document.getElementById('ses-meta-arrow');
  if (!body) return;
  const open = body.classList.contains('open');
  body.classList.toggle('open', !open);
  if (arrow) arrow.style.transform = open ? '' : 'rotate(90deg)';
}

function _sesImportanceLabel(val) { return val === 'key' ? '⭐ مهم' : '🟢 معمولی'; }

function _updateSesMetaSummary() {
  const summaryEl = document.getElementById('ses-meta-summary');
  if (!summaryEl) return;
  const date = document.getElementById('f-ses-date')?.value || '';
  const importance = document.getElementById('f-ses-importance')?.value || 'normal';
  let studentLabel = '';
  const studentStatic = document.getElementById('ses-meta-student-static');
  if (studentStatic) {
    studentLabel = studentStatic.textContent.replace('👤 ', '').trim();
  } else {
    const sel = document.getElementById('f-ses-student');
    const opt = sel?.options[sel.selectedIndex];
    studentLabel = opt ? opt.textContent : '';
  }
  summaryEl.innerHTML = `
    ${studentLabel ? `<span>👤 ${escapeHtml(studentLabel)}</span><span class="dot">•</span>` : ''}
    <span>📅 ${date}</span><span class="dot">•</span>
    <span>${_sesImportanceLabel(importance)}</span>`;
}

function _toggleSesStudentEdit() {
  const staticEl = document.getElementById('meta-student-static-row');
  const editEl = document.getElementById('meta-student-select-row');
  if (!staticEl || !editEl) return;
  staticEl.style.display = 'none';
  editEl.style.display = 'flex';
  document.getElementById('f-ses-student')?.focus();
}

function _toggleExtraNote() {
  const body = document.getElementById('f-ses-extra-body');
  const arrow = document.getElementById('f-ses-extra-arrow');
  if (!body) return;
  const open = body.style.display !== 'none';
  body.style.display = open ? 'none' : 'block';
  if (arrow) arrow.style.transform = open ? '' : 'rotate(90deg)';
  if (!open) setTimeout(() => document.getElementById('f-ses-extra')?.focus(), 50);
}

let _sessionTimerInterval = null;
let _sessionTimerElapsed = 0;
let _sessionTimerStartedAt = 0;

function _renderSessionTimer() {
  const timeEl = document.getElementById('ses-timer-time');
  if (!timeEl) return;
  const total = _sessionTimerElapsed + (_sessionTimerInterval ? Math.floor((Date.now() - _sessionTimerStartedAt) / 1000) : 0);
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  timeEl.textContent = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function _toggleSessionTimer() {
  const button = document.getElementById('ses-form-timer');
  const icon = document.getElementById('ses-timer-icon');
  if (!button) return;
  if (_sessionTimerInterval) {
    _sessionTimerElapsed += Math.floor((Date.now() - _sessionTimerStartedAt) / 1000);
    clearInterval(_sessionTimerInterval);
    _sessionTimerInterval = null;
    button.classList.remove('running');
    button.setAttribute('aria-label', 'ادامه تایمر جلسه');
    if (icon) icon.textContent = '▶';
    _renderSessionTimer();
    return;
  }
  _sessionTimerStartedAt = Date.now();
  _sessionTimerInterval = setInterval(_renderSessionTimer, 250);
  button.classList.add('running');
  button.setAttribute('aria-label', 'توقف تایمر جلسه');
  if (icon) icon.textContent = 'Ⅱ';
  _renderSessionTimer();
}

function _resetSessionTimer() {
  if (_sessionTimerInterval) clearInterval(_sessionTimerInterval);
  _sessionTimerInterval = null;
  _sessionTimerElapsed = 0;
  _sessionTimerStartedAt = 0;
}

function _sessionTimerTotalSeconds() {
  return _sessionTimerElapsed + (_sessionTimerInterval
    ? Math.floor((Date.now() - _sessionTimerStartedAt) / 1000)
    : 0);
}

function _appendSessionTimerToNote(note) {
  const total = _sessionTimerTotalSeconds();
  const text = String(note || '').trimEnd();
  if (total <= 0) return text;
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  const durationLine = `مدت زمان جلسه: ${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  const withoutPreviousDuration = text.replace(/(?:\r?\n){0,2}مدت زمان جلسه:\s*\d+:\d+\s*$/u, '').trimEnd();
  return withoutPreviousDuration ? `${withoutPreviousDuration}\n\n${durationLine}` : durationLine;
}

function _bindSessionTextareaVisibilityGuard() {
  const ta = document.getElementById('f-ses-note');
  if (!ta || ta.dataset.visibilityGuard === '1') return;
  ta.dataset.visibilityGuard = '1';
  const keepCaretVisible = () => {
    if (!document.body.classList.contains('modal-keyboard-open')) return;
    requestAnimationFrame(() => {
      const nearEnd = ta.selectionStart >= Math.max(0, ta.value.length - 2);
      if (nearEnd) ta.scrollTop = ta.scrollHeight;
      const body = ta.closest('.modal-body');
      const wrap = ta.closest('.session-note-wrap');
      if (body && wrap) {
        const bodyRect = body.getBoundingClientRect();
        const wrapRect = wrap.getBoundingClientRect();
        const overflow = wrapRect.bottom - bodyRect.bottom + 10;
        if (overflow > 0) body.scrollTop += overflow;
      }
    });
  };
  ta.addEventListener('input', keepCaretVisible);
  ta.addEventListener('focus', keepCaretVisible);
  ta.addEventListener('keyup', keepCaretVisible);
}

function _toggleAdvSes() {
  const body = document.getElementById('f-ses-adv-body');
  const arrow = document.getElementById('f-ses-adv-arrow');
  if (!body) return;
  const open = body.style.display !== 'none';
  body.style.display = open ? 'none' : 'block';
  if (arrow) arrow.style.transform = open ? '' : 'rotate(90deg)';
}

function _addSesFollowupItem() {
  const input = document.getElementById('f-ses-followup-input');
  const text = input?.value.trim();
  if (!text) return;
  window._pendingFollowups = window._pendingFollowups || [];
  window._pendingFollowups.push({ text });
  input.value = '';
  _renderSesFollowupList();
}

function _removeSesFollowupItem(idx) {
  window._pendingFollowups = window._pendingFollowups || [];
  window._pendingFollowups.splice(idx, 1);
  _renderSesFollowupList();
}

function _renderSesFollowupList() {
  const container = document.getElementById('ses-followup-list');
  if (!container) return;
  const items = window._pendingFollowups || [];
  container.innerHTML = items.map((f, i) => `
    <div style="display:flex;align-items:center;gap:6px;padding:5px 8px;background:var(--bg3);border-radius:6px;margin-bottom:4px;font-size:12px">
      <span style="color:var(--text3)">☐</span>
      <span style="flex:1">${escapeHtml(f.text)}</span>
      <button class="x-close-sm" onclick="_removeSesFollowupItem(${i})">✕</button>
    </div>`).join('');
}

async function saveSessionGeneral() {
  const studentId = +document.getElementById('f-ses-student')?.value;
  const date = document.getElementById('f-ses-date')?.value;
  if (!date) { showToast('تاریخ را وارد کنید', 'error'); return; }
  const title = document.getElementById('f-ses-title')?.value || '';
  const note = _appendSessionTimerToNote(document.getElementById('f-ses-note')?.value);
  const addAsTopic = document.getElementById('f-ses-add-topic')?.checked;
  const caseFormData = _collectSessionCaseForm();
  const { formId: autoFormId, pid: autoPid } = _matchPeriodForDate(studentId, date);
  await window.api.sessions.add({
    student_id: studentId, date,
    title,
    importance: document.getElementById('f-ses-importance')?.value || 'normal',
    note,
    extra_note: document.getElementById('f-ses-extra')?.value,
    followups: (window._pendingFollowups || []).map(f => ({ text: f.text })),
    achievements: document.getElementById('f-ses-achievements')?.value || '',
    eval_form_id: autoFormId || null,
    eval_period_id: autoPid || null,
    achievement_tags: _getCheckedAchievementTags(),
    ...caseFormData,
  });
  window._pendingFollowups = [];
  // ذخیره پیوست‌ها در جلسه جدید
  const pending = window._pendingSessionAttachments || [];
  if (pending.length > 0) {
    const allSessions = _db.sessions;
    const newSes = allSessions[allSessions.length - 1];
    if (newSes) { newSes.attachments = pending; _save(false); }
    window._pendingSessionAttachments = [];
  }
  if (addAsTopic) {
    await window.api.topics.add({ student_id: studentId, date, title, text: note });
  }
  closeModal();
  showToast(`${META.sessionSingular||'جلسه'} ثبت شد ✓`, 'success');
  openSessionGroups.add(studentId);
  await renderSessions();
}

