async function saveEditSession(sessionId) {
  const s = (_db.sessions || []).find(x => x.id === sessionId);
  const studentId = s ? s.student_id : null;
  const date = document.getElementById('f-ses-date')?.value;
  const { formId: autoFormId, pid: autoPid } = studentId ? _matchPeriodForDate(studentId, date) : { formId: null, pid: null };
  const title = document.getElementById('f-ses-title')?.value || '';
  const note = _appendSessionTimerToNote(document.getElementById('f-ses-note')?.value);
  const caseFormData = _collectSessionCaseForm();
  await window.api.sessions.update({
    id: sessionId,
    title,
    date,
    importance: document.getElementById('f-ses-importance')?.value,
    note,
    extra_note: document.getElementById('f-ses-extra')?.value,
    achievements: document.getElementById('f-ses-achievements')?.value || '',
    eval_form_id: autoFormId || null,
    eval_period_id: autoPid || null,
    achievement_tags: _getCheckedAchievementTags(),
    ...caseFormData,
  });
  if (document.getElementById('f-ses-add-topic')?.checked && studentId) {
    await window.api.topics.add({ student_id: studentId, date, title, text: note });
  }
  closeModal();
  showToast('ذخیره شد ✓', 'success');
  await renderSessions();
}

async function toggleEditFollowup(sessionId, itemId, checkbox) {
  await window.api.sessions.toggleFollowup({ session_id: sessionId, item_id: itemId });
  // update label style inline
  const label = checkbox.nextElementSibling;
  if (label) label.style.cssText = checkbox.checked ? 'flex:1;text-decoration:line-through;color:var(--text3)' : 'flex:1';
  showToast(checkbox.checked ? '✅ انجام شد' : 'بازگشت به باز', 'success');
}

async function addEditFollowup(sessionId) {
  const input = document.getElementById('f-edit-followup-input');
  const text = input?.value.trim();
  if (!text) return;
  await window.api.sessions.addFollowup({ session_id: sessionId, text });
  input.value = '';
  showToast('اقدام اضافه شد ✓', 'success');
  await _refreshEditFollowupList(sessionId);
}

async function deleteEditFollowup(sessionId, itemId) {
  await window.api.sessions.deleteFollowup({ session_id: sessionId, item_id: itemId });
  await _refreshEditFollowupList(sessionId);
}

async function _refreshEditFollowupList(sessionId) {
  const groups = await window.api.sessions.getAll();
  let session = null;
  for (const g of groups) {
    const found = g.sessions.find(s => s.id === sessionId);
    if (found) { session = found; break; }
  }
  const container = document.getElementById('ses-edit-followup-list');
  if (!session || !container) return;
  container.innerHTML = (session.followups || []).map((f, i) => `
    <div style="display:flex;align-items:center;gap:6px;padding:5px 8px;background:var(--bg3);border-radius:6px;margin-bottom:4px;font-size:12px">
      <input type="checkbox" ${f.done ? 'checked' : ''} onchange="toggleEditFollowup(${sessionId}, ${f.id}, this)" style="width:15px;height:15px;accent-color:var(--accent2)">
      <span style="flex:1;${f.done ? 'text-decoration:line-through;color:var(--text3)' : ''}">${escapeHtml(f.text)}</span>
      <button class="x-close-sm" onclick="deleteEditFollowup(${sessionId}, ${f.id})">✕</button>
    </div>`).join('');
}

