async function renderCustomerList() {
  updateTopbarActions(`<button class="btn btn-primary" onclick="exportCustomerList()">⬇ دانلود اکسل (CSV)</button>`);
  allStudents = await window.api.students.getAll();

  let html = `${studentSectionNav('customerlist')}<div class="table-card">
    <div class="table-header"><span class="title">📋 لیست ${META.entityPlural || 'شاگردان'}</span></div>
    <table>
      <thead><tr><th>#</th><th>نام</th><th>نام خانوادگی</th><th>شماره تماس</th><th>پکیج‌ها</th></tr></thead>
      <tbody>`;

  if (allStudents.length === 0) {
    html += `<tr><td colspan="5"><div class="empty"><span>📋</span>موردی ثبت نشده</div></td></tr>`;
  } else {
    allStudents.slice().reverse().forEach((s, i) => {
      html += `<tr>
        <td>${fa(i+1)}</td>
        <td style="font-weight:500">${escapeHtml(s.name)}</td>
        <td style="font-weight:500">${escapeHtml(s.lname)}</td>
        <td style="direction:ltr;text-align:right">${escapeHtml(s.phone || '—')}</td>
        <td>${(s.packages||[]).map(pkgTag).join('') || '<span style="color:var(--text3)">—</span>'}</td>
      </tr>`;
    });
  }
  html += `</tbody></table></div>`;
  setContent(html);
}

async function exportCustomerList() {
  const rows = [['نام','نام خانوادگی','شماره تماس','پکیج‌ها']];
  allStudents.slice().reverse().forEach(s => rows.push([
    s.name, s.lname, s.phone || '',
    (s.packages||[]).map(p=>p.type_label).join('، ')
  ]));
  const csv = rows.map(r => r.map(cell => `"${String(cell).replace(/"/g,'""')}"`).join(',')).join('\r\n');
  const result = await window.api.exportCsv({ filename: 'customers.csv', content: csv });
  if (result.ok) showToast('فایل ذخیره شد ✓', 'success');
  else showToast('لغو شد');
}

