function _confirmClearAllData() {
  // تایید اول
  const step1 = confirm(
    '⚠️ هشدار جدی\n\n' +
    'این عمل تمام داده‌های حساب شما را پاک می‌کند:\n' +
    '• تمام شاگردان و مشتریان\n' +
    '• تمام پرداخت‌ها و جلسات\n' +
    '• تمام کارها و یادآوری‌ها\n' +
    '• تمام تنظیمات\n\n' +
    'آیا مطمئن هستید؟'
  );
  if (!step1) return;

  // تایید دوم — تایپ کردن عبارت تایید
  const confirm2 = window.prompt(
    '⛔ تایید نهایی\n\n' +
    'برای تایید، عبارت زیر را دقیقاً تایپ کنید:\n' +
    'پاک شود'
  );
  if (confirm2 !== 'پاک شود') {
    showToast('عملیات لغو شد', 'error');
    return;
  }

  // پاک کردن
  _clearAllAccountData();
}

async function _clearAllAccountData() {
  try {
    // ذخیره اطلاعات احراز هویت
    const session = localStorage.getItem('tp_session');
    const adminSettings = localStorage.getItem('tp_admin_settings');

    // پاک کردن localStorage
    const keysToDelete = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key !== 'tp_session' && key !== TP_AUTH_CREDENTIALS_KEY && key !== 'tp_admin_settings') {
        keysToDelete.push(key);
      }
    }
    keysToDelete.forEach(k => localStorage.removeItem(k));

    // پاک کردن روی سرور
    if (_sbUser?.id) {
      try {
        await _apiFetch('/api/data/' + _sbUser.id, {
          method: 'PUT',
          body: JSON.stringify({ data: null })
        });
      } catch(e) {}
    }

    // ریست کردن _db
    _db = _freshData();
    window._activeDBKey = _userDBKey();
    _save(false);

    showToast('✓ تمام داده‌ها پاک شدند — در حال بارگذاری مجدد...', 'success');

    setTimeout(() => {
      currentPage = 'students';
      allStudents = [];
      init();
      renderPage();
    }, 1500);

  } catch(e) {
    showToast('خطا در پاک کردن داده‌ها: ' + e.message, 'error');
  }
}

function saveLocaleSettings() {
  META.timezone = document.getElementById('set-timezone')?.value || META.timezone;
  META.calendarType = document.getElementById('set-calendar-type')?.value || 'jalali';
  META.appLanguage = document.getElementById('set-app-language')?.value || 'fa';
  META.language = META.appLanguage === 'en' ? 'en-US' : 'fa-IR';
  META.numberLang = document.getElementById('set-number-lang')?.value || 'fa';
  META.location = document.getElementById('set-location')?.value.trim() || '';
  _db.meta = { ..._db.meta, ...META };
  _save();
  applyMetaToUI();
  showToast('تنظیمات منطقه ذخیره شد ✓', 'success');
  renderSettings();
}

