function _syncThemeToggleUI() {
  const btn = document.getElementById('theme-btn');
  const lbl = document.getElementById('theme-label');
  if (!btn) return;
  btn.classList.toggle('on', isDark);
  if (lbl) lbl.textContent = isDark ? 'حالت تیره' : 'حالت روشن';
}

function initPkgTypesDragDrop() {
  const list = document.getElementById('pkg-types-list');
  if (!list) return;
  let dragEl = null;
  list.querySelectorAll('.settings-pkg-row').forEach(row => {
    row.addEventListener('dragstart', () => { dragEl = row; row.style.opacity='0.4'; });
    row.addEventListener('dragend', () => { row.style.opacity=''; savePkgTypesOrder(); });
    row.addEventListener('dragover', e => {
      e.preventDefault();
      if (!dragEl || dragEl === row) return;
      const rect = row.getBoundingClientRect();
      const before = e.clientY < rect.top + rect.height / 2;
      list.insertBefore(dragEl, before ? row : row.nextSibling);
    });
  });
}

async function savePkgTypesOrder() {
  const list = document.getElementById('pkg-types-list');
  if (!list) return;
  const order = [...list.querySelectorAll('.settings-pkg-row')].map(el => +el.dataset.pkgId);
  await window.api.packageTypes.reorder(order);
  PKG_TYPES = await window.api.packageTypes.getAll();
}

async function loadVersionsList() {
  const versions = await window.api.versions.list();
  const wrap = document.getElementById('versions-list');
  if (!wrap) return;
  if (versions.length === 0) {
    wrap.innerHTML = `<p style="font-size:12px;color:var(--text3)">هنوز نسخه‌ای ثبت نشده</p>`;
    return;
  }
  window._availableRestoreVersions = versions;
  const options = versions.map((v,i) => {
    const dateStr = new Date(v.mtime).toLocaleString('fa-IR', {dateStyle:'medium',timeStyle:'medium'});
    const source = v.source === 'server' ? 'سرور' : 'این دستگاه';
    return `<option value="${i}">${i===0?'جدیدترین · ':''}${dateStr} — ${source}</option>`;
  }).join('');
  wrap.innerHTML = `
    ${!versions.serverAvailable ? `<div style="margin-bottom:10px;padding:10px 12px;border-radius:9px;background:rgba(248,113,113,.08);border:1px solid rgba(248,113,113,.3);color:var(--red);font-size:11px;line-height:1.8">⚠️ ${escapeHtml(versions.serverError || 'تاریخچه سرور در دسترس نیست')}؛ موارد زیر فقط نسخه‌های قدیمی همین مرورگر هستند.</div>` : ''}
    <div class="form-group" style="max-width:720px;margin-bottom:10px">
      <label>نسخه موردنظر را انتخاب کنید (${fa(versions.length)} نسخه در دسترس)</label>
      <select class="form-select" id="restore-version-select" onchange="_renderVersionChoice(this.value)">${options}</select>
    </div>
    <div id="restore-version-preview"></div>`;
  _renderVersionChoice(0);
}

function _renderVersionChoice(index) {
  const v = (window._availableRestoreVersions || [])[Number(index)];
  const wrap = document.getElementById('restore-version-preview');
  if (!v || !wrap) return;
  const s = v.summary || {};
  const dateStr = new Date(v.mtime).toLocaleString('fa-IR', {dateStyle:'full',timeStyle:'medium'});
  const size = v.size ? `${(v.size/1024/1024).toLocaleString('fa-IR',{maximumFractionDigits:2})} مگابایت` : '—';
  wrap.innerHTML = `
    <div style="padding:12px;border:1px solid var(--border);border-radius:10px;background:var(--bg2);display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap">
      <div style="font-size:11px;color:var(--text2);line-height:2">
        <div><b style="color:var(--text)">${dateStr}</b> · ${v.source==='server'?'☁️ نسخه سرور':'💻 نسخه این دستگاه'}</div>
        <div>کارها: ${fa(s.todos||0)} · مراجعین: ${fa(s.students||0)} · پرسنل: ${fa(s.staff||0)} · یادداشت‌ها: ${fa(s.instructions||0)} · حجم: ${size}</div>
      </div>
      <button class="btn btn-primary btn-sm" onclick="restoreVersion(${escapeAttr(v.source)},${escapeAttr(String(v.ref))})">بازگشت به نسخه انتخاب‌شده</button>
    </div>`;
}

async function restoreVersion(source, ref) {
  const selected = (window._availableRestoreVersions || []).find(v => v.source===source && String(v.ref)===String(ref));
  const label = selected ? new Date(selected.mtime).toLocaleString('fa-IR') : '';
  if (!confirm(`نسخه ${label} جایگزین داده فعلی شود؟ نسخه فعلی ابتدا در تاریخچه سرور محفوظ می‌ماند. این عملیات فقط با تأیید شما انجام می‌شود.`)) return;
  const result = await window.api.versions.restore(source, ref);
  if (!result.ok) { showToast(result.error || 'خطا', 'error'); return; }
  showToast('بازگردانی شد ✓ — برنامه دوباره بارگذاری می‌شود', 'success');
  setTimeout(() => location.reload(), 900);
}

async function importBackup() {
  if (!confirm('با وارد کردن فایل پشتیبان، تمام داده‌های فعلی این برنامه با آن جایگزین می‌شود (نسخه فعلی هم ذخیره می‌ماند). ادامه می‌دهی؟')) return;
  const result = await window.api.backup.import();
  if (!result.ok) {
    if (result.error) showToast(result.error, 'error');
    return;
  }
  showToast('فایل پشتیبان با موفقیت بار شد — در حال بارگذاری مجدد... ✓', 'success');
  setTimeout(() => location.reload(), 1200);
}

async function reloadAllData() {
  META = await window.api.meta.get();
  PKG_TYPES = await window.api.packageTypes.getAll();
  FAMILIES = await window.api.families.getAll();
  applyMetaToUI();
  try {
    const reminders = await window.api.reminders.getAll();
    const pending = reminders.filter(r => !r.done).length;
    updateReminderBadges(pending);
  } catch(e) {}
  await renderPage();
}

async function saveMeta() {
  const payload = {
    appTitle: document.getElementById('set-app-title')?.value.trim() || 'سیستم مدیریت',
    entitySingular: document.getElementById('set-entity-singular')?.value.trim() || 'شاگرد',
    entityPlural: document.getElementById('set-entity-plural')?.value.trim() || 'شاگردان',
    sessionSingular: document.getElementById('set-session-singular')?.value.trim() || 'جلسه',
    sessionPlural: document.getElementById('set-session-plural')?.value.trim() || 'جلسات',
  };
  META = await window.api.meta.update(payload);
  applyMetaToUI();
  showToast('تغییرات ذخیره شد ✓', 'success');
}

async function addPkgType() {
  const label = document.getElementById('new-pkg-label')?.value.trim();
  const color = document.getElementById('new-pkg-color')?.value || '#7c6af7';
  if (!label) { showToast('نام پکیج را وارد کنید', 'error'); return; }
  await window.api.packageTypes.add({ label, color });
  showToast('اضافه شد ✓', 'success');
  await renderSettings();
}

async function updatePkgType(id, color, label) {
  const pt = PKG_TYPES.find(x => x.id === id);
  await window.api.packageTypes.update({
    id,
    color: color !== null ? color : pt.color,
    label: label !== null ? label : pt.label,
  });
  showToast('ذخیره شد ✓', 'success');
  PKG_TYPES = await window.api.packageTypes.getAll();
}

async function deletePkgType(id) {
  if (!confirm('این نوع پکیج حذف شود؟')) return;
  const result = await window.api.packageTypes.delete(id);
  if (!result.ok) { showToast(result.error, 'error'); return; }
  showToast('حذف شد', 'error');
  await renderSettings();
}

function richToolbar(textareaId) {
  // فقط پراستفاده‌ترین ابزارها همیشه نمایش داده می‌شوند؛ بقیه پشت دکمه «+» هستند (مثل Notion)
  // «حالت تمرکز» چون خیلی زیاد استفاده می‌شود همیشه در دسترس است، نه پشت «+»
  const mainStickers = ['⭐','📌','🔥','✅','⚠️'];
  const moreStickers = ['❗','💡','👍','❤️','🎯'];
  const moreId = textareaId + '-more';
  return `
  <div class="rich-toolbar">
    ${mainStickers.map(s => `<button type="button" class="rt-btn rt-sticker" onclick="insertAtCursor('${textareaId}','${s}')">${s}</button>`).join('')}
    <button type="button" class="rt-btn" title="هایلایت" onclick="wrapSelection('${textareaId}','==','==')">🖍️</button>
    <span class="rt-sep"></span>
    <button type="button" class="rt-btn" title="پیش‌نمایش Markdown" aria-label="پیش‌نمایش Markdown" onclick="_toggleRichPreview('${textareaId}',this)">👁️</button>
    <button type="button" class="rt-btn rt-focus-btn" title="حالت تمرکز" onclick="_focusTextarea('${textareaId}')" aria-label="حالت تمرکز">⛶</button>
    <span class="rt-sep"></span>
    <button type="button" class="rt-btn" title="ابزارهای بیشتر" onclick="_toggleToolbarMore('${moreId}')">+</button>
  </div>
  <div id="${moreId}" class="rt-more" style="display:none">
    <button type="button" class="rt-btn" title="پررنگ" onclick="wrapSelection('${textareaId}','**','**')"><b>B</b></button>
    <button type="button" class="rt-btn" title="زیرخط" onclick="insertUnderline('${textareaId}')"><u style="text-decoration:underline;font-size:11px;font-weight:700">U</u></button>
    <button type="button" class="rt-btn" title="کج" onclick="wrapSelection('${textareaId}','*','*')"><i style="font-size:12px">I</i></button>
    <span class="rt-sep"></span>
    <button type="button" class="rt-btn" title="لیست نقطه‌ای" onclick="insertBulletedItem('${textareaId}')"><span class="rt-list-icon" style="font-size:15px;line-height:1">•</span></button>
    <button type="button" class="rt-btn" title="چک‌لیست" onclick="insertChecklistItem('${textareaId}')"><span class="rt-list-icon">✓</span></button>
    <button type="button" class="rt-btn" title="لیست شماره‌دار" onclick="insertNumberedItem('${textareaId}')"><span class="rt-list-icon">1.</span></button>
    <span class="rt-sep"></span>
    <button type="button" class="rt-btn" title="درج لینک" onclick="insertLink('${textareaId}')"><span style="font-size:12px">🔗</span></button>
    <div class="rt-color-wrap">
      <button type="button" class="rt-color-btn" title="رنگ متن" onclick="_toggleColorPicker('${textareaId}-cpicker')">
        <span style="font-size:10px;font-weight:700;line-height:1">A</span>
        <span class="rt-color-bar"></span>
      </button>
      ${_buildColorPicker(textareaId, textareaId + '-cpicker')}
    </div>
    <span class="rt-sep"></span>
    <button type="button" class="rt-btn" title="خط افقی" onclick="insertHorizontalLine('${textareaId}')"><span class="rt-hr-icon"></span></button>
    <button type="button" class="rt-btn" title="جدول" onclick="insertTable('${textareaId}')" style="font-size:12px">⊞</button>
    <span class="rt-sep"></span>
    ${moreStickers.map(s => `<button type="button" class="rt-btn rt-sticker" onclick="insertAtCursor('${textareaId}','${s}')">${s}</button>`).join('')}
  </div>`;
}

// تبدیل HTML موجود در کلیپ‌بورد به Markdown امنِ قابل‌نمایش در تیم‌پالس.
// محتوای جلسه به‌صورت متن ذخیره می‌شود؛ بنابراین HTML خام را نگه نمی‌داریم تا
// هم ظاهر برنامه یکدست بماند و هم کد ناخواسته از کلیپ‌بورد وارد نشود.
function _clipboardHtmlToRichText(html) {
  const doc = new DOMParser().parseFromString(String(html || ''), 'text/html');
  const clean = value => String(value || '').replace(/\u00a0/g, ' ').replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').trim();
  const joinBlocks = values => values.map(clean).filter(Boolean).join('\n\n');
  const inline = node => {
    if (!node) return '';
    if (node.nodeType === Node.TEXT_NODE) return node.nodeValue || '';
    if (node.nodeType !== Node.ELEMENT_NODE) return '';
    const tag = node.tagName.toLowerCase();
    if (tag === 'br') return '\n';
    if (tag === 'script' || tag === 'style' || tag === 'noscript') return '';
    const content = Array.from(node.childNodes).map(inline).join('');
    if (tag === 'strong' || tag === 'b') return content.trim() ? `**${content.trim()}**` : '';
    if (tag === 'em' || tag === 'i') return content.trim() ? `*${content.trim()}*` : '';
    if (tag === 'u') return content.trim() ? `<u>${content.trim()}</u>` : '';
    if (tag === 'a') {
      const href = (node.getAttribute('href') || '').trim();
      return /^https?:\/\//i.test(href) && content.trim() ? `[${content.trim()}](${href})` : content;
    }
    if (tag === 'img') {
      const src = (node.getAttribute('src') || '').trim();
      const alt = (node.getAttribute('alt') || 'تصویر').trim();
      return /^https?:\/\//i.test(src) ? `![${alt}](${src})` : '';
    }
    return content;
  };
  const list = (node, ordered, depth) => {
    const start = Number(node.getAttribute('start')) || 1;
    return Array.from(node.children).filter(child => child.tagName && child.tagName.toLowerCase() === 'li').map((li, index) => {
      const direct = Array.from(li.childNodes).filter(child => !(child.nodeType === Node.ELEMENT_NODE && /^(ul|ol)$/i.test(child.tagName))).map(inline).join('');
      const prefix = ordered ? `${start + index}. ` : '- ';
      const nested = Array.from(li.children).filter(child => /^(ul|ol)$/i.test(child.tagName)).map(child => list(child, child.tagName.toLowerCase() === 'ol', depth + 1)).filter(Boolean).join('\n');
      const indent = '  '.repeat(depth || 0);
      return indent + prefix + clean(direct) + (nested ? '\n' + nested : '');
    }).join('\n');
  };
  const table = node => {
    const rows = Array.from(node.querySelectorAll('tr')).map(row => Array.from(row.querySelectorAll(':scope > th, :scope > td')).map(cell => clean(inline(cell))).filter((_, index, cells) => index < cells.length));
    if (!rows.length || !rows[0].length) return '';
    const width = rows[0].length;
    const markdownRows = rows.map(cells => `| ${Array.from({ length: width }, (_, i) => String(cells[i] || '').replace(/\|/g, '\\|')).join(' | ')} |`);
    markdownRows.splice(1, 0, `| ${Array.from({ length: width }, () => '---').join(' | ')} |`);
    return markdownRows.join('\n');
  };
  const block = node => {
    if (!node) return '';
    if (node.nodeType === Node.TEXT_NODE) return clean(node.nodeValue);
    if (node.nodeType !== Node.ELEMENT_NODE) return '';
    const tag = node.tagName.toLowerCase();
    if (tag === 'script' || tag === 'style' || tag === 'noscript') return '';
    if (/^h[1-6]$/.test(tag)) return `${'#'.repeat(Number(tag[1]))} ${clean(inline(node))}`;
    if (tag === 'ul' || tag === 'ol') return list(node, tag === 'ol', 0);
    if (tag === 'table') return table(node);
    if (tag === 'blockquote') return clean(inline(node)).split('\n').filter(Boolean).map(line => `> ${line}`).join('\n');
    if (tag === 'pre') return `\`\`\`\n${node.textContent || ''}\n\`\`\``;
    if (tag === 'hr') return '---';
    if (/^(p|div|section|article|main|header|footer|figure|figcaption|li)$/.test(tag)) {
      const hasBlocks = Array.from(node.children).some(child => /^(h[1-6]|p|div|section|article|ul|ol|table|blockquote|pre|hr)$/i.test(child.tagName));
      return hasBlocks ? joinBlocks(Array.from(node.childNodes).map(block)) : clean(inline(node));
    }
    return clean(inline(node));
  };
  return joinBlocks(Array.from(doc.body.childNodes).map(block));
}

function pasteRichClipboard(event, textareaId) {
  const html = event.clipboardData && event.clipboardData.getData('text/html');
  if (!html) return;
  const converted = _clipboardHtmlToRichText(html);
  if (!converted) return;
  const textarea = document.getElementById(textareaId);
  if (!textarea) return;
  event.preventDefault();
  const start = textarea.selectionStart;
  const end = textarea.selectionEnd;
  textarea.value = textarea.value.slice(0, start) + converted + textarea.value.slice(end);
  textarea.focus();
  textarea.selectionStart = textarea.selectionEnd = start + converted.length;
  textarea.dispatchEvent(new Event('input', { bubbles: true }));
  showToast('عنوان‌ها، فهرست‌ها و جدولِ متن کپی‌شده حفظ شد ✓', 'success');
}

function _toggleToolbarMore(id) {
  const el = document.getElementById(id);
  if (!el) return;
  el.style.display = el.style.display === 'none' ? 'flex' : 'none';
}

function wrapSelection(textareaId, before, after) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd;
  const scrollTop = el.scrollTop;
  const val = el.value;
  el.value = val.slice(0,start) + before + val.slice(start,end) + after + val.slice(end);
  el.focus();
  el.selectionStart = start + before.length;
  el.selectionEnd = end + before.length;
  el.scrollTop = scrollTop;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function insertUnderline(textareaId) {
  // از فرمت HTML-like برای زیرخط استفاده می‌کنیم: <u>متن</u>
  wrapSelection(textareaId, '<u>', '</u>');
}

function insertLink(textareaId) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd;
  const selected = el.value.slice(start, end);
  const url = prompt('آدرس لینک را وارد کنید:', 'https://');
  if (!url || url === 'https://') return;
  const label = selected || prompt('متن نمایشی لینک:', url) || url;
  const mdLink = `[${label}](${url})`;
  const val = el.value;
  el.value = val.slice(0, start) + mdLink + val.slice(end);
  el.focus();
  el.selectionStart = el.selectionEnd = start + mdLink.length;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function insertBulletedItem(textareaId) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd, val = el.value;
  const scrollTop = el.scrollTop;
  const selected = val.slice(start, end);
  const prefix = (start === 0 || val[start - 1] === '\n') ? '' : '\n';
  const lines = selected ? selected.split('\n') : [''];
  const insert = prefix + lines.map(line => {
    const clean = line.replace(/^(\[ \] |\[x\] |\d+\. |- )/, '');
    return '- ' + clean;
  }).join('\n');
  el.value = val.slice(0, start) + insert + val.slice(end);
  el.focus(); el.selectionStart = el.selectionEnd = start + insert.length;
  el.scrollTop = scrollTop;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function applyTextColor(textareaId, color) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd;
  const scrollTop = el.scrollTop;
  const rawSelected = el.value.slice(start, end) || 'متن';
  // اگر متن انتخاب‌شده خودش قبلاً رنگی شده (یعنی کاربر دارد رنگ را عوض می‌کند، نه اینکه
  // متن تازه‌ای را رنگی می‌کند)، به‌جای پیچیدن یک لایه‌ی جدید دور آن، رنگ قبلی را با رنگ
  // جدید جایگزین می‌کنیم و هر لایه‌ی تودرتوی احتمالی (باقی‌مانده از این باگ) را هم پاک می‌کنیم.
  const wrapMatch = rawSelected.match(/^\{\{c:#[0-9a-fA-F]{3,8}\}\}([\s\S]*)\{\{\/c\}\}$/);
  let inner = wrapMatch ? wrapMatch[1] : rawSelected;
  // پاک‌سازی لایه‌های تودرتوی باقی‌مانده از نسخه‌ی قبلی باگ، مثل {{c:x}}{{c:y}}متن{{/c}}{{/c}}
  let prevInner;
  do {
    prevInner = inner;
    inner = inner.replace(/^\{\{c:#[0-9a-fA-F]{3,8}\}\}([\s\S]*)\{\{\/c\}\}$/, '$1');
  } while (inner !== prevInner);
  const colored = `{{c:${color}}}${inner}{{/c}}`;
  const val = el.value;
  el.value = val.slice(0, start) + colored + val.slice(end);
  el.focus();
  el.selectionStart = start;
  el.selectionEnd = start + colored.length;
  el.scrollTop = scrollTop;
  el.dispatchEvent(new Event('input', { bubbles: true }));
  // بستن color picker
  document.querySelectorAll('.rt-color-picker.open').forEach(p => p.classList.remove('open'));
  // آپدیت نوار رنگی
  const bar = el.closest ? null : null;
  document.querySelectorAll('.rt-color-bar').forEach(b => { b.style.background = color; });
}

function _toggleColorPicker(pickerId) {
  const picker = document.getElementById(pickerId);
  if (!picker) return;
  const isOpen = picker.classList.contains('open');
  document.querySelectorAll('.rt-color-picker.open').forEach(p => p.classList.remove('open'));
  if (!isOpen) picker.classList.add('open');
}

function _buildColorPicker(textareaId, pickerId) {
  const colors = [
    '#f87171','#fb923c','#fbbf24','#4ade80','#60a5fa','#c084fc',
    '#f472b6','#e11d48','#ea580c','#ca8a04','#16a34a','#2563eb',
    '#7c3aed','#be185d','#ffffff','#d1d5db','#6b7280','#374151',
    '#1f2937','#111827','#3ecf8e','#06b6d4','#8b5cf6','#ec4899',
  ];
  return `<div id="${pickerId}" class="rt-color-picker">
    <div class="rt-color-label">رنگ متن</div>
    <div class="rt-color-grid">
      ${colors.map(c => `<div class="rt-color-swatch" style="background:${c}" title="${c}" onclick="applyTextColor('${textareaId}','${c}')"></div>`).join('')}
    </div>
  </div>`;
}

// بستن color picker با کلیک خارج
document.addEventListener('click', function(e) {
  if (!e.target.closest('.rt-color-wrap')) {
    document.querySelectorAll('.rt-color-picker.open').forEach(p => p.classList.remove('open'));
  }
});

function insertAtCursor(textareaId, text) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd;
  const scrollTop = el.scrollTop;
  const val = el.value;
  el.value = val.slice(0,start) + text + val.slice(end);
  el.focus();
  el.selectionStart = el.selectionEnd = start + text.length;
  el.scrollTop = scrollTop;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function insertChecklistItem(textareaId) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd, val = el.value;
  const scrollTop = el.scrollTop;
  const selected = val.slice(start, end);
  const prefix = (start === 0 || val[start - 1] === '\n') ? '' : '\n';
  const lines = selected ? selected.split('\n') : [''];
  const insert = prefix + lines.map(line => {
    const clean = line.replace(/^(\[ \] |\[x\] |\d+\. )/, '');
    return '[ ] ' + clean;
  }).join('\n');
  el.value = val.slice(0, start) + insert + val.slice(end);
  el.focus(); el.selectionStart = el.selectionEnd = start + insert.length;
  el.scrollTop = scrollTop;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function insertNumberedItem(textareaId) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd, val = el.value;
  const scrollTop = el.scrollTop;
  const before = val.slice(0, start);
  const lastNum = before.match(/(?:^|\n)(\d+)\. [^\n]*(?:\n)?$/);
  const nextNum = lastNum ? parseInt(lastNum[1]) + 1 : 1;
  const prefix = (start === 0 || val[start-1] === '\n') ? '' : '\n';
  const selected = val.slice(start, end);
  const lines = selected ? selected.split('\n') : [''];
  const insert = prefix + lines.map((line, i) => {
    const clean = line.replace(/^(\[ \] |\[x\] |\d+\. )/, '');
    return (nextNum + i) + '. ' + clean;
  }).join('\n');
  el.value = val.slice(0, start) + insert + val.slice(end);
  el.focus(); el.selectionStart = el.selectionEnd = start + insert.length;
  el.scrollTop = scrollTop;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function insertHorizontalLine(textareaId) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, end = el.selectionEnd, val = el.value;
  const scrollTop = el.scrollTop;
  const beforeBreak = (start === 0 || val[start - 1] === '\n') ? '' : '\n';
  const afterBreak = (end >= val.length || val[end] === '\n') ? '\n' : '\n';
  const insert = beforeBreak + '---' + afterBreak;
  el.value = val.slice(0, start) + insert + val.slice(end);
  el.focus(); el.selectionStart = el.selectionEnd = start + insert.length;
  el.scrollTop = scrollTop;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function insertTable(textareaId) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const start = el.selectionStart, val = el.value;
  const prefix = (start === 0 || val[start-1] === '\n') ? '' : '\n';
  const tbl = prefix + '| ستون ۱ | ستون ۲ | ستون ۳ |\n|--------|--------|--------|\n| داده ۱ | داده ۲ | داده ۳ |\n| داده ۴ | داده ۵ | داده ۶ |\n';
  el.value = val.slice(0, start) + tbl + val.slice(start);
  el.focus(); el.selectionStart = el.selectionEnd = start + tbl.length;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function _focusTextarea(textareaId) {
  const el = document.getElementById(textareaId);
  if (!el) return;
  const fieldMap = {'instr-content':'content','instr-extra':'extra_note','ei-content':'content','ei-extra':'extra_note'};
  _openFocusMode(el, window._currentEditNoteId || null, fieldMap[textareaId] || 'content');
}

function _toggleRichPreview(textareaId, button) {
  const textarea = document.getElementById(textareaId);
  if (!textarea) return;
  const previewId = textareaId + '-markdown-preview';
  let preview = document.getElementById(previewId);
  const isOpen = preview && preview.style.display !== 'none';
  if (isOpen) {
    preview.style.display = 'none';
    textarea.style.display = '';
    button?.classList.remove('active');
    if (button) { button.textContent = '👁️'; button.title = 'پیش‌نمایش Markdown'; }
    textarea.focus();
    return;
  }
  if (!preview) {
    preview = document.createElement('div');
    preview.id = previewId;
    preview.style.cssText = 'flex:1;min-height:220px;max-height:52vh;overflow:auto;padding:18px;border:1px solid var(--border2);border-radius:10px;background:var(--bg3);color:var(--text);font-size:14px;line-height:2;direction:rtl;text-align:right';
    textarea.insertAdjacentElement('afterend', preview);
  }
  preview.innerHTML = renderRich(textarea.value, { interactive:true, textareaId:textareaId });
  textarea.style.display = 'none';
  preview.style.display = 'block';
  button?.classList.add('active');
  if (button) { button.textContent = '✏️'; button.title = 'بازگشت به ویرایش'; }
}

function _openFocusMode(textarea, noteId, field) {
  if (document.getElementById('focus-mode-overlay')) return;
  noteId = noteId || null; field = field || 'content';

  // ── حالت تمرکز باید حس «نوشتن در یک ویرایشگر حرفه‌ای» بدهد،
  // نه یک فرم تمام‌عرض. برای همین محتوا در یک ستون مرکزی با عرض محدود قرار می‌گیرد
  // و هدر/تولبار/فوتر همگی دقیقاً هم‌عرض همان ستون می‌شوند.
  const FOCUS_IS_MOBILE = window.matchMedia && window.matchMedia('(max-width: 640px)').matches;
  const FOCUS_MAXW = FOCUS_IS_MOBILE ? '480px' : '1040px';
  const FOCUS_PAD = FOCUS_IS_MOBILE ? 'max(16px, env(safe-area-inset-left, 0px), env(safe-area-inset-right, 0px))' : '40px';
  const FOCUS_HEADER_H = FOCUS_IS_MOBILE ? '48px' : '60px';
  const FOCUS_TOP_GAP = FOCUS_IS_MOBILE ? 'max(54px, calc(env(safe-area-inset-top, 0px) + 12px))' : '0px';
  const FOCUS_BTN_PAD = '4px 14px';
  const FOCUS_BTN_FONT = '12px';

  const overlay = document.createElement('div');
  overlay.id = 'focus-mode-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:var(--bg);display:flex;align-items:stretch;justify-content:stretch;animation:fadeInFocus .2s ease';

  // حالت تمرکز باید یک محیط ویرایش واقعیِ تمام‌صفحه باشد، نه یک فرم/مودال
  const box = document.createElement('div');
  box.style.cssText = `background:var(--bg2);border-radius:0;width:100vw;height:calc(var(--app-vh, 100dvh) - ${FOCUS_TOP_GAP});margin-top:${FOCUS_TOP_GAP};display:flex;flex-direction:column;border:none;box-shadow:none;animation:fadeInFocus .2s ease;overflow:hidden`;

  // header — کوتاه و محتوایش هم‌عرض ستون نوشتن، نه چسبیده به لبه‌های صفحه
  const header = document.createElement('div');
  header.style.cssText = `display:flex;align-items:center;justify-content:center;height:${FOCUS_HEADER_H};min-height:${FOCUS_HEADER_H};border-bottom:1px solid var(--border);flex-shrink:0`;
  const headerInner = document.createElement('div');
  headerInner.style.cssText = `width:100%;max-width:${FOCUS_MAXW};margin:0 auto;padding:0 ${FOCUS_PAD};display:flex;align-items:center;justify-content:space-between;box-sizing:border-box`;
  const modeToggle = document.createElement('div');
  modeToggle.style.cssText = 'display:flex;gap:3px;background:var(--bg3);border-radius:8px;padding:3px;flex-shrink:0';
  const _btnEdit = document.createElement('button');
  _btnEdit.id = 'fm-edit-btn';
  _btnEdit.style.cssText = `padding:${FOCUS_BTN_PAD};border-radius:6px;border:none;cursor:pointer;font-size:${FOCUS_BTN_FONT};font-family:var(--font);background:var(--accent2);color:#fff;white-space:nowrap`;
  _btnEdit.innerHTML = '✏️ ویرایش';
  _btnEdit.onclick = function(){ window._fmSetMode('edit'); };
  const _btnPrev = document.createElement('button');
  _btnPrev.id = 'fm-preview-btn';
  _btnPrev.style.cssText = `padding:${FOCUS_BTN_PAD};border-radius:6px;border:none;cursor:pointer;font-size:${FOCUS_BTN_FONT};font-family:var(--font);background:transparent;color:var(--text2);white-space:nowrap`;
  _btnPrev.innerHTML = '👁 پیش‌نمایش';
  _btnPrev.onclick = function(){ window._fmSetMode('preview'); };
  modeToggle.appendChild(_btnEdit);
  modeToggle.appendChild(_btnPrev);
  const rightSide = document.createElement('div');
  rightSide.style.cssText = 'display:flex;gap:8px;align-items:center';
  const _spanEsc = document.createElement('span');
  _spanEsc.style.cssText = `font-size:11px;color:var(--text3);${FOCUS_IS_MOBILE ? 'display:none' : ''}`;
  _spanEsc.textContent = '📝 حالت تمرکز | ESC برای خروج';
  const _btnClose = document.createElement('button');
  _btnClose.className = 'x-close';
  _btnClose.title = 'بستن (ESC)';
  _btnClose.textContent = '✕';
  _btnClose.onclick = function(){ textarea.value = focusTa.value; textarea.dispatchEvent(new Event('input',{bubbles:true})); overlay.remove(); };
  rightSide.appendChild(_spanEsc);
  rightSide.appendChild(_btnClose);
  headerInner.appendChild(modeToggle); headerInner.appendChild(rightSide);
  header.appendChild(headerInner);

  // edit pane — این خودِ ناحیه‌ی اسکرول‌شونده‌ی تمام‌عرض است؛ محتوای داخلش محدود می‌شود
  const editPane = document.createElement('div');
  editPane.id = 'fm-edit-pane';
  editPane.style.cssText = 'flex:1;display:flex;flex-direction:column;overflow-y:auto;overflow-x:hidden';

  const editInner = document.createElement('div');
  editInner.style.cssText = `width:100%;max-width:${FOCUS_MAXW};margin:0 auto;display:flex;flex-direction:column;flex:1;box-sizing:border-box`;

  // toolbar — هم‌عرض ستون نوشتن، نزدیک به متن (نه چسبیده به گوشه‌ی بالای صفحه)
  const fmToolbar = document.createElement('div');
  fmToolbar.className = 'rich-toolbar';
  fmToolbar.style.cssText = `flex-shrink:0;margin:${FOCUS_IS_MOBILE ? '12px' : '20px'} ${FOCUS_PAD} 0;border-radius:10px;width:auto`;
  const _fmStickers = ['⭐','✅','❗','💡','🔥','👍','📌','⚠️','❤️','🎯'];
  (function() {
    function _b(title, html, fn, st) {
      const b = document.createElement('button');
      b.type='button'; b.className='rt-btn'; b.title=title; b.innerHTML=html;
      if(st) b.style.cssText=st;
      b.addEventListener('click', fn);
      fmToolbar.appendChild(b);
    }
    function _sep() { const s=document.createElement('span'); s.className='rt-sep'; fmToolbar.appendChild(s); }
    _b('پررنگ','<b>B</b>',function(){ wrapSelection('fm-textarea','**','**'); });
    _b('زیرخط','<u style="text-decoration:underline;font-size:11px;font-weight:700">U</u>',function(){ insertUnderline('fm-textarea'); });
    _b('کج','<i style="font-size:12px">I</i>',function(){ wrapSelection('fm-textarea','*','*'); });
    _b('هایلایت','🖍️',function(){ wrapSelection('fm-textarea','==','=='); });
    _sep();
    _b('لیست نقطه‌ای','<span class="rt-list-icon" style="font-size:15px;line-height:1">•</span>',function(){ insertBulletedItem('fm-textarea'); });
    _b('چک‌لیست','<span class="rt-list-icon">✓</span>',function(){ insertChecklistItem('fm-textarea'); });
    _b('لیست شماره‌دار','<span class="rt-list-icon">1.</span>',function(){ insertNumberedItem('fm-textarea'); });
    _sep();
    _b('درج لینک','<span style="font-size:12px">🔗</span>',function(){ insertLink('fm-textarea'); });
    (function(){
      const wrap = document.createElement('div');
      wrap.className = 'rt-color-wrap';
      const cbtn = document.createElement('button');
      cbtn.type='button'; cbtn.className='rt-color-btn'; cbtn.title='رنگ متن';
      cbtn.innerHTML='<span style="font-size:10px;font-weight:700;line-height:1">A</span><span class="rt-color-bar"></span>';
      const pickerEl = document.createElement('div');
      pickerEl.id='fm-textarea-cpicker'; pickerEl.className='rt-color-picker';
      pickerEl.innerHTML = '<div class="rt-color-label">رنگ متن</div><div class="rt-color-grid">' +
        ['#f87171','#fb923c','#fbbf24','#4ade80','#60a5fa','#c084fc','#f472b6','#e11d48','#ea580c','#ca8a04','#16a34a','#2563eb','#7c3aed','#be185d','#ffffff','#d1d5db','#6b7280','#374151','#1f2937','#111827','#3ecf8e','#06b6d4','#8b5cf6','#ec4899'].map(function(c){ return '<div class="rt-color-swatch" style="background:'+c+'" title="'+c+'" onclick="applyTextColor(\'fm-textarea\',\''+c+'\')"></div>'; }).join('') + '</div>';
      cbtn.addEventListener('click',function(){ _toggleColorPicker('fm-textarea-cpicker'); });
      wrap.appendChild(cbtn); wrap.appendChild(pickerEl);
      fmToolbar.appendChild(wrap);
    })();
    _sep();
    _b('خط افقی','<span class="rt-hr-icon"></span>',function(){ insertHorizontalLine('fm-textarea'); });
    _b('جدول','⊞',function(){ insertTable('fm-textarea'); },'font-size:12px');
    _sep();
    _fmStickers.forEach(function(s){ _b(s,s,function(){ insertAtCursor('fm-textarea',s); },'font-size:15px'); });
  })();
  editInner.appendChild(fmToolbar);

  // ستون متن: فاصله‌ی افقی ۴۰px از دو طرف، و کمی فاصله از پایین تا میکروفون به فوتر نچسبد
  const textWrap = document.createElement('div');
  textWrap.style.cssText = `position:relative;flex:1;display:flex;flex-direction:column;padding:0 ${FOCUS_PAD};margin-bottom:${FOCUS_IS_MOBILE ? '24px' : '40px'};box-sizing:border-box`;

  const focusTa = document.createElement('textarea');
  focusTa.id = 'fm-textarea';
  focusTa.value = _cleanupColorMarkers(textarea.value);
  focusTa.style.cssText = `flex:1;width:100%;resize:none;background:transparent;border:none;padding:${FOCUS_IS_MOBILE ? '22px' : '32px'} 0 20px;font-family:var(--font);font-size:14px;line-height:2;color:var(--text);direction:rtl;text-align:right;outline:none;white-space:pre-wrap;box-sizing:border-box`;
  focusTa.placeholder = textarea.placeholder || 'بنویس...';
  textWrap.appendChild(focusTa);
  editInner.appendChild(textWrap);
  editPane.appendChild(editInner);
  // ورودی صوتی دقیقا همان‌جایی که کاربر در حالت تمرکز بیشترین نیاز را دارد: شناور، پایین-چپ ستون متن
  // (نه چسبیده به دکمهٔ ذخیره در فوتر — بین آن‌ها فاصلهٔ عمودی کافی وجود دارد)
  _attachVoiceButton(focusTa);

  // preview pane — همان منطق ستون مرکزی
  const previewPane = document.createElement('div');
  previewPane.id = 'fm-preview-pane';
  previewPane.style.cssText = 'flex:1;overflow-y:auto;display:none';
  const previewInner = document.createElement('div');
  previewInner.id = 'fm-preview-inner';
  previewInner.style.cssText = `max-width:${FOCUS_MAXW};margin:0 auto;padding:${FOCUS_IS_MOBILE ? '22px' : '32px'} ${FOCUS_PAD} 60px;font-size:14px;line-height:2;color:var(--text);direction:rtl;text-align:right;box-sizing:border-box`;
  previewPane.appendChild(previewInner);

  // footer — هم‌عرض ستون نوشتن، نه تمام‌عرض صفحه
  const footer = document.createElement('div');
  footer.style.cssText = 'display:flex;justify-content:center;border-top:1px solid var(--border);flex-shrink:0';
  const footerInner = document.createElement('div');
  footerInner.style.cssText = `width:100%;max-width:${FOCUS_MAXW};margin:0 auto;padding:14px ${FOCUS_PAD};display:flex;justify-content:space-between;align-items:center;box-sizing:border-box`;
  const charCount = document.createElement('span');
  charCount.style.cssText = 'font-size:11px;color:var(--text3)';
  charCount.textContent = focusTa.value.length + ' کاراکتر';
  const closeBtn = document.createElement('button');
  closeBtn.className = 'btn btn-primary';
  closeBtn.textContent = '✓ ذخیره و بستن';
  closeBtn.onclick = function() {
    // sync آخرین مقدار به textarea اصلی قبل از بستن
    textarea.value = focusTa.value;
    textarea.dispatchEvent(new Event('input', {bubbles:true}));
    overlay.remove();
  };
  footerInner.appendChild(charCount); footerInner.appendChild(closeBtn);
  footer.appendChild(footerInner);

  // sync textarea → اصلی هنگام input
  focusTa.addEventListener('input', function() {
    textarea.value = focusTa.value;
    charCount.textContent = focusTa.value.length + ' کاراکتر';
    textarea.dispatchEvent(new Event('input', {bubbles:true}));
    if (previewPane.style.display !== 'none') {
      previewInner.innerHTML = renderRich(focusTa.value, {interactive:!!noteId, noteId:noteId, field:field});
    }
  });

  box.appendChild(header); box.appendChild(editPane); box.appendChild(previewPane); box.appendChild(footer);
  overlay.appendChild(box); document.body.appendChild(overlay);

  window._fmSetMode = function(mode) {
    const eb = document.getElementById('fm-edit-btn'), pb = document.getElementById('fm-preview-btn');
    if (mode === 'preview') {
      previewInner.innerHTML = renderRich(focusTa.value, {interactive:!!noteId, noteId:noteId, field:field});
      editPane.style.display = 'none'; previewPane.style.display = 'block';
      if(eb){eb.style.background='transparent';eb.style.color='var(--text2)';}
      if(pb){pb.style.background='var(--accent2)';pb.style.color='#fff';}
    } else {
      editPane.style.display = 'flex'; previewPane.style.display = 'none';
      if(eb){eb.style.background='var(--accent2)';eb.style.color='#fff';}
      if(pb){pb.style.background='transparent';pb.style.color='var(--text2)';}
      setTimeout(function(){ focusTa.focus(); }, 50);
    }
  };

  setTimeout(function(){ focusTa.focus(); }, 50);
  const escH = function(e){ if(e.key==='Escape'){ textarea.value=focusTa.value; textarea.dispatchEvent(new Event('input',{bubbles:true})); overlay.remove(); document.removeEventListener('keydown',escH); } };
  document.addEventListener('keydown', escH);
  overlay.addEventListener('click', function(e){ if(e.target===overlay){ textarea.value=focusTa.value; textarea.dispatchEvent(new Event('input',{bubbles:true})); overlay.remove(); document.removeEventListener('keydown',escH); } });
}


// ── Archive ────────────────────────────────────────────────────────────────
async function archiveStudent(id, name) {
  if (!confirm(`آیا مطمئنی می‌خوای "${name}" به بایگانی منتقل بشه؟`)) return;
  if (!confirm(`تأیید نهایی: "${name}" از لیست فعال حذف و به بخش "بایگانی ${META.entityPlural||'شاگردان'}" منتقل می‌شود. ادامه می‌دهی؟`)) return;
  await window.api.students.setArchived({ id, archived: true });
  showToast(`${name} به بایگانی منتقل شد ✓`, 'success');
  await renderSessions();
}

async function unarchiveStudent(id, name) {
  await window.api.students.setArchived({ id, archived: false });
  showToast(`${name} به مشتری تبدیل و به پرونده‌ها منتقل شد ✓`, 'success');
  await renderArchive();
}

let archiveStudents = [];
let archiveColumns = [];
let archiveVisibleRows = [];
const archiveSelectedIds = new Set();
let archiveCategoryOptions = ['شخصی','فروشگاهی','تولیدی','خدماتی','تعمیراتی'];
let archiveStatusOptions = ['تماس نگرفته','تماس گرفته شد','جلسه','نیازمند پیگیری','مشتری شد','ناموفق'];
const ARCHIVE_DEFAULT_COLUMNS = ['نام و نام خانوادگی','شماره تماس','نام مجموعه','دسته‌بندی','نحوه آشنایی','وضعیت ارتباط','شهر','توضیحات'];

function archiveHeaderKey(v){return String(v||'').trim().replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\s‌_\-\/]/g,'').toLowerCase();}
function archiveFieldForHeader(label){
  const k=archiveHeaderKey(label);
  const aliases={
    full_name:['نامونامخانوادگی','نامکامل','fullname'],name:['نام','firstname'],lname:['نامخانوادگی','فامیلی','lastname'],phone:['شمارهتماس','شمارهتلفن','موبایل','تلفن','phone','mobile'],
    organization_name:['ناممجموعه','مجموعه','شرکت','organization','company'],customer_category:['دستهبندی','دسته','category'],referral_source:['نحوهآشنایی','طریقآشنایی','معرف','منبعآشنایی','referralsource','source'],description:['توضیحات','آدرس','آدرستوضیحات','آدرسوتوضیحات','نشانی','نیازیامشکلاصلی','نیازاصلی','مشکلاصلی','description','address','need','mainneed'],
    relationship_status:['وضعیتارتباط','وضعیتتماس','relationshipstatus','status'],
    date_jalali:['تاریخرزرو','تاریخشروعهمکاری','شروعهمکاری','تاریخثبتنام','تاریخ','date','startdate']
  };
  return Object.keys(aliases).find(field=>aliases[field].includes(k))||'';
}
function normalizeArchiveColumns(columns){const result=[];let hasDescription=false;(columns||[]).map(x=>String(x||'').trim()).filter(Boolean).forEach(label=>{if(archiveFieldForHeader(label)==='description'){if(hasDescription)return;hasDescription=true;result.push('توضیحات');return;}result.push(label);});return result;}
function archiveColumnValue(s,label){const field=archiveFieldForHeader(label);if(field==='full_name')return [s.name,s.lname].filter(Boolean).join(' ').trim();if(field)return field==='date_jalali'?(DateService.disp(s[field])||''):String(s[field]??'');return String(s.archive_data?.[archiveHeaderKey(label)]??'');}
function archiveColumnClass(label){const field=archiveFieldForHeader(label);if(archiveHeaderKey(label)==='شهر')return 'archive-col-city';return ({full_name:'archive-col-name',name:'archive-col-name',lname:'archive-col-name',phone:'archive-col-phone',organization_name:'archive-col-org',customer_category:'archive-col-category',referral_source:'archive-col-referral',description:'archive-col-need',relationship_status:'archive-col-status',date_jalali:'archive-col-date'})[field]||'';}
function archiveStatusClass(value){const k=archiveHeaderKey(value);return ({'نیازمندپیگیری':'archive-status-followup','ناموفق':'archive-status-failed','تماسگرفتهشد':'archive-status-contacted','جلسه':'archive-status-meeting'})[k]||'';}
function archiveStatusBadge(value){const label=String(value||'').trim();if(!label)return '<span class="archive-status-badge is-neutral">—</span>';const k=archiveHeaderKey(label),cls=({'تماسنگرفته':'is-uncontacted','تماسگرفتهشد':'is-contacted','جلسه':'is-meeting','نیازمندپیگیری':'is-followup','مشتریشد':'is-customer','ناموفق':'is-failed'})[k]||'is-neutral';return `<span class="archive-status-badge ${cls}">${escapeHtml(label)}</span>`;}
function sortArchiveFieldReferralsFirst(rows){return [...(rows||[])].sort((a,b)=>Number(archiveHeaderKey(b.referral_source)==='میدانی')-Number(archiveHeaderKey(a.referral_source)==='میدانی'));}
function archiveExtraFieldsHtml(s={},scope='archive',excluded=[]){const excludedKeys=excluded.map(archiveHeaderKey);return archiveColumns.filter(c=>!archiveFieldForHeader(c)&&!excludedKeys.includes(archiveHeaderKey(c))).map(c=>{const key=archiveHeaderKey(c),value=String(s.archive_data?.[key]??'');return `<div class="form-group"><label class="form-label">${escapeHtml(c)}</label><input class="form-input" data-archive-extra data-archive-scope="${scope}" data-archive-key="${escapeHtml(key)}" value="${escapeHtml(value)}"></div>`;}).join('');}
function collectArchiveExtraData(scope,base={}){const data={...(base||{})};document.querySelectorAll(`[data-archive-extra][data-archive-scope="${scope}"]`).forEach(input=>{data[input.dataset.archiveKey]=input.value.trim();});return data;}

async function renderArchive() {
  updateTopbarActions('');
  const archiveData = await Promise.all([window.api.students.getArchived(),window.api.students.getArchiveColumns(),window.api.students.getArchiveOptions()]);
  archiveStudents=sortArchiveFieldReferralsFirst(archiveData[0]);archiveColumns=[...ARCHIVE_DEFAULT_COLUMNS];archiveCategoryOptions=archiveData[2].categories;archiveStatusOptions=archiveData[2].statuses;
  const html = `${studentSectionNav('archive')}<div class="table-card">
    <div class="archive-toolbar">
      <div><div class="title">🗃 فهرست بایگانی</div><div class="archive-sheet-count" id="archive-count">${fa(archiveStudents.length)} نفر</div></div>
      <input class="form-input archive-search" id="archive-search" placeholder="جست‌وجو در تمام ستون‌های بایگانی..." oninput="filterArchiveTable(this.value)">
      <div class="archive-toolbar-actions"><button class="btn btn-primary btn-sm" onclick="openArchiveImport()">📥 ورود از Excel</button><button class="btn btn-ghost btn-sm" onclick="openArchivePersonModal()">＋ افزودن دستی</button><button class="btn btn-ghost btn-sm" onclick="exportArchiveExcel()">⬇ دانلود Excel</button></div>
    </div>
    <div class="archive-bulkbar" id="archive-bulkbar"><span class="archive-selected-count" id="archive-selected-count"></span><button class="btn btn-ghost btn-sm" onclick="selectAllArchiveRows()">☑ انتخاب همه</button><button class="btn btn-primary btn-sm" onclick="bulkConvertArchive()">✓ تبدیل به مشتری</button><button class="btn btn-ghost btn-sm" onclick="bulkSetArchiveCategory()">🏷 دسته‌بندی</button><button class="btn btn-ghost btn-sm" onclick="bulkSetArchiveStatus()">📞 وضعیت ارتباط</button><button class="btn btn-danger btn-sm" onclick="bulkDeleteArchive()">🗑 حذف کامل</button><button class="btn btn-ghost btn-sm" onclick="clearArchiveSelection()">لغو انتخاب</button></div>
    <div class="archive-sheet"><table dir="rtl"><thead><tr><th class="archive-select-col"><input class="archive-check" id="archive-check-all" type="checkbox" aria-label="انتخاب همه" onchange="toggleArchiveSelectAll(this.checked)"></th><th class="archive-number-col">ردیف</th>${archiveColumns.map(c=>`<th class="${archiveColumnClass(c)}">${escapeHtml(c)}</th>`).join('')}<th class="archive-operation-col"><span class="archive-operation-title">عملیات</span></th></tr></thead><tbody id="archive-tbody"></tbody></table></div>
    <div class="archive-mobile-list" id="archive-mobile-list"></div>
  </div>`;
  setContent(html); paintArchiveRows(archiveStudents);
}

function paintArchiveRows(rows) {
  const body=document.getElementById('archive-tbody'),mobile=document.getElementById('archive-mobile-list'); if(!body)return;
  archiveVisibleRows=rows;
  document.getElementById('archive-count').textContent=`${fa(rows.length)} نفر`;
  body.innerHTML=rows.length?rows.map((s,index)=>`<tr class="${archiveStatusClass(s.relationship_status)}" onclick="openArchivePersonDetail(${s.id})">
    <td class="archive-select-col" onclick="event.stopPropagation()"><input class="archive-check" type="checkbox" ${archiveSelectedIds.has(Number(s.id))?'checked':''} aria-label="انتخاب این فرد" onchange="toggleArchiveSelection(${s.id},this.checked)"></td>
    <td class="archive-number-col">${fa(index+1)}</td>
    ${archiveColumns.map(c=>{const v=archiveColumnValue(s,c),isStatus=archiveFieldForHeader(c)==='relationship_status';return `<td class="${archiveColumnClass(c)}" title="${escapeHtml(v)}">${isStatus?archiveStatusBadge(v):escapeHtml(v||'—')}</td>`;}).join('')}
    <td class="archive-operation-col" onclick="event.stopPropagation()"><div class="archive-actions"><button class="btn btn-primary btn-sm" onclick="convertArchiveToCustomer(${s.id})">✓ تبدیل به مشتری</button><button class="btn btn-ghost btn-sm" onclick="openArchivePersonModal(${s.id})">✏️</button><button class="btn btn-danger btn-sm" onclick="deleteArchivePerson(${s.id})">🗑</button></div></td></tr>`).join('')
    :`<tr><td colspan="${archiveColumns.length+3}"><div class="empty"><span>📦</span>هنوز فردی در بایگانی ثبت نشده؛ دستی اضافه کنید یا فایل Excel وارد کنید.</div></td></tr>`;
  if(mobile)mobile.innerHTML=rows.length?rows.map(s=>{const fullName=`${escapeHtml(s.name||'')} ${escapeHtml(s.lname||'')}`.trim()||'بدون نام',city=archiveColumnValue(s,'شهر')||'—',category=s.customer_category||'—',referral=s.referral_source||'متفرقه',startDate=DateService.disp(s.date_jalali)||'—',phone=String(s.phone||'').trim(),tel=phone.replace(/[^\d+]/g,'');return `<article class="archive-mobile-card" data-archive-mobile-id="${s.id}"><div class="archive-mobile-head"><div class="archive-mobile-title">${escapeHtml(fullName)}</div>${archiveStatusBadge(s.relationship_status)}</div><div class="archive-mobile-sub">${escapeHtml(s.organization_name||'بدون نام مجموعه')}</div><div class="archive-mobile-phone">☎ ${escapeHtml(phone||'—')}</div><div class="archive-mobile-meta">${escapeHtml(category)} · ${escapeHtml(city)} · ${escapeHtml(referral)}</div><button type="button" class="archive-details-toggle" aria-expanded="false" onclick="toggleArchiveMobileCard(${s.id},this)">جزئیات <span class="archive-details-chevron">⌄</span></button><div class="archive-mobile-quick-actions">${tel?`<a class="btn btn-ghost btn-sm" href="tel:${escapeHtml(tel)}">☎ تماس</a>`:'<button class="btn btn-ghost btn-sm" disabled>☎ تماس</button>'}<button type="button" class="btn btn-ghost btn-sm" onclick="markArchiveFollowup(${s.id})">پیگیری</button><button type="button" class="btn btn-ghost btn-sm" onclick="convertArchiveToCustomer(${s.id})">تبدیل به مشتری</button><button type="button" class="btn btn-ghost btn-sm archive-more-btn" aria-label="عملیات بیشتر" onclick="openArchiveMobileMore(${s.id})">⋮</button></div><div class="archive-mobile-expand"><div class="archive-mobile-grid"><div class="archive-mobile-field"><small>نحوه آشنایی</small><span>${escapeHtml(referral)}</span></div><div class="archive-mobile-field"><small>تاریخ شروع همکاری</small><span>${escapeHtml(startDate)}</span></div><div class="archive-mobile-field full"><small>توضیحات</small><span title="${escapeHtml(s.description||'')}">${escapeHtml(s.description||'—')}</span></div></div><div class="archive-mobile-actions"><button class="btn btn-ghost btn-sm" onclick="openArchivePersonModal(${s.id})">✏️ ویرایش اطلاعات</button></div></div></article>`;}).join(''):`<div class="empty"><span>📦</span>هنوز فردی در بایگانی ثبت نشده</div>`;
  updateArchiveBulkbar();
}

function toggleArchiveMobileCard(id,button){const card=document.querySelector(`[data-archive-mobile-id="${id}"]`);if(!card)return;const expanded=card.classList.toggle('expanded');button?.setAttribute('aria-expanded',String(expanded));}
async function markArchiveFollowup(id){const person=archiveStudents.find(x=>Number(x.id)===Number(id));if(!person)return;if(archiveHeaderKey(person.relationship_status)==='نیازمندپیگیری'){showToast('این مخاطب از قبل نیازمند پیگیری است','info');return;}await window.api.students.bulkArchiveAction({ids:[id],action:'status',value:'نیازمند پیگیری'});showToast('وضعیت به «نیازمند پیگیری» تغییر کرد ✓','success');await renderArchive();}
function openArchiveMobileMore(id){const person=archiveStudents.find(x=>Number(x.id)===Number(id));if(!person)return;const fullName=[person.name,person.lname].filter(Boolean).join(' ').trim()||'این مخاطب';openModal('عملیات بیشتر',`<div style="font-size:12px;color:var(--text2)">${escapeHtml(fullName)}</div>`,[{label:'✏️ ویرایش اطلاعات',cls:'btn-ghost',action:`closeModal();openArchivePersonModal(${id})`},{label:'🗑 حذف مخاطب',cls:'btn-danger',action:`closeModal();deleteArchivePerson(${id})`},{label:'انصراف',cls:'btn-ghost',action:'closeModal()'}]);}

function filterArchiveTable(value){const q=String(value||'').trim().toLowerCase();paintArchiveRows(!q?archiveStudents:archiveStudents.filter(s=>archiveColumns.some(c=>archiveColumnValue(s,c).toLowerCase().includes(q))));}

function updateArchiveBulkbar(){const bar=document.getElementById('archive-bulkbar'),count=document.getElementById('archive-selected-count'),all=document.getElementById('archive-check-all');const n=archiveSelectedIds.size;if(bar)bar.classList.toggle('active',n>0);if(count)count.textContent=`${fa(n)} مورد انتخاب شده`;if(all){const visibleIds=archiveVisibleRows.map(s=>Number(s.id));const selectedVisible=visibleIds.filter(id=>archiveSelectedIds.has(id)).length;all.checked=visibleIds.length>0&&selectedVisible===visibleIds.length;all.indeterminate=selectedVisible>0&&selectedVisible<visibleIds.length;}}
function toggleArchiveSelection(id,checked){if(checked)archiveSelectedIds.add(Number(id));else archiveSelectedIds.delete(Number(id));paintArchiveRows(archiveVisibleRows);}
function toggleArchiveSelectAll(checked){archiveVisibleRows.forEach(s=>checked?archiveSelectedIds.add(Number(s.id)):archiveSelectedIds.delete(Number(s.id)));paintArchiveRows(archiveVisibleRows);}
function selectAllArchiveRows(){archiveStudents.forEach(s=>archiveSelectedIds.add(Number(s.id)));paintArchiveRows(archiveVisibleRows);showToast(`${fa(archiveSelectedIds.size)} مورد انتخاب شد`,'success');}
function clearArchiveSelection(){archiveSelectedIds.clear();paintArchiveRows(archiveVisibleRows);}
function selectedArchiveIds(){return [...archiveSelectedIds];}
async function bulkConvertArchive(){const ids=selectedArchiveIds();if(!ids.length)return;if(!confirm(`${fa(ids.length)} مورد انتخاب‌شده به پرونده‌های مشتریان منتقل شوند؟`))return;await window.api.students.bulkArchiveAction({ids,action:'convert'});archiveSelectedIds.clear();showToast(`${fa(ids.length)} مورد به مشتری تبدیل شد ✓`,'success');await renderArchive();}
function bulkSetArchiveCategory(){if(!archiveSelectedIds.size)return;openModal('تغییر دسته‌بندی گروهی',`<div class="form-group"><label class="form-label">دسته‌بندی جدید</label><select class="form-select" id="archive-bulk-category">${archiveCategoryOptions.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('')}</select></div>`,[{label:'اعمال به موارد انتخاب‌شده',cls:'btn-primary',action:'applyBulkArchiveCategory()'},{label:'انصراف',cls:'btn-ghost',action:'closeModal()'}]);}
async function applyBulkArchiveCategory(){const ids=selectedArchiveIds(),value=document.getElementById('archive-bulk-category')?.value;if(!ids.length||!value)return;await window.api.students.bulkArchiveAction({ids,action:'category',value});closeModal();archiveSelectedIds.clear();showToast('دسته‌بندی گروهی اعمال شد ✓','success');await renderArchive();}
function bulkSetArchiveStatus(){if(!archiveSelectedIds.size)return;openModal('تغییر گروهی وضعیت ارتباط',`<div class="form-group"><label class="form-label">وضعیت ارتباط جدید</label><select class="form-select" id="archive-bulk-status">${archiveStatusOptions.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('')}</select></div>`,[{label:'اعمال به موارد انتخاب‌شده',cls:'btn-primary',action:'applyBulkArchiveStatus()'},{label:'انصراف',cls:'btn-ghost',action:'closeModal()'}]);}
async function applyBulkArchiveStatus(){const ids=selectedArchiveIds(),value=document.getElementById('archive-bulk-status')?.value;if(!ids.length||!value)return;await window.api.students.bulkArchiveAction({ids,action:'status',value});closeModal();archiveSelectedIds.clear();showToast('وضعیت ارتباط گروهی اعمال شد ✓','success');await renderArchive();}
async function bulkDeleteArchive(){const ids=selectedArchiveIds();if(!ids.length)return;if(!confirm(`${fa(ids.length)} مورد انتخاب‌شده و تمام اطلاعات مرتبط برای همیشه حذف شوند؟`))return;await window.api.students.bulkArchiveAction({ids,action:'delete'});archiveSelectedIds.clear();showToast(`${fa(ids.length)} مورد حذف شد`,'error');await renderArchive();}

function archiveComboField(id,label,value,options,kind,placeholder=''){const selected=String(value||'');const choices=[...options];if(selected&&!choices.includes(selected))choices.unshift(selected);return `<div class="form-group"><label class="form-label">${label}</label><div style="display:flex;gap:6px"><select class="form-select" style="flex:1;min-width:0" id="${id}">${kind==='status'?`<option value="">${escapeHtml(placeholder||'— انتخاب کنید —')}</option>`:''}${choices.map(x=>`<option value="${escapeHtml(x)}" ${x===selected?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select><button type="button" class="btn btn-ghost btn-sm" style="flex-shrink:0" onclick="addArchiveComboOption('${kind}','${id}')">＋ افزودن</button></div></div>`;}
function archiveFormHtml(s={}){const description=s.description||[s.address,s.main_need].filter(Boolean).join('\n'),fullName=[s.name,s.lname].filter(Boolean).join(' ').trim(),cityKey=archiveHeaderKey('شهر'),city=String(s.archive_data?.[cityKey]??'');return `<div class="form-grid"><div class="form-group"><label class="form-label">نام و نام خانوادگی</label><input class="form-input" id="ar-full-name" value="${escapeHtml(fullName)}"></div><div class="form-group"><label class="form-label">شماره تماس</label><input class="form-input" id="ar-phone" value="${escapeHtml(s.phone||'')}"></div><div class="form-group"><label class="form-label">نام مجموعه</label><input class="form-input" id="ar-org" value="${escapeHtml(s.organization_name||'')}"></div>${archiveComboField('ar-category','دسته‌بندی',s.customer_category||'شخصی',archiveCategoryOptions,'category','انتخاب کنید یا بنویسید') }<div class="form-group"><label class="form-label">نحوه آشنایی</label><input class="form-input" id="ar-referral-source" value="${escapeHtml(s.referral_source||'متفرقه')}" placeholder="مثلاً معرفی، اینستاگرام، متفرقه"></div>${archiveComboField('ar-relationship-status','وضعیت ارتباط',s.relationship_status||'',archiveStatusOptions,'status','انتخاب کنید یا بنویسید')}<div class="form-group"><label class="form-label">شهر</label><input class="form-input" data-archive-extra data-archive-scope="archive" data-archive-key="${escapeHtml(cityKey)}" value="${escapeHtml(city)}"></div><div class="form-group full"><label class="form-label">توضیحات</label><textarea class="form-textarea" id="ar-description" rows="3">${escapeHtml(description)}</textarea></div>${archiveExtraFieldsHtml(s,'archive',['نوع فعالیت','شهر'])}</div>`;}

async function addArchiveComboOption(kind,inputId){const label=kind==='status'?'وضعیت ارتباط جدید':'دسته‌بندی جدید';const value=prompt(`${label} را وارد کنید:`)?.trim();if(!value)return;await window.api.students.addArchiveOption({kind,value});const input=document.getElementById(inputId);if(input&&!Array.from(input.options).some(x=>x.value===value)){const option=document.createElement('option');option.value=value;option.textContent=value;input.appendChild(option);}if(input)input.value=value;if(kind==='status'){if(!archiveStatusOptions.includes(value))archiveStatusOptions.push(value);}else if(!archiveCategoryOptions.includes(value))archiveCategoryOptions.push(value);}

function openArchivePersonModal(id=null){const s=id?archiveStudents.find(x=>x.id===id):{};openModal(id?'ویرایش فرد بایگانی‌شده':'افزودن فرد به بایگانی',archiveFormHtml(s),[{label:'ذخیره',cls:'btn-primary',action:`saveArchivePerson(${id||'null'})`},{label:'انصراف',cls:'btn-ghost',action:'closeModal()'}]);initDatePickers();}
async function saveArchivePerson(id){const old=id?archiveStudents.find(x=>x.id===id):null,fullName=document.getElementById('ar-full-name').value.trim().replace(/\s+/g,' '),oldFullName=[old?.name,old?.lname].filter(Boolean).join(' ').trim();let name='',lname='';if(old&&fullName===oldFullName){name=old.name||'';lname=old.lname||'';}else{const parts=fullName.split(' ').filter(Boolean);name=parts.shift()||'';lname=parts.join(' ');}const data={name,lname,phone:document.getElementById('ar-phone').value.trim(),organization_name:document.getElementById('ar-org').value.trim(),customer_category:document.getElementById('ar-category').value.trim()||'شخصی',referral_source:document.getElementById('ar-referral-source').value.trim()||'متفرقه',description:document.getElementById('ar-description').value.trim(),relationship_status:document.getElementById('ar-relationship-status').value.trim(),date:old?.date_jalali||'',archive_data:collectArchiveExtraData('archive',old?.archive_data||{}),packages:[]};if(id){await window.api.students.update({...data,id,packages:old?.packages||[]});}else await window.api.students.addArchivedBulk([data]);closeModal();showToast('در بایگانی ذخیره شد ✓','success');await renderArchive();}
function openArchivePersonDetail(id){const s=archiveStudents.find(x=>x.id===id);if(!s)return;openModal(`${escapeHtml(s.name)} ${escapeHtml(s.lname)}`,`<div class="detail-section">${archiveColumns.map(c=>`<div class="detail-row"><span class="detail-key">${escapeHtml(c)}</span><span class="detail-val">${escapeHtml(archiveColumnValue(s,c)||'—')}</span></div>`).join('')}</div>`,[{label:'✓ تبدیل به مشتری',cls:'btn-primary',action:`closeModal();convertArchiveToCustomer(${id})`},{label:'✏️ ویرایش',cls:'btn-ghost',action:`closeModal();openArchivePersonModal(${id})`},{label:'🗑 حذف کامل',cls:'btn-danger',action:`closeModal();deleteArchivePerson(${id})`}]);}
async function convertArchiveToCustomer(id){const s=archiveStudents.find(x=>x.id===id);if(!s)return;if(!confirm(`«${s.name} ${s.lname}» به پرونده‌های مشتریان منتقل شود؟`))return;await unarchiveStudent(id,`${s.name} ${s.lname}`);}
async function deleteArchivePerson(id){const s=archiveStudents.find(x=>x.id===id);if(!s||!confirm(`«${s.name} ${s.lname}» و تمام اطلاعات مرتبط برای همیشه حذف شود؟`))return;await window.api.students.delete(id);showToast('فرد از بایگانی حذف شد','error');await renderArchive();}

let _xlsxLoaderPromise=null;
function loadXlsxLibrary(){
  if(typeof XLSX!=='undefined')return Promise.resolve(XLSX);
  if(_xlsxLoaderPromise)return _xlsxLoaderPromise;
  _xlsxLoaderPromise=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='/xlsx.full.min.js';
    script.async=true;
    script.onload=()=>typeof XLSX!=='undefined'?resolve(XLSX):reject(new Error('کتابخانه Excel بارگذاری نشد'));
    script.onerror=()=>reject(new Error('دانلود کتابخانه Excel ممکن نشد'));
    document.head.appendChild(script);
  }).catch(error=>{_xlsxLoaderPromise=null;throw error;});
  return _xlsxLoaderPromise;
}

// Keep Excel out of the critical startup path, then warm it quietly for imports.
setTimeout(()=>loadXlsxLibrary().catch(()=>{}),5000);

async function exportArchiveExcel(){
  if(!archiveStudents.length){showToast('فهرست بایگانی خالی است','error');return;}
  const rows=[archiveColumns,...archiveStudents.map(s=>archiveColumns.map(c=>archiveColumnValue(s,c)))];
  try{
    await loadXlsxLibrary();
    const wb=XLSX.utils.book_new();
    const ws=XLSX.utils.aoa_to_sheet(rows);
    ws['!cols']=archiveColumns.map((c,i)=>({wch:Math.min(45,Math.max(12,String(c).length+3,...archiveStudents.slice(0,100).map(s=>String(archiveColumnValue(s,c)||'').length+2)))}));
    if(!ws['!views'])ws['!views']=[];
    ws['!views'].push({rightToLeft:true});
    XLSX.utils.book_append_sheet(wb,ws,'فهرست بایگانی');
    XLSX.writeFile(wb,'فهرست-بایگانی.xlsx',{compression:true});
    showToast('فایل Excel بایگانی دانلود شد ✓','success');
  }catch(e){showToast('دانلود فایل ممکن نشد','error');}
}

let archiveImportRows=[],archiveImportColumns=[];
function openArchiveImport(){openModal('📥 افزودن گروهی با Excel',`<div class="archive-import-help">ردیف اول فایل باید عنوان ستون‌ها باشد. <b>عنوان، ترتیب و تمام ستون‌های فایل شما عیناً در جدول بایگانی نمایش داده می‌شود</b> و ستون ناشناخته‌ای حذف نخواهد شد.<br>برای تبدیل درست به پرونده، وجود ستون نام یا نام خانوادگی پیشنهاد می‌شود.</div><input type="file" id="archive-file" class="form-input" accept=".xlsx,.xls,.csv" onchange="readArchiveImportFile(this.files[0])"><div id="archive-import-status" style="margin-top:12px"></div>`,[{label:'ثبت و استفاده از همین ستون‌ها',cls:'btn-primary',action:'commitArchiveImport()'},{label:'انصراف',cls:'btn-ghost',action:'closeModal()'}]);archiveImportRows=[];archiveImportColumns=[];}
function mapArchiveImportRow(row){const data={};Object.keys(row||{}).forEach(label=>data[archiveHeaderKey(label)]=String(row[label]??'').trim());const result={archive_data:data};Object.keys(row||{}).forEach(label=>{const field=archiveFieldForHeader(label),value=String(row[label]??'').trim();if(!field)return;const target=field==='date_jalali'?'date':field;if(target==='description'&&result.description&&value&&!result.description.split('\n').includes(value))result.description+=`\n${value}`;else if(value||result[target]===undefined)result[target]=value;});result.phone=enDigits(result.phone||'').replace(/\.0$/,'');result.referral_source=String(result.referral_source||'').trim()||'متفرقه';return result;}
async function readArchiveImportFile(file){if(!file)return;const status=document.getElementById('archive-import-status');status.innerHTML='در حال خواندن فایل...';try{if(typeof XLSX==='undefined')throw new Error('کتابخانه Excel بارگذاری نشده');const buffer=await file.arrayBuffer();const wb=/\.csv$/i.test(file.name)?XLSX.read(new TextDecoder('utf-8').decode(buffer).replace(/^\uFEFF/,''),{type:'string'}):XLSX.read(buffer,{type:'array',cellDates:false});const sheet=wb.Sheets[wb.SheetNames[0]];const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false});const headerCells=matrix.shift()||[];const columnDefs=headerCells.map((x,index)=>({label:String(x||'').trim(),index})).filter(x=>x.label);archiveImportColumns=columnDefs.map(x=>x.label);if(!archiveImportColumns.length)throw new Error('ردیف عنوان ستون‌ها پیدا نشد');const raw=matrix.map(values=>Object.fromEntries(columnDefs.map(c=>[c.label,values[c.index]??''])));archiveImportRows=raw.map(mapArchiveImportRow).filter(r=>r.name||r.lname||Object.values(r.archive_data||{}).some(Boolean));status.innerHTML=`<div style="margin-bottom:8px;color:var(--green)">${fa(archiveImportRows.length)} ردیف و ${fa(archiveImportColumns.length)} ستون آماده ثبت است.</div><div class="archive-preview"><table dir="rtl"><thead><tr>${archiveImportColumns.map(c=>`<th>${escapeHtml(c)}</th>`).join('')}</tr></thead><tbody>${raw.slice(0,100).map(row=>`<tr>${archiveImportColumns.map(c=>`<td>${escapeHtml(row[c]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${archiveImportRows.length>100?'<div style="margin-top:6px;color:var(--text3)">فقط ۱۰۰ ردیف اول در پیش‌نمایش نشان داده شده است.</div>':''}`;}catch(e){archiveImportRows=[];archiveImportColumns=[];status.innerHTML=`<div style="color:var(--red)">خواندن فایل ممکن نشد: ${escapeHtml(e.message||'فرمت نامعتبر')}</div>`;}}
async function commitArchiveImport(){if(!archiveImportRows.length||!archiveImportColumns.length){showToast('ابتدا یک فایل معتبر انتخاب کنید','error');return;}const result=await window.api.students.addArchivedBulk({rows:archiveImportRows,columns:archiveImportColumns});closeModal();showToast(`${fa(result.count)} نفر با ساختار ستون‌های فایل به بایگانی افزوده شد ✓`,'success');await renderArchive();}

// ── Full sessions summary (journal-style) ─────────────────────────────────────
async function openSessionsSummary(studentId, displayName) {
  const groups = await window.api.sessions.getAll();
  const g = groups.find(x => x.student_id === studentId);
  const sessions = (g?.sessions || []).slice().sort((a,b) => jalaliKey(a.date_jalali) - jalaliKey(b.date_jalali) || a.id - b.id);
  const copyText = sessions.length === 0
    ? `خلاصه کل ${META.sessionPlural||'جلسات'} — ${displayName}\n\nهنوز ${META.sessionSingular||'جلسه'}‌ای ثبت نشده`
    : [
        `خلاصه کل ${META.sessionPlural||'جلسات'} — ${displayName}`,
        '',
        ...sessions.map(s => [
          `${DateService.disp(s.date_jalali)}${s.importance==='key'?' ⭐':''}`,
          s.title || '(بدون عنوان)',
          s.note ? String(s.note).trim() : '',
          s.extra_note ? String(s.extra_note).trim() : ''
        ].filter(Boolean).join('\n'))
      ].join('\n\n--------------------\n\n');
  window._sessionsSummaryCopyText = copyText;

  const body = sessions.length === 0
    ? `<p style="font-size:12px;color:var(--text3)">هنوز ${META.sessionSingular||'جلسه'}‌ای ثبت نشده</p>`
    : sessions.map(s => `
      <div class="summary-entry">
        <div class="summary-entry-date">${DateService.disp(s.date_jalali)}${s.importance==='key'?' ⭐':''}</div>
        <div class="summary-entry-title">${escapeHtml(s.title) || '(بدون عنوان)'}</div>
        ${s.note ? `<div class="summary-entry-note">${renderRich(s.note)}</div>` : ''}
        ${s.extra_note ? `<div class="summary-entry-extra">${renderRich(s.extra_note)}</div>` : ''}
      </div>`).join('');

  openModal(`📋 خلاصه کل ${META.sessionPlural||'جلسات'} — ${escapeHtml(displayName)}`, `
    <div style="display:flex;justify-content:flex-start;margin-bottom:10px">
      <button class="btn btn-ghost btn-sm" onclick="copyToClipboard(window._sessionsSummaryCopyText || '', 'کل متن خلاصه کپی شد ✓')" style="min-width:150px">📋 کپی کل متن</button>
    </div>
    <div class="detail-section" style="max-height:60vh;overflow-y:auto">${body}</div>
  `, [
    { label: '📋 کپی کل متن', cls: 'btn-ghost', action: `copyToClipboard(window._sessionsSummaryCopyText || '', 'کل متن خلاصه کپی شد ✓')` },
    { label: 'بستن', cls: 'btn-primary', action: 'closeModal()' },
  ]);
}

// ── Performance Evaluation Module ────────────────────────────────────────────

function evalKey(studentId) { return `eval_forms_${studentId}`; }
function loadEvalForms(studentId) {
  let forms;
  // از _db بخون (sync با سرور)
  if (_db && _db.eval_forms && _db.eval_forms[studentId]) {
    forms = _db.eval_forms[studentId];
  } else {
    // migration: داده قدیمی localStorage رو منتقل کن
    try {
      const local = JSON.parse(localStorage.getItem(evalKey(studentId)) || '[]');
      if (local.length > 0) {
        saveEvalForms(studentId, local);
        localStorage.removeItem(evalKey(studentId));
      }
      forms = local;
    } catch(e) { forms = []; }
  }
  // اطمینان از این‌که هر دوره یک id ثابت دارد (برای اتصال دستاوردها به دوره)
  let anyChanged = false;
  forms.forEach(f => {
    if (_ensurePeriodIds(f)) anyChanged = true;
    (f.rows || []).forEach(row => { if (!row.type) { row.type = 'score'; anyChanged = true; } });
    // Migration for forms selected before raw imported content was preserved.
    // Match only imported case forms with the same title and extracted field labels.
    if (!f.source_case_form_id) {
      const candidates = (_db?.case_forms || []).filter(template =>
        (template.creation_mode || 'import') === 'import' && String(template.title || '').trim() === String(f.title || '').trim()
      );
      const template = candidates.find(candidate => {
        const extracted = _caseFormEvalRows(candidate).map(row => row.label);
        const existing = (f.rows || []).map(row => row.label);
        return existing.length > 0 && existing.every(label => extracted.includes(label));
      });
      if (template) {
        f.source_case_form_id = template.id;
        f.source_case_form_mode = 'import';
        f.source_case_form_content = template.content || '';
        (f.periods || []).forEach(period => {
          if (period.form_content === undefined) period.form_content = template.content || '';
        });
        anyChanged = true;
      }
    }
  });
  if (anyChanged) saveEvalForms(studentId, forms);
  return forms;
}
function saveEvalForms(studentId, forms) {
  if (!_db) { localStorage.setItem(evalKey(studentId), JSON.stringify(forms)); return; }
  if (!_db.eval_forms) _db.eval_forms = {};
  _db.eval_forms[studentId] = forms;
  _save();
}
function genEvalId() { return Date.now() + Math.floor(Math.random()*1000); }

// ── Achievement ↔ Evaluation-Period linking helpers ──────────────────────
// Ensures every period has a stable id (older data may not have one yet).
function _ensurePeriodIds(form) {
  let changed = false;
  (form.periods || []).forEach(p => { if (!p.id) { p.id = genEvalId() + Math.floor(Math.random()*1000); changed = true; } });
  return changed;
}

// Flat, date-sorted (newest first) list of every period across every eval form of a student.
// An open period (date === null, not yet closed) is treated as the newest/current one.
function _studentAllPeriodsFlat(studentId) {
  const forms = loadEvalForms(studentId);
  let anyChanged = false;
  const flat = [];
  forms.forEach(f => {
    if (_ensurePeriodIds(f)) anyChanged = true;
    (f.periods || []).forEach((p, idx) => flat.push({ formId: f.id, formTitle: f.title, pid: p.id, date: p.date, idx }));
  });
  if (anyChanged) saveEvalForms(studentId, forms);
  flat.sort((a, b) => (b.date ? _jalaliKey(b.date) : Infinity) - (a.date ? _jalaliKey(a.date) : Infinity));
  return flat;
}

// Build <option>/<optgroup> markup for choosing an evaluation period (used in session forms).
function _buildEvalPeriodSelectOptions(studentId, selectedFormId, selectedPid) {
  const forms = loadEvalForms(studentId);
  let anyChanged = false;
  let html = `<option value="">— بدون دوره ارزیابی —</option>`;
  forms.forEach(f => {
    if (_ensurePeriodIds(f)) anyChanged = true;
    if (!f.periods || !f.periods.length) return;
    html += `<optgroup label="${escapeHtml(f.title)}">`;
    f.periods.forEach((p, idx) => {
      const val = `${f.id}:${p.id}`;
      const sel = (String(selectedFormId) === String(f.id) && String(selectedPid) === String(p.id)) ? 'selected' : '';
      html += `<option value="${val}" ${sel}>دوره ${fa(idx + 1)} · ${p.date || 'باز'}</option>`;
    });
    html += `</optgroup>`;
  });
  if (anyChanged) saveEvalForms(studentId, forms);
  return html;
}

// Default period to preselect in the session form = the most recent period overall.
function _defaultEvalPeriodValue(studentId) {
  const flat = _studentAllPeriodsFlat(studentId);
  return flat.length ? `${flat[0].formId}:${flat[0].pid}` : '';
}

// ── Automatic date → evaluation-period matching ───────────────────────────
// A period with a date has been CLOSED on that date — it covers every day up to and
// including that date. A period with date === null is OPEN (not yet closed) and covers
// everything from whenever the previous period closed up to today and beyond, until the
// coach closes it too. There is always at most one open period per form, and it's always
// the chronologically last one.
//
// The form used for automatic matching is the student's "primary" evaluation form: the one
// with an open period if any form has one, otherwise whichever form has the most recently
// closed period, otherwise the first form. This mirrors how most coaches use a single
// scorecard per student.
function _primaryEvalFormId(studentId) {
  const forms = loadEvalForms(studentId);
  if (!forms.length) return null;
  const withOpen = forms.find(f => (f.periods || []).some(p => !p.date));
  if (withOpen) return withOpen.id;
  let best = null, bestKey = -1;
  forms.forEach(f => {
    (f.periods || []).forEach(p => {
      if (!p.date) return;
      const k = _jalaliKey(p.date);
      if (k > bestKey) { bestKey = k; best = f.id; }
    });
  });
  return best !== null ? best : forms[0].id;
}

// Given a student + an achievement's date, find which evaluation period it belongs to.
// Returns { formId, pid }. Matches the earliest CLOSED period whose date is on/after the
// given date; if none, falls back to the OPEN period (if one exists); if there are no
// periods at all yet, pid is null.
function _matchPeriodForDate(studentId, dateStr) {
  const formId = _primaryEvalFormId(studentId);
  if (!formId) return { formId: null, pid: null };
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods || !form.periods.length) return { formId, pid: null };
  const dKey = _jalaliKey(dateStr);
  const closed = form.periods.filter(p => p.date).sort((a, b) => _jalaliKey(a.date) - _jalaliKey(b.date));
  const match = closed.find(p => _jalaliKey(p.date) >= dKey);
  if (match) return { formId, pid: match.id };
  const open = form.periods.find(p => !p.date);
  return { formId, pid: open ? open.id : null };
}

// Human-readable line shown under the achievements textarea explaining where this will land.
function _describeAutoPeriod(studentId, dateStr) {
  if (!studentId || !dateStr) return '';
  const { formId, pid } = _matchPeriodForDate(studentId, dateStr);
  if (!formId) return '🗓 هنوز دوره ارزیابی‌ای برای این فرد ساخته نشده — بعد از ساخت اولین دوره، این دستاورد خودکار به آن متصل می‌شود.';
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form) return '';
  if (!pid) return '🗓 هنوز دوره ارزیابی‌ای برای این فرد ساخته نشده — بعد از ساخت اولین دوره، این دستاورد خودکار به آن متصل می‌شود.';
  const idx = form.periods.findIndex(p => p.id === pid);
  const isOpen = !form.periods[idx].date;
  return isOpen
    ? `🗓 به‌صورت خودکار در دورهٔ فعلی «${escapeHtml(form.title)} · دوره ${fa(idx + 1)} (باز)» ثبت می‌شود.`
    : `🗓 به‌صورت خودکار در «${escapeHtml(form.title)} · دوره ${fa(idx + 1)}» ثبت می‌شود.`;
}

// Recomputes eval_form_id / eval_period_id for every achievement-bearing session of a
// student, based on the current period timeline. Call this whenever periods are created,
// closed, edited, or deleted, so every achievement always sits in the right period.
function _relinkAchievementsForStudent(studentId) {
  let changed = false;
  (_db.sessions || []).forEach(s => {
    if (s.student_id !== studentId) return;
    if (!s.achievements || !s.achievements.trim()) return;
    const { formId, pid } = _matchPeriodForDate(studentId, s.date_jalali);
    if (s.eval_form_id !== formId || s.eval_period_id !== pid) {
      s.eval_form_id = formId;
      s.eval_period_id = pid;
      changed = true;
    }
  });
  if (changed) _save();
}

// Refresh the small auto-period info line under the achievements field in the session form.
function _updateSesPeriodBadge() {
  const badge = document.getElementById('f-ses-period-badge');
  if (!badge) return;
  const studentId = +document.getElementById('f-ses-student')?.value || 0;
  const dateStr = document.getElementById('f-ses-date')?.value || '';
  badge.textContent = '';
  badge.innerHTML = _describeAutoPeriod(studentId, dateStr);
}

// Render the indicator "which score does this achievement relate to?" chip picker.
function _renderAchievementTagPicker(formId, selectedTags) {
  const container = document.getElementById('ses-ach-tags');
  if (!container) return;
  if (!formId) { container.innerHTML = ''; return; }
  const key = evalFindKey(formId);
  const forms = key ? _evalLoadByKey(key) : [];
  const form = forms.find(f => f.id === formId);
  if (!form) { container.innerHTML = ''; return; }
  const progressRows = (form.rows || []).filter(row => row.progress_indicator === true);
  if (!progressRows.length) { container.innerHTML = ''; return; }
  const sel = (selectedTags || []).map(String);
  container.innerHTML = `
    <div style="font-size:10px;color:var(--text3);margin:8px 0 4px">این دستاورد به کدام شاخص(ها) مربوط است؟ (اختیاری)</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px">
      ${progressRows.map(r => `
        <label style="display:flex;align-items:center;gap:4px;font-size:11px;background:var(--bg3);border:1px solid var(--border);border-radius:20px;padding:4px 10px;cursor:pointer">
          <input type="checkbox" value="${r.id}" class="ses-ach-tag-cb" ${sel.includes(String(r.id)) ? 'checked' : ''} style="width:13px;height:13px;accent-color:var(--accent2)">
          ${escapeHtml(r.label)}
        </label>`).join('')}
    </div>`;
}

function _getCheckedAchievementTags() {
  return Array.from(document.querySelectorAll('.ses-ach-tag-cb:checked')).map(cb => +cb.value);
}

// Small "🗓 دوره فلان · شاخص‌های فلان" chip shown under an achievement, wherever it's displayed.
function _achievementPeriodBadge(session) {
  if (!session.eval_form_id || !session.eval_period_id) return '';
  const key = evalFindKey(session.eval_form_id);
  const forms = key ? _evalLoadByKey(key) : [];
  const form = forms.find(f => f.id === session.eval_form_id);
  if (!form) return '';
  const idx = (form.periods || []).findIndex(p => p.id === session.eval_period_id);
  if (idx === -1) return '';
  const tagLabels = (session.achievement_tags || [])
    .map(tid => form.rows.find(r => r.id === tid)?.label)
    .filter(Boolean);
  const isOpen = !form.periods[idx].date;
  return `<div style="margin-top:8px;display:flex;flex-wrap:wrap;gap:6px">
    <span style="font-size:10px;background:${isOpen?'rgba(96,165,250,.1)':'rgba(62,207,142,.1)'};color:${isOpen?'var(--blue)':'var(--green)'};border-radius:20px;padding:3px 10px">🗓 ${escapeHtml(form.title)} · دوره ${fa(idx + 1)}${isOpen?' (باز)':''}</span>
    ${tagLabels.map(l => `<span style="font-size:10px;background:rgba(96,165,250,.1);color:var(--blue);border-radius:20px;padding:3px 10px">🏷 ${escapeHtml(l)}</span>`).join('')}
  </div>`;
}

// Called when the student (session form) changes → rebuild the indicator tag picker
// and refresh the auto-period info line. The evaluation period itself is no longer
// picked by the user — it's derived automatically from the session date (see
// _matchPeriodForDate / _updateSesPeriodBadge).
function _onSesStudentChangeRebuildPeriods(selectEl) {
  const studentId = +selectEl.value;
  _renderAchievementTagPicker(_primaryEvalFormId(studentId), []);
  _updateSesPeriodBadge();
  // اگر در فرم «ثبت جلسه» هستیم، خلاصهٔ قبل از جلسه، زیرعنوان مودال و نوار اطلاعات را هم به‌روز کن
  const preContainer = document.getElementById('ses-presummary-container');
  const subtitle = document.getElementById('ses-modal-subtitle');
  const student = (allStudents || []).find(s => s.id === studentId);
  if (subtitle && student) subtitle.textContent = `${META.entitySingular||'شاگرد'}: ${student.name} ${student.lname}`;
  if (preContainer && studentId) {
    _buildPreSessionSummary(studentId).then(html => { preContainer.innerHTML = html; });
  }
  _updateSesMetaSummary();
}

// Kept for the tag picker refresh; the period select this used to respond to no longer exists.
function _onSesPeriodChange(selectEl) {
  const studentId = +document.getElementById('f-ses-student')?.value || 0;
  if (!studentId) { const c = document.getElementById('ses-ach-tags'); if (c) c.innerHTML = ''; return; }
  _renderAchievementTagPicker(_primaryEvalFormId(studentId), []);
}

// ── helper: compute weighted total for one period ──
function evalPeriodTotal(form, period) {
  const scoreRows = (form.rows || []).filter(row => !row.type || row.type === 'score');
  if (!period || !scoreRows.length) return null;
  let ws = 0, wt = 0;
  scoreRows.forEach(row => {
    const s = parseFloat(period.scores[row.id]);
    if (!isNaN(s)) { ws += (s / row.maxScore) * (row.weight||1); wt += (row.weight||1); }
  });
  return wt > 0 ? Math.round((ws / wt) * 100) : null;
}

// ── resolve studentId from a formId ──
function _studentIdForForm(formId) {
  const key = evalFindKey(formId);
  return key ? parseInt(key.replace('eval_forms_', '')) : null;
}

// ── find form's student key ──
function evalFindKey(formId) {
  // اول در _db جستجو کن
  if (_db && _db.eval_forms) {
    for (const sid of Object.keys(_db.eval_forms)) {
      const forms = _db.eval_forms[sid];
      if (Array.isArray(forms) && forms.find(f => f.id === formId)) return evalKey(sid);
    }
  }
  // fallback localStorage
  for (const key of Object.keys(localStorage).filter(k => k.startsWith('eval_forms_'))) {
    try {
      const forms = _evalLoadByKey(key);
      if (forms.find(f => f.id === formId)) return key;
    } catch(e) {}
  }
  return null;
}

// ── eval storage helpers that work with key string ──
function _evalLoadByKey(key) {
  const sid = parseInt(key.replace('eval_forms_',''));
  return loadEvalForms(sid);
}
function _evalSaveByKey(key, forms) {
  const sid = parseInt(key.replace('eval_forms_',''));
  saveEvalForms(sid, forms);
}

// Convert a reusable case-form template into evaluation indicators.
// Checklist items and text fields are meaningful indicators; headings and guide text are not.
function _caseFormEvalRows(caseForm) {
  const content = String(caseForm?.content || '').replace(/\r/g, '');
  const rows = [];
  const addRow = (raw, type) => {
    let label = String(raw || '').trim()
      .replace(/^\*\*(.*?)\*\*$/, '$1')
      .replace(/[:：]\s*$/, '')
      .replace(/[.…·_ـ-]{3,}\s*$/, '')
      .trim();
    if (label && !rows.some(row => row.label === label && row.type === type)) rows.push({ label, type });
  };

  content.split('\n').forEach((line, index, lines) => {
    const checklist = line.match(/^\s*(?:[-+*]\s+)?\[[ xX]\]\s+(.+?)\s*$/);
    if (checklist) {
      const hasColon = /[:：]\s*$/.test(checklist[1]);
      addRow(checklist[1], hasColon ? 'description' : 'checklist');
      return;
    }

    // A label followed by a blank/dotted answer area is a free-text field.
    const field = line.match(/^\s*([^#\n]{1,100}?)\s*[:：]\s*(.*)$/);
    if (!field) return;
    const answer = field[2].trim();
    const next = String(lines[index + 1] || '').trim();
    if ((!answer && !next) || /^[.…·_ـ-]{3,}$/.test(answer) || /^[.…·_ـ-]{3,}$/.test(next)) addRow(field[1], 'description');
  });

  return rows.map((row, index) => ({ id: index + 1, label:row.label, type:row.type, maxScore:10, weight:1 }));
}

function _studentEvalDisplayName(studentId) {
  const student = (allStudents || []).find(item => +item.id === +studentId);
  return student ? `${student.name || ''} ${student.lname || ''}`.trim() : (META.entitySingular || 'شاگرد');
}

function _isImportedEvalForm(form) {
  return !!form?.source_case_form_id && form.source_case_form_mode !== 'manual';
}

function selectCaseFormForEvaluation(studentId, caseFormId) {
  const displayName = _studentEvalDisplayName(studentId);
  const template = (_db.case_forms || []).find(item => +item.id === +caseFormId);
  if (!template) { showToast('فرم پرونده پیدا نشد', 'error'); return; }

  const forms = loadEvalForms(studentId);
  const alreadySelected = forms.find(form => +form.source_case_form_id === +caseFormId);
  if (alreadySelected) {
    showToast('این فرم قبلاً برای این فرد انتخاب شده است');
    openEvalFormDetail(studentId, displayName, alreadySelected.id);
    return;
  }

  const rows = _caseFormEvalRows(template);
  const sourceMode = template.creation_mode || 'import';
  if (!rows.length && sourceMode === 'manual') {
    showToast('در این فرم فیلد یا چک‌باکسی برای تبدیل به شاخص پیدا نشد', 'error');
    return;
  }

  const newForm = {
    id: genEvalId(),
    title: template.title,
    desc: template.description || 'ساخته‌شده از فرم پرونده',
    rows,
    periods: [],
    created: formatJalali(...todayJalali()),
    source_case_form_id: template.id,
    source_case_form_mode: sourceMode,
    source_case_form_content: template.content || '',
  };
  forms.push(newForm);
  saveEvalForms(studentId, forms);
  showToast('فرم برای این فرد انتخاب شد ✓', 'success');
  openEvalFormDetail(studentId, displayName, newForm.id);
}

// ── LIST of forms for a student ──
function openEvaluation(studentId, displayName) {
  const forms = loadEvalForms(studentId);
  const caseForms = Array.isArray(_db.case_forms) ? _db.case_forms : [];
  const caseFormsPickerHtml = caseForms.length ? `
    <section style="margin-bottom:14px;padding:12px;background:rgba(124,106,247,.06);border:1px solid rgba(124,106,247,.22);border-radius:11px" aria-label="انتخاب فرم از پرونده‌ها">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px">
        <div><div style="font-size:12px;font-weight:700;color:var(--text)">انتخاب از فرم‌های پرونده</div><div style="font-size:10px;color:var(--text3);margin-top:2px">یک نسخه مستقل برای ${escapeHtml(displayName)} ساخته می‌شود</div></div>
        <span style="font-size:10px;color:var(--accent2);white-space:nowrap">${fa(caseForms.length)} فرم آماده</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px">
        ${caseForms.map(template => {
          const selected = forms.find(form => +form.source_case_form_id === +template.id);
          const rowCount = _caseFormEvalRows(template).length;
          return `<div style="display:flex;align-items:center;gap:8px;padding:9px 10px;background:var(--bg2);border:1px solid ${selected?'rgba(62,207,142,.35)':'var(--border)'};border-radius:9px">
            <div style="flex:1;min-width:0"><div style="font-size:11px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${escapeHtml(template.title)}">${escapeHtml(template.title)}</div><div style="font-size:9px;color:var(--text3);margin-top:3px">${fa(rowCount)} شاخص قابل ارزیابی</div></div>
            <button type="button" class="btn ${selected?'btn-ghost':'btn-primary'} btn-sm" style="min-height:36px;white-space:nowrap;${selected?'color:var(--green)':''}" onclick="${selected?`openEvalFormDetail(${studentId},_studentEvalDisplayName(${studentId}),${selected.id})`:`selectCaseFormForEvaluation(${studentId},${template.id})`}">${selected?'✓ انتخاب‌شده':'انتخاب'}</button>
          </div>`;
        }).join('')}
      </div>
    </section>` : `
    <div style="margin-bottom:12px;padding:10px 12px;border:1px dashed var(--border2);border-radius:9px;color:var(--text3);font-size:10px;line-height:1.8">فرم آماده‌ای در بخش «پرونده‌ها» ساخته نشده است.</div>`;
  const formsHtml = forms.length === 0
    ? `<div style="text-align:center;padding:24px 0;color:var(--text3);font-size:12px">هنوز فرمی ایجاد نشده<br><span style="font-size:11px">از دکمه زیر یک فرم ارزیابی جدید بساز</span></div>`
    : forms.map(f => {
        const totals = f.periods.map(p => evalPeriodTotal(f, p)).filter(t => t !== null);
        const lastTotal = totals.length ? totals[totals.length-1] : null;
        const trend = totals.length >= 2 ? totals[totals.length-1] - totals[totals.length-2] : null;
        const trendHtml = trend !== null
          ? `<span style="font-size:11px;color:${trend>0?'var(--green)':trend<0?'var(--red)':'var(--text3)'}">
              ${trend>0?'▲':'▼'} ${fa(Math.abs(trend))}٪
             </span>` : '';
        return `
        <div style="background:var(--bg3);border:1px solid var(--border);border-radius:10px;margin-bottom:8px;overflow:hidden">
          <div style="display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:var(--bg2);border-bottom:1px solid var(--border)">
            <div>
              <div style="font-size:13px;font-weight:600;color:var(--text)">${escapeHtml(f.title)}</div>
              <div style="font-size:10px;color:var(--text3);margin-top:2px;display:flex;align-items:center;gap:8px">
                <span>${fa(f.rows.length)} المان · ${fa(f.periods.length)} دوره</span>
                ${lastTotal!==null?`<span style="color:var(--green);font-weight:600">آخرین: ${fa(lastTotal)}٪</span>`:''}
                ${trendHtml}
              </div>
            </div>
            <div style="display:flex;gap:6px;flex-shrink:0">
              <button class="btn btn-ghost btn-sm" onclick="openEvalFormDetail(${studentId},${escapeAttr(displayName)},${f.id})">📋 باز کردن</button>
              <button class="btn btn-ghost btn-sm" style="color:var(--red)" onclick="deleteEvalForm(${studentId},${escapeAttr(displayName)},${f.id})">🗑</button>
            </div>
          </div>
          ${f.periods.length > 0 ? `<div style="padding:6px 12px 8px;font-size:10px;color:var(--text3)">
            ${f.periods.map((p,i)=>`<span style="display:inline-block;margin-left:6px;margin-bottom:2px;background:${p.date?'rgba(62,207,142,.1)':'rgba(96,165,250,.1)'};color:${p.date?'var(--green)':'var(--blue)'};border-radius:4px;padding:1px 6px">دوره ${fa(i+1)} · ${p.date || 'باز'}</span>`).join('')}
          </div>` : ''}
        </div>`;
      }).join('');

  // Build permanent achievements timeline (تاریخچه رشد شاگرد — همه دوره‌ها، همه فرم‌ها)
  const allSessions = (_db.sessions||[]).filter(s=>s.student_id===studentId&&s.achievements&&s.achievements.trim()).sort((a,b)=>_jalaliKey(b.date_jalali)-_jalaliKey(a.date_jalali));
  window._achTimelineState = { filter: 'all', search: '' };
  const flatPeriodsForFilters = _studentAllPeriodsFlat(studentId);
  const filterBtn = (key, label, disabled) => `
    <button class="ach-filter-btn" data-filter="${key}" ${disabled ? 'disabled' : ''} onclick="setAchTimelineFilter(${studentId},'${key}')"
      style="padding:4px 10px;font-size:11px;border-radius:20px;border:none;cursor:${disabled?'not-allowed':'pointer'};opacity:${disabled?'.4':'1'};font-family:var(--font);
      background:${key==='all'?'var(--accent)':'var(--bg3)'};color:${key==='all'?'white':'var(--text2)'}">${label}</button>`;

  const achPanelHtml = `
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">
      ${filterBtn('all','همه')}
      ${filterBtn('current','این دوره', !flatPeriodsForFilters[0])}
      ${filterBtn('prev','دوره قبل', !flatPeriodsForFilters[1])}
      ${filterBtn('important','⭐ فقط دستاوردهای مهم')}
    </div>
    <input class="form-input" placeholder="🔎 جستجو در دستاوردها..." style="margin-bottom:10px"
      oninput="setAchTimelineSearch(${studentId}, this.value)">
    <div id="eval-panel-ach-list"></div>`;

  openModal(`📊 ارزیابی عملکرد — ${escapeHtml(displayName)}`, `
    <div style="display:flex;gap:8px;margin-bottom:12px">
      <button id="eval-tab-forms" onclick="document.getElementById('eval-panel-forms').style.display='block';document.getElementById('eval-panel-ach').style.display='none';this.style.background='var(--accent)';this.style.color='white';document.getElementById('eval-tab-ach').style.background='var(--bg3)';document.getElementById('eval-tab-ach').style.color='var(--text2)'" style="flex:1;padding:7px;border-radius:8px;border:none;cursor:pointer;font-family:var(--font);font-size:12px;font-weight:600;background:var(--accent);color:white">📋 فرم‌های ارزیابی</button>
      <button id="eval-tab-ach" onclick="document.getElementById('eval-panel-ach').style.display='block';document.getElementById('eval-panel-forms').style.display='none';this.style.background='var(--accent)';this.style.color='white';document.getElementById('eval-tab-forms').style.background='var(--bg3)';document.getElementById('eval-tab-forms').style.color='var(--text2)'" style="flex:1;padding:7px;border-radius:8px;border:none;cursor:pointer;font-family:var(--font);font-size:12px;font-weight:600;background:var(--bg3);color:var(--text2)">🌱 تاریخچه دستاوردها (${fa(allSessions.length)})</button>
    </div>
    <div id="eval-panel-forms" style="max-height:55vh;overflow-y:auto">
      ${caseFormsPickerHtml}
      <div id="eval-forms-list">${formsHtml}</div>
    </div>
    <div id="eval-panel-ach" style="display:none;max-height:55vh;overflow-y:auto">
      ${achPanelHtml}
    </div>
  `, [
    { label: '+ فرم جدید', cls: 'btn-primary', action: `openNewEvalForm(${studentId},${escapeAttr(displayName)})` },
    { label: 'بستن', cls: 'btn-ghost', action: 'closeModal()' },
  ]);
  setTimeout(() => renderAchTimelinePanel(studentId), 0);
}

// ── permanent achievements timeline: filtering + rendering ──
function _achTimelineFilterSessions(studentId, filter, search) {
  let sessions = (_db.sessions||[]).filter(s=>s.student_id===studentId&&s.achievements&&s.achievements.trim());
  const flat = _studentAllPeriodsFlat(studentId);
  if (filter === 'current' && flat[0]) {
    sessions = sessions.filter(s => s.eval_form_id===flat[0].formId && s.eval_period_id===flat[0].pid);
  } else if (filter === 'prev' && flat[1]) {
    sessions = sessions.filter(s => s.eval_form_id===flat[1].formId && s.eval_period_id===flat[1].pid);
  } else if (filter === 'important') {
    sessions = sessions.filter(s => s.importance === 'key');
  }
  if (search && search.trim()) {
    const q = search.trim().toLowerCase();
    sessions = sessions.filter(s => (s.achievements||'').toLowerCase().includes(q));
  }
  return sessions.sort((a,b)=>_jalaliKey(b.date_jalali)-_jalaliKey(a.date_jalali));
}

function _achTimelineItemHtml(s) {
  return `<div style="display:flex;gap:10px;padding:10px 0;border-bottom:1px solid var(--border)">
    <div style="flex-shrink:0;width:8px;height:8px;background:var(--green);border-radius:50%;margin-top:5px"></div>
    <div style="flex:1;min-width:0">
      <div style="font-size:10px;color:var(--text3);margin-bottom:3px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
        <span>${DateService.disp(s.date_jalali)}</span>
        ${s.importance==='key' ? '<span style="color:var(--amber)">⭐</span>' : ''}
      </div>
      <div style="font-size:12px;color:var(--text);line-height:1.7">${renderRich(s.achievements)}</div>
      ${_achievementPeriodBadge(s)}
    </div>
    <button onclick="closeModal();openSessionDetail(${s.id})" title="باز کردن جلسه"
      style="flex-shrink:0;align-self:flex-start;border:none;background:none;color:var(--accent2);cursor:pointer;font-size:13px">📄</button>
  </div>`;
}

function renderAchTimelinePanel(studentId) {
  const st = window._achTimelineState || { filter: 'all', search: '' };
  const sessions = _achTimelineFilterSessions(studentId, st.filter, st.search);
  const container = document.getElementById('eval-panel-ach-list');
  if (!container) return;
  container.innerHTML = sessions.length === 0
    ? '<div style="text-align:center;padding:16px;color:var(--text3);font-size:12px">موردی یافت نشد<br><span style="font-size:11px">هنگام ثبت جلسه، بخش «پیشرفت‌ها» را پر کنید</span></div>'
    : sessions.map(_achTimelineItemHtml).join('');
}

function setAchTimelineFilter(studentId, filter) {
  window._achTimelineState = window._achTimelineState || { filter: 'all', search: '' };
  window._achTimelineState.filter = filter;
  document.querySelectorAll('.ach-filter-btn').forEach(b => {
    const active = b.dataset.filter === filter;
    b.style.background = active ? 'var(--accent)' : 'var(--bg3)';
    b.style.color = active ? 'white' : 'var(--text2)';
  });
  renderAchTimelinePanel(studentId);
}

function setAchTimelineSearch(studentId, value) {
  window._achTimelineState = window._achTimelineState || { filter: 'all', search: '' };
  window._achTimelineState.search = value;
  renderAchTimelinePanel(studentId);
}

function deleteEvalForm(studentId, displayName, formId) {
  if (!confirm('این فرم و تمام دوره‌هایش حذف شود؟')) return;
  saveEvalForms(studentId, loadEvalForms(studentId).filter(f => f.id !== formId));
  openEvaluation(studentId, displayName);
}

// ── CREATE new form ──
// ── EDIT ROWS ──────────────────────────────────────────────────────────────
function _evalBuilderRowHtml(row = {}, existingId = '') {
  const type = row.type || 'score';
  return `<div class="eval-builder-row" data-existing-id="${existingId || ''}" style="display:grid;grid-template-columns:130px 1fr 90px 42px;gap:8px;align-items:center;margin-bottom:8px;padding:9px;background:var(--bg3);border:1px solid var(--border);border-radius:9px">
    <select class="form-select eval-builder-type" aria-label="نوع المان فرم" onchange="_syncEvalBuilderRow(this)">
      <option value="score" ${type==='score'?'selected':''}>امتیاز</option>
      <option value="description" ${type==='description'?'selected':''}>توضیحات</option>
      <option value="goal" ${type==='goal'?'selected':''}>هدف</option>
      <option value="checklist" ${type==='checklist'?'selected':''}>چک‌لیست</option>
    </select>
    <input class="form-input eval-builder-label" value="${escapeHtml(row.label || '')}" placeholder="عنوان المان، مثلاً کیفیت اجرا" aria-label="عنوان المان">
    <input class="form-input eval-builder-max" type="number" min="1" max="100" value="${row.maxScore || 10}" aria-label="حداکثر امتیاز" style="${type==='score'?'':'visibility:hidden'}" title="حداکثر امتیاز">
    <button type="button" class="btn btn-ghost" onclick="this.closest('.eval-builder-row').remove()" aria-label="حذف المان" title="حذف" style="min-width:42px;padding:8px;color:var(--red)">×</button>
    <label style="grid-column:1/-1;display:flex;align-items:center;gap:7px;font-size:11px;color:var(--text2);cursor:pointer"><input type="checkbox" class="eval-builder-progress" ${row.progress_indicator?'checked':''} style="width:17px;height:17px;accent-color:var(--green)"><span>این المان به‌عنوان «شاخص پیشرفت» در ثبت جلسه نمایش داده شود</span></label>
  </div>`;
}

function _syncEvalBuilderRow(select) {
  const max = select.closest('.eval-builder-row')?.querySelector('.eval-builder-max');
  if (max) max.style.visibility = select.value === 'score' ? 'visible' : 'hidden';
}

function addEvalBuilderRow(type = 'score') {
  document.getElementById('eval-builder-rows')?.insertAdjacentHTML('beforeend', _evalBuilderRowHtml({ type }));
}

function _collectEvalBuilderRows() {
  return [...document.querySelectorAll('.eval-builder-row')].map(row => ({
    existingId:+row.dataset.existingId || null,
    type:row.querySelector('.eval-builder-type')?.value || 'score',
    label:row.querySelector('.eval-builder-label')?.value.trim() || '',
    maxScore:parseInt(row.querySelector('.eval-builder-max')?.value) || 10,
    progress_indicator:!!row.querySelector('.eval-builder-progress')?.checked,
  })).filter(row => row.label);
}

function _setNewEvalFormMode(mode) {
  const defaultPanel = document.getElementById('ef-default-panel');
  const customPanel = document.getElementById('ef-custom-panel');
  const hidden = document.getElementById('ef-mode');
  if (hidden) hidden.value = mode;
  if (defaultPanel) defaultPanel.style.display = mode === 'default' ? 'block' : 'none';
  if (customPanel) customPanel.style.display = mode === 'custom' ? 'block' : 'none';
  document.querySelectorAll('.ef-mode-btn').forEach(button => {
    const active = button.dataset.mode === mode;
    button.style.background = active ? 'var(--accent)' : 'var(--bg3)';
    button.style.color = active ? 'white' : 'var(--text2)';
  });
}

function openEditEvalRows(studentId, displayName, formId) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form) return;

  openModal(`ویرایش المان‌های فرم — ${escapeHtml(form.title)}`, `
    <div class="form-group full"><label class="form-label">المان‌های فرم ارزیابی</label><div id="eval-builder-rows">${form.rows.map(row => _evalBuilderRowHtml(row, row.id)).join('')}</div></div>
    <div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:10px">
      <button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('score')">+ امتیاز</button>
      <button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('description')">+ توضیحات</button>
      <button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('goal')">+ هدف</button>
      <button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('checklist')">+ چک‌لیست</button>
    </div>
    <div style="padding:10px 12px;background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.2);border-radius:8px;font-size:11px;color:var(--text2);margin-top:10px;line-height:1.8">
      ⚠️ امتیازهای ثبت‌شده برای شاخص‌های موجود حفظ می‌شن. شاخص‌های جدید از صفر شروع می‌کنن.
    </div>
  `, [
    { label: '✅ ذخیره تغییرات', cls: 'btn-primary', action: `saveEditEvalRows(${studentId},${escapeAttr(displayName)},${formId})` },
    { label: 'انصراف', cls: 'btn-ghost', action: `openEvalFormDetail(${studentId},${escapeAttr(displayName)},${formId})` },
  ]);
}

function saveEditEvalRows(studentId, displayName, formId) {
  const builderRows = _collectEvalBuilderRows();
  if (!builderRows.length) { showToast('حداقل یک المان اضافه کنید','error'); return; }

  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form) return;

  let nextId = Math.max(0, ...form.rows.map(row => +row.id || 0)) + 1;
  form.rows = builderRows.map(row => ({ id:row.existingId || nextId++, label:row.label, type:row.type, maxScore:row.maxScore,weight:1,progress_indicator:row.progress_indicator }));

  saveEvalForms(studentId, forms);
  showToast('شاخص‌ها ذخیره شدند ✅');
  openEvalFormDetail(studentId, displayName, formId);
}

function openNewEvalForm(studentId, displayName) {
  openModal(`📊 فرم ارزیابی جدید — ${escapeHtml(displayName)}`, `
    <input type="hidden" id="ef-mode" value="default">
    <div class="form-group full">
      <label class="form-label">عنوان فرم ارزیابی</label>
      <input class="form-input" id="ef-title" value="فرم ارزیابی پیش‌فرض" placeholder="مثلاً: ارزیابی عملکرد">
    </div>
    <div style="display:flex;gap:7px;margin:12px 0" role="tablist" aria-label="نوع فرم ارزیابی">
      <button type="button" class="ef-mode-btn" data-mode="default" onclick="_setNewEvalFormMode('default')" style="flex:1;min-height:44px;border:0;border-radius:9px;background:var(--accent);color:white;font-family:var(--font);font-weight:700;cursor:pointer">فرم ارزیابی پیش‌فرض</button>
      <button type="button" class="ef-mode-btn" data-mode="custom" onclick="_setNewEvalFormMode('custom')" style="flex:1;min-height:44px;border:0;border-radius:9px;background:var(--bg3);color:var(--text2);font-family:var(--font);font-weight:700;cursor:pointer">فرم سفارشی</button>
    </div>
    <div id="ef-default-panel">
      <div class="form-group full"><label class="form-label">شاخص‌های ارزیابی؛ هر خط یک شاخص</label><textarea class="form-textarea" id="ef-default-rows" rows="9" placeholder="آرامش&#10;نظم و استمرار&#10;کیفیت باورها&#10;عزت نفس&#10;اعتماد به نفس&#10;سلامتی&#10;انرژی"></textarea><div style="font-size:10px;color:var(--text3);line-height:1.8;margin-top:5px">برای هر شاخص چهار ستون «شاخص، امتیاز، توضیحات و هدف» ساخته می‌شود.</div></div>
      <div class="form-group full" style="margin-top:10px"><label class="form-label">شاخص‌های پیشرفت برای نمایش در ثبت جلسه (اختیاری)</label><textarea class="form-textarea" id="ef-default-progress" rows="3" placeholder="فقط نام شاخص‌هایی را بنویسید که می‌خواهید هنگام ثبت دستاورد قابل انتخاب باشند؛ هر خط یک مورد"></textarea></div>
      <div class="form-group" style="margin-top:10px"><label class="form-label">حداکثر امتیاز هر شاخص</label><input class="form-input" id="ef-default-maxscore" type="number" value="10" min="1" max="100"></div>
    </div>
    <div id="ef-custom-panel" style="display:none">
      <div class="form-group full"><label class="form-label">المان‌های فرم ارزیابی</label><div id="eval-builder-rows">${_evalBuilderRowHtml({type:'score',label:''})}</div></div>
      <div style="display:flex;gap:7px;flex-wrap:wrap;margin:10px 0 14px"><button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('score')">+ امتیاز</button><button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('description')">+ توضیحات</button><button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('goal')">+ هدف</button><button type="button" class="btn btn-ghost btn-sm" onclick="addEvalBuilderRow('checklist')">+ چک‌لیست</button></div>
    </div>
    <div class="form-grid"><div class="form-group full">
        <label class="form-label">توضیحات فرم (اختیاری)</label>
        <input class="form-input" id="ef-desc" placeholder="هدف این ارزیابی...">
      </div></div>
  `, [
    { label: 'ایجاد فرم', cls: 'btn-primary', action: `saveNewEvalForm(${studentId},${escapeAttr(displayName)})` },
    { label: 'انصراف', cls: 'btn-ghost', action: `openEvaluation(${studentId},${escapeAttr(displayName)})` },
  ]);
}

function saveNewEvalForm(studentId, displayName) {
  const title = document.getElementById('ef-title').value.trim();
  const mode = document.getElementById('ef-mode')?.value || 'default';
  const desc = document.getElementById('ef-desc').value.trim();
  if (!title) { alert('عنوان فرم را وارد کنید'); return; }
  let rows;
  if (mode === 'default') {
    const labels = (document.getElementById('ef-default-rows')?.value || '').split('\n').map(value => value.trim()).filter(Boolean);
    const maxScore = parseInt(document.getElementById('ef-default-maxscore')?.value) || 10;
    if (!labels.length) { showToast('حداقل یک شاخص وارد کنید','error'); return; }
    const progressLabels = (document.getElementById('ef-default-progress')?.value || '').split('\n').map(value => value.trim()).filter(Boolean);
    rows = labels.map((label,index) => ({id:index+1,label,type:'score',maxScore,weight:1,progress_indicator:progressLabels.includes(label)}));
  } else {
    const builderRows = _collectEvalBuilderRows();
    if (!builderRows.length) { showToast('حداقل یک المان اضافه کنید','error'); return; }
    rows = builderRows.map((row,index) => ({id:index+1,label:row.label,type:row.type,maxScore:row.maxScore,weight:1,progress_indicator:row.progress_indicator}));
  }
  const newForm = { id:genEvalId(), title, desc, rows, periods:[], form_mode:mode, created:formatJalali(...todayJalali()) };
  const forms = loadEvalForms(studentId);
  forms.push(newForm);
  saveEvalForms(studentId, forms);
  openEvalFormDetail(studentId, displayName, newForm.id, forms.length - 1 >= 0 ? -1 : -1);
}

// ── FORM DETAIL — tabs + table + compare ──
function openEvalFormDetail(studentId, displayName, formId, activePeriodIdx) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form) { openEvaluation(studentId, displayName); return; }
  setTimeout(() => _ensureEvalFormAttachmentsShared(studentId, formId), 0);

  // Imported case forms are immediately usable like Knowledge Center forms.
  // Keep a separate content snapshot per period so filling one period never changes the template.
  if (_isImportedEvalForm(form)) {
    const template = (_db.case_forms || []).find(item => +item.id === +form.source_case_form_id);
    const originalContent = form.source_case_form_content !== undefined ? form.source_case_form_content : (template?.content || '');
    let changed = false;
    if (form.source_case_form_content === undefined) { form.source_case_form_content = originalContent; changed = true; }
    if (!form.periods.length) {
      form.periods.push({ id:genEvalId(), date:null, scores:{}, notes:{}, targets:{}, checks:{}, summary:'', actions:'', form_content:originalContent });
      changed = true;
    }
    form.periods.forEach(period => {
      if (period.form_content === undefined) { period.form_content = originalContent; changed = true; }
    });
    if (changed) saveEvalForms(studentId, forms);
  }

  const lastIdx = form.periods.length - 1;
  const curIdx = (activePeriodIdx !== undefined && activePeriodIdx >= 0 && activePeriodIdx <= lastIdx)
    ? activePeriodIdx : lastIdx;

  // period tabs
  const periodTabsHtml = form.periods.length === 0
    ? `<div style="font-size:11px;color:var(--text3);padding:4px 0 10px">هنوز دوره‌ای ثبت نشده — از دکمه «دوره جدید» شروع کن.</div>`
    : `<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:10px" id="eval-period-tabs">
        ${form.periods.map((p,i) => {
          const isOpen = !p.date;
          const active = i === curIdx;
          const border = active ? (isOpen ? 'var(--blue)' : 'var(--green)') : 'var(--border)';
          const bg = active ? (isOpen ? 'rgba(96,165,250,.12)' : 'rgba(62,207,142,.12)') : 'var(--bg3)';
          const color = active ? (isOpen ? 'var(--blue)' : 'var(--green)') : 'var(--text2)';
          return `
          <button id="eval-tab-${i}"
            onclick="evalSwitchTab(${studentId},${escapeAttr(displayName)},${formId},${i})"
            style="padding:4px 10px;font-size:11px;border-radius:6px;cursor:pointer;border:1px solid ${border};background:${bg};color:${color};display:flex;align-items:center;gap:5px">
            ${isOpen ? '<span style="width:6px;height:6px;border-radius:50%;background:var(--blue);display:inline-block;flex-shrink:0"></span>' : ''}
            دوره ${fa(i+1)} · ${isOpen ? 'باز' : p.date}
          </button>`;
        }).join('')}
        ${form.periods.filter(p=>p.date).length >= 2 ? `
          <button onclick="openEvalCompare(${studentId},${escapeAttr(displayName)},${formId})"
            style="padding:4px 10px;font-size:11px;border-radius:6px;cursor:pointer;border:1px solid rgba(96,165,250,.4);background:rgba(96,165,250,.08);color:var(--blue)">
            📈 مقایسه دوره‌ها
          </button>` : ''}
      </div>`;

  const tableHtml = buildEvalTable(form, curIdx, studentId);
  const formAttachmentsHtml = _evalFormAttachmentsHtml(form, studentId, displayName, curIdx);

  // ── تحلیل خودکار: سرعت رشد + نقاط قوت/ضعف ──
  const analysisHtml = !_isImportedEvalForm(form) && form.periods.length >= 2 ? (() => {
    const last = form.periods[form.periods.length - 1];
    const prev = form.periods[form.periods.length - 2];
    const growthData = form.rows.filter(row => !row.type || row.type === 'score').map(row => {
      const s1 = prev.scores[row.id] !== undefined ? parseFloat(prev.scores[row.id]) : null;
      const s2 = last.scores[row.id] !== undefined ? parseFloat(last.scores[row.id]) : null;
      const pct2 = s2 !== null ? Math.round((s2 / row.maxScore) * 100) : null;
      const diff = (s1 !== null && s2 !== null) ? Math.round(((s2 - s1) / row.maxScore) * 100) : null;
      return { label: row.label, pct: pct2, diff, s2, maxScore: row.maxScore };
    }).filter(r => r.pct !== null);

    // نقاط قوت: top 3 بیشترین امتیاز
    const strengths = [...growthData].sort((a,b) => b.pct - a.pct).slice(0,3);
    // نقاط ضعف: bottom 3 کمترین امتیاز
    const weaknesses = [...growthData].sort((a,b) => a.pct - b.pct).slice(0,3);
    // سرعت رشد: مرتب‌شده از بیشترین رشد
    const sorted = [...growthData].filter(r => r.diff !== null).sort((a,b) => b.diff - a.diff);
    const topGrowth = sorted.slice(0,3);
    const stagnant = sorted.filter(r => r.diff <= 0).slice(-3).reverse();

    const strengthsList = strengths.map(r =>
      `<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid var(--border)">
        <span style="font-size:12px;color:var(--text)">${escapeHtml(r.label)}</span>
        <span style="font-size:12px;font-weight:600;color:var(--green)">${fa(r.pct)}٪</span>
      </div>`).join('');

    const weaknessesList = weaknesses.map(r =>
      `<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid var(--border)">
        <span style="font-size:12px;color:var(--text)">${escapeHtml(r.label)}</span>
        <span style="font-size:12px;font-weight:600;color:var(--red)">${fa(r.pct)}٪</span>
      </div>`).join('');

    const growthList = topGrowth.map(r =>
      `<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid var(--border)">
        <span style="font-size:12px;color:var(--text)">${escapeHtml(r.label)}</span>
        <span style="font-size:11px;font-weight:600;color:${r.diff > 0 ? 'var(--green)' : 'var(--text3)'}">${r.diff > 0 ? '▲' : '='} ${fa(Math.abs(r.diff))}٪</span>
      </div>`).join('');

    const stagnantList = stagnant.map(r =>
      `<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid var(--border)">
        <span style="font-size:12px;color:var(--text)">${escapeHtml(r.label)}</span>
        <span style="font-size:11px;font-weight:600;color:${r.diff < 0 ? 'var(--red)' : 'var(--text3)'}">${r.diff < 0 ? '▼' : '='} ${fa(Math.abs(r.diff))}٪</span>
      </div>`).join('');

    // ── داده‌های کیفی: دستاوردهای ثبت‌شده در همین دوره (سطح جلسه) ──
    const periodAchSessions = _periodAchievementSessions(studentId, form.id, last.id);
    const tagCountByRow = {};
    periodAchSessions.forEach(s => (s.achievement_tags || []).forEach(tid => { tagCountByRow[tid] = (tagCountByRow[tid] || 0) + 1; }));
    const qualitativeNotes = form.rows
      .map(row => tagCountByRow[row.id] ? { label: row.label, count: tagCountByRow[row.id] } : null)
      .filter(Boolean);

    const narrativeParts = [];
    growthData.forEach(r => {
      const q = qualitativeNotes.find(q => q.label === r.label);
      if (q && r.diff !== null && r.diff <= 10) {
        narrativeParts.push(`در شاخص «${r.label}» اگرچه امتیاز عددی ${r.diff > 0 ? `فقط ${fa(r.diff)}٪ رشد داشته` : 'تغییر محسوسی نکرده'}، اما ${fa(q.count)} دستاورد کیفی مرتبط در این دوره ثبت شده — نشانه‌ای از رشدی که هنوز در عدد دیده نمی‌شود.`);
      } else if (q) {
        narrativeParts.push(`در شاخص «${r.label}» علاوه بر رشد ${fa(r.diff)}٪ در امتیاز، ${fa(q.count)} دستاورد کیفی نیز ثبت شده است.`);
      }
    });
    const untaggedCount = periodAchSessions.length - periodAchSessions.filter(s => (s.achievement_tags || []).length > 0).length;
    if (untaggedCount > 0) narrativeParts.push(`${fa(untaggedCount)} دستاورد این دوره به شاخص خاصی متصل نشده و به‌صورت عمومی ثبت شده است.`);

    const qualitativeHtml = periodAchSessions.length > 0 ? `
      <div style="margin-top:14px;padding-top:12px;border-top:1px dashed var(--border)">
        <div style="font-size:10px;font-weight:600;color:var(--green);margin-bottom:6px;text-transform:uppercase;letter-spacing:.05em">🌱 داده‌های کیفی این دوره (${fa(periodAchSessions.length)} دستاورد)</div>
        ${narrativeParts.length ? narrativeParts.map(t => `<div style="font-size:12px;color:var(--text);line-height:1.9;padding:3px 0">• ${t}</div>`).join('') : '<div style="font-size:11px;color:var(--text3)">دستاوردهای این دوره هنوز به شاخص خاصی وصل نشده‌اند.</div>'}
      </div>` : '';

    return `
      <div style="margin-top:16px;padding:12px 14px;background:var(--bg2);border-radius:10px;border:1px solid var(--border)">
        <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:12px">📊 تحلیل خودکار — آخرین دوره</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
          <div>
            <div style="font-size:10px;font-weight:600;color:var(--green);margin-bottom:6px;text-transform:uppercase;letter-spacing:.05em">💪 نقاط قوت</div>
            ${strengthsList}
          </div>
          <div>
            <div style="font-size:10px;font-weight:600;color:var(--red);margin-bottom:6px;text-transform:uppercase;letter-spacing:.05em">⚠️ نقاط ضعف</div>
            ${weaknessesList}
          </div>
          ${topGrowth.length > 0 ? `
          <div>
            <div style="font-size:10px;font-weight:600;color:var(--blue);margin-bottom:6px;text-transform:uppercase;letter-spacing:.05em">🚀 بیشترین رشد</div>
            ${growthList}
          </div>` : ''}
          ${stagnant.length > 0 ? `
          <div>
            <div style="font-size:10px;font-weight:600;color:rgba(251,191,36,1);margin-bottom:6px;text-transform:uppercase;letter-spacing:.05em">🔄 گیر کرده</div>
            ${stagnantList}
          </div>` : ''}
        </div>
        ${qualitativeHtml}
      </div>`;
  })() : '';

  // ── تنظیمات یادآوری ──
  const reminder = form.reminder || {};
  const reminderHtml = `
    <div style="margin-top:12px;padding:12px 14px;background:var(--bg2);border-radius:10px;border:1px solid var(--border)">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
        <div style="font-size:12px;font-weight:600;color:var(--text)">⏰ یادآوری ارزیابی</div>
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer">
          <input type="checkbox" id="er-enabled" ${reminder.enabled ? 'checked' : ''} onchange="saveEvalReminder(${formId},${studentId})">
          <span style="font-size:11px;color:var(--text2)">فعال</span>
        </label>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
        <span style="font-size:11px;color:var(--text3)">هر</span>
        <input type="number" id="er-interval" value="${reminder.interval || 30}" min="1" max="365"
          style="width:60px;padding:4px 8px;font-size:12px;border:1px solid var(--border);border-radius:6px;background:var(--bg3);color:var(--text);text-align:center"
          onchange="saveEvalReminder(${formId},${studentId})">
        <select id="er-unit" style="padding:4px 8px;font-size:12px;border:1px solid var(--border);border-radius:6px;background:var(--bg3);color:var(--text)"
          onchange="saveEvalReminder(${formId},${studentId})">
          <option value="day" ${(reminder.unit||'day')==='day'?'selected':''}>روز</option>
          <option value="week" ${(reminder.unit||'')==='week'?'selected':''}>هفته</option>
        </select>
        <span style="font-size:11px;color:var(--text3)">یک‌بار · یادآوری</span>
        <input type="number" id="er-before" value="${reminder.beforeHours || 24}" min="1" max="720"
          style="width:60px;padding:4px 8px;font-size:12px;border:1px solid var(--border);border-radius:6px;background:var(--bg3);color:var(--text);text-align:center"
          onchange="saveEvalReminder(${formId},${studentId})">
        <span style="font-size:11px;color:var(--text3)">ساعت قبل</span>
      </div>
      ${reminder.nextDate ? `<div style="margin-top:8px;font-size:10px;color:var(--text3)">یادآوری بعدی: ${reminder.nextDate}</div>` : ''}
    </div>`;

  const openPeriodIdx = form.periods.findIndex(p => !p.date);
  const primaryBtn = openPeriodIdx !== -1
    ? { label: `🔵 پایان دوره ${fa(openPeriodIdx + 1)}`, cls: 'btn-primary', action: `endEvalPeriod(${studentId},${escapeAttr(displayName)},${formId},${openPeriodIdx})` }
    : { label: '+ دوره جدید', cls: 'btn-primary', action: `startNewEvalPeriod(${studentId},${escapeAttr(displayName)},${formId})` };
  const editFormBtn = _isImportedEvalForm(form)
    ? { label:'ویرایش فرم اصلی', cls:'btn-ghost', action:`openCaseFormBuilder(${form.source_case_form_id})` }
    : { label:'ویرایش المان‌ها', cls:'btn-ghost', action:`openEditEvalRows(${studentId},${escapeAttr(displayName)},${formId})` };

  openModal(`📊 ${escapeHtml(form.title)} — ${escapeHtml(displayName)}`, `
    <div class="detail-section" style="max-height:65vh;overflow-y:auto">
      ${form.desc ? `<div style="font-size:11px;color:var(--text3);margin-bottom:8px">${escapeHtml(form.desc)}</div>` : ''}
      ${periodTabsHtml}
      <div id="eval-table-container" data-student="${escapeHtml(displayName)}">${tableHtml}</div>
      ${analysisHtml}
      ${formAttachmentsHtml}
      ${reminderHtml}
    </div>
  `, [
    primaryBtn,
    editFormBtn,
    ...(_isImportedEvalForm(form) ? [{label:'کپی فرم',cls:'btn-ghost',action:`copyCaseForm(${form.source_case_form_id})`}] : []),
    { label: 'بازگشت', cls: 'btn-ghost', action: `openEvaluation(${studentId},${escapeAttr(displayName)})` },
  ]);
  setTimeout(() => {
    document.querySelectorAll('#eval-table-container .jdate').forEach(el => attachJalaliDatePicker(el));
  }, 0);
}

function evalSwitchTab(studentId, displayName, formId, periodIdx) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form) return;
  // update tab styles
  form.periods.forEach((p,i) => {
    const btn = document.getElementById(`eval-tab-${i}`);
    if (!btn) return;
    const isOpen = !p.date;
    const active = i === periodIdx;
    const c = active ? (isOpen ? 'var(--blue)' : 'var(--green)') : 'var(--text2)';
    btn.style.border = `1px solid ${active ? c : 'var(--border)'}`;
    btn.style.background = active ? (isOpen ? 'rgba(96,165,250,.12)' : 'rgba(62,207,142,.12)') : 'var(--bg3)';
    btn.style.color = c;
  });
  document.getElementById('eval-table-container').innerHTML = buildEvalTable(form, periodIdx, studentId);
  setTimeout(() => {
    document.querySelectorAll('#eval-table-container .jdate').forEach(el => attachJalaliDatePicker(el));
  }, 0);
}

function _evalFormAttachmentsHtml(form, studentId, displayName, activePeriodIdx) {
  const attachments = form.attachments || [];
  const safeDisplayName = String(displayName || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return `
    <div style="margin-top:12px;padding:12px 14px;background:var(--bg2);border-radius:10px;border:1px solid var(--border)">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap">
        <div>
          <div style="font-size:12px;font-weight:700;color:var(--text)">📎 فایل‌های پیوست فرم</div>
          <div style="font-size:10px;color:var(--text3);margin-top:3px">هر فایل می‌تواند یادداشت مستقل داشته باشد.</div>
        </div>
        <button type="button" class="btn btn-ghost btn-sm" onclick="addEvalFormAttachments(${studentId},'${safeDisplayName}',${form.id},${activePeriodIdx})">+ افزودن فایل</button>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:10px;margin-top:12px">
        ${attachments.length ? attachments.map(a => `
          <div style="padding:10px;background:var(--bg3);border:1px solid var(--border2);border-radius:10px;min-width:0">
            <div style="display:flex;align-items:center;gap:9px;min-width:0">
              <button type="button" onclick="_openAttachment('${a.id}',decodeURIComponent('${encodeURIComponent(a.name || '')}'),decodeURIComponent('${encodeURIComponent(a.type || '')}'))"
                style="width:42px;height:42px;flex:0 0 42px;border:1px solid var(--border);border-radius:8px;background:var(--bg4);cursor:pointer;font-size:21px;overflow:hidden;padding:0">
                ${a.type?.startsWith('image/') && a.thumb ? `<img src="${a.thumb}" style="width:100%;height:100%;object-fit:cover">` : _fileIcon(a.type)}
              </button>
              <button type="button" onclick="_openAttachment('${a.id}',decodeURIComponent('${encodeURIComponent(a.name || '')}'),decodeURIComponent('${encodeURIComponent(a.type || '')}'))"
                style="min-width:0;flex:1;text-align:right;border:0;background:none;color:var(--text);cursor:pointer;font-family:var(--font)">
                <div style="font-size:11px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(a.name)}</div>
                <div style="font-size:10px;color:var(--text3);margin-top:2px">${_formatSize(a.size || 0)} · بازکردن فایل</div>
              </button>
              <button type="button" title="حذف پیوست" aria-label="حذف پیوست" onclick="deleteEvalFormAttachment(${studentId},'${safeDisplayName}',${form.id},'${a.id}',${activePeriodIdx})"
                style="width:30px;height:30px;flex:0 0 30px;border:1px solid rgba(248,113,113,.35);border-radius:7px;background:rgba(248,113,113,.08);color:var(--red);cursor:pointer">×</button>
            </div>
            <label style="display:block;font-size:10px;color:var(--text3);margin:9px 1px 5px" for="eval-attachment-note-${a.id}">یادداشت این پیوست</label>
            <textarea id="eval-attachment-note-${a.id}" class="form-textarea" rows="2" placeholder="توضیح مربوط به این فایل را بنویسید..."
              onblur="saveEvalFormAttachmentNote(${studentId},${form.id},'${a.id}',this.value)" style="min-height:58px;font-size:11px">${escapeHtml(a.note || '')}</textarea>
          </div>
        `).join('') : '<div style="grid-column:1/-1;padding:14px;text-align:center;border:1px dashed var(--border);border-radius:9px;font-size:11px;color:var(--text3)">هنوز فایلی به این فرم پیوست نشده است.</div>'}
      </div>
    </div>`;
}

async function addEvalFormAttachments(studentId, displayName, formId, activePeriodIdx) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(item => +item.id === +formId);
  if (!form) return;
  const beforeCount = (form.attachments || []).length;
  form.attachments = await attachFiles('eval_form', formId, form.attachments || []);
  if (form.attachments.length === beforeCount) return;
  saveEvalForms(studentId, forms);
  showToast('پیوست فرم اضافه شد ✓', 'success');
  openEvalFormDetail(studentId, displayName, formId, activePeriodIdx);
}

function saveEvalFormAttachmentNote(studentId, formId, attachmentId, note) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(item => +item.id === +formId);
  const attachment = form?.attachments?.find(item => item.id === attachmentId);
  if (!attachment) return;
  attachment.note = String(note || '');
  saveEvalForms(studentId, forms);
}

async function deleteEvalFormAttachment(studentId, displayName, formId, attachmentId, activePeriodIdx) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(item => +item.id === +formId);
  if (!form) return;
  form.attachments = (form.attachments || []).filter(item => item.id !== attachmentId);
  saveEvalForms(studentId, forms);
  try { await _IDB.delete(attachmentId); } catch (_) {}
  try { await _apiFetch('/api/files/' + encodeURIComponent(attachmentId), {method:'DELETE'}); } catch (_) {}
  showToast('پیوست فرم حذف شد', 'success');
  openEvalFormDetail(studentId, displayName, formId, activePeriodIdx);
}

function _buildImportedEvalForm(form, period, periodIdx) {
  if (!period) return '';
  const sourceId = `imported-eval-source-${form.id}-${periodIdx}`;
  const content = String(period.form_content || '');
  return `<div class="imported-eval-form" style="padding:14px;border:1px solid var(--border);border-radius:11px;background:var(--bg2)">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px;padding-bottom:9px;border-bottom:1px solid var(--border)">
      <div><div style="font-size:13px;font-weight:700;color:var(--text)">${escapeHtml(form.title)}</div><div style="font-size:10px;color:var(--text3);margin-top:3px">فرم واردشده · پاسخ‌ها خودکار ذخیره می‌شوند</div></div>
      <span style="font-size:10px;color:var(--green);white-space:nowrap">آماده تکمیل</span>
    </div>
    <textarea id="${sourceId}" aria-hidden="true" tabindex="-1" style="display:none" oninput="_saveImportedEvalContent(${form.id},${periodIdx},this.value)">${escapeHtml(content)}</textarea>
    <div class="imported-eval-form-content" style="font-size:13px;line-height:1.9">${renderRich(content,{interactive:true,textareaId:sourceId})}</div>
  </div>`;
}

function _saveImportedEvalContent(formId, periodIdx, value) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(item => +item.id === +formId);
  const period = form?.periods?.[periodIdx];
  if (!period) return;
  period.form_content = value;
  clearTimeout(window._importedEvalSaveTimer);
  window._importedEvalSaveTimer = setTimeout(() => _evalSaveByKey(key, forms), 400);
}

// ── BUILD the scoring table ──
function buildEvalTable(form, periodIdx, studentId) {
  const period = form.periods[periodIdx];
  const scores = period ? period.scores : {};
  const notes = period ? period.notes : {};
  const targets = period ? (period.targets || {}) : {};
  const checks = period ? (period.checks || {}) : {};

  // editable date header (closed period) vs. "still open" banner with an end-period button
  const dateRow = period ? (period.date ? `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;padding:6px 10px;background:var(--bg2);border-radius:7px;border:1px solid var(--border);flex-wrap:wrap">
      <span style="font-size:11px;color:var(--text3);white-space:nowrap">تاریخ پایان دوره ${fa((periodIdx||0)+1)}:</span>
      <input type="text" id="eval-date-${periodIdx}" value="${period.date}"
        class="form-input jdate" style="font-size:12px;padding:3px 8px;height:30px;text-align:center;width:120px"
        placeholder="۱۴۰۵/۰۱/۰۱"
        oninput="this.value=this.value.replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));updateEvalDate(${form.id},${periodIdx},this.value)">
      <span style="font-size:10px;color:var(--text3)">(قابل ویرایش)</span>
      <button onclick="confirmDeleteEvalPeriod(${form.id},${periodIdx})"
        style="margin-right:auto;padding:3px 10px;font-size:11px;border-radius:6px;border:1px solid rgba(248,113,113,.35);background:rgba(248,113,113,.08);color:var(--red);cursor:pointer">
        🗑 حذف این دوره
      </button>
    </div>` : `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;padding:6px 10px;background:rgba(96,165,250,.08);border-radius:7px;border:1px solid rgba(96,165,250,.35);flex-wrap:wrap">
      <span style="width:7px;height:7px;border-radius:50%;background:var(--blue);display:inline-block;flex-shrink:0"></span>
      <span style="font-size:11px;color:var(--blue);font-weight:600;white-space:nowrap">دوره ${fa((periodIdx||0)+1)} هنوز باز است — پایان نیافته</span>
      <button onclick="endEvalPeriod(${studentId || 'null'},'',${form.id},${periodIdx})"
        style="margin-right:auto;padding:3px 10px;font-size:11px;border-radius:6px;border:none;background:var(--blue);color:#fff;cursor:pointer;font-weight:600">
        🔵 پایان دوره و تعیین تاریخ
      </button>
      <button onclick="confirmDeleteEvalPeriod(${form.id},${periodIdx})"
        style="padding:3px 10px;font-size:11px;border-radius:6px;border:1px solid rgba(248,113,113,.35);background:rgba(248,113,113,.08);color:var(--red);cursor:pointer">
        🗑 حذف این دوره
      </button>
    </div>`) : '';

  if (_isImportedEvalForm(form)) return `${dateRow}${_buildImportedEvalForm(form,period,periodIdx)}`;

  const rows = form.rows.map(row => {
    const rowType = row.type || 'score';
    const score = scores[row.id] !== undefined ? scores[row.id] : '';
    const note = notes[row.id] || '';
    const target = targets[row.id] !== undefined ? targets[row.id] : '';
    if (rowType === 'description') return `<tr><td style="padding:9px 10px;font-size:12px;color:var(--text);font-weight:600;border-bottom:1px solid var(--border)">${escapeHtml(row.label)}</td><td colspan="3" style="padding:8px 6px;border-bottom:1px solid var(--border)">${period?`<textarea rows="2" placeholder="توضیحات را بنویسید..." style="width:100%;padding:7px 9px;font-size:12px;border:1px solid var(--border);border-radius:7px;background:var(--bg3);color:var(--text);font-family:inherit;resize:vertical" onchange="updateEvalNote(${form.id},${row.id},this.value,${periodIdx})">${escapeHtml(note)}</textarea>`:'<span style="font-size:11px;color:var(--text3)">— ابتدا دوره شروع کن</span>'}</td></tr>`;
    if (rowType === 'goal') return `<tr><td style="padding:9px 10px;font-size:12px;color:var(--text);font-weight:600;border-bottom:1px solid var(--border)">${escapeHtml(row.label)}</td><td colspan="3" style="padding:8px 6px;border-bottom:1px solid var(--border)">${period?`<input type="text" value="${escapeHtml(target)}" placeholder="هدف را بنویسید..." style="width:100%;padding:7px 9px;font-size:12px;border:1px solid rgba(96,165,250,.35);border-radius:7px;background:rgba(96,165,250,.05);color:var(--text)" onchange="updateEvalTarget(${form.id},${row.id},this.value,${periodIdx})">`:'<span style="font-size:11px;color:var(--text3)">— ابتدا دوره شروع کن</span>'}</td></tr>`;
    if (rowType === 'checklist') return `<tr><td colspan="4" style="padding:8px 10px;border-bottom:1px solid var(--border)">${period?`<label style="display:flex;align-items:center;gap:9px;padding:8px 10px;background:var(--bg3);border:1px solid var(--border);border-radius:8px;cursor:pointer"><input type="checkbox" ${checks[row.id]?'checked':''} onchange="updateEvalCheck(${form.id},${row.id},this.checked,${periodIdx},this)" style="width:18px;height:18px;accent-color:var(--accent2);cursor:pointer;flex-shrink:0"><span style="font-size:12px;color:var(--text);${checks[row.id]?'text-decoration:line-through;color:var(--text3)':''}">${escapeHtml(row.label)}</span></label>`:`<span style="font-size:11px;color:var(--text3)">${escapeHtml(row.label)} — ابتدا دوره شروع کن</span>`}</td></tr>`;
    const pct = score !== '' ? Math.round((parseFloat(score) / row.maxScore) * 100) : 0;
    const barColor = pct >= 70 ? 'var(--green)' : pct >= 40 ? 'rgba(251,191,36,1)' : 'var(--red)';
    return `
      <tr>
        <td style="padding:8px 10px;font-size:12px;color:var(--text);font-weight:500;border-bottom:1px solid var(--border)">${escapeHtml(row.label)}</td>
        <td style="padding:8px 6px;border-bottom:1px solid var(--border)">
          ${period ? `
            <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
              <input type="number" min="0" max="${row.maxScore}" value="${score}"
                style="width:50px;padding:3px 6px;font-size:12px;border:1px solid var(--border);border-radius:5px;background:var(--bg3);color:var(--text);text-align:center"
                onchange="updateEvalScore(${form.id},${row.id},this.value,${periodIdx})">
              <span style="font-size:10px;color:var(--text3)">/${fa(row.maxScore)}</span>
              <div style="width:34px;height:4px;background:var(--border);border-radius:2px;overflow:hidden">
                <div style="width:${pct}%;height:100%;background:${barColor};border-radius:2px"></div>
              </div>
            </div>` : `<span style="font-size:11px;color:var(--text3)">— ابتدا دوره شروع کن</span>`}
        </td>
        <td style="padding:8px 6px;border-bottom:1px solid var(--border)">${period ? `<input type="text" value="${escapeHtml(note)}" placeholder="توضیحات..." style="width:100%;padding:5px 7px;font-size:11px;border:1px solid var(--border);border-radius:6px;background:var(--bg3);color:var(--text)" onchange="updateEvalNote(${form.id},${row.id},this.value,${periodIdx})">` : ''}</td>
        <td style="padding:8px 6px;border-bottom:1px solid var(--border)">${period ? `<input type="number" min="0" max="${row.maxScore}" value="${target}" placeholder="هدف" style="width:58px;padding:5px 6px;font-size:11px;border:1px solid rgba(96,165,250,.35);border-radius:6px;background:rgba(96,165,250,.05);color:var(--blue);text-align:center" onchange="updateEvalTarget(${form.id},${row.id},this.value,${periodIdx})">` : ''}</td>
      </tr>`;
  }).join('');

  const totalScore = evalPeriodTotal(form, period);

  // summary + actions section
  const coachSection = period ? `
    <div style="margin-top:14px;display:flex;flex-direction:column;gap:8px">
      <div>
        <div style="font-size:10px;font-weight:600;color:var(--text3);margin-bottom:4px;text-transform:uppercase;letter-spacing:.05em">📝 جمع‌بندی مربی</div>
        <textarea rows="2" placeholder="نظر کلی، مهم‌ترین نکات این دوره..."
          style="width:100%;padding:7px 10px;font-size:12px;border:1px solid var(--border);border-radius:7px;background:var(--bg3);color:var(--text);resize:vertical;font-family:inherit;line-height:1.7"
          onchange="updateEvalSummary(${form.id},${periodIdx},this.value)">${escapeHtml(period.summary || '')}</textarea>
      </div>
      <div>
        <div style="font-size:10px;font-weight:600;color:var(--text3);margin-bottom:4px;text-transform:uppercase;letter-spacing:.05em">🎯 اقدام بعدی</div>
        <textarea rows="2" placeholder="تکالیف و اقدامات مشخص برای دوره بعد..."
          style="width:100%;padding:7px 10px;font-size:12px;border:1px solid rgba(96,165,250,.3);border-radius:7px;background:rgba(96,165,250,.04);color:var(--text);resize:vertical;font-family:inherit;line-height:1.7"
          onchange="updateEvalActions(${form.id},${periodIdx},this.value)">${escapeHtml(period.actions || '')}</textarea>
      </div>
    </div>` : '';

  const dlBtn = period ? `
    <div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap">
      <button onclick="downloadEvalPeriod(${form.id},${periodIdx})"
        style="padding:5px 14px;font-size:11px;border-radius:6px;border:1px solid rgba(96,165,250,.4);background:rgba(96,165,250,.08);color:var(--blue);cursor:pointer">
        ⬇ دانلود این دوره
      </button>
      <button onclick="shareEvalPeriod(${form.id},${periodIdx})"
        style="padding:5px 14px;font-size:11px;border-radius:6px;border:1px solid rgba(62,207,142,.4);background:rgba(62,207,142,.08);color:var(--green);cursor:pointer">
        ↗ اشتراک‌گذاری
      </button>
    </div>` : '';

  const achievementsSection = period ? _buildPeriodAchievementsHtml(studentId, form, period) : '';

  return `
    ${dateRow}
    <table style="width:100%;border-collapse:collapse">
      <thead>
        <tr style="background:var(--bg2)">
          <th style="padding:7px 10px;text-align:right;font-size:11px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);width:34%">شاخص</th>
          <th style="padding:7px 6px;text-align:right;font-size:11px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);width:28%">امتیاز</th>
          <th style="padding:7px 6px;text-align:right;font-size:11px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);width:28%">توضیحات</th>
          <th style="padding:7px 6px;text-align:center;font-size:11px;font-weight:600;color:var(--blue);border-bottom:1px solid var(--border);width:10%" title="هدف">🎯</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
    ${period && totalScore !== null ? `
      <div style="margin-top:10px;padding:8px 12px;background:rgba(62,207,142,.08);border:1px solid rgba(62,207,142,.2);border-radius:8px;display:flex;align-items:center;justify-content:space-between">
        <span style="font-size:12px;color:var(--text2)">امتیاز کل این دوره:</span>
        <span style="font-size:18px;font-weight:700;color:var(--green)">${fa(totalScore)}٪</span>
      </div>` : ''}
    ${achievementsSection}
    ${coachSection}
    ${dlBtn}`;
}

// ── دستاوردهای همین دوره (فقط، نه همه تاریخچه) ──
function _periodAchievementSessions(studentId, formId, periodId) {
  return (_db.sessions || [])
    .filter(s => s.student_id === studentId && s.eval_form_id === formId && s.eval_period_id === periodId && s.achievements && s.achievements.trim())
    .sort((a, b) => _jalaliKey(b.date_jalali) - _jalaliKey(a.date_jalali));
}

function _buildPeriodAchievementsHtml(studentId, form, period) {
  const sessions = _periodAchievementSessions(studentId, form.id, period.id);
  if (!sessions.length) {
    return `<div style="margin-top:14px;padding:10px 12px;background:var(--bg2);border-radius:10px;border:1px dashed var(--border);font-size:11px;color:var(--text3);text-align:center">
      🌱 هنوز دستاوردی برای این دوره ثبت نشده — دستاوردهای جلسات این بازه زمانی خودکار اینجا نمایش داده می‌شوند
    </div>`;
  }
  const items = sessions.map(s => `
    <div style="display:flex;gap:8px;padding:8px 0;border-bottom:1px solid var(--border)">
      <div style="flex-shrink:0;width:7px;height:7px;background:var(--green);border-radius:50%;margin-top:5px"></div>
      <div style="flex:1;min-width:0">
        <div style="font-size:10px;color:var(--text3);margin-bottom:2px">${DateService.disp(s.date_jalali)}</div>
        <div style="font-size:12px;color:var(--text);line-height:1.6">${renderRich(s.achievements)}</div>
      </div>
      <button onclick="closeModal();openSessionDetail(${s.id})" title="باز کردن جلسه"
        style="flex-shrink:0;align-self:flex-start;border:none;background:none;color:var(--accent2);cursor:pointer;font-size:13px">📄</button>
    </div>`).join('');
  return `
    <div style="margin-top:14px;padding:12px 14px;background:var(--bg2);border-radius:10px;border:1px solid var(--border)">
      <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:6px">🌱 دستاوردهای این دوره (${fa(sessions.length)})</div>
      ${items}
    </div>`;
}

// ── START a new period (shows date input first) ──
// "+ دوره جدید" — only relevant when there's no open period yet (e.g. the very first
// period for this form). If one is already open, just jump to it instead of duplicating.
function startNewEvalPeriod(studentId, displayName, formId) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form) return;
  const openIdx = form.periods.findIndex(p => !p.date);
  if (openIdx !== -1) {
    showToast('یک دوره در حال حاضر باز است — از دکمه «پایان دوره» برای بستن آن استفاده کن');
    openEvalFormDetail(studentId, displayName, formId, openIdx);
    return;
  }
  const importedContent = _isImportedEvalForm(form) ? (form.source_case_form_content || '') : null;
  const newPeriod = { id: genEvalId(), date: null, scores: {}, notes: {}, targets: {}, checks:{}, summary: '', actions: '', ...(importedContent !== null ? {form_content:importedContent} : {}) };
  form.periods.push(newPeriod);
  saveEvalForms(studentId, forms);
  _relinkAchievementsForStudent(studentId);
  showToast(`دوره ${fa(form.periods.length)} شروع شد ✅`);
  openEvalFormDetail(studentId, displayName, formId, form.periods.length - 1);
}

// "پایان دوره" — closes the currently open period with a chosen end date, then immediately
// opens a fresh (open) period right after it. Only valid on a period that is still open.
function endEvalPeriod(studentId, displayName, formId, periodIdx) {
  if (!studentId) studentId = _studentIdForForm(formId);
  if (!displayName) {
    const titleEl = document.querySelector('.modal-title');
    displayName = titleEl ? titleEl.textContent.replace(/^📊 .*?—\s*/, '').trim() : '';
  }
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods[periodIdx] || form.periods[periodIdx].date) return;
  const today = formatJalali(...todayJalali());
  openModal(`📅 پایان دوره ${fa(periodIdx + 1)}`, `
    <div class="form-group full">
      <label class="form-label">تاریخ پایان این دوره</label>
      <input class="form-input jdate" id="enp-date" value="${today}" placeholder="۱۴۰۵/۰۱/۰۱"
        style="text-align:center;font-size:15px;font-weight:600;letter-spacing:1px"
        oninput="this.value=this.value.replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d))">
      <div style="font-size:10px;color:var(--text3);margin-top:4px">تاریخ امروز به‌صورت پیش‌فرض وارد شده — از آیکون 📅 یا تایپ مستقیم تغییر بده</div>
      <div style="font-size:10px;color:var(--text3);margin-top:8px;line-height:1.8">با ثبت این تاریخ، دوره ${fa(periodIdx + 1)} بسته می‌شود، تمام دستاوردهای این بازه زمانی خودکار به همین دوره متصل می‌شوند و یک دوره جدید (باز) بلافاصله شروع می‌شود.</div>
    </div>
  `, [
    { label: '✅ پایان دوره', cls: 'btn-primary', action: `confirmEndEvalPeriod(${studentId},${escapeAttr(displayName)},${formId},${periodIdx})` },
    { label: 'انصراف', cls: 'btn-ghost', action: `openEvalFormDetail(${studentId},${escapeAttr(displayName)},${formId},${periodIdx})` },
  ]);
  setTimeout(() => {
    const inp = document.getElementById('enp-date');
    if (inp) attachJalaliDatePicker(inp);
  }, 0);
}

function confirmEndEvalPeriod(studentId, displayName, formId, periodIdx) {
  const raw = (document.getElementById('enp-date').value || '').trim();
  const dateVal = raw.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
  if (!dateVal) { alert('تاریخ را وارد کنید'); return; }
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods[periodIdx] || form.periods[periodIdx].date) return;
  form.periods[periodIdx].date = dateVal;
  const importedContent = _isImportedEvalForm(form) ? (form.source_case_form_content || '') : null;
  const newPeriod = { id: genEvalId(), date: null, scores: {}, notes: {}, targets: {}, checks:{}, summary: '', actions: '', ...(importedContent !== null ? {form_content:importedContent} : {}) };
  form.periods.splice(periodIdx + 1, 0, newPeriod);
  saveEvalForms(studentId, forms);
  _relinkAchievementsForStudent(studentId);
  showToast(`دوره ${fa(periodIdx + 1)} بسته شد و دوره ${fa(periodIdx + 2)} شروع شد ✅`);
  openEvalFormDetail(studentId, displayName, formId, periodIdx + 1);
}

// ── UPDATE helpers ──
// ── DELETE a period (two-step confirm) ──
function confirmDeleteEvalPeriod(formId, periodIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods[periodIdx]) return;
  const period = form.periods[periodIdx];

  // Step 1 — show confirmation inside current modal
  const container = document.getElementById('eval-table-container');
  if (!container) return;

  container.innerHTML = `
    <div style="padding:24px 16px;text-align:center">
      <div style="font-size:32px;margin-bottom:12px">⚠️</div>
      <div style="font-size:14px;font-weight:600;color:var(--text);margin-bottom:8px">حذف دوره ${fa(periodIdx+1)}</div>
      <div style="font-size:12px;color:var(--text2);margin-bottom:6px;line-height:1.8">
        دوره <strong>${fa(periodIdx+1)} · ${period.date || 'باز'}</strong> با تمام امتیازها و توضیحاتش حذف می‌شود.
      </div>
      <div style="font-size:11px;color:var(--red);margin-bottom:20px">این عمل غیر قابل بازگشت است.</div>
      <div style="display:flex;gap:10px;justify-content:center">
        <button onclick="doDeleteEvalPeriod(${formId},${periodIdx})"
          style="padding:8px 22px;font-size:13px;font-weight:600;border-radius:8px;border:none;background:var(--red);color:#fff;cursor:pointer">
          بله، حذف کن
        </button>
        <button id="cancel-delete-period"
          style="padding:8px 22px;font-size:13px;border-radius:8px;border:1px solid var(--border);background:var(--bg3);color:var(--text);cursor:pointer">
          انصراف
        </button>
      </div>
    </div>`;

  // cancel restores table — re-read from storage (fresh)
  document.getElementById('cancel-delete-period').onclick = () => {
    const freshForms = _evalLoadByKey(key);
    const freshForm = freshForms.find(f => f.id === formId);
    if (freshForm) {
      const lastIdx = freshForm.periods.length - 1;
      const safeIdx = periodIdx <= lastIdx ? periodIdx : lastIdx;
      container.innerHTML = buildEvalTable(freshForm, safeIdx, null);
      setTimeout(() => {
        container.querySelectorAll('.jdate').forEach(el => attachJalaliDatePicker(el));
      }, 0);
    }
  };
}

function doDeleteEvalPeriod(formId, periodIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form) return;

  form.periods.splice(periodIdx, 1);
  _evalSaveByKey(key, forms);
  showToast(`دوره ${fa(periodIdx+1)} حذف شد`);

  // find studentId from key
  const studentId = parseInt(key.replace('eval_forms_',''));
  _relinkAchievementsForStudent(studentId);
  // re-open form detail — need displayName, try to get from modal title
  const titleEl = document.querySelector('.modal-title');
  const displayName = titleEl ? titleEl.textContent.replace(/^📊 .*?—\s*/, '').trim() : '';
  openEvalFormDetail(studentId, displayName, formId, Math.max(0, form.periods.length - 1));
}

function updateEvalDate(formId, periodIdx, value) {
  const key = evalFindKey(formId);
  if (!key) return;
  const normalized = String(value).replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).trim();
  // only save if format looks like a date (at least 8 chars: 1404/1/1)
  if (!normalized || normalized.length < 8) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (form && form.periods[periodIdx]) {
    form.periods[periodIdx].date = normalized;
    _evalSaveByKey(key, forms);
    const studentId = parseInt(key.replace('eval_forms_',''));
    _relinkAchievementsForStudent(studentId);
    // update tab button — rebuild its full content
    const btn = document.getElementById(`eval-tab-${periodIdx}`);
    if (btn) btn.innerHTML = `دوره ${fa(periodIdx+1)} · ${normalized}`;
    showToast('تاریخ ذخیره شد ✅');
  }
}

function updateEvalScore(formId, rowId, value, periodIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (form && form.periods[periodIdx]) {
    form.periods[periodIdx].scores[rowId] = parseFloat(value) || 0;
    _evalSaveByKey(key, forms);
    // refresh total score box
    const total = evalPeriodTotal(form, form.periods[periodIdx]);
    const container = document.getElementById('eval-table-container');
    if (container && total !== null) {
      // just update the total-score div if present, avoiding full re-render that loses focus
      let totalDiv = container.querySelector('.eval-total-box');
      if (totalDiv) {
        totalDiv.querySelector('span:last-child').textContent = `${fa(total)}٪`;
      }
    }
  }
}

// ── EVAL REMINDER ──────────────────────────────────────────────────────────
function saveEvalReminder(formId, studentId) {
  const enabled = document.getElementById('er-enabled')?.checked || false;
  const interval = parseInt(document.getElementById('er-interval')?.value) || 30;
  const unit = document.getElementById('er-unit')?.value || 'day';
  const beforeHours = parseInt(document.getElementById('er-before')?.value) || 24;

  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form) return;

  // محاسبه تاریخ بعدی بر اساس آخرین دوره
  let nextDate = '';
  if (enabled && form.periods.length > 0) {
    const lastDate = form.periods[form.periods.length - 1].date;
    const parts = lastDate.split('/').map(Number);
    if (parts.length === 3) {
      // تبدیل شمسی به میلادی برای محاسبه
      try {
        const [gy, gm, gd] = jalaliToGregorian(parts[0], parts[1], parts[2]);
        const base = new Date(gy, gm - 1, gd);
        const days = unit === 'week' ? interval * 7 : interval;
        base.setDate(base.getDate() + days);
        const [jy, jm, jd] = gregorianToJalali(base.getFullYear(), base.getMonth() + 1, base.getDate());
        nextDate = `${jy}/${String(jm).padStart(2,'0')}/${String(jd).padStart(2,'0')}`;
      } catch(e) {}
    }
  }

  form.reminder = { enabled, interval, unit, beforeHours, nextDate };
  saveEvalForms(studentId, forms);
  showToast(enabled ? `یادآوری هر ${fa(interval)} ${unit==='week'?'هفته':'روز'} فعال شد ✅` : 'یادآوری غیرفعال شد');

  // آپدیت نمایش nextDate
  const nd = document.querySelector('.er-next-date');
  if (nd) nd.textContent = nextDate ? `یادآوری بعدی: ${nextDate}` : '';
}

// بررسی یادآوری‌های eval هنگام لود
function checkEvalReminders() {
  if (typeof _isTeamGuest === 'function' && _isTeamGuest()) return;
  if (!_db || !_db.eval_forms) return;
  const today = todayJalali();
  const todayStr = `${today[0]}/${String(today[1]).padStart(2,'0')}/${String(today[2]).padStart(2,'0')}`;

  Object.entries(_db.eval_forms).forEach(([sid, forms]) => {
    if (!Array.isArray(forms)) return;
    forms.forEach(form => {
      const r = form.reminder;
      if (!r || !r.enabled || !r.nextDate) return;

      // تبدیل nextDate به میلادی برای مقایسه
      try {
        const nParts = r.nextDate.split('/').map(Number);
        const [ngy, ngm, ngd] = jalaliToGregorian(nParts[0], nParts[1], nParts[2]);
        const nextMs = new Date(ngy, ngm - 1, ngd).getTime();
        const nowMs = Date.now();
        const beforeMs = (r.beforeHours || 24) * 3600000;

        // اگه در بازه یادآوری هستیم
        if (nowMs >= nextMs - beforeMs && nowMs < nextMs + 86400000) {
          const alreadyKey = `eval_reminded_${form.id}_${r.nextDate}`;
          if (!localStorage.getItem(alreadyKey)) {
            localStorage.setItem(alreadyKey, '1');
            const student = _db.students?.find(s => s.id === parseInt(sid));
            const name = student ? `${student.name} ${student.lname}` : 'شاگرد';
            showToast(`⏰ وقت ارزیابی عملکرد ${name} — ${form.title}`, 5000);
            // ارسال push notification
            if (window._pushSubscription) {
              _apiFetch('/api/reminders/send-push', {
                method: 'POST',
                body: JSON.stringify({
                  title: `⏰ یادآوری ارزیابی عملکرد`,
                  body: `${name} — ${form.title}`,
                  url: '/app'
                })
              }).catch(() => {});
            }
          }
        }
      } catch(e) {}
    });
  });
}

// چک هر ۱۵ دقیقه
setInterval(checkEvalReminders, 15 * 60 * 1000);

function updateEvalTarget(formId, rowId, value, periodIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods[periodIdx]) return;
  if (!form.periods[periodIdx].targets) form.periods[periodIdx].targets = {};
  form.periods[periodIdx].targets[rowId] = value;
  _evalSaveByKey(key, forms);
}

function updateEvalSummary(formId, periodIdx, value) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods[periodIdx]) return;
  form.periods[periodIdx].summary = value;
  _evalSaveByKey(key, forms);
  showToast('جمع‌بندی ذخیره شد ✅');
}

function updateEvalActions(formId, periodIdx, value) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods[periodIdx]) return;
  form.periods[periodIdx].actions = value;
  _evalSaveByKey(key, forms);
  showToast('اقدامات ذخیره شدند ✅');
}

function updateEvalNote(formId, rowId, value, periodIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (form && form.periods[periodIdx]) {
    form.periods[periodIdx].notes[rowId] = value;
    _evalSaveByKey(key, forms);
  }
}

// ── COMPARE two periods ──
function openEvalCompare(studentId, displayName, formId) {
  const forms = loadEvalForms(studentId);
  const form = forms.find(f => f.id === formId);
  if (!form || form.periods.length < 2) return;

  const periodOptions = form.periods.map((p,i) =>
    `<option value="${i}">دوره ${fa(i+1)} · ${p.date || 'باز'}</option>`).join('');

  openModal(`📈 مقایسه دوره‌ها — ${escapeHtml(form.title)}`, `
    <div style="display:flex;gap:10px;align-items:flex-end;margin-bottom:14px;flex-wrap:wrap">
      <div class="form-group" style="flex:1;min-width:120px;margin:0">
        <label class="form-label">دوره اول</label>
        <select class="form-input" id="cmp-a" style="padding:5px 8px">${periodOptions}</select>
      </div>
      <div class="form-group" style="flex:1;min-width:120px;margin:0">
        <label class="form-label">دوره دوم</label>
        <select class="form-input" id="cmp-b" style="padding:5px 8px">
          ${form.periods.map((p,i) => `<option value="${i}" ${i===form.periods.length-1?'selected':''}>${`دوره ${fa(i+1)} · ${p.date || 'باز'}`}</option>`).join('')}
        </select>
      </div>
      <button class="btn btn-primary" style="flex-shrink:0;padding:6px 14px" onclick="renderEvalCompare(${formId})">مقایسه</button>
    </div>
    <div id="eval-compare-result" data-student="${escapeHtml(displayName)}">${buildEvalCompareHtml(form, 0, form.periods.length-1)}</div>
  `, [
    { label: 'بازگشت', cls: 'btn-ghost', action: `openEvalFormDetail(${studentId},${escapeAttr(displayName)},${formId})` },
  ]);
}

function renderEvalCompare(formId) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form) return;
  const aIdx = parseInt(document.getElementById('cmp-a').value);
  const bIdx = parseInt(document.getElementById('cmp-b').value);
  if (aIdx === bIdx) { alert('دو دوره متفاوت انتخاب کن'); return; }
  document.getElementById('eval-compare-result').innerHTML = buildEvalCompareHtml(form, aIdx, bIdx);
}

function buildEvalCompareHtml(form, aIdx, bIdx) {
  const pA = form.periods[aIdx], pB = form.periods[bIdx];
  if (!pA || !pB) return '<p style="color:var(--text3);font-size:12px">دوره‌ای پیدا نشد</p>';

  const totalA = evalPeriodTotal(form, pA);
  const totalB = evalPeriodTotal(form, pB);
  const totalDiff = (totalA !== null && totalB !== null) ? totalB - totalA : null;
  const diffColor = totalDiff > 0 ? 'var(--green)' : totalDiff < 0 ? 'var(--red)' : 'var(--text3)';
  const diffArrow = totalDiff > 0 ? '▲' : totalDiff < 0 ? '▼' : '◆';

  // overall summary
  const summaryHtml = `
    <div style="display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap">
      <div style="flex:1;min-width:90px;background:var(--bg3);border:1px solid var(--border);border-radius:8px;padding:10px 12px;text-align:center">
        <div style="font-size:10px;color:var(--text3);margin-bottom:4px">دوره ${fa(aIdx+1)} · ${pA.date}</div>
        <div style="font-size:20px;font-weight:700;color:var(--text)">${totalA!==null?fa(totalA)+'٪':'—'}</div>
      </div>
      <div style="flex:1;min-width:90px;background:var(--bg3);border:1px solid var(--border);border-radius:8px;padding:10px 12px;text-align:center">
        <div style="font-size:10px;color:var(--text3);margin-bottom:4px">دوره ${fa(bIdx+1)} · ${pB.date}</div>
        <div style="font-size:20px;font-weight:700;color:var(--text)">${totalB!==null?fa(totalB)+'٪':'—'}</div>
      </div>
      ${totalDiff !== null ? `
      <div style="flex:1;min-width:90px;background:${totalDiff>0?'rgba(62,207,142,.08)':totalDiff<0?'rgba(248,113,113,.08)':'var(--bg3)'};border:1px solid ${totalDiff>0?'rgba(62,207,142,.25)':totalDiff<0?'rgba(248,113,113,.25)':'var(--border)'};border-radius:8px;padding:10px 12px;text-align:center">
        <div style="font-size:10px;color:var(--text3);margin-bottom:4px">تغییر کلی</div>
        <div style="font-size:20px;font-weight:700;color:${diffColor}">${diffArrow} ${fa(Math.abs(totalDiff))}٪</div>
      </div>` : ''}
    </div>`;

  // per-row comparison table
  const rowsHtml = form.rows.filter(row => !row.type || row.type === 'score').map(row => {
    const sA = pA.scores[row.id] !== undefined ? parseFloat(pA.scores[row.id]) : null;
    const sB = pB.scores[row.id] !== undefined ? parseFloat(pB.scores[row.id]) : null;
    const pctA = sA !== null ? Math.round((sA / row.maxScore) * 100) : null;
    const pctB = sB !== null ? Math.round((sB / row.maxScore) * 100) : null;
    const diff = (pctA !== null && pctB !== null) ? pctB - pctA : null;
    const dc = diff > 0 ? 'var(--green)' : diff < 0 ? 'var(--red)' : 'var(--text3)';
    const barA = pctA !== null ? `<div style="height:4px;border-radius:2px;background:${pctA>=70?'var(--green)':pctA>=40?'rgba(251,191,36,1)':'var(--red)'};width:${pctA}%;min-width:2px"></div>` : '';
    const barB = pctB !== null ? `<div style="height:4px;border-radius:2px;background:${pctB>=70?'var(--green)':pctB>=40?'rgba(251,191,36,1)':'var(--red)'};width:${pctB}%;min-width:2px"></div>` : '';
    return `
      <tr>
        <td style="padding:7px 10px;font-size:12px;color:var(--text);font-weight:500;border-bottom:1px solid var(--border)">${escapeHtml(row.label)}</td>
        <td style="padding:7px 6px;border-bottom:1px solid var(--border)">
          <div style="font-size:12px;color:var(--text2)">${sA!==null?fa(sA)+'/'+fa(row.maxScore):'—'}</div>
          <div style="width:100%;background:var(--border);border-radius:2px;overflow:hidden;margin-top:3px;height:4px">${barA}</div>
        </td>
        <td style="padding:7px 6px;border-bottom:1px solid var(--border)">
          <div style="font-size:12px;color:var(--text2)">${sB!==null?fa(sB)+'/'+fa(row.maxScore):'—'}</div>
          <div style="width:100%;background:var(--border);border-radius:2px;overflow:hidden;margin-top:3px;height:4px">${barB}</div>
        </td>
        <td style="padding:7px 6px;border-bottom:1px solid var(--border);text-align:center">
          ${diff !== null ? `<span style="font-size:12px;font-weight:600;color:${dc}">${diff>0?'▲':'▼'} ${fa(Math.abs(diff))}٪</span>` : '<span style="color:var(--text3);font-size:11px">—</span>'}
        </td>
      </tr>`;
  }).join('');

  // mini trend chart (SVG bar chart — no lib needed)
  const allTotals = form.periods.map(p => evalPeriodTotal(form, p));
  const chartHtml = buildEvalTrendChart(form, allTotals, aIdx, bIdx);

  // ── دستاوردهای هر دوره + مقایسه (جدید / تکرارشونده) — شواهد کیفی رشد ──
  const achCompareHtml = (() => {
    const studentId = _studentIdForForm(form.id);
    if (!studentId) return '';
    const sessA = _periodAchievementSessions(studentId, form.id, pA.id);
    const sessB = _periodAchievementSessions(studentId, form.id, pB.id);
    if (!sessA.length && !sessB.length) return '';
    const norm = t => (t || '').replace(/\s+/g, ' ').trim().toLowerCase();
    const aTexts = sessA.map(s => norm(s.achievements));
    const newOnes = sessB.filter(s => !aTexts.includes(norm(s.achievements)));
    const repeatedOnes = sessB.filter(s => aTexts.includes(norm(s.achievements)));
    const listItem = s => `<div style="font-size:12px;color:var(--text);padding:3px 0;display:flex;align-items:flex-start;gap:6px">
        <span style="flex:1">${renderRich(s.achievements)}</span>
        <button onclick="closeModal();openSessionDetail(${s.id})" style="border:none;background:none;color:var(--accent2);cursor:pointer;font-size:12px;flex-shrink:0">📄</button>
      </div>`;
    return `
      <div style="margin-top:14px;padding:12px 14px;background:var(--bg2);border-radius:10px;border:1px solid var(--border)">
        <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:8px">🌱 دستاوردهای دوره ${fa(bIdx+1)} در مقایسه با دوره ${fa(aIdx+1)}</div>
        ${newOnes.length ? `
          <div style="margin-bottom:8px">
            <div style="font-size:10px;font-weight:600;color:var(--green);margin-bottom:4px">✨ دستاوردهای جدید (${fa(newOnes.length)})</div>
            ${newOnes.map(listItem).join('')}
          </div>` : ''}
        ${repeatedOnes.length ? `
          <div>
            <div style="font-size:10px;font-weight:600;color:rgba(251,191,36,1);margin-bottom:4px">🔄 دستاوردهای تکرارشونده (${fa(repeatedOnes.length)})</div>
            ${repeatedOnes.map(listItem).join('')}
          </div>` : ''}
        ${!newOnes.length && !repeatedOnes.length ? '<div style="font-size:11px;color:var(--text3)">دستاوردی برای دوره دوم ثبت نشده</div>' : ''}
      </div>`;
  })();

  return `
    ${summaryHtml}
    ${chartHtml}
    ${achCompareHtml}
    <table style="width:100%;border-collapse:collapse;margin-top:12px">
      <thead>
        <tr style="background:var(--bg2)">
          <th style="padding:6px 10px;text-align:right;font-size:11px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);width:34%">شاخص</th>
          <th style="padding:6px 6px;text-align:right;font-size:11px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);width:22%">دوره ${fa(aIdx+1)}</th>
          <th style="padding:6px 6px;text-align:right;font-size:11px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);width:22%">دوره ${fa(bIdx+1)}</th>
          <th style="padding:6px 6px;text-align:center;font-size:11px;font-weight:600;color:var(--text2);border-bottom:1px solid var(--border);width:22%">تغییر</th>
        </tr>
      </thead>
      <tbody>${rowsHtml}</tbody>
    </table>
    <div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap">
      <button onclick="downloadEvalCompare(${form.id},${aIdx},${bIdx})"
        style="padding:5px 14px;font-size:11px;border-radius:6px;border:1px solid rgba(96,165,250,.4);background:rgba(96,165,250,.08);color:var(--blue);cursor:pointer">
        ⬇ دانلود گزارش مقایسه
      </button>
      <button onclick="shareEvalCompare(${form.id},${aIdx},${bIdx})"
        style="padding:5px 14px;font-size:11px;border-radius:6px;border:1px solid rgba(62,207,142,.4);background:rgba(62,207,142,.08);color:var(--green);cursor:pointer">
        ↗ اشتراک‌گذاری
      </button>
    </div>`;
}

// ── SHARE helpers ──
function _evalBuildSharePage(title, senderName, bodyHtml, studentName) {
  const appTitle = (typeof META !== 'undefined' && META.appTitle) ? META.appTitle : 'TeamPulse';
  // همیشه از URL ثابت سرور استفاده می‌کنیم
  const logoUrl = '/logo.png';
  const inviteUrl = 'https://teampulse.ir';

  return `<!DOCTYPE html>
<html lang="fa" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta property="og:title" content="${title}">
<meta property="og:description" content="ارزیابی عملکرد توسط ${senderName} از ${appTitle}">
<meta property="og:url" content="${inviteUrl}">
<link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700&display=swap" rel="stylesheet">
<title>${title}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Vazirmatn',Tahoma,sans-serif;direction:rtl;background:#f0f2f8;color:#1a1d2e;min-height:100vh;padding:24px 16px 48px}
.wrap{max-width:640px;margin:0 auto}
.brand{display:flex;align-items:center;gap:12px;margin-bottom:20px;padding:14px 16px;background:#fff;border-radius:12px;border:1px solid #e5e7eb}
.brand-logo{width:44px;height:44px;border-radius:10px;object-fit:cover;flex-shrink:0;background:#7c6af7;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:700;color:#fff}
.brand-name{font-size:15px;font-weight:700;color:#1a1d2e}
.brand-sub{font-size:11px;color:#6b7280;margin-top:2px}
.card{background:#fff;border-radius:12px;border:1px solid #e5e7eb;padding:20px;margin-bottom:16px}
.card-title{font-size:14px;font-weight:700;color:#1a1d2e;margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid #f3f4f6}
.cards{display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap}
.stat{flex:1;min-width:80px;border:1px solid #e5e7eb;border-radius:8px;padding:10px 12px;text-align:center;background:#f9fafb}
.stat-label{font-size:10px;color:#9ca3af;margin-bottom:4px}
.stat-val{font-size:20px;font-weight:700;color:#1a1d2e}
.stat-val.green{color:#059669}.stat-val.red{color:#dc2626}
table{width:100%;border-collapse:collapse;margin-bottom:12px}
th{padding:7px 10px;text-align:right;font-size:11px;font-weight:600;color:#6b7280;border-bottom:2px solid #e5e7eb;background:#f9fafb}
td{padding:7px 10px;font-size:12px;border-bottom:1px solid #f3f4f6;color:#374151}
.bar-wrap{width:52px;height:5px;background:#e5e7eb;border-radius:3px;display:inline-block;vertical-align:middle;margin-right:5px;overflow:hidden}
.bar-fill{height:100%;border-radius:3px}
.total-box{padding:10px 14px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.total-val{font-size:18px;font-weight:700;color:#059669}
.diff-pos{color:#059669;font-weight:600}.diff-neg{color:#dc2626;font-weight:600}.diff-zero{color:#6b7280}
.invite{background:linear-gradient(135deg,#7c6af7,#60a5fa);border-radius:12px;padding:20px 18px;text-align:center;color:#fff;margin-top:20px}
.invite-title{font-size:15px;font-weight:700;margin-bottom:6px}
.invite-sub{font-size:12px;opacity:.85;margin-bottom:14px;line-height:1.8}
.invite-sender{font-size:11px;opacity:.7;margin-bottom:14px}
.invite-btn{display:inline-block;padding:10px 28px;background:#fff;color:#7c6af7;border-radius:8px;font-size:13px;font-weight:700;text-decoration:none;font-family:'Vazirmatn',Tahoma,sans-serif}
.invite-btn:hover{opacity:.9}
.chart-box{border:1px solid #e5e7eb;border-radius:8px;padding:10px 12px;margin-bottom:14px;background:#f9fafb}
.chart-label{font-size:10px;color:#9ca3af;margin-bottom:6px}
.section-title{font-size:10px;font-weight:600;color:#9ca3af;margin:12px 0 6px;text-transform:uppercase;letter-spacing:.05em}
</style>
</head>
<body>
<div class="wrap">
  <div class="brand">
    ${logoUrl ? `<img src="${logoUrl}" class="brand-logo" alt="${appTitle}" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div class="brand-logo" style="display:none">${appTitle.charAt(0)}</div>` : `<div class="brand-logo">${appTitle.charAt(0)}</div>`}
    <div>
      <div class="brand-name">${appTitle}</div>
      <div class="brand-sub">ارسال‌شده توسط ${senderName}</div>
    </div>
  </div>
  <div class="card">
    <div class="card-title">${title}</div>
    ${studentName ? `<div style="display:flex;align-items:center;gap:6px;margin-bottom:12px;padding:7px 10px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:7px"><span style="font-size:12px">👤</span><span style="font-size:12px;font-weight:600;color:#0369a1">${studentName}</span></div>` : ''}
    ${bodyHtml}
  </div>
  <div class="invite">
    <div class="invite-title">به برنامه مدیریتی &quot;تیم پالس&quot; بپیوندید</div>
    <div class="invite-sub">سیستم مدیریت کوچینگ و ارزیابی عملکرد<br>ثبت جلسات · پیگیری پیشرفت · گزارش‌های هوشمند</div>
    <div class="invite-sender">دعوت‌نامه از ${senderName}</div>
    <a href="${inviteUrl}" class="invite-btn">ورود به برنامه تیم پالس</a>
  </div>
</div>
</body></html>`;
}

function _evalGetSenderName() {
  // Try to get coach name from sidebar
  const el = document.querySelector('.sidebar-logo h1') || document.getElementById('app-title');
  if (el && el.textContent && el.textContent.trim()) {
    // sidebar logo h1 shows app title — look for user name in sidebar bottom
    const coachBtn = document.querySelector('#logout-btn') || null;
    const nameEl = document.querySelector('.btn-sidebar[onclick*="openWalletPanel"]') || null;
  }
  // Fallback: use META appTitle or default
  return (typeof META !== 'undefined' && META.appTitle) ? META.appTitle : 'TeamPulse';
}

async function _evalShare(filename, htmlContent, title, studentName) {
  // Show loading state
  const loadingId = 'share-loading-' + Date.now();
  document.getElementById('modals').innerHTML += `
    <div class="modal-overlay open" id="share-overlay" style="z-index:1001">
      <div class="modal" style="max-width:320px;text-align:center">
        <div class="modal-body" style="padding:32px 24px">
          <div style="font-size:28px;margin-bottom:12px">⏳</div>
          <div style="font-size:13px;color:var(--text2)">در حال آماده‌سازی لینک اشتراک‌گذاری...</div>
        </div>
      </div>
    </div>`;

  let shareUrl = null;
  try {
    const res = await _apiFetch('/api/share', {
      method: 'POST',
      body: JSON.stringify({ html: htmlContent }),
    });
    const ct = res.headers.get('content-type') || '';
    if (res.ok && ct.includes('application/json')) {
      const data = await res.json();
      shareUrl = data.url;
    } else {
      console.warn('[share] server not ready yet (status:', res.status, ')');
    }
  } catch(e) {
    console.warn('[share] upload failed:', e.message);
  }

  // Remove loading modal
  const overlay = document.getElementById('share-overlay');
  if (overlay) overlay.remove();

  if (!shareUrl) {
    // Fallback: download only
    _evalShareFallback(filename, htmlContent, title);
    return;
  }

  // Build default share message
  const sender = _evalGetSenderName();
  const greeting = studentName ? (studentName + ' عزیز،\n') : '';
  const defaultMsg = `${greeting}نتایج ارزیابی عملکردت آماده‌ست 📊\n\nیه نگاه بنداز — اعداد از رشدت حرف می‌زنن 👇\n${shareUrl}\n\n— ${sender || 'کوچ'} | TeamPulse`;

  document.getElementById('modals').innerHTML += `
    <div class="modal-overlay open" id="share-overlay" onclick="if(event.target===this)closeShareModal()" style="z-index:1001">
      <div class="modal" style="max-width:440px">
        <div class="modal-header">
          <div class="modal-title">↗ اشتراک‌گذاری فرم</div>
          <button class="modal-close" onclick="closeShareModal()">×</button>
        </div>
        <div class="modal-body">

          <!-- لینک -->
          <div style="background:var(--bg3);border-radius:8px;padding:10px 12px;margin-bottom:12px;border:1px solid var(--border)">
            <div style="font-size:10px;color:var(--text3);margin-bottom:5px">لینک اشتراک‌گذاری (۳۰ روز معتبر):</div>
            <div style="display:flex;gap:6px;align-items:center">
              <input id="share-link-input" type="text" value="${shareUrl}" readonly
                style="flex:1;font-size:11px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;background:var(--bg2);color:var(--text);direction:ltr;text-align:left">
              <button onclick="evalCopyLink('${shareUrl}')"
                style="padding:5px 10px;font-size:11px;border-radius:6px;border:1px solid var(--border);background:var(--bg2);color:var(--text2);cursor:pointer;white-space:nowrap">
                📋 کپی لینک
              </button>
            </div>
            <div style="font-size:10px;color:var(--text3);margin-top:4px">گیرنده بدون ثبت‌نام می‌تواند فرم را ببیند</div>
          </div>

          <!-- پیش‌نمایش پیام قابل ویرایش -->
          <div style="margin-bottom:12px">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
              <span style="font-size:10px;color:var(--text3)">پیش‌نمایش پیام — قابل ویرایش:</span>
              <button onclick="evalResetMsg()" style="font-size:10px;color:var(--text3);background:none;border:none;cursor:pointer;text-decoration:underline">بازنشانی</button>
            </div>
            <textarea id="share-msg-preview"
              style="width:100%;min-height:100px;padding:9px 12px;font-size:12px;font-family:Vazirmatn,Tahoma,sans-serif;line-height:1.9;border:1px solid var(--border);border-radius:8px;background:var(--bg3);color:var(--text);resize:vertical;direction:rtl"
              oninput="evalUpdateShareLinks()"
            >${defaultMsg}</textarea>
          </div>

          <!-- دکمه‌های share -->
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px">

            <a id="share-btn-whatsapp" href="https://api.whatsapp.com/send?text=${encodeURIComponent(defaultMsg)}" target="_blank" rel="noopener noreferrer" onclick="setTimeout(closeShareModal,500)"
              style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:8px;background:rgba(37,211,102,.1);border:1px solid rgba(37,211,102,.3);color:#128c7e;text-decoration:none;font-size:12px;font-weight:600">
              <span style="font-size:18px">📱</span> واتساپ
            </a>

            <a id="share-btn-telegram" href="https://t.me/share/url?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(defaultMsg)}" target="_blank" rel="noopener noreferrer" onclick="setTimeout(closeShareModal,500)"
              style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:8px;background:rgba(41,182,246,.1);border:1px solid rgba(41,182,246,.3);color:#0088cc;text-decoration:none;font-size:12px;font-weight:600">
              <span style="font-size:18px">✈️</span> تلگرام
            </a>

            <button id="share-btn-eitaa" onclick="evalShareCopyMsg()"
              style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:8px;background:rgba(124,106,247,.1);border:1px solid rgba(124,106,247,.3);color:var(--accent2);font-size:12px;font-weight:600;cursor:pointer">
              <span style="font-size:18px">💜</span> ایتا / روبیکا
            </button>

            <a id="share-btn-sms" href="sms:?body=${encodeURIComponent(defaultMsg)}"
              style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:8px;background:rgba(62,207,142,.1);border:1px solid rgba(62,207,142,.3);color:var(--green);text-decoration:none;font-size:12px;font-weight:600">
              <span style="font-size:18px">💬</span> پیامک
            </a>

            <a id="share-btn-email" href="mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(defaultMsg)}"
              style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:8px;background:rgba(96,165,250,.1);border:1px solid rgba(96,165,250,.3);color:var(--blue);text-decoration:none;font-size:12px;font-weight:600">
              <span style="font-size:18px">📧</span> ایمیل
            </a>

            <a id="share-btn-linkedin" href="https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}" target="_blank" rel="noopener noreferrer" onclick="setTimeout(closeShareModal,500)"
              style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:8px;background:rgba(10,102,194,.1);border:1px solid rgba(10,102,194,.3);color:#0a66c2;text-decoration:none;font-size:12px;font-weight:600">
              <span style="font-size:18px">💼</span> لینکدین
            </a>

          </div>

          <div style="font-size:10px;color:var(--text3);text-align:center;line-height:1.7">
            متن پیام رو ویرایش کن — لینک‌ها خودکار آپدیت می‌شن
          </div>

        </div>
      </div>
    </div>`;

  // store defaults for reset
  window._evalShareDefaultMsg = defaultMsg;
  window._evalShareUrl = shareUrl;
  window._evalShareTitle = title;
}

function evalCopyLink(url) {
  navigator.clipboard.writeText(url).then(() => {
    showToast('لینک کپی شد ✅');
  }).catch(() => {
    const inp = document.getElementById('share-link-input');
    if (inp) { inp.select(); document.execCommand('copy'); showToast('لینک کپی شد ✅'); }
  });
}

// وقتی textarea تغییر می‌کنه، همه لینک‌ها آپدیت می‌شن
function evalUpdateShareLinks() {
  const ta = document.getElementById('share-msg-preview');
  if (!ta) return;
  const msg = ta.value;
  const enc = encodeURIComponent(msg);
  const url = window._evalShareUrl || '';
  const title = window._evalShareTitle || '';

  const wa = document.getElementById('share-btn-whatsapp');
  const tg = document.getElementById('share-btn-telegram');
  const sm = document.getElementById('share-btn-sms');
  const em = document.getElementById('share-btn-email');

  if (wa) wa.href = `https://api.whatsapp.com/send?text=${enc}`;
  if (tg) tg.href = `https://t.me/share/url?url=${encodeURIComponent(url)}&text=${enc}`;
  if (sm) sm.href = `sms:?body=${enc}`;
  if (em) em.href = `mailto:?subject=${encodeURIComponent(title)}&body=${enc}`;
}

function evalResetMsg() {
  const ta = document.getElementById('share-msg-preview');
  if (ta && window._evalShareDefaultMsg) {
    ta.value = window._evalShareDefaultMsg;
    evalUpdateShareLinks();
  }
}

function evalShareCopyMsg() {
  const ta = document.getElementById('share-msg-preview');
  const msg = ta ? ta.value : (window._evalShareDefaultMsg || '');
  navigator.clipboard.writeText(msg).then(() => {
    showToast('متن کپی شد — برو ایتا / روبیکا و Paste کن ✅');
    closeShareModal();
  }).catch(() => { showToast('خطا در کپی'); });
}

function _evalShareFallback(filename, htmlContent, title) {
  const blob = new Blob([htmlContent], { type: 'text/html;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const shareText = `${title}\n\nارزیابی عملکرد با TeamPulse\n🔗 teampulse.ir`;
  const encodedText = encodeURIComponent(shareText);

  document.getElementById('modals').innerHTML += `
    <div class="modal-overlay open" id="share-overlay" onclick="if(event.target===this)closeShareModal()" style="z-index:1001">
      <div class="modal" style="max-width:400px">
        <div class="modal-header">
          <div class="modal-title">↗ اشتراک‌گذاری فرم</div>
          <button class="modal-close" onclick="closeShareModal()">×</button>
        </div>
        <div class="modal-body">

          <div style="background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.25);border-radius:8px;padding:12px 14px;margin-bottom:14px;font-size:12px;color:var(--text2);line-height:1.9">
            <div style="font-weight:600;margin-bottom:4px">⚙️ سرویس لینک‌سازی هنوز فعال نشده</div>
            برای ارسال مستقیم، فایل رو دانلود کن و در پیام‌رسان ارسال کن — یا متن رو کپی کن.
          </div>

          <div style="background:var(--bg3);border-radius:8px;padding:10px 12px;margin-bottom:12px;border:1px solid var(--border)">
            <div style="font-size:10px;color:var(--text3);margin-bottom:4px">متن آماده برای ارسال:</div>
            <div style="font-size:12px;color:var(--text);line-height:1.8;white-space:pre-wrap">${shareText}</div>
          </div>

          <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
            <button onclick="evalShareCopy('${encodedText}','متن کپی شد ✅')"
              style="display:flex;align-items:center;justify-content:center;gap:6px;padding:9px;border-radius:7px;border:1px solid var(--border);background:var(--bg3);color:var(--text);font-size:12px;cursor:pointer">
              📋 کپی متن
            </button>
            <button onclick="downloadShareFile('${url}','${filename}')"
              style="display:flex;align-items:center;justify-content:center;gap:6px;padding:9px;border-radius:7px;border:1px solid rgba(96,165,250,.3);background:rgba(96,165,250,.1);color:var(--blue);font-size:12px;cursor:pointer">
              ⬇ دانلود فایل HTML
            </button>
            <a href="https://api.whatsapp.com/send?text=${encodedText}" target="_blank" rel="noopener noreferrer" onclick="setTimeout(closeShareModal,500)"
              style="display:flex;align-items:center;justify-content:center;gap:6px;padding:9px;border-radius:7px;border:1px solid rgba(37,211,102,.3);background:rgba(37,211,102,.1);color:#128c7e;text-decoration:none;font-size:12px;font-weight:600">
              📱 واتساپ
            </a>
            <button onclick="evalShareSMS('${encodedText}')"
              style="display:flex;align-items:center;justify-content:center;gap:6px;padding:9px;border-radius:7px;border:1px solid rgba(62,207,142,.3);background:rgba(62,207,142,.1);color:var(--green);font-size:12px;cursor:pointer">
              💬 پیامک
            </button>
          </div>

          <div style="margin-top:10px;font-size:10px;color:var(--text3);text-align:center">
            برای فعال‌سازی لینک‌سازی، کد share-route.js رو به سرور اضافه کن
          </div>
        </div>
      </div>
    </div>`;
}

function closeShareModal() {
  const el = document.getElementById('share-overlay');
  if (el) el.remove();
}

function evalShareCopy(encodedText, toastMsg) {
  const text = decodeURIComponent(encodedText);
  navigator.clipboard.writeText(text).then(() => {
    showToast(toastMsg || 'کپی شد ✅');
    closeShareModal();
  }).catch(() => { showToast('خطا در کپی — متن را دستی کپی کنید'); });
}

function evalShareCopyForTelegram(encodedText) {
  evalShareCopy(encodedText, 'متن کپی شد — برو تلگرام و Paste کن ✅');
}

function evalShareCopyText(encodedText) {
  evalShareCopy(encodedText, 'متن کپی شد ✅');
}

function evalShareSMS(encodedText) {
  const text = decodeURIComponent(encodedText);
  window.location.href = `sms:?body=${encodeURIComponent(text)}`;
  setTimeout(closeShareModal, 500);
}

function evalShareEmail(encodedText, encodedSubject) {
  const text = decodeURIComponent(encodedText);
  const subject = decodeURIComponent(encodedSubject);
  window.location.href = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(text)}`;
  setTimeout(closeShareModal, 500);
}

function shareEvalCopyLink() {
  navigator.clipboard.writeText('https://teampulse.ir').then(() => {
    showToast('لینک دعوت کپی شد ✅');
  }).catch(() => { showToast('لینک: teampulse.ir'); });
}

function downloadShareFile(url, filename) {
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
  showToast('فایل دانلود شد ✅');
  closeShareModal();
}

function shareEvalPeriod(formId, periodIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form) return;
  const period = form.periods[periodIdx];
  if (!period) return;
  const totalScore = evalPeriodTotal(form, period);
  const sender = _evalGetSenderName();

  // اسم شاگرد از عنوان مودال
  const studentName = document.getElementById('eval-table-container')?.dataset?.student || '';

  const rowsHtml = form.rows.map(row => {
    const score = period.scores[row.id] !== undefined ? parseFloat(period.scores[row.id]) : null;
    const note = period.notes[row.id] || '';
    const target = (period.targets || {})[row.id];
    const pct = score !== null ? Math.round((score / row.maxScore) * 100) : null;
    const tgtPct = target !== undefined && target !== '' ? Math.round((parseFloat(target) / row.maxScore) * 100) : null;
    const barColor = pct !== null ? (pct >= 70 ? '#059669' : pct >= 40 ? '#d97706' : '#dc2626') : '#e5e7eb';
    const gapCell = tgtPct !== null && pct !== null
      ? (tgtPct <= pct
          ? `<span style="font-size:10px;padding:1px 6px;border-radius:4px;background:#d1fae5;color:#065f46">✓ هدف</span>`
          : `<span style="font-size:10px;padding:1px 6px;border-radius:4px;background:#fef3c7;color:#92400e">${tgtPct - pct}٪ مانده</span>`)
      : '';
    return `<tr>
      <td>${escapeHtml(row.label)}</td>
      <td>${score !== null ? `<span class="bar-wrap"><span class="bar-fill" style="width:${pct}%;background:${barColor}"></span></span>${score}/${row.maxScore} <span style="font-size:10px;color:#9ca3af">(${pct}٪)</span>` : '—'}</td>
      <td style="color:#6b7280;font-size:11px">${note || '—'}</td>
      <td style="text-align:center">${tgtPct !== null ? `<span style="font-size:10px;color:#6b7280">${target}/${row.maxScore}</span><br>${gapCell}` : '—'}</td>
    </tr>`;
  }).join('');

  // نام شاگرد بالای جدول
  const studentBadge = studentName ? `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;padding:8px 12px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px">
      <span style="font-size:13px">👤</span>
      <span style="font-size:12px;font-weight:600;color:#0369a1">شاگرد: ${studentName}</span>
    </div>` : '';

  const summarySection = period.summary ? `
    <div class="section-title">جمع‌بندی مربی</div>
    <div style="padding:10px 14px;background:#f9fafb;border-right:3px solid #7c6af7;border-radius:0 8px 8px 0;font-size:12px;color:#374151;line-height:1.9;margin-bottom:12px">${period.summary.replace(/\n/g,'<br>')}</div>` : '';

  const actionsSection = period.actions ? `
    <div class="section-title">اقدامات و تکالیف بعدی</div>
    <div style="padding:10px 14px;background:#f0fdf4;border-right:3px solid #059669;border-radius:0 8px 8px 0;font-size:12px;color:#374151;line-height:1.9;margin-bottom:12px">${period.actions.replace(/\n/g,'<br>')}</div>` : '';

  const body = `
    ${studentBadge}
    ${totalScore !== null ? `<div class="total-box"><span style="font-size:12px;color:#374151">امتیاز کل · دوره ${periodIdx+1}</span><span class="total-val">${fa(totalScore)}٪</span></div>` : ''}
    <div class="section-title">جدول ارزیابی</div>
    <table>
      <thead><tr><th style="width:35%">شاخص</th><th style="width:30%">امتیاز</th><th style="width:22%">توضیحات</th><th style="width:13%;text-align:center">هدف</th></tr></thead>
      <tbody>${rowsHtml}</tbody>
    </table>
    <p style="font-size:10px;color:#9ca3af;margin-top:8px;margin-bottom:14px">تاریخ دوره: ${period.date || 'باز (هنوز پایان نیافته)'}</p>
    ${summarySection}
    ${actionsSection}`;

  const title = `ارزیابی عملکرد · ${escapeHtml(form.title)} · ${studentName ? studentName + ' · ' : ''}دوره ${periodIdx+1}`;
  const html = _evalBuildSharePage(title, sender, body, studentName);
  _evalShare(`اشتراک-ارزیابی-${form.title}-د${periodIdx+1}.html`, html, title, studentName);
}

function shareEvalCompare(formId, aIdx, bIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form) return;
  const pA = form.periods[aIdx], pB = form.periods[bIdx];
  if (!pA || !pB) return;
  const totalA = evalPeriodTotal(form, pA);
  const totalB = evalPeriodTotal(form, pB);
  const totalDiff = (totalA !== null && totalB !== null) ? totalB - totalA : null;
  const sender = _evalGetSenderName();

  // اسم شاگرد از عنوان مودال
  const studentName = document.getElementById('eval-compare-result')?.dataset?.student ||
                      document.getElementById('eval-table-container')?.dataset?.student || '';

  const cardsHtml = `
    <div class="cards">
      <div class="stat"><div class="stat-label">دوره ${fa(aIdx+1)} · ${pA.date}</div><div class="stat-val">${totalA !== null ? fa(totalA)+'٪' : '—'}</div></div>
      <div class="stat"><div class="stat-label">دوره ${fa(bIdx+1)} · ${pB.date}</div><div class="stat-val">${totalB !== null ? fa(totalB)+'٪' : '—'}</div></div>
      ${totalDiff !== null ? `<div class="stat" style="border-color:${totalDiff>0?'#bbf7d0':totalDiff<0?'#fecaca':'#e5e7eb'}"><div class="stat-label">تغییر کلی</div><div class="stat-val ${totalDiff>0?'green':totalDiff<0?'red':''}">${totalDiff>0?'▲':'▼'} ${fa(Math.abs(totalDiff))}٪</div></div>` : ''}
    </div>`;

  // trend chart
  const allTotals = form.periods.map(p => evalPeriodTotal(form, p));
  const valid = allTotals.map((t,i)=>({i,t})).filter(x=>x.t!==null);
  let chartSvg = '';
  if (valid.length >= 2) {
    const W=400,H=80,pad=20;
    const xStep = (W-pad*2)/(valid.length-1);
    const pts = valid.map((x,j)=>({ cx:pad+j*xStep, cy:H-pad-((x.t/100)*(H-pad*2)), t:x.t, i:x.i }));
    const polyline = pts.map(p=>`${p.cx},${p.cy}`).join(' ');
    const dots = pts.map(p=>{
      const hl = p.i===aIdx||p.i===bIdx;
      return `<circle cx="${p.cx}" cy="${p.cy}" r="${hl?5:3}" fill="${hl?'#059669':'#7c6af7'}" stroke="#fff" stroke-width="1.5"/>
        <text x="${p.cx}" y="${p.cy-9}" text-anchor="middle" font-size="9" fill="${hl?'#059669':'#6b7280'}" font-family="Vazirmatn,Tahoma">${fa(p.t)}٪</text>`;
    }).join('');
    const labels = pts.map((p,j)=>`<text x="${p.cx}" y="${H-3}" text-anchor="middle" font-size="8" fill="#9ca3af" font-family="Vazirmatn,Tahoma">د${fa(valid[j].i+1)}</text>`).join('');
    chartSvg = `<div class="chart-box"><div class="chart-label">روند پیشرفت</div>
      <svg width="100%" viewBox="0 0 ${W} ${H}" style="overflow:visible">
        <polyline points="${polyline}" fill="none" stroke="#7c6af7" stroke-width="1.5" stroke-linejoin="round"/>
        ${dots}${labels}
      </svg></div>`;
  }

  const rowsHtml = form.rows.map(row => {
    const sA = pA.scores[row.id] !== undefined ? parseFloat(pA.scores[row.id]) : null;
    const sB = pB.scores[row.id] !== undefined ? parseFloat(pB.scores[row.id]) : null;
    const pctA = sA !== null ? Math.round((sA/row.maxScore)*100) : null;
    const pctB = sB !== null ? Math.round((sB/row.maxScore)*100) : null;
    const diff = (pctA!==null&&pctB!==null) ? pctB-pctA : null;
    const bA = pctA!==null ? `<span class="bar-wrap"><span class="bar-fill" style="width:${pctA}%;background:${pctA>=70?'#059669':pctA>=40?'#d97706':'#dc2626'}"></span></span>${fa(sA)}/${fa(row.maxScore)}` : '—';
    const bB = pctB!==null ? `<span class="bar-wrap"><span class="bar-fill" style="width:${pctB}%;background:${pctB>=70?'#059669':pctB>=40?'#d97706':'#dc2626'}"></span></span>${fa(sB)}/${fa(row.maxScore)}` : '—';
    const diffHtml = diff!==null ? `<span class="${diff>0?'diff-pos':diff<0?'diff-neg':'diff-zero'}">${diff>0?'▲':'▼'} ${fa(Math.abs(diff))}٪</span>` : '—';
    return `<tr><td>${escapeHtml(row.label)}</td><td>${bA}</td><td>${bB}</td><td style="text-align:center">${diffHtml}</td></tr>`;
  }).join('');

  // نام شاگرد بالای مقایسه
  const studentBadge = studentName ? `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;padding:8px 12px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px">
      <span style="font-size:13px">👤</span>
      <span style="font-size:12px;font-weight:600;color:#0369a1">شاگرد: ${studentName}</span>
    </div>` : '';

  const body = `
    ${cardsHtml}
    ${chartSvg}
    <div class="section-title">مقایسه شاخص به شاخص</div>
    <table>
      <thead><tr><th style="width:34%">شاخص</th><th style="width:22%">دوره ${fa(aIdx+1)}</th><th style="width:22%">دوره ${fa(bIdx+1)}</th><th style="width:22%;text-align:center">تغییر</th></tr></thead>
      <tbody>${rowsHtml}</tbody>
    </table>`;

  const title = `مقایسه عملکرد · ${escapeHtml(form.title)} · ${studentName ? studentName + ' · ' : ''}دوره ${aIdx+1} vs ${bIdx+1}`;
  const html = _evalBuildSharePage(title, sender, body, studentName);
  _evalShare(`اشتراک-مقایسه-${form.title}-د${aIdx+1}-د${bIdx+1}.html`, html, title, studentName);
}

// ── DOWNLOAD helpers ──
function _evalDownload(filename, htmlContent) {
  const blob = new Blob([htmlContent], { type: 'text/html;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

function _evalPrintShell(title, bodyHtml) {
  const printScript = '<' + 'script>window.onload=()=>{window.focus();setTimeout(()=>window.print(),500);</' + 'script>';
  return `<!DOCTYPE html>
<html lang="fa" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700&display=swap" rel="stylesheet">
<title>${title}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Vazirmatn',Tahoma,sans-serif;direction:rtl;background:#fff;color:#1a1d2e;padding:32px 36px;font-size:13px;line-height:1.8}
h1{font-size:18px;font-weight:700;margin-bottom:4px;color:#1a1d2e}
.meta{font-size:11px;color:#6b7280;margin-bottom:20px}
.cards{display:flex;gap:12px;margin-bottom:18px;flex-wrap:wrap}
.card{flex:1;min-width:90px;border:1px solid #e5e7eb;border-radius:8px;padding:10px 14px;text-align:center}
.card-label{font-size:10px;color:#9ca3af;margin-bottom:4px}
.card-val{font-size:22px;font-weight:700;color:#1a1d2e}
.card-val.green{color:#059669}.card-val.red{color:#dc2626}.card-val.blue{color:#2563eb}
table{width:100%;border-collapse:collapse;margin-bottom:16px}
th{padding:7px 10px;text-align:right;font-size:11px;font-weight:600;color:#6b7280;border-bottom:2px solid #e5e7eb;background:#f9fafb}
td{padding:7px 10px;font-size:12px;border-bottom:1px solid #f3f4f6;color:#374151}
.bar-wrap{width:60px;height:5px;background:#e5e7eb;border-radius:3px;display:inline-block;vertical-align:middle;margin-right:6px;overflow:hidden}
.bar-fill{height:100%;border-radius:3px}
.total-box{padding:10px 16px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}
.total-label{font-size:12px;color:#374151}
.total-val{font-size:20px;font-weight:700;color:#059669}
.diff-pos{color:#059669;font-weight:600}
.diff-neg{color:#dc2626;font-weight:600}
.diff-zero{color:#6b7280}
.section-title{font-size:11px;font-weight:600;color:#9ca3af;margin:14px 0 6px;padding-bottom:4px;border-bottom:1px solid #e5e7eb;text-transform:uppercase;letter-spacing:.05em}
.chart-box{border:1px solid #e5e7eb;border-radius:8px;padding:10px 14px;margin-bottom:16px;background:#f9fafb}
.chart-label{font-size:10px;color:#9ca3af;margin-bottom:6px}
.footer{margin-top:24px;padding-top:12px;border-top:1px solid #e5e7eb;font-size:10px;color:#9ca3af;display:flex;justify-content:space-between}
@media print{body{padding:16px 20px}.footer{position:fixed;bottom:0;width:100%}}
</style>
</head>
<body>
${bodyHtml}
<div class="footer">
  <span>TeamPulse · ارزیابی عملکرد</span>
  <span>تاریخ دانلود: ${new Date().toLocaleDateString('fa-IR')}</span>
</div>
${printScript}
</body></html>`;
}

function downloadEvalPeriod(formId, periodIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form) return;
  const period = form.periods[periodIdx];
  if (!period) return;
  const totalScore = evalPeriodTotal(form, period);

  const rowsHtml = form.rows.map(row => {
    const score = period.scores[row.id] !== undefined ? parseFloat(period.scores[row.id]) : null;
    const note = period.notes[row.id] || '';
    const pct = score !== null ? Math.round((score / row.maxScore) * 100) : null;
    const barColor = pct !== null ? (pct >= 70 ? '#059669' : pct >= 40 ? '#d97706' : '#dc2626') : '#e5e7eb';
    return `<tr>
      <td>${escapeHtml(row.label)}</td>
      <td>
        ${score !== null ? `<span class="bar-wrap"><span class="bar-fill" style="width:${pct}%;background:${barColor}"></span></span>
        ${score}/${row.maxScore} <span style="font-size:10px;color:#9ca3af">(${pct}٪)</span>` : '—'}
      </td>
      <td style="color:#6b7280;font-size:11px">${note || '—'}</td>
    </tr>`;
  }).join('');

  const body = `
    <h1>${escapeHtml(form.title)}</h1>
    <div class="meta">دوره ${fa(periodIdx+1)} · تاریخ: ${period.date || 'باز (هنوز پایان نیافته)'} ${form.desc ? '· ' + form.desc : ''}</div>
    ${totalScore !== null ? `
    <div class="total-box">
      <span class="total-label">امتیاز کل دوره ${fa(periodIdx+1)}</span>
      <span class="total-val">${fa(totalScore)}٪</span>
    </div>` : ''}
    <div class="section-title">جدول ارزیابی شاخص‌ها</div>
    <table>
      <thead><tr>
        <th style="width:40%">شاخص</th>
        <th style="width:35%">امتیاز</th>
        <th style="width:25%">توضیحات</th>
      </tr></thead>
      <tbody>${rowsHtml}</tbody>
    </table>`;

  const html = _evalPrintShell(`ارزیابی · ${escapeHtml(form.title)} · دوره ${periodIdx+1}`, body);
  _evalDownload(`ارزیابی-${escapeHtml(form.title)}-دوره${periodIdx+1}.html`, html);
  showToast('فایل دانلود شد ✅');
}

function downloadEvalCompare(formId, aIdx, bIdx) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form) return;
  const pA = form.periods[aIdx], pB = form.periods[bIdx];
  if (!pA || !pB) return;

  const totalA = evalPeriodTotal(form, pA);
  const totalB = evalPeriodTotal(form, pB);
  const totalDiff = (totalA !== null && totalB !== null) ? totalB - totalA : null;

  const cardsHtml = `
    <div class="cards">
      <div class="card">
        <div class="card-label">دوره ${fa(aIdx+1)} · ${pA.date}</div>
        <div class="card-val">${totalA !== null ? fa(totalA)+'٪' : '—'}</div>
      </div>
      <div class="card">
        <div class="card-label">دوره ${fa(bIdx+1)} · ${pB.date}</div>
        <div class="card-val">${totalB !== null ? fa(totalB)+'٪' : '—'}</div>
      </div>
      ${totalDiff !== null ? `
      <div class="card" style="border-color:${totalDiff>0?'#bbf7d0':totalDiff<0?'#fecaca':'#e5e7eb'}">
        <div class="card-label">تغییر کلی</div>
        <div class="card-val ${totalDiff>0?'green':totalDiff<0?'red':''}">
          ${totalDiff>0?'▲':'▼'} ${fa(Math.abs(totalDiff))}٪
        </div>
      </div>` : ''}
    </div>`;

  // SVG trend chart (plain hex for print)
  const allTotals = form.periods.map(p => evalPeriodTotal(form, p));
  const valid = allTotals.map((t,i)=>({i,t})).filter(x=>x.t!==null);
  let chartSvg = '';
  if (valid.length >= 2) {
    const W=400,H=80,pad=20;
    const xStep = (W-pad*2)/(valid.length-1);
    const pts = valid.map((x,j)=>({ cx:pad+j*xStep, cy:H-pad-((x.t/100)*(H-pad*2)), t:x.t, i:x.i }));
    const polyline = pts.map(p=>`${p.cx},${p.cy}`).join(' ');
    const dots = pts.map(p=>{
      const hl = p.i===aIdx||p.i===bIdx;
      return `<circle cx="${p.cx}" cy="${p.cy}" r="${hl?5:3}" fill="${hl?'#059669':'#6355e8'}" stroke="#fff" stroke-width="1.5"/>
        <text x="${p.cx}" y="${p.cy-9}" text-anchor="middle" font-size="9" fill="${hl?'#059669':'#6b7280'}" font-family="Vazirmatn,Tahoma">${fa(p.t)}٪</text>`;
    }).join('');
    const labels = pts.map((p,j)=>`<text x="${p.cx}" y="${H-3}" text-anchor="middle" font-size="8" fill="#9ca3af" font-family="Vazirmatn,Tahoma">د${fa(valid[j].i+1)}</text>`).join('');
    chartSvg = `<div class="chart-box"><div class="chart-label">روند پیشرفت — همه دوره‌ها</div>
      <svg width="100%" viewBox="0 0 ${W} ${H}" style="overflow:visible">
        <polyline points="${polyline}" fill="none" stroke="#6355e8" stroke-width="1.5" stroke-linejoin="round"/>
        ${dots}${labels}
      </svg></div>`;
  }

  const rowsHtml = form.rows.map(row => {
    const sA = pA.scores[row.id] !== undefined ? parseFloat(pA.scores[row.id]) : null;
    const sB = pB.scores[row.id] !== undefined ? parseFloat(pB.scores[row.id]) : null;
    const pctA = sA !== null ? Math.round((sA/row.maxScore)*100) : null;
    const pctB = sB !== null ? Math.round((sB/row.maxScore)*100) : null;
    const diff = (pctA!==null&&pctB!==null) ? pctB-pctA : null;
    const bA = pctA!==null ? `<span class="bar-wrap"><span class="bar-fill" style="width:${pctA}%;background:${pctA>=70?'#059669':pctA>=40?'#d97706':'#dc2626'}"></span></span>${fa(sA)}/${fa(row.maxScore)}` : '—';
    const bB = pctB!==null ? `<span class="bar-wrap"><span class="bar-fill" style="width:${pctB}%;background:${pctB>=70?'#059669':pctB>=40?'#d97706':'#dc2626'}"></span></span>${fa(sB)}/${fa(row.maxScore)}` : '—';
    const diffHtml = diff!==null
      ? `<span class="${diff>0?'diff-pos':diff<0?'diff-neg':'diff-zero'}">${diff>0?'▲':'▼'} ${fa(Math.abs(diff))}٪</span>`
      : '—';
    return `<tr><td>${escapeHtml(row.label)}</td><td>${bA}</td><td>${bB}</td><td style="text-align:center">${diffHtml}</td></tr>`;
  }).join('');

  const body = `
    <h1>${escapeHtml(form.title)} — مقایسه دوره‌ها</h1>
    <div class="meta">دوره ${fa(aIdx+1)} (${pA.date}) در مقابل دوره ${fa(bIdx+1)} (${pB.date})</div>
    ${cardsHtml}
    ${chartSvg}
    <div class="section-title">مقایسه شاخص به شاخص</div>
    <table>
      <thead><tr>
        <th style="width:34%">شاخص</th>
        <th style="width:22%">دوره ${fa(aIdx+1)}</th>
        <th style="width:22%">دوره ${fa(bIdx+1)}</th>
        <th style="width:22%;text-align:center">تغییر</th>
      </tr></thead>
      <tbody>${rowsHtml}</tbody>
    </table>`;

  const html = _evalPrintShell(`مقایسه · ${escapeHtml(form.title)} · دوره ${aIdx+1} vs ${bIdx+1}`, body);
  _evalDownload(`مقایسه-${escapeHtml(form.title)}-د${aIdx+1}-د${bIdx+1}.html`, html);
  showToast('گزارش مقایسه دانلود شد ✅');
}

// ── SVG trend chart ──
function buildEvalTrendChart(form, totals, highlightA, highlightB) {
  const valid = totals.map((t,i) => ({ i, t })).filter(x => x.t !== null);
  if (valid.length < 2) return '';
  const W = 320, H = 80, pad = 16;
  const maxT = 100;
  const xStep = valid.length > 1 ? (W - pad*2) / (valid.length - 1) : 0;
  const points = valid.map((x, j) => ({
    cx: pad + j * xStep,
    cy: H - pad - ((x.t / maxT) * (H - pad*2)),
    t: x.t, i: x.i
  }));
  const polyline = points.map(p => `${p.cx},${p.cy}`).join(' ');
  const dots = points.map(p => {
    const isHL = p.i === highlightA || p.i === highlightB;
    return `<circle cx="${p.cx}" cy="${p.cy}" r="${isHL?5:3}" fill="${isHL?'var(--green)':'var(--accent2)'}" stroke="var(--bg2)" stroke-width="1.5"/>
      <text x="${p.cx}" y="${p.cy-8}" text-anchor="middle" font-size="9" fill="${isHL?'var(--green)':'var(--text3)'}" font-family="Vazirmatn,Tahoma">${fa(p.t)}٪</text>`;
  }).join('');
  const labels = points.map((p, j) =>
    `<text x="${p.cx}" y="${H-2}" text-anchor="middle" font-size="8" fill="var(--text3)" font-family="Vazirmatn,Tahoma">د${fa(valid[j].i+1)}</text>`
  ).join('');

  return `
    <div style="margin-bottom:10px;padding:10px 12px;background:var(--bg2);border:1px solid var(--border);border-radius:8px">
      <div style="font-size:10px;color:var(--text3);margin-bottom:6px">روند پیشرفت — همه دوره‌ها</div>
      <svg width="100%" viewBox="0 0 ${W} ${H}" style="overflow:visible">
        <polyline points="${polyline}" fill="none" stroke="var(--accent2)" stroke-width="1.5" stroke-linejoin="round"/>
        ${dots}
        ${labels}
      </svg>
    </div>`;
}

// ── Important Topics (per-student, title + full description) ─────────────────
async function openTopics(studentId, displayName) {
  const topics = await window.api.topics.getByStudent(studentId);

  openModal(`📌 موضوعات مهم — ${escapeHtml(displayName)}`, `
    <div class="form-group full">
      <label class="form-label">عنوان موضوع</label>
      <input class="form-input" id="f-topic-title" placeholder="مثلاً: تصمیم برای تغییر شغل">
    </div>
    <div class="form-group full" style="margin-top:8px">
      <label class="form-label">توضیحات کامل</label>
      ${richToolbar('f-topic-text')}
      <textarea class="form-textarea" id="f-topic-text" rows="4" placeholder="توضیح کامل این موضوع..."></textarea>
    </div>
    <div class="form-grid" style="margin-top:8px">
      <div class="form-group">
        <label class="form-label">تاریخ (شمسی)</label>
        <input class="form-input jdate" id="f-topic-date" value="${formatJalali(...todayJalali())}">
      </div>
      <div class="form-group" style="align-self:flex-end">
        <button class="btn btn-primary" onclick="saveTopic(${studentId}, ${escapeAttr(displayName)})">+ افزودن</button>
      </div>
    </div>
    <div class="form-group full" style="margin-top:8px">
      <label class="form-label">✅ آیتم‌های چک‌لیست (اختیاری)</label>
      <div id="new-topic-checklist" style="margin-bottom:6px"></div>
      <div style="display:flex;gap:6px">
        <input class="form-input" id="f-new-checklist-item" placeholder="متن آیتم چک‌لیست..." style="flex:1" onkeydown="if(event.key===&#39;Enter&#39;){event.preventDefault();_addNewTopicChecklistItem()}">
        <button class="btn btn-ghost" onclick="_addNewTopicChecklistItem()">+ اضافه</button>
      </div>
    </div>
    <div class="topics-section-head">
      <div class="form-section">موضوعات ثبت‌شده</div>
      ${topics.length ? `<button class="btn btn-ghost btn-sm topics-show-all-btn" type="button" onclick="openAllTopics(${studentId}, decodeURIComponent('${encodeURIComponent(displayName)}'))">نمایش و کپی همه</button>` : ''}
    </div>
    <div id="topics-list">
      ${topics.length === 0
        ? '<p style="font-size:12px;color:var(--text3)">هنوز موضوعی ثبت نشده</p>'
        : topics.map(t => `
          <div class="topic-item">
            <div class="topic-item-date">${DateService.disp(t.date_jalali)}${t.checklist?.length ? ` · ☑ ${fa(t.checklist.filter(c=>c.done).length)}/${fa(t.checklist.length)}` : ''}</div>
            <div class="topic-item-title" onclick="openTopicDetail(${t.id}, ${studentId}, ${escapeAttr(displayName)})">${escapeHtml(t.title) || '(بدون عنوان)'}</div>
            <div class="topic-item-excerpt" onclick="openTopicDetail(${t.id}, ${studentId}, ${escapeAttr(displayName)})">${renderRich(excerpt(t.text, 90))}</div>
            <div style="display:flex;gap:6px;margin-top:4px">
              <button class="btn btn-ghost btn-sm" data-tid="${t.id}" data-sid="${studentId}" data-dname="${escapeHtml(displayName)}" onclick="event.stopPropagation();openEditTopic(+this.dataset.tid,+this.dataset.sid,this.dataset.dname)">✏️ ویرایش</button>
              <button class="btn btn-ghost btn-sm topic-copy-btn" onclick="event.stopPropagation();openCopyTopic(${t.id}, ${studentId})">📋 کپی</button>
            </div>
          </div>`).join('')}
    </div>
  `, [
    { label: 'بستن', cls: 'btn-primary', action: 'closeModal()' },
  ]);
  initDatePickers();
}

function _topicPlainText(value) {
  const el = document.createElement('div');
  el.innerHTML = String(value || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n');
  return (el.textContent || '').replace(/\u00a0/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

async function openAllTopics(studentId, displayName) {
  const topics = await window.api.topics.getByStudent(studentId);
  const sortedTopics = topics.slice().sort((a, b) => jalaliKey(b.date_jalali) - jalaliKey(a.date_jalali) || b.id - a.id);
  const divider = '\n\n--------------------\n\n';
  const topicCopyEntries = sortedTopics.map((t, index) => {
      const checklist = (t.checklist || []).map(c => `${c.done ? '☑' : '☐'} ${_topicPlainText(c.text)}`).join('\n');
      return [
        `${index + 1}. ${_topicPlainText(t.title) || '(بدون عنوان)'}`,
        `تاریخ: ${DateService.disp(t.date_jalali)}`,
        _topicPlainText(t.text),
        checklist ? `چک‌لیست:\n${checklist}` : ''
      ].filter(Boolean).join('\n');
    });
  window._allTopicsCopyText = sortedTopics.length
    ? `همه موضوعات مهم — ${displayName}\n\n${topicCopyEntries.join(divider)}`
    : `همه موضوعات مهم — ${displayName}\n\nهنوز موضوعی ثبت نشده`;

  const body = sortedTopics.length ? sortedTopics.map(t => {
    const checklist = t.checklist || [];
    return `<article class="topics-all-item">
      <div class="topic-item-date">${DateService.disp(t.date_jalali)}</div>
      <div class="topics-all-title">${escapeHtml(t.title) || '(بدون عنوان)'}</div>
      ${t.text ? `<div class="topics-all-text">${renderRich(t.text)}</div>` : ''}
      ${checklist.length ? `<div class="topics-all-checklist">${checklist.map(c => `<div>${c.done ? '☑' : '☐'} ${escapeHtml(c.text)}</div>`).join('')}</div>` : ''}
    </article>`;
  }).join('') : '<p style="font-size:12px;color:var(--text3)">هنوز موضوعی ثبت نشده</p>';

  openModal(`همه موضوعات مهم — ${escapeHtml(displayName)}`, `
    <div style="display:flex;justify-content:flex-start;margin-bottom:10px">
      <button class="btn btn-primary btn-sm" type="button" onclick="copyToClipboard(window._allTopicsCopyText || '', 'همه موضوعات کپی شد ✓')" style="min-width:150px">کپی همه موضوعات</button>
    </div>
    <div class="topics-all-list">${body}</div>
  `, [
    { label: 'کپی همه موضوعات', cls: 'btn-ghost', action: `copyToClipboard(window._allTopicsCopyText || '', 'همه موضوعات کپی شد ✓')` },
    { label: 'بستن', cls: 'btn-primary', action: 'closeModal()' },
  ]);
}

async function openCopyTopic(topicId, fromStudentId) {
  const topics = await window.api.topics.getByStudent(fromStudentId);
  const t = topics.find(x => x.id === topicId);
  if (!t) return;
  allStudents = allStudents.length ? allStudents : await window.api.students.getAll();
  const options = allStudents.filter(s => s.id !== fromStudentId)
    .map(s => `<option value="${s.id}">${escapeHtml(s.name)} ${escapeHtml(s.lname)}</option>`).join('');

  openModal(`📋 کپی موضوع: "${escapeHtml(t.title) || '(بدون عنوان)'}"`, `
    <div class="form-group full">
      <label class="form-label">کپی برای کدام ${META.entitySingular||'شاگرد'}؟</label>
      <select class="form-select" id="copy-target-student">${options}</select>
    </div>
    <p style="font-size:11px;color:var(--text3);margin-top:8px">عنوان، توضیحات و چک‌لیست این موضوع عیناً برای فرد انتخاب‌شده کپی می‌شود.</p>
  `, [
    { label: 'کپی کن', cls: 'btn-primary', action: `saveCopyTopic(${topicId}, ${fromStudentId})` },
    { label: 'انصراف', cls: 'btn-ghost', action: 'closeModal()' },
  ]);
}

async function saveCopyTopic(topicId, fromStudentId) {
  const topics = await window.api.topics.getByStudent(fromStudentId);
  const t = topics.find(x => x.id === topicId);
  const targetId = +document.getElementById('copy-target-student')?.value;
  if (!t || !targetId) return;
  await window.api.topics.add({
    student_id: targetId,
    date: t.date_jalali,
    title: t.title,
    text: t.text,
    checklist: (t.checklist || []).map(c => ({ text: c.text })),
  });
  closeModal();
  showToast('کپی شد ✓', 'success');
}

// Helper: add checklist item to new topic form
let _newTopicChecklist = [];
function _addNewTopicChecklistItem() {
  const input = document.getElementById('f-new-checklist-item');
  const text = input?.value.trim();
  if (!text) return;
  _newTopicChecklist.push({ text });
  input.value = '';
  const container = document.getElementById('new-topic-checklist');
  if (container) {
    const idx = _newTopicChecklist.length - 1;
    const div = document.createElement('div');
    div.style.cssText = 'display:flex;align-items:center;gap:6px;padding:4px 0;font-size:13px;';
    div.innerHTML = '<span style="color:var(--text3)">☐</span><span style="flex:1">' + escapeHtml(text) + '</span><button class="x-close-sm" onclick="this.parentNode.remove();_newTopicChecklist.splice(' + idx + ',1)">✕</button>';
    container.appendChild(div);
  }
}

async function saveTopic(studentId, displayName) {
  const title = document.getElementById('f-topic-title')?.value.trim();
  const text = document.getElementById('f-topic-text')?.value.trim();
  const date = document.getElementById('f-topic-date')?.value;
  if (!title && !text) { showToast('عنوان یا توضیحات را وارد کنید', 'error'); return; }
  await window.api.topics.add({ student_id: studentId, date, title, text, checklist: _newTopicChecklist.map(c => ({text: c.text})) });
  _newTopicChecklist = [];
  showToast('موضوع ثبت شد ✓', 'success');
  await openTopics(studentId, displayName);
}

