// ── Key events (per-student important notes board) ───────────────────────────

// محاسبه تاریخ بعدی تکرار یادآوری
function _nextRepeatDate(dateStr, repeatType, repeatDays = null) {
  const parts = _jalaliParse(dateStr);
  if (!parts || !parts[0]) return dateStr;
  let [jy, jm, jd] = parts;
  if (repeatType === 'daily') { jd += 1; }
  else if (repeatType === 'every_days') { return _formatJalali(..._addDays(jy, jm, jd, Math.max(1, Number(repeatDays) || 1))); }
  else if (repeatType === 'weekly') { jd += 7; }
  else if (repeatType === 'biweekly') { jd += 14; }
  else if (repeatType === 'monthly') { jm += 1; if (jm > 12) { jm = 1; jy++; } }
  else if (repeatType === 'bimonthly') { jm += 2; if (jm > 12) { jm -= 12; jy++; } }
  else if (repeatType === 'quarterly') { jm += 3; if (jm > 12) { jm -= 12; jy++; } }
  else if (repeatType === 'yearly') { jy += 1; }
  // normalize روز
  const maxDay = jm <= 6 ? 31 : (jm <= 11 ? 30 : 29);
  if (jd > maxDay) { jd -= maxDay; jm++; if (jm > 12) { jm = 1; jy++; } }
  return _formatJalali(jy, jm, jd);
}

function updateEvalCheck(formId, rowId, checked, periodIdx, control) {
  const key = evalFindKey(formId);
  if (!key) return;
  const forms = _evalLoadByKey(key);
  const form = forms.find(f => f.id === formId);
  if (!form || !form.periods[periodIdx]) return;
  if (!form.periods[periodIdx].checks) form.periods[periodIdx].checks = {};
  form.periods[periodIdx].checks[rowId] = !!checked;
  _evalSaveByKey(key, forms);
  const label = control?.closest('label')?.querySelector('span');
  if (label) label.style.cssText = checked ? 'font-size:12px;text-decoration:line-through;color:var(--text3)' : 'font-size:12px;color:var(--text)';
}

function _syncKeyEventRepeatDays(prefix) {
  const select = document.getElementById(prefix + '-repeat');
  const wrap = document.getElementById(prefix + '-repeat-days-wrap');
  if (wrap) wrap.style.display = select?.value === 'every_days' ? 'block' : 'none';
}

function _readKeyEventRepeatDays(prefix) {
  if (document.getElementById(prefix + '-repeat')?.value !== 'every_days') return null;
  return Math.max(1, +(document.getElementById(prefix + '-repeat-days')?.value || 1));
}

async function openKeyEvents(studentId, displayName) {
  const events = await window.api.keyEvents.getByStudent(studentId);
  const today = formatJalali(...todayJalali());

  function renderEventsList(evts) {
    if (!evts.length) return '<p style="font-size:12px;color:var(--text3)">هنوز رویدادی ثبت نشده</p>';
    return evts.map(e => {
      const hasRemind = e.remind_date && !e.remind_done;
      const remindPast = hasRemind && _jalaliKey(e.remind_date) < _jalaliKey(today);
      return '<div class="key-event-item" style="flex-direction:column;gap:6px">' +
        '<div style="display:flex;align-items:flex-start;gap:8px">' +
          '<div style="flex:1">' +
            '<div class="key-event-date">' + DateService.disp(e.date_jalali) +
              (hasRemind ? ' · <span style="color:' + (remindPast?'var(--red)':'var(--amber)') + ';font-size:10px">⏰ یادآوری: ' + DateService.disp(e.remind_date) + (remindPast?' (گذشته)':'') + (e.repeat_type&&e.repeat_type!=='none'?' 🔁':'') + '</span>' : '') +
            '</div>' +
            '<div class="key-event-text">' + renderRich(e.text) + '</div>' +
          '</div>' +
          '<div style="display:flex;gap:4px;flex-shrink:0">' +
            '<button class="btn btn-ghost btn-sm" onclick="openEditKeyEvent(' + e.id + ',' + studentId + ',' + escapeAttr(displayName) + ')" title="ویرایش">✏️</button>' +
            (hasRemind ? '<button class="btn btn-ghost btn-sm" onclick="markKeyEventRemindDone(' + e.id + ',' + studentId + ',' + escapeAttr(displayName) + ')" title="یادآوری انجام شد" style="color:var(--green)">✓</button>' : '') +
            '<button class="btn btn-danger btn-sm" onclick="deleteKeyEvent(' + e.id + ',' + studentId + ',' + escapeAttr(displayName) + ')" title="حذف">🗑</button>' +
          '</div>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  openModal('🌟 رویدادهای مهم — ' + displayName, `
    <div class="form-group full">
      <label class="form-label">افزودن رویداد جدید</label>
      ${richToolbar('f-ke-text')}
      <textarea class="form-textarea" id="f-ke-text" rows="3" placeholder="مثلاً: تصمیم گرفت کسب‌وکار جدید را شروع کند..."></textarea>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px">
      <div class="form-group">
        <label class="form-label">📅 تاریخ رویداد</label>
        <input class="form-input jdate" id="f-ke-date" value="${today}">
      </div>
      <div class="form-group">
        <label class="form-label">⏰ تاریخ یادآوری (اختیاری)</label>
        <input class="form-input jdate" id="f-ke-remind" placeholder="مثلاً: ۱۴۰۳/۰۴/۰۱">
      </div>
      <div class="form-group">
        <label class="form-label">🔁 تکرار یادآوری</label>
        <select class="form-select" id="f-ke-repeat" onchange="_syncKeyEventRepeatDays('f-ke')">
          <option value="none">بدون تکرار</option>
          <option value="daily">روزانه</option>
          <option value="every_days">هر X روز</option>
          <option value="weekly">هفتگی</option>
          <option value="biweekly">دو هفته یک‌بار</option>
          <option value="monthly">ماهانه</option>
          <option value="bimonthly">دو ماه یک‌بار</option>
          <option value="quarterly">سه ماه یک‌بار</option>
          <option value="yearly">سالانه</option>
        </select>
      </div>
      <div class="form-group" id="f-ke-repeat-days-wrap" style="display:none">
        <label class="form-label">هر چند روز؟</label>
        <input class="form-input" id="f-ke-repeat-days" type="number" min="1" step="1" value="2" inputmode="numeric">
      </div>
    </div>
    <div style="margin-top:8px">
      <button class="btn btn-primary" onclick="saveKeyEvent(${studentId}, ${escapeAttr(displayName)})">+ افزودن رویداد</button>
    </div>
    <div class="form-section" style="margin-top:14px">رویدادهای ثبت‌شده (${fa(events.length)})</div>
    <div id="key-events-list" style="max-height:280px;overflow-y:auto">
      ${renderEventsList(events)}
    </div>
  `, [
    { label: 'بستن', cls: 'btn-primary', action: 'closeModal()' },
  ]);
  initDatePickers();
}

async function saveKeyEvent(studentId, displayName) {
  const text = document.getElementById('f-ke-text')?.value.trim();
  const date = document.getElementById('f-ke-date')?.value;
  const remindDate = document.getElementById('f-ke-remind')?.value.trim() || null;
  const repeatType = document.getElementById('f-ke-repeat')?.value || 'none';
  if (!text) { showToast('متن رویداد را وارد کنید', 'error'); return; }
  const repeatDays = _readKeyEventRepeatDays('f-ke');
  await window.api.keyEvents.add({ student_id: studentId, date, text, remind_date: remindDate, repeat_type: repeatType, repeat_days:repeatDays });
  showToast('رویداد ثبت شد ✓', 'success');
  await openKeyEvents(studentId, displayName);
}

