// ── Init ──────────────────────────────────────────────────────────────────────
async function init() {
  try {
    console.log('[TeamPulse] init() starting...');
    document.getElementById('theme-btn')?.classList.add('on');
    console.log('[TeamPulse] getting meta...');
    META = await window.api.meta.get();
    PKG_TYPES = await window.api.packageTypes.getAll();
    FAMILIES = await window.api.families.getAll();
    CURRENCIES = await window.api.meta.currencies();
    console.log('[TeamPulse] applyMetaToUI...');
    applyMetaToUI();
    try {
      const reminders = await window.api.reminders.getAll();
      const pending = reminders.filter(r => !r.done).length;
      updateReminderBadges(pending);
    } catch(e) { console.warn('[TeamPulse] reminders error:', e); }
    console.log('[TeamPulse] renderPage...');
    await renderPage();
    console.log('[TeamPulse] init() DONE');
  _tpPrefetchExtra();
  // Schedule نوتیفیکیشن‌ها بعد از load
  clearTimeout(window._todoNotificationsScheduleTimer);
  window._todoNotificationsScheduleTimer = setTimeout(_scheduleTodoNotifications, 2000);
  // اشتراک موجود مرورگر را در هر ورود دوباره با سرور همگام کن؛ ممکن است
  // رکورد سمت سرور پاک/منقضی شده باشد، درحالی‌که مرورگر هنوز آن را فعال نشان دهد.
  setTimeout(_refreshReminderPushRegistration, 2500);
    // Sync default account name to separate storage key
    // نکته: در دسترسی هم‌تیمی META.appTitle نام/عنوان کسب‌وکار کارفرماست، نه
    // میزکار خودِ کاربر؛ اگر اینجا ذخیره‌اش کنیم روی حساب account-name-display
    // (که با _applyTeamAccessToNav روی «هم‌تیمی» تنظیم شده) رو بازنویسی می‌کند.
    if (!_teamAccessSession() && _currentAccountId() === 'default' && (_sbUser?.name || _sbUser?.email)) {
      _setDefaultAccountName(_sbUser.name || _sbUser.email.split('@')[0]);
    }
  } catch(e) {
    console.error('[TeamPulse] init() ERROR:', e);
    document.getElementById('content').innerHTML = '<div style="text-align:center;padding:40px;color:#f87171"><h2>خطا: ' + escapeHtml(e.message) + '</h2><button onclick="location.reload()" style="padding:10px 24px;background:#7c6af7;color:white;border:none;border-radius:8px;cursor:pointer">تلاش مجدد</button></div>';
  }
}


// ════════════════════════════════════════════════════════════════════════════
// NAV ORDER EDITOR
// ════════════════════════════════════════════════════════════════════════════

const DEFAULT_NAV_ORDER = [
  { page: 'students',     icon: '👥', label: () => 'امور مشتریان' },
  { page: 'goals',        icon: '🎯', label: () => 'اهداف' },
  { page: 'habits',       icon: '🔥', label: () => 'عادت‌ها' },
  { page: 'todolist',     icon: '✅', label: () => 'لیست کارها' },
  { page: 'instructions', icon: '💡', label: () => 'مرکز دانش' },
  { page: 'payments',     icon: '🛒', label: () => 'حساب مشتریان' },
  { page: 'staff',        icon: '🧑‍💼', label: () => 'حساب پرسنل و اعضا' },
  { page: 'dashboard',    icon: '📊', label: () => 'داشبورد مالی' },
  { page: 'transactions', icon: '📒', label: () => 'تراکنش‌های مالی' },
  { page: 'reminders',    icon: '⏰', label: () => 'یادآوری' },
  { page: 'families',     icon: '👨‍👩‍👧', label: () => 'حساب‌های مشترک' },
  { page: 'admin_panel',  icon: '👑', label: () => 'پنل مدیریت' },
  { page: 'settings',     icon: '⚙️', label: () => 'تنظیمات' },
  { page: 'tutorial',     icon: '🎓', label: () => 'آموزش‌ها' },
];

function _normalizeNavOrder(order) {
  const clean = Array.isArray(order) ? order.filter(Boolean) : DEFAULT_NAV_ORDER.map(n => n.page);
  ['staff', 'dashboard'].forEach(page => {
    const index = clean.indexOf(page);
    if (index !== -1) clean.splice(index, 1);
  });
  const paymentsIndex = clean.indexOf('payments');
  const insertAt = paymentsIndex !== -1 ? paymentsIndex + 1 : clean.length;
  clean.splice(insertAt, 0, 'staff', 'dashboard');
  return clean;
}

function _getNavOrder() {
  try {
    const saved = JSON.parse(localStorage.getItem('teampulse_nav_order') || 'null');
    if (saved && Array.isArray(saved)) return _normalizeNavOrder(saved);
  } catch(e) {}
  return _normalizeNavOrder(DEFAULT_NAV_ORDER.map(n => n.page));
}

function renderNavOrderEditor() {
  const list = document.getElementById('nav-order-list');
  if (!list) return;
  const order = _getNavOrder();
  const hiddenPages = new Set(['sessions', 'families']);
  const ordered = order.map(page => DEFAULT_NAV_ORDER.find(n => n.page === page)).filter(Boolean).filter(item => !hiddenPages.has(item.page));
  // اضافه کردن آیتم‌هایی که در order نیستن
  DEFAULT_NAV_ORDER.forEach(n => { if (!order.includes(n.page) && !hiddenPages.has(n.page)) ordered.push(n); });

  list.innerHTML = ordered.map((item, i) => `
    <div draggable="true" data-page="${item.page}" style="touch-action:none" data-index="${i}"
      style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--bg3);
             border:1px solid var(--border2);border-radius:8px;cursor:grab;user-select:none"
      ondragstart="this.style.opacity='.4';window._dragNavIdx=${i}"
      ondragend="this.style.opacity='1';renderNavOrderEditor()"
      ondragover="event.preventDefault()"
      ondrop="event.preventDefault();_dropNavItem(${i})">
      <span style="color:var(--text3);font-size:16px">⠿</span>
      <span style="font-size:16px">${escapeHtml(item.icon)}</span>
      <span style="flex:1;font-size:13px">${item.label()}</span>
      <span style="color:var(--text3);font-size:11px">${i+1}</span>
    </div>
  `).join('');
  
  // ذخیره ترتیب موقت در window
  window._currentNavItems = ordered;
}

function _dropNavItem(toIndex) {
  if (window._dragNavIdx === undefined) return;
  const from = window._dragNavIdx;
  if (from === toIndex) return;
  const items = [...window._currentNavItems];
  const [moved] = items.splice(from, 1);
  items.splice(toIndex, 0, moved);
  const newOrder = items.map(i => i.page);
  localStorage.setItem('teampulse_nav_order', JSON.stringify(newOrder));
  renderNavOrderEditor();
}

function saveNavOrder() {
  if (!window._currentNavItems) return;
  const order = window._currentNavItems.map(i => i.page);
  localStorage.setItem('teampulse_nav_order', JSON.stringify(order));
  applyNavOrder();
  showToast('ترتیب منو ذخیره شد ✓', 'success');
}

function resetNavOrder() {
  localStorage.removeItem('teampulse_nav_order');
  renderNavOrderEditor();
  applyNavOrder();
  showToast('ترتیب پیش‌فرض بازگردانده شد ✓', 'success');
}

function applyNavOrder() {
  const order = _getNavOrder();
  const sidebar = document.querySelector('.sidebar-nav');
  if (!sidebar) return;
  const hiddenPages = new Set(['sessions', 'families']);
  
  // ذخیره section‌ها
  const sections = {};
  sidebar.querySelectorAll('.nav-section').forEach(s => {
    sections[s.textContent.trim()] = s;
  });
  
  // ذخیره nav-item‌ها
  const navItems = {};
  sidebar.querySelectorAll('a.nav-item[data-page]').forEach(a => {
    navItems[a.dataset.page] = a;
  });
  
  // پاک کردن nav-item‌ها (نه section‌ها)
  sidebar.querySelectorAll('a.nav-item[data-page]').forEach(a => a.remove());
  
  // حذف section‌های خالی فعلی به جز اولین
  sidebar.querySelectorAll('.nav-section').forEach((s, i) => { if (i > 0) s.remove(); });
  
  // پیدا کردن section اول
  const firstSection = sidebar.querySelector('.nav-section');
  
  // اضافه کردن به ترتیب
  const gapPages = ['settings'];
  let addedGap = false;
  
  order.forEach(page => {
    if (hiddenPages.has(page)) return;
    if (gapPages.includes(page) && !addedGap) {
      // اضافه کردن section "گزارش" قبل از این آیتم
      const sec = document.createElement('div');
      sec.className = 'nav-section';
      sec.textContent = 'گزارش';
      sidebar.appendChild(sec);
      addedGap = true;
    }
    if (navItems[page]) sidebar.appendChild(navItems[page]);
  });
  
  // اضافه کردن آیتم‌هایی که در order نیستن
  Object.entries(navItems).forEach(([page, el]) => {
    if (hiddenPages.has(page)) return;
    if (!order.includes(page)) sidebar.appendChild(el);
  });

  // rebind nav click listeners after DOM rebuild
  sidebar.querySelectorAll('a.nav-item[data-page]').forEach(el => {
    el.addEventListener('click', (e) => {
      e.preventDefault();
      sidebar.querySelectorAll('.nav-item').forEach(x => x.classList.remove('active'));
      el.classList.add('active');
      currentPage = el.dataset.page;
      if (currentPage === 'students') { _studentsTab = 'sessions'; _keySessionsExpanded = false; }
      updatePageTitle();
      renderPage();
      closeSidebar();
    });
  });
  _bindSidebarScrollUX();
  requestAnimationFrame(_updateSidebarScrollState);
}



// ════════════════════════════════════════════════════════════════════════════
// FILE ATTACHMENT SYSTEM — IndexedDB
// ════════════════════════════════════════════════════════════════════════════

const _IDB = {
  db: null,
  DB_NAME: 'teampulse_files',
  DB_VERSION: 1,
  STORE: 'attachments',

  async open() {
    if (this.db) return this.db;
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(this.DB_NAME, this.DB_VERSION);
      req.onupgradeneeded = e => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains(this.STORE)) {
          db.createObjectStore(this.STORE, { keyPath: 'id' });
        }
      };
      req.onsuccess = e => { this.db = e.target.result; resolve(this.db); };
      req.onerror = e => reject(e.target.error);
    });
  },

  async save(id, data) {
    const db = await this.open();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.STORE, 'readwrite');
      tx.objectStore(this.STORE).put({ id, data });
      tx.oncomplete = () => resolve(true);
      tx.onerror = e => reject(e.target.error);
    });
  },

  async get(id) {
    const db = await this.open();
    return new Promise((resolve, reject) => {
      const req = db.transaction(this.STORE, 'readonly')
                    .objectStore(this.STORE).get(id);
      req.onsuccess = e => resolve(e.target.result?.data || null);
      req.onerror = e => reject(e.target.error);
    });
  },

  async delete(id) {
    const db = await this.open();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.STORE, 'readwrite');
      tx.objectStore(this.STORE).delete(id);
      tx.oncomplete = () => resolve(true);
      tx.onerror = e => reject(e.target.error);
    });
  },

  async deleteMany(ids) {
    const db = await this.open();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(this.STORE, 'readwrite');
      const store = tx.objectStore(this.STORE);
      ids.forEach(id => store.delete(id));
      tx.oncomplete = () => resolve(true);
      tx.onerror = e => reject(e.target.error);
    });
  },
};

// ── Attachment helpers ────────────────────────────────────────────────────────
function _fileId() {
  return 'f_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
}

function _fileIcon(type) {
  if (!type) return '📄';
  if (type.startsWith('image/')) return '🖼️';
  if (type.startsWith('video/')) return '🎥';
  if (type.startsWith('audio/')) return '🎵';
  if (type.includes('pdf')) return '📕';
  if (type.includes('word') || type.includes('document')) return '📝';
  if (type.includes('sheet') || type.includes('excel')) return '📊';
  if (type.includes('zip') || type.includes('rar')) return '🗜️';
  return '📄';
}

function _formatSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024*1024) return (bytes/1024).toFixed(1) + ' KB';
  return (bytes/(1024*1024)).toFixed(1) + ' MB';
}

const _RASTER_IMAGE_MIME = /^(image\/(?:jpeg|png|gif|webp|avif|bmp))(?:;.*)?$/i;
const _ACTIVE_FILE_MIME = /html|xhtml|svg|xml|javascript|ecmascript|wasm/i;

function _safeAttachmentMime(type) {
  const mime = String(type || '').split(';')[0].trim().toLowerCase();
  if (_RASTER_IMAGE_MIME.test(mime)) return mime.split(';')[0].toLowerCase();
  if (/^audio\/(mpeg|mp4|wav|x-wav|webm|ogg|aac)$/i.test(mime)) return mime;
  if (/^video\/(mp4|webm|ogg)$/i.test(mime)) return mime;
  return 'application/octet-stream';
}

function _rewriteDataUrlMime(dataURL, mime) {
  const raw = String(dataURL || '');
  const idx = raw.indexOf(',');
  if (idx < 0) return raw;
  const b64 = /;base64/i.test(raw.slice(0, idx));
  return 'data:' + _safeAttachmentMime(mime) + (b64 ? ';base64,' : ',') + raw.slice(idx + 1);
}

async function _readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = e => resolve(_rewriteDataUrlMime(e.target.result, file && file.type));
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

async function _makeThumbnail(file, maxW=200, maxH=200) {
  if (!_RASTER_IMAGE_MIME.test(file.type || '')) return null;
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = e => {
      const img = new Image();
      img.onload = () => {
        const ratio = Math.min(maxW/img.width, maxH/img.height, 1);
        const w = Math.round(img.width * ratio);
        const h = Math.round(img.height * ratio);
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL('image/jpeg', 0.75));
      };
      img.onerror = () => resolve(null);
      img.src = e.target.result;
    };
    reader.onerror = () => resolve(null);
    reader.readAsDataURL(file);
  });
}

// ── Upload attachments ────────────────────────────────────────────────────────
async function attachFiles(entityType, entityId, existingAttachments) {
  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.multiple = true;
    input.accept = '*/*';
    input.style.cssText = 'position:fixed;top:-100px;left:-100px;opacity:0';
    document.body.appendChild(input);

    let resolved = false;
    let selectionProcessing = false;
    const done = (val) => {
      if (resolved) return;
      resolved = true;
      document.body.removeChild(input);
      resolve(val);
    };

    input.onchange = async () => {
      selectionProcessing = true;
      const files = Array.from(input.files || []);
      if (!files.length) { done(existingAttachments || []); return; }
      const newAttachments = [...(existingAttachments || [])];
      showToast('در حال بارگذاری فایل‌ها...', '');
      for (const file of files) {
        const id = _fileId();
        try {
          const dataURL = await _readFileAsDataURL(file);
          await _IDB.save(id, dataURL);
          const thumb = await _makeThumbnail(file);
          const serverStored = await _uploadSharedAttachment(id, file);
          newAttachments.push({ id, name: file.name, type: file.type, size: file.size, thumb, server_stored:serverStored, created: new Date().toISOString() });
        } catch(e) { showToast('خطا: ' + file.name, 'error'); }
      }
      done(newAttachments);
    };

    // fallback: اگه dialog بدون انتخاب بسته شد
    const onFocus = () => {
      window.removeEventListener('focus', onFocus);
      // هنگام انتخاب فایل، بازگشت فوکوس مرورگر ممکن است پیش از پایانِ تبدیل
      // فایل به Data URL رخ دهد. فقط وقتی واقعاً هیچ انتخابی انجام نشده است
      // دیالوگ را لغو‌شده در نظر بگیر.
      setTimeout(() => {
        if (!resolved && !selectionProcessing && !(input.files && input.files.length)) done(existingAttachments || []);
      }, 500);
    };
    window.addEventListener('focus', onFocus);
    input.click();
  });
}

async function _uploadSharedAttachment(id,fileOrBlob,name=''){if(!_sbSession?.token||!fileOrBlob)return false;try{const fd=new FormData();fd.append('id',id);fd.append('owner_account_id',_teamAccessSession()?.ownerUserId||_sbUser?.id||'');fd.append('workspace_id',_currentAccountId());fd.append('file',fileOrBlob,name||fileOrBlob.name||'file');return(await _apiFetch('/api/files',{method:'POST',body:fd})).ok;}catch(_){return false;}}
async function _attachmentDataURL(id){let data=await _IDB.get(id);if(data){const header=String(data).slice(0,80);if(_ACTIVE_FILE_MIME.test(header))data=_rewriteDataUrlMime(data,'application/octet-stream');return data;}if(!_sbSession?.token)return null;try{const res=await _apiFetch('/api/files/'+encodeURIComponent(id));if(!res.ok)return null;const blob=await res.blob();data=await _readFileAsDataURL(new Blob([blob],{type:_safeAttachmentMime(blob.type)}));await _IDB.save(id,data);return data;}catch(_){return null;}}
async function _ensureEvalFormAttachmentsShared(studentId,formId){const forms=loadEvalForms(studentId),form=forms.find(x=>+x.id===+formId);if(!form?.attachments?.length)return;let changed=false;for(const a of form.attachments){if(a.server_stored)continue;const data=await _IDB.get(a.id);if(!data)continue;const blob=await(await fetch(data)).blob();if(await _uploadSharedAttachment(a.id,blob,a.name)){a.server_stored=true;changed=true;}}if(changed)saveEvalForms(studentId,forms);}

// ── Render attachments grid ───────────────────────────────────────────────────
function renderAttachmentsGrid(attachments, onDelete) {
  if (!attachments || !attachments.length) return '';
  const deleteCall = (fileId) => onDelete
    ? (String(onDelete).includes('=>') ? `(${onDelete})('${fileId}')` : `${onDelete}('${fileId}')`)
    : '';
  return `
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:10px;margin-top:8px">
      ${attachments.map(a => `
        <div style="background:var(--bg3);border:1px solid var(--border2);border-radius:10px;
             overflow:hidden;position:relative;cursor:pointer"
             onclick="_openAttachment(${escapeAttr(a.id)},${escapeAttr(a.name)},${escapeAttr(a.type)})">
          ${a.type && a.type.startsWith('image/') && a.thumb
            ? `<div style="height:90px;background:var(--bg4);overflow:hidden">
                <img src="${a.thumb}" style="width:100%;height:100%;object-fit:cover">
               </div>`
            : `<div style="height:90px;display:flex;align-items:center;justify-content:center;
                           background:var(--bg4);font-size:36px">${_fileIcon(a.type)}</div>`
          }
          <div style="padding:6px 8px">
            <div style="font-size:11px;font-weight:600;overflow:hidden;text-overflow:ellipsis;
                        white-space:nowrap;color:var(--text)">${escapeHtml(a.name)}</div>
            <div style="font-size:10px;color:var(--text3)">${_formatSize(a.size)}</div>
          </div>
          ${onDelete ? `
          <button onclick="event.stopPropagation();${deleteCall(a.id)}"
            style="position:absolute;top:4px;left:4px;width:22px;height:22px;border-radius:50%;
                   background:rgba(248,113,113,.9);color:white;border:none;cursor:pointer;
                   font-size:11px;display:flex;align-items:center;justify-content:center;
                   line-height:1">×</button>` : ''}
        </div>
      `).join('')}
    </div>`;
}

// پیوست‌های جلسه علاوه بر بازکردن فایل، یادداشت مستقل و حذف مستقیم دارند.
function renderSessionAttachments(sessionId, attachments) {
  if (!attachments || !attachments.length) return '';
  return `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:10px;margin-top:8px">
    ${attachments.map(a => {
      const safeId = encodeURIComponent(a.id || '');
      const safeName = encodeURIComponent(a.name || '');
      const safeType = encodeURIComponent(a.type || '');
      const fieldId = `session-attachment-note-${a.id}`;
      return `<div style="padding:10px;background:var(--bg3);border:1px solid var(--border2);border-radius:10px;min-width:0">
        <div style="display:flex;align-items:center;gap:9px;min-width:0">
          <button type="button" onclick="_openAttachment(decodeURIComponent('${safeId}'),decodeURIComponent('${safeName}'),decodeURIComponent('${safeType}'))"
            aria-label="باز کردن ${escapeHtml(a.name || 'فایل')}" style="width:44px;height:44px;flex:0 0 44px;border:1px solid var(--border);border-radius:8px;background:var(--bg4);cursor:pointer;font-size:21px;overflow:hidden;padding:0">
            ${a.type?.startsWith('image/') && a.thumb ? `<img src="${a.thumb}" alt="" style="width:100%;height:100%;object-fit:cover">` : _fileIcon(a.type)}
          </button>
          <button type="button" onclick="_openAttachment(decodeURIComponent('${safeId}'),decodeURIComponent('${safeName}'),decodeURIComponent('${safeType}'))"
            style="min-width:0;flex:1;text-align:right;border:0;background:none;color:var(--text);cursor:pointer;font-family:var(--font)">
            <div style="font-size:11px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(a.name)}</div>
            <div style="font-size:10px;color:var(--text3);margin-top:2px">${_formatSize(a.size || 0)} · بازکردن فایل</div>
          </button>
          <button type="button" title="حذف پیوست" aria-label="حذف پیوست" onclick="deleteSessionAttachment(${sessionId},decodeURIComponent('${safeId}'))"
            style="width:30px;height:30px;flex:0 0 30px;border:1px solid rgba(248,113,113,.35);border-radius:7px;background:rgba(248,113,113,.08);color:var(--red);cursor:pointer">×</button>
        </div>
        <label style="display:block;font-size:10px;color:var(--text3);margin:9px 1px 5px" for="${fieldId}">یادداشت این پیوست</label>
        <textarea id="${fieldId}" class="form-textarea" rows="2" placeholder="توضیح مربوط به این فایل را بنویسید..." onblur="saveSessionAttachmentNote(${sessionId},decodeURIComponent('${safeId}'),this.value)" style="min-height:58px;font-size:11px">${escapeHtml(a.note || '')}</textarea>
      </div>`;
    }).join('')}
  </div>`;
}

function saveSessionAttachmentNote(sessionId, attachmentId, note) {
  const session = (_db.sessions || []).find(item => +item.id === +sessionId);
  const attachment = session?.attachments?.find(item => item.id === attachmentId);
  if (!attachment) return;
  attachment.note = String(note || '');
  _save();
}

async function deleteSessionAttachment(sessionId, attachmentId) {
  const session = (_db.sessions || []).find(item => +item.id === +sessionId);
  if (!session) return;
  session.attachments = (session.attachments || []).filter(item => item.id !== attachmentId);
  try { await _IDB.delete(attachmentId); } catch (_) {}
  try { await _apiFetch('/api/files/' + encodeURIComponent(attachmentId), { method: 'DELETE' }); } catch (_) {}
  _save();
  showToast('پیوست حذف شد', 'success');
  openSessionDetail(sessionId);
}

// ── Open/download attachment ──────────────────────────────────────────────────
async function _openAttachment(id, name, type) {
  try {
    showToast('در حال بارگذاری...', '');
    const dataURL = await _attachmentDataURL(id);
    if (!dataURL) { showToast('فایل یافت نشد', 'error'); return; }

    if (_RASTER_IMAGE_MIME.test(type || '') && String(dataURL).startsWith('data:image/') && !_ACTIVE_FILE_MIME.test(String(dataURL).slice(0, 64))) {
      // نمایش تصویر در modal
      document.getElementById('modals').innerHTML = `
        <div class="modal-overlay open" onclick="this.innerHTML===event.target.outerHTML&&(document.getElementById('modals').innerHTML='')">
          <div style="max-width:90vw;max-height:90vh;background:var(--bg2);border-radius:14px;
                      overflow:hidden;position:relative">
            <div style="display:flex;align-items:center;justify-content:space-between;
                        padding:10px 14px;border-bottom:1px solid var(--border)">
              <span style="font-size:13px;font-weight:600">${escapeHtml(name)}</span>
              <div style="display:flex;gap:8px">
                <button class="btn btn-ghost btn-sm" onclick="_downloadAttachment('${id}',${escapeAttr(name)})">⬇️ دانلود</button>
                <button class="modal-close" onclick="document.getElementById('modals').innerHTML=''">×</button>
              </div>
            </div>
            <img src="${dataURL}" style="max-width:90vw;max-height:80vh;object-fit:contain;display:block">
          </div>
        </div>`;
    } else {
      await _downloadAttachment(id, name, dataURL);
    }
  } catch(e) {
    showToast('خطا در بارگذاری فایل', 'error');
  }
}

function _dataUrlToOctetBlob(dataURL) {
  const raw = String(dataURL || '');
  const idx = raw.indexOf(',');
  if (idx < 0) return new Blob([new Uint8Array(0)], { type: 'application/octet-stream' });
  const payload = raw.slice(idx + 1);
  if (/;base64/i.test(raw.slice(0, idx))) {
    const bin = atob(payload);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return new Blob([bytes], { type: 'application/octet-stream' });
  }
  try {
    return new Blob([decodeURIComponent(payload)], { type: 'application/octet-stream' });
  } catch (_) {
    return new Blob([payload], { type: 'application/octet-stream' });
  }
}

async function _downloadAttachment(id, name, dataURL) {
  if (!dataURL) dataURL = await _attachmentDataURL(id);
  if (!dataURL) { showToast('فایل یافت نشد', 'error'); return; }
  const url = URL.createObjectURL(_dataUrlToOctetBlob(dataURL));
  const a = document.createElement('a');
  a.href = url;
  a.download = String(name || 'file').replace(/\.(?:html?|svg|xml|js|mjs|xhtml)$/i, '$&.download');
  a.rel = 'noopener';
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
  showToast('دانلود شروع شد ✓', 'success');
}

// ── Attach button component ───────────────────────────────────────────────────
function attachButtonHTML(entityType, entityId) {
  return `<button class="btn btn-ghost btn-sm" onclick="_triggerAttach('${entityType}','${entityId}')"
    style="display:inline-flex;align-items:center;gap:5px">
    📎 <span>پیوست</span>
  </button>`;
}

// پیوست برای topics
async function _triggerAttach(entityType, entityId) {
  const id = +entityId || entityId;
  if (entityType === 'topic') {
    const topics = _db.topics || [];
    const topic = topics.find(t => t.id == id);
    if (!topic) { showToast('موضوع یافت نشد', 'error'); return; }
    const newAttachments = await attachFiles(entityType, id, topic.attachments || []);
    topic.attachments = newAttachments;
    _save();
    showToast('پیوست اضافه شد ✓', 'success');
    // refresh current modal if open
    const studentId = topic.student_id;
    const displayName = (allStudents.find(s=>s.id===studentId)||{name:'',lname:''});
    openTopicDetail(id, studentId, escapeHtml(displayName.name+' '+displayName.lname));
  } else if (entityType === 'session') {
    const session = _db.sessions.find(s => s.id == id);
    if (!session) { showToast('جلسه یافت نشد', 'error'); return; }
    const newAttachments = await attachFiles(entityType, id, session.attachments || []);
    session.attachments = newAttachments;
    _save();
    showToast('پیوست اضافه شد ✓', 'success');
    openSessionDetail(id);
  } else if (entityType === 'instruction') {
    const findNode = (list) => {
      for (const n of list) {
        if (n.id == id) return n;
        if (n.items) { const r = findNode(n.items); if (r) return r; }
      }
      return null;
    };
    const node = findNode(_db.instructions || []);
    if (!node) { showToast('موردی یافت نشد', 'error'); return; }
    const wasEditing = !!document.getElementById('ei-title') && Number(window._currentEditNoteId) === Number(id);
    const newAttachments = await attachFiles(entityType, id, node.attachments || []);
    node.attachments = newAttachments;
    _save();
    showToast('پیوست اضافه شد ✓', 'success');
    // در فرم ویرایش، همان فرم را دوباره باز کن تا پیش‌نمایش فایل تازه فوراً
    // دیده شود؛ خارج از فرم ویرایش، جزئیات یادداشت را به‌روز نمایش بده.
    if (wasEditing) openEditInstruction(id);
    else openNoteDetail(id);
  }
}

async function _deleteAttachment(entityType, entityId, fileId) {
  const id = +entityId || entityId;
  let entity = null;
  if (entityType === 'topic') {
    entity = (_db.topics||[]).find(t => t.id == id);
  } else if (entityType === 'session') {
    entity = _db.sessions.find(s => s.id == id);
  } else if (entityType === 'instruction') {
    const findNode = (list) => {
      for (const n of list) {
        if (n.id == id) return n;
        if (n.items) { const r = findNode(n.items); if (r) return r; }
      }
    };
    entity = findNode(_db.instructions||[]);
  }
  if (!entity) return;
  entity.attachments = (entity.attachments||[]).filter(a => a.id !== fileId);
  await _IDB.delete(fileId);
  _save();
  showToast('پیوست حذف شد', 'error');
  if (entityType === 'instruction') openNoteDetail(id);
}



async function _pickSessionFiles() {
  const current = window._pendingSessionAttachments || [];
  const updated = await attachFiles('session', null, current);
  window._pendingSessionAttachments = updated;
  // آپدیت preview
  const preview = document.getElementById('ses-attach-preview');
  const countEl = document.getElementById('ses-attach-count');
  if (preview) {
    if (updated.length === 0) {
      preview.innerHTML = '';
    } else {
      preview.innerHTML = renderAttachmentsGrid(updated, '(fid)=>{window._pendingSessionAttachments=window._pendingSessionAttachments.filter(a=>a.id!==fid);_pickSessionFilesRefresh();}');
    }
  }
  if (countEl) countEl.textContent = updated.length > 0 ? fa(updated.length) + ' فایل انتخاب شده' : '';
}

function _pickSessionFilesRefresh() {
  const updated = window._pendingSessionAttachments || [];
  const preview = document.getElementById('ses-attach-preview');
  const countEl = document.getElementById('ses-attach-count');
  if (preview) preview.innerHTML = updated.length ? renderAttachmentsGrid(updated, '(fid)=>{window._pendingSessionAttachments=window._pendingSessionAttachments.filter(a=>a.id!==fid);_pickSessionFilesRefresh();}') : '';
  if (countEl) countEl.textContent = updated.length > 0 ? fa(updated.length) + ' فایل انتخاب شده' : '';
}

// ════════════════════════════════════════════════════════════════════════════
// SUPABASE AUTH SYSTEM
// ════════════════════════════════════════════════════════════════════════════
// ── TeamPulse Server API (سرور خودت) ─────────────────────────────────────
const _API_URL = window.location.origin; // خودکار: همون سرور

let _sbSession = null;
let _sbUser = null;
const TP_AUTH_CREDENTIALS_KEY = 'tp_auth_credentials_v1';
const TP_SESSION_TTL_SECONDS = 10 * 365 * 24 * 3600;

function _authSaveCredentials(email, password) {
  if (!email || !password) return;
  try {
    localStorage.setItem(TP_AUTH_CREDENTIALS_KEY, JSON.stringify({
      email,
      password,
      saved_at: Date.now(),
    }));
  } catch(e) {}
}

function _authLoadCredentials() {
  try {
    const raw = localStorage.getItem(TP_AUTH_CREDENTIALS_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch(e) {
    return null;
  }
}

async function _authTrySavedCredentialLogin() {
  const creds = _authLoadCredentials();
  if (!creds?.email || !creds?.password) return false;
  try {
    await _auth.signIn(creds.email, creds.password);
    return true;
  } catch(e) {
    console.warn('[TeamPulse] saved credential login failed:', e.message);
    return false;
  }
}

// ── API helper برای سرور خودمان ─────────────────────────────────────────────
async function _apiFetch(path, opts = {}) {
  const url = _API_URL + path;
  const isFormData = (typeof FormData !== 'undefined') && opts.body instanceof FormData;
  const headers = {
    ...(isFormData ? {} : { 'Content-Type': 'application/json' }),
    ...(opts.headers || {}),
  };
  if (_sbSession?.token) {
    headers['Authorization'] = 'Bearer ' + _sbSession.token;
  }
  const method = String(opts.method || 'GET').toUpperCase();
  const attempts = method === 'GET' ? 2 : 1;
  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      return await fetch(url, { ...opts, headers });
    } catch (error) {
      if (attempt + 1 < attempts) {
        await new Promise(resolve => setTimeout(resolve, 450));
        continue;
      }
      // fetch rejects on DNS/proxy/server disconnects. Returning an HTTP-like
      // response keeps fire-and-forget callers from producing unhandled promise
      // rejections and lets every existing caller use its normal !res.ok path.
      console.warn('[TeamPulse API] request unavailable:', method, path, error?.message || error);
      return new Response(JSON.stringify({
        error: 'network_unavailable',
        message: 'ارتباط با سرور برقرار نشد. اینترنت را بررسی کنید و دوباره تلاش کنید.'
      }), {
        status: 503,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  }
}

async function _compressedJsonRequestBody(value) {
  const json = typeof value === 'string' ? value : JSON.stringify(value);
  if (json.length < 450 * 1024 || typeof CompressionStream === 'undefined') {
    return { body: json, headers: {} };
  }
  const stream = new Blob([json], { type: 'application/json' })
    .stream()
    .pipeThrough(new CompressionStream('gzip'));
  const compressed = await new Response(stream).blob();
  return {
    body: compressed,
    headers: { 'Content-Encoding': 'gzip', 'Content-Type': 'application/json' },
  };
}

async function _sendChunkedWorkspacePayload(accId, payload) {
  const json = JSON.stringify(payload);
  const chunkSize = 300 * 1024;
  const total = Math.ceil(json.length / chunkSize);
  const uploadId = `sync_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
  let response = null;
  for (let index = 0; index < total; index++) {
    response = await _apiFetch('/api/data/' + accId + '/chunks' + _workspaceQuery(), {
      method: 'POST',
      body: JSON.stringify({
        upload_id: uploadId,
        index,
        total,
        chunk: json.slice(index * chunkSize, (index + 1) * chunkSize),
      }),
    });
    if (!response.ok) return response;
  }
  return response;
}

async function _readApiJson(res) {
  const text = await res.text();
  const trimmed = String(text || '').trim();
  if (!trimmed) return {};
  try {
    return JSON.parse(trimmed);
  } catch (e) {
    if (res.status >= 500 || trimmed.startsWith('<')) {
      throw new Error('ارتباط با سرور برقرار نشد. صفحه را رفرش کن یا چند لحظه بعد دوباره تلاش کن');
    }
    throw new Error('پاسخ سرور نامعتبر بود');
  }
}

function _getApiAuthToken() {
  if (_sbSession?.token) return _sbSession.token;
  const saved = (typeof _authLoadSession === 'function') ? _authLoadSession() : null;
  return saved?.token || saved?.access_token || null;
}

const _auth = {
  async signUp(email, password, name, phone) {
    email = String(email || '').trim().toLowerCase();
    const res = await _apiFetch('/api/auth/register', {
      method: 'POST',
      body: JSON.stringify({ email, password, name: name || '', phone: phone || '' })
    });
    const data = await _readApiJson(res);
    if (!res.ok) throw new Error(data.error || 'خطا در ثبت‌نام');
    _sbSession = { token: data.token };
    _sbUser = data.user;
    _authSaveSession({ token: data.token, user: data.user });
    _authSaveCredentials(email, password);
    return data;
  },

  async signIn(email, password) {
    email = String(email || '').trim().toLowerCase();
    const res = await _apiFetch('/api/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password })
    });
    const data = await _readApiJson(res);
    if (!res.ok) throw new Error(data.error || 'خطا در ورود');
    _sbSession = { token: data.token };
    _sbUser = data.user;
    _authSaveSession({ token: data.token, user: data.user });
    _authSaveCredentials(email, password);
    return data;
  },

  async signOut() {
    try { await _apiFetch('/api/auth/logout', { method: 'POST' }); } catch(e) {}
    _sbSession = null;
    _sbUser = null;
    localStorage.removeItem('tp_session');
    _showAuthScreen('login');
  },

  async resetPassword(email) {
    // در این نسخه: تغییر رمز از پنل کاربری
    showToast('برای تغییر رمز با پشتیبانی تماس بگیرید', 'error');
    return false;
  },

  async refreshSession() {
    const saved = _authLoadSession();
    if (!saved?.token) return null;
    // بررسی توکن از سرور
    try {
      const res = await _apiFetch('/api/auth/me');
      if (!res.ok) return null;
      const user = await res.json();
      _sbUser = user;
      _sbSession = { token: saved.token };
      _authSaveSession({ token: saved.token, user });
      return { token: saved.token, user };
    } catch(e) {
      _sbSession = { token: saved.token };
      _sbUser = saved.user || _sbUser;
      return { token: saved.token, user: _sbUser, offline: true };
    }
  },

  isAdmin() {
    return _sbUser?.role === 'admin';
  },
};

function _authSaveSession(session) {
  const data = JSON.stringify({
    token: session.token || session.access_token,
    user: session.user,
    saved_at: Date.now(),
    expires_at: Math.floor(Date.now() / 1000) + TP_SESSION_TTL_SECONDS,
  });
  try { localStorage.setItem('tp_session', data); } catch(e) {}
  try { sessionStorage.setItem('tp_session', data); } catch(e) {}
}

function _authLoadSession() {
  try {
    // Safari ITP fix: try sessionStorage as fallback
    let s = null;
    try { s = localStorage.getItem('tp_session'); } catch(e) {}
    if (!s) { try { s = sessionStorage.getItem('tp_session'); } catch(e) {} }
    const parsed = s ? JSON.parse(s) : null;
    if (!parsed) return null;
    const expiresAt = Number(parsed.expires_at || 0);
    if (expiresAt && expiresAt <= Math.floor(Date.now() / 1000)) {
      try { localStorage.removeItem('tp_session'); } catch(e) {}
      try { sessionStorage.removeItem('tp_session'); } catch(e) {}
      return null;
    }
    return parsed;
  } catch(e) { return null; }
}

function _userDBKey() {
  if (!_sbUser) return 'coaching_reza_v3';
  return _localWorkspaceDBKey();
}

function _dataSignatureForIsolation(data) {
  if (!data) return '';
  const pick = {};
  ['students','packages','payments','sessions','families','todos','staff','instructions'].forEach(k => {
    pick[k] = data[k] || [];
  });
  return JSON.stringify(pick);
}

const _ISOLATION_COLLECTIONS = [
  'students','packages','payments','sessions','families','todos','staff','instructions',
  'wallet_tx','reminders','key_events','topics','expense_reminders','staff_roles','staff_payments',
  'staff_reminders','staff_adjustments','staff_monthly'
];

function _isolationItemHash(value) {
  const text = JSON.stringify(value || null);
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function _buildDataIsolationProbe(data) {
  const collections = {};
  _ISOLATION_COLLECTIONS.forEach(key => {
    collections[key] = (Array.isArray(data?.[key]) ? data[key] : []).map(_isolationItemHash);
  });
  return { version: 1, collections };
}

function _adminCopyStats(data, probe) {
  if (!data || !probe?.collections) return { shared: 0, target: 0, admin: 0, byKey: {} };
  let shared = 0, target = 0, admin = 0;
  const byKey = {};
  _ISOLATION_COLLECTIONS.forEach(key => {
    const adminHashes = new Set(probe.collections[key] || []);
    const targetItems = Array.isArray(data[key]) ? data[key] : [];
    const matched = targetItems.reduce((n, item) => n + (adminHashes.has(_isolationItemHash(item)) ? 1 : 0), 0);
    byKey[key] = { matched, target: targetItems.length, admin: adminHashes.size };
    shared += matched;
    target += targetItems.length;
    admin += adminHashes.size;
  });
  return { shared, target, admin, byKey };
}

function _hasAdminCopiesInTarget(data, probe) {
  const stats = _adminCopyStats(data, probe);
  const students = stats.byKey.students || {};
  const instructions = stats.byKey.instructions || {};
  const strongStudentMatch = students.matched >= 3 && students.matched >= Math.min(students.target, students.admin) * 0.5;
  const strongInstructionMatch = instructions.matched >= 3 && instructions.matched >= Math.min(instructions.target, instructions.admin) * 0.5;
  const broadMatch = stats.shared >= 8 && stats.shared >= Math.min(stats.target, stats.admin) * 0.5;
  return strongStudentMatch || strongInstructionMatch || broadMatch;
}

function _removeAdminCopiesFromTargetData(data, probe) {
  if (!probe?.collections) {
    const removed = _ISOLATION_COLLECTIONS.reduce((sum, key) => sum + (Array.isArray(data?.[key]) ? data[key].length : 0), 0);
    const fresh = _freshData();
    fresh._lastSaved = Date.now();
    return { data: fresh, removed };
  }
  const cleaned = _cloneData(data);
  let removed = 0;
  _ISOLATION_COLLECTIONS.forEach(key => {
    const adminHashes = new Set(probe?.collections?.[key] || []);
    if (!adminHashes.size || !Array.isArray(cleaned[key])) return;
    const before = cleaned[key].length;
    cleaned[key] = cleaned[key].filter(item => !adminHashes.has(_isolationItemHash(item)));
    removed += before - cleaned[key].length;
  });
  cleaned._lastSaved = Date.now();
  return { data: cleaned, removed };
}

function _looksLikeAdminDataDuringImpersonation(data, adminDBKey) {
  if (!data || !adminDBKey) return false;
  try {
    const incomingSignature = _dataSignatureForIsolation(data);
    const expectedAdminSignature = window._impersonating?.adminDataSignature || '';
    if (expectedAdminSignature && incomingSignature === expectedAdminSignature) return true;
    if (_hasAdminCopiesInTarget(data, window._impersonating?.adminIsolationProbe)) return true;
    const adminRaw = localStorage.getItem(adminDBKey);
    if (!adminRaw) return false;
    const adminData = JSON.parse(adminRaw);
    return incomingSignature === _dataSignatureForIsolation(adminData);
  } catch(e) {
    return false;
  }
}

function _cloneData(data) {
  try { return JSON.parse(JSON.stringify(data || {})); }
  catch(e) { return {}; }
}

function _todoMergeTime(item) {
  return Date.parse(item?.updated_at || item?.done_at || item?.completed_at || item?.completedAt || item?.created_at || '') || 0;
}

function _pickMergedTodo(localItem, serverItem) {
  if (!localItem) return _cloneData(serverItem);
  if (!serverItem) return _cloneData(localItem);
  const localTime = _todoMergeTime(localItem);
  const serverTime = _todoMergeTime(serverItem);
  const localSnap = !!(localItem._snapshot || localItem._occurrence);
  const serverSnap = !!(serverItem._snapshot || serverItem._occurrence);
  if (!localSnap && !serverSnap &&
      typeof _isTodoRecurring === 'function' && _isTodoRecurring(localItem) && _isTodoRecurring(serverItem)) {
    const localKey = _jalaliKey(_todoScheduledDate(localItem) || '');
    const serverKey = _jalaliKey(_todoScheduledDate(serverItem) || '');
    if (localKey !== serverKey) return _cloneData(localKey > serverKey ? localItem : serverItem);
  }
  if (!!localItem.done !== !!serverItem.done) {
    const doneItem = localItem.done ? localItem : serverItem;
    const openItem = localItem.done ? serverItem : localItem;
    if (_todoMergeTime(doneItem) >= _todoMergeTime(openItem)) return _cloneData(doneItem);
    return _cloneData(openItem);
  }
  if (localTime === serverTime) return _cloneData(serverItem);
  return _cloneData(localTime > serverTime ? localItem : serverItem);
}

function _mergeLocalPendingChangesIntoOwnerData(localBeforeLoad, ownerData, options = {}) {
  if (!localBeforeLoad || !ownerData) return ownerData;
  const collections = [
    'students','packages','payments','sessions','expenses','expense_reminders','financial_accounts','fiscal_year_closings','financial_budgets','families','wallet_tx','reminders','key_events','topics',
    'staff_roles','staff','staff_payments','staff_reminders','staff_adjustments','staff_monthly',
    'instructions','todos'
  ];
  const merged = ownerData;
  merged._nextId = merged._nextId || {};
  merged._deletedItems = merged._deletedItems && typeof merged._deletedItems === 'object' ? merged._deletedItems : {};
  const localDeleted = localBeforeLoad._deletedItems && typeof localBeforeLoad._deletedItems === 'object'
    ? localBeforeLoad._deletedItems
    : {};

  Object.entries(localDeleted).forEach(([key, tombstones]) => {
    if (options.teamSafe && key !== 'todos') return;
    if (!tombstones || typeof tombstones !== 'object') return;
    merged._deletedItems[key] = merged._deletedItems[key] && typeof merged._deletedItems[key] === 'object'
      ? merged._deletedItems[key]
      : {};
    Object.entries(tombstones).forEach(([id, deletedAt]) => {
      const remoteDeletedAt = merged._deletedItems[key][id] || '';
      if (!remoteDeletedAt || String(deletedAt || '') >= String(remoteDeletedAt)) {
        merged._deletedItems[key][id] = deletedAt || new Date().toISOString();
      }
    });
  });

  collections.forEach(key => {
    const localArr = Array.isArray(localBeforeLoad[key]) ? localBeforeLoad[key] : [];
    const tombstones = merged._deletedItems[key] && typeof merged._deletedItems[key] === 'object'
      ? merged._deletedItems[key]
      : {};
    const serverArr = (Array.isArray(merged[key]) ? merged[key] : [])
      .filter(item => !item || item.id == null || !Object.prototype.hasOwnProperty.call(tombstones, String(item.id)));
    const allowLocal = !options.teamSafe || key === 'todos';
    if (!allowLocal || !localArr.length) {
      merged[key] = serverArr;
      return;
    }
    const byId = new Map(serverArr.map(item => [String(item.id), item]));
    let maxId = Math.max(0, ...(serverArr.map(item => +item.id || 0)), +(merged._nextId[key] || 1) - 1);

    localArr.forEach(localItem => {
      if (!localItem || localItem.id == null) return;
      const idKey = String(localItem.id);
      if (Object.prototype.hasOwnProperty.call(tombstones, idKey)) return;
      const serverItem = byId.get(idKey);
      if (!serverItem) {
        serverArr.push(_cloneData(localItem));
        maxId = Math.max(maxId, +localItem.id || 0);
        return;
      }

      const same = JSON.stringify(serverItem) === JSON.stringify(localItem);
      if (same) return;

      const localCreated = localItem.created_at || '';
      const serverCreated = serverItem.created_at || '';
      if (localCreated && serverCreated && localCreated !== serverCreated) {
        const copy = _cloneData(localItem);
        copy.id = ++maxId;
        serverArr.push(copy);
        return;
      }

      const localTime = Date.parse(localItem.updated_at || localItem.created_at || '') || 0;
      const serverTime = Date.parse(serverItem.updated_at || serverItem.created_at || '') || 0;
      if (key === 'todos') {
        Object.assign(serverItem, _pickMergedTodo(localItem, serverItem));
      } else if (localTime > serverTime) {
        Object.assign(serverItem, _cloneData(localItem));
      }
    });

    merged[key] = serverArr;
    const maxAfter = Math.max(0, ...(serverArr.map(item => +item.id || 0)));
    merged._nextId[key] = Math.max(+(merged._nextId[key] || 1), maxAfter + 1);
  });

  merged._lastSaved = Math.max(Date.now(), localBeforeLoad._lastSaved || 0, merged._lastSaved || 0);
  return merged;
}

function _useLocalImpersonatedFallback(userName, targetKey) {
  _db = _freshData();
  _db.meta = { ..._db.meta, appTitle: userName || 'TeamPulse' };
  _db._lastSaved = Date.now();
  _migrate(_db);
  _purgeLegacyImpersonationCaches();
  window._impersonateServerBlocked = true;
}

function _cacheImpersonatedData(targetKey, data) {
  // Kept as a compatibility hook for existing call sites. Target data is
  // intentionally excluded from localStorage and stored in IndexedDB instead.
  _purgeLegacyImpersonationCaches();
  _queueIndexedDBSnapshot(targetKey, data, 'impersonation-cache');
  return true;
}

function _loadSafeImpersonatedCache(targetKey, adminDBKey) {
  _purgeLegacyImpersonationCaches();
  return false;
}

function _serverSafeData(data) {
  const copy = _cloneData(data || {});
  delete copy._gdrive_token;
  delete copy._gdrive_token_expiry;
  delete copy._gcal_token;
  delete copy._gcal_token_expiry;
  return copy;
}

function _serverDataSignature(data) {
  try { return JSON.stringify(_serverSafeData(data || {})); }
  catch(e) { return ''; }
}

function _serverDataChanged(nextData, currentData) {
  if (!nextData || typeof nextData !== 'object') return false;
  return _serverDataSignature(nextData) !== _serverDataSignature(currentData || {});
}

function _serverTimes(data) {
  return {
    serverTime: Number(data?._lastSaved || 0) || 0,
    localTime: Number(_db?._lastSaved || 0) || 0,
  };
}

// ── ذخیره داده روی سرور (async) ─────────────────────────────────────────
function _scheduleServerSyncRetry() {
  clearTimeout(window._serverSyncRetryTimer);
  const attempt = Math.min(6, Number(window._serverSyncRetryAttempt || 0) + 1);
  window._serverSyncRetryAttempt = attempt;
  const delay = Math.min(60000, 1500 * Math.pow(2, attempt - 1));
  window._serverSyncRetryTimer = setTimeout(() => _syncToServer(), delay);
}

function _fullSyncConflictPendingMatchesCurrentData(pending = _readServerSyncPending()) {
  return (pending?.reason === 'conflict-merged' || pending?.reason === 'conflict-merged-stopped') &&
    pending.fingerprint === _dataFingerprint(_serverDataSignature(_db || {}));
}

function _stopStaleFullSyncConflictPending() {
  const pending = _readServerSyncPending();
  if (!_fullSyncConflictPendingMatchesCurrentData(pending)) return false;
  if (pending.reason === 'conflict-merged') {
    _markServerSyncPending('conflict-merged-stopped');
  }
  clearTimeout(window._serverSyncRetryTimer);
  window._serverSyncRetryAttempt = 0;
  return true;
}

function _notifyRecentCreatedTodos(accountId) {
  if (!accountId || !_sbSession?.token) return;
  window._todoCreatedNotifyRequests = window._todoCreatedNotifyRequests || new Set();
  const cutoff = Date.now() - 15 * 60 * 1000;
  (_db?.todos || [])
    .filter(todo => {
      const createdAt = Date.parse(todo?.created_at || '') || 0;
      return todo && todo.id != null && !todo.archived && createdAt >= cutoff;
    })
    .slice(-20)
    .forEach(todo => {
      const requestKey = `${accountId}:${todo.id}:${todo.created_at || ''}`;
      if (window._todoCreatedNotifyRequests.has(requestKey)) return;
      window._todoCreatedNotifyRequests.add(requestKey);
      _apiFetch('/api/reminders/notify-todo-created', {
        method: 'POST',
        body: JSON.stringify({ ownerAccountId: accountId, workspaceId: _currentAccountId(), todoId: todo.id }),
      }).then(res => {
        if (res.status >= 500) window._todoCreatedNotifyRequests.delete(requestKey);
      }).catch(e => {
        window._todoCreatedNotifyRequests.delete(requestKey);
        console.warn('[Push] todo-created request failed:', e.message);
      });
    });
}

// Serialize whole-document saves. Several UI actions, the poller and retry timer
// can request a sync at the same time. Letting those uploads run concurrently
// gives every request the same base_etag; the first succeeds and all the others
// become 409 conflicts (especially noisy for multi-chunk payloads). Coalesce
// concurrent requests into one trailing pass, which will no-op when data did not
// change while the first save was running.
function _isTerminalTodoCollisionPending() {
  const pending = _readServerSyncPending();
  if (pending?.reason !== 'todo-id-collision-stopped') return false;
  const stoppedFingerprint = pending.stoppedFingerprint || pending.fingerprint;
  return !!stoppedFingerprint && stoppedFingerprint === _dataFingerprint(_serverDataSignature(_db || {}));
}

function _stopTerminalTodoCollisionSync() {
  clearTimeout(window._serverSyncRetryTimer);
  window._serverSyncRetryTimer = null;
  window._serverSyncRetryAttempt = 0;
  window._serverSyncQueued = false;
}

const TODO_COLLISION_REPAIR_VERSION = 2;

function _remapTodoIdReferences(idRemap) {
  if (!(idRemap instanceof Map) || !idRemap.size) return;
  const todoReferenceFields = ['recurrence_parent_id', 'recurring_parent_id', 'parent_todo_id', 'root'];
  (_db.todos || []).forEach(todo => {
    todoReferenceFields.forEach(field => {
      const replacement = idRemap.get(String(todo?.[field]));
      if (replacement != null) todo[field] = replacement;
    });
    if (Array.isArray(todo.history)) {
      todo.history.forEach(row => {
        const replacement = idRemap.get(String(row?.task_id));
        if (replacement != null) row.task_id = replacement;
      });
    }
  });
  (_db.todo_history || []).forEach(row => {
    const replacement = idRemap.get(String(row?.task_id));
    if (replacement != null) row.task_id = replacement;
  });
}

async function _reconcileTerminalTodoCollisions(pending) {
  const todoIds = [...new Set((Array.isArray(pending?.todoIds) ? pending.todoIds : []).map(String))].sort();
  const unknownKey = `${TODO_COLLISION_REPAIR_VERSION}:${todoIds.join(',')}:unknown`;
  let recoveryKey = unknownKey;
  if (pending?.recoveryFailed && pending?.recoveryKey === unknownKey) return false;
  const teamSession = _teamAccessSession();
  const accId = teamSession?.ownerUserId || _sbUser?.id;
  if (!accId || !_sbSession?.token) return false;
  try {
    const statusRes = await _apiFetch('/api/data/' + accId + '/status' + _workspaceQuery());
    if (!statusRes.ok) throw new Error('collision_status_unavailable');
    const status = await statusRes.json();
    const serverHighWater = _applyTodoIdHighWater(status.todo_id_high_water);
    recoveryKey = `${TODO_COLLISION_REPAIR_VERSION}:${todoIds.join(',')}:${serverHighWater}`;
    if (pending?.recoveryFailed && pending?.recoveryKey === recoveryKey) return false;

    const currentRes = await _apiFetch('/api/data/' + accId + _workspaceQuery());
    if (!currentRes.ok) throw new Error('collision_server_data_unavailable');
    const currentPayload = await currentRes.json();
    if (currentPayload?.workspace_id && String(currentPayload.workspace_id) !== _currentAccountId()) {
      throw new Error('collision_workspace_mismatch');
    }
    const serverTodos = Array.isArray(currentPayload?.data?.todos) ? currentPayload.data.todos : [];
    const serverById = new Map(serverTodos.map(todo => [String(todo?.id), todo]));
    const localById = new Map((_db.todos || []).map(todo => [String(todo?.id), todo]));
    const idRemap = new Map();
    const serverBacked = [];

    todoIds.forEach(oldId => {
      const localTodo = localById.get(oldId);
      if (!localTodo) return;
      const serverTodo = serverById.get(oldId);
      if (serverTodo) {
        serverBacked.push(serverTodo);
        return;
      }
      const newId = _allocateTodoId();
      localTodo.id = newId;
      idRemap.set(oldId, newId);
    });

    _remapTodoIdReferences(idRemap);
    _syncTodoIdAllocator(_db);
    if (serverBacked.length) _mergeServerTodosIntoLocal({ todos: serverBacked });
    try { _persistDatabaseSnapshot(window._activeDBKey || DB_KEY, _db); } catch(e) {}

    _clearServerSyncPending(Infinity);
    _markServerSyncPending(idRemap.size ? 'todo-id-collision-remapped' : 'todo-id-collision-resolved');
    return true;
  } catch(e) {
    _markServerSyncPending('todo-id-collision-stopped', {
      todoIds,
      recoveryKey,
      recoveryFailed: true,
      stoppedFingerprint: _dataFingerprint(_serverDataSignature(_db || {})),
    });
    return false;
  }
}

async function _syncToServer(conflictAttempt = 0) {
  if (_isTerminalTodoCollisionPending()) {
    _stopTerminalTodoCollisionSync();
    return null;
  }
  if (window._serverSyncInFlight) {
    window._serverSyncQueued = true;
    return window._serverSyncInFlight;
  }
  if (_stopStaleFullSyncConflictPending()) return;
  const run = (async () => {
    let result = null;
    do {
      window._serverSyncQueued = false;
      result = await _syncToServerOnce(conflictAttempt);
      conflictAttempt = 0;
    } while (window._serverSyncQueued && !_isTerminalTodoCollisionPending());
    if (_isTerminalTodoCollisionPending()) _stopTerminalTodoCollisionSync();
    return result;
  })();
  window._serverSyncInFlight = run;
  try {
    return await run;
  } finally {
    if (window._serverSyncInFlight === run) window._serverSyncInFlight = null;
    if (_isTerminalTodoCollisionPending()) _stopTerminalTodoCollisionSync();
  }
}

function _rebaseTerminalTodoCollisionPending(pending, todoIds) {
  const details = {
    todoIds,
    stoppedFingerprint: _dataFingerprint(_serverDataSignature(_db || {})),
  };
  if (pending.recoveryKey != null) details.recoveryKey = pending.recoveryKey;
  if (pending.recoveryFailed != null) details.recoveryFailed = pending.recoveryFailed;
  _markServerSyncPending('todo-id-collision-stopped', details);
}

function _clearServerSyncPendingAfterTodoDelta(syncSavedAt, todoId) {
  const pending = _readServerSyncPending();
  if (!pending) return;
  const targetId = String(todoId);
  const isCollisionPending = pending.reason === 'todo-id-collision-stopped' ||
    pending.reason === 'todo-delta-collision-stopped' ||
    pending.reason === 'todo-delta-collision-remapped';
  if (!isCollisionPending) {
    _clearServerSyncPending(syncSavedAt);
    return;
  }
  const pendingIds = Array.isArray(pending.todoIds) ? pending.todoIds.map(String) : [];
  if (!pendingIds.includes(targetId)) {
    if (pending.reason === 'todo-id-collision-stopped') {
      _rebaseTerminalTodoCollisionPending(pending, pendingIds);
    }
    return;
  }
  const remainingIds = pendingIds.filter(id => id !== targetId);
  if (!remainingIds.length) {
    _clearServerSyncPending(Infinity);
    return;
  }
  if (pending.reason === 'todo-id-collision-stopped') {
    _rebaseTerminalTodoCollisionPending(pending, remainingIds);
  } else {
    _markServerSyncPending(pending.reason, { ...pending, todoIds: remainingIds });
  }
}

function _syncTodoDelta(todo, operation = 'upsert') {
  clearTimeout(window._serverSyncTimer);
  let todoSnapshot = _cloneData(todo);
  const syncSavedAt = Number(_db?._lastSaved || Date.now()) || Date.now();
  const execute = async () => {
    if (!todoSnapshot || todoSnapshot.id == null) return null;
    const teamSession = _teamAccessSession();
    const accId = teamSession?.ownerUserId || _sbUser?.id;
    if (!accId || !_sbSession?.token) return null;
    try {
      let deltaCollisionAttempt = 0;
      let deltaStateConflictAttempt = 0;
      const resolvedCollisionIds = new Set();
      while (true) {
        const res = await _apiFetch('/api/data/' + accId + '/todos/delta' + _workspaceQuery(), {
          method: 'POST',
          body: JSON.stringify({
            workspace: _currentAccountId(),
            operation,
            todo: todoSnapshot,
            base_etag: window._serverDataEtag || null,
            todo_id_high_water: _db?._todoIdHighWater || 0,
          }),
        });
        let responseData = null;
        try { responseData = await res.clone().json(); } catch(e) {}
        if (res.ok) {
          _applyTodoIdHighWater(responseData?.todo_id_high_water);
          const localTodo = (_db.todos || []).find(item => String(item?.id) === String(todoSnapshot.id));
          if (localTodo && responseData?.todo &&
              String(localTodo.updated_at || '') === String(todoSnapshot.updated_at || '')) {
            Object.assign(localTodo, responseData.todo);
          }
          window._serverDataEtag = responseData?.etag || window._serverDataEtag || null;
          window._lastServerSyncSavedAt = Math.max(window._lastServerSyncSavedAt || 0, syncSavedAt);
          const syncPayload = _serverSafeData(_db);
          window._lastServerSyncFingerprint = _dataFingerprint(_serverDataSignature(syncPayload));
          _writeServerSyncBaseline(syncPayload, window._serverDataEtag);
          _clearServerSyncPendingAfterTodoDelta(syncSavedAt, todoSnapshot.id);
          resolvedCollisionIds.forEach(id => _clearServerSyncPendingAfterTodoDelta(syncSavedAt, id));
          if (teamSession) window._teamLastOwnerDataSavedAt = Math.max(window._teamLastOwnerDataSavedAt || 0, syncSavedAt);
          setTimeout(() => _notifyRecentCreatedTodos(accId), 0);
          if (responseData?.server_changed) {
            setTimeout(() => {
              _loadFromServer().then(updated => _refreshUiAfterServerLoad(updated));
            }, 0);
          }
          return res;
        }
        if (res.status === 409 && responseData?.error === 'todo_id_collision') {
          _applyTodoIdHighWater(responseData.todo_id_high_water);
          const localTodo = (_db.todos || []).find(item => String(item?.id) === String(todoSnapshot.id));
          if (operation === 'create' && deltaCollisionAttempt < 1 && localTodo) {
            const oldId = String(localTodo.id);
            const newId = _allocateTodoId();
            localTodo.id = newId;
            resolvedCollisionIds.add(oldId);
            _remapTodoIdReferences(new Map([[oldId, newId]]));
            _save(false);
            _markServerSyncPending('todo-delta-collision-remapped', { todoIds: [oldId] });
            todoSnapshot = _cloneData(localTodo);
            deltaCollisionAttempt += 1;
            continue;
          }
          _markServerSyncPending('todo-delta-collision-stopped', {
            todoIds: Array.isArray(responseData.todo_ids) ? responseData.todo_ids.map(String) : [String(todoSnapshot.id)],
          });
          if (operation !== 'create') {
            const updated = await _loadFromServer();
            _refreshUiAfterServerLoad(updated);
          }
          return res;
        }
        if (res.status === 409 && responseData?.error === 'todo_delta_conflict' &&
            (operation === 'complete' || operation === 'reopen') &&
            deltaStateConflictAttempt < 1 && responseData?.todo) {
          const localTodo = (_db.todos || []).find(item => String(item?.id) === String(todoSnapshot.id));
          if (localTodo) {
            const intendedState = todoSnapshot;
            const rebasedTodo = { ...responseData.todo };
            ['done', 'status', 'done_at', 'completedAt', 'completed_at', 'completed_by',
             'completed_by_email', 'archived', 'skipped_at', 'staff_report',
             'report_updated_at', 'report_attachment_name', 'report_attachment_at'].forEach(field => {
              if (Object.prototype.hasOwnProperty.call(intendedState, field)) {
                rebasedTodo[field] = _cloneData(intendedState[field]);
              }
            });
            const historyKeys = new Set();
            rebasedTodo.history = [...(Array.isArray(responseData.todo.history) ? responseData.todo.history : []),
              ...(Array.isArray(intendedState.history) ? intendedState.history : [])].filter(row => {
              const key = [row?.action, row?.created_at, row?.user_id, row?.new_value]
                .map(value => String(value ?? '')).join('|');
              if (historyKeys.has(key)) return false;
              historyKeys.add(key);
              return true;
            });
            rebasedTodo.updated_at = new Date().toISOString();
            Object.assign(localTodo, rebasedTodo);
            todoSnapshot = _cloneData(localTodo);
            window._serverDataEtag = responseData.etag || window._serverDataEtag || null;
            try { _persistDatabaseSnapshot(window._activeDBKey || DB_KEY, _db); } catch(e) {}
            deltaStateConflictAttempt += 1;
            continue;
          }
        }
        if (res.status === 409) {
          // A Delta conflict is target-scoped. Reload the authoritative Todo
          // state, but never turn it into a whole-document/chunk upload.
          window._serverDataEtag = responseData?.etag || window._serverDataEtag || null;
          try {
            const updated = await _loadFromServer();
            _refreshUiAfterServerLoad(updated);
          } catch(e) {
            console.warn('[TeamPulse] Delta conflict reload failed:', e.message);
          }
          return res;
        }
        return _syncToServer();
      }
    } catch(e) {
      return _syncToServer();
    }
  };
  const previous = window._todoDeltaChain || Promise.resolve();
  const run = previous.catch(() => null).then(execute);
  const chained = run.finally(() => {
    if (window._todoDeltaChain === chained) window._todoDeltaChain = null;
  });
  window._todoDeltaChain = chained;
  return run;
}

async function _syncToServerOnce(conflictAttempt = 0, todoCollisionAttempt = 0) {
  if (_isTerminalTodoCollisionPending()) {
    _stopTerminalTodoCollisionSync();
    return null;
  }
  if (_fullSyncConflictPendingMatchesCurrentData() && _readServerSyncPending()?.reason === 'conflict-merged-stopped') return null;
  if (window._leavingTeamAccess) return null;
  if (!_sbUser || !_sbSession?.token) return null;
  if (_adoptManualRestoreFromLocalStorage('before-sync')) {
    _forceNextServerSync();
  }
  // block sync اگه impersonating هستیم و هنوز داده load نشده
  if (window._impersonateLoadPending) return null;
  try {
    const teamSession = _teamAccessSession();
    const accId = teamSession?.ownerUserId || _sbUser.id;
    // An older backend ignores ?workspace= and would write this document over
    // the owner's default workspace. Never sync a secondary workspace until
    // the registry endpoint has positively confirmed workspace support.
    if (!teamSession && _currentAccountId() !== 'default' && window._workspaceServerSupported !== true) {
      await _refreshWorkspacesFromServer();
      if (window._workspaceServerSupported !== true) {
        _markServerSyncPending('workspace-api-unavailable');
        return null;
      }
    }
    if (window._impersonating && window._impersonateServerBlocked) {
      console.warn('[Impersonate] blocked sync while target data is isolated locally');
      return null;
    }
    if (window._impersonating && _looksLikeAdminDataDuringImpersonation(_db, window._impersonating.adminDBKey)) {
      console.warn('[Impersonate] blocked admin-like data sync for target account');
      return null;
    }
    if (teamSession && !teamSession.ownerUserId) {
      if (!window._teamMissingOwnerWarned) {
        window._teamMissingOwnerWarned = true;
        showToast('لینک هم‌تیمی قدیمی است؛ صاحب حساب لینک دعوت را دوباره کپی کند', 'error');
      }
      return null;
    }
    if (teamSession && !window._teamOwnerDataReady) {
      const localPending = _cloneData(_db);
      const loaded = await _loadFromServer();
      if (!loaded && !window._teamOwnerDataReady) {
        if (!window._teamOwnerDataNotReadyWarned) {
          window._teamOwnerDataNotReadyWarned = true;
          showToast('ذخیره انجام نشد؛ داده‌های حساب اصلی هنوز کامل لود نشده است', 'error');
        }
        return null;
      }
      _db = _mergeLocalPendingChangesIntoOwnerData(localPending, _db, { teamSafe: true });
      _migrate(_db);
      try {
        const key = window._activeDBKey || _teamActiveDBKey();
        _persistDatabaseSnapshot(key, _db);
      } catch(e) {}
      window._teamOwnerDataReady = true;
    }
    if (!accId) return null;
    const activeWorkspaceId = _currentAccountId();
    if (!teamSession && activeWorkspaceId !== 'default' && window._workspaceDataReady !== true) {
      _markServerSyncPending('workspace-awaiting-authoritative-load');
      return null;
    }
    if (!teamSession && activeWorkspaceId !== 'default' && String(_db?._workspaceId || '') !== activeWorkspaceId) {
      // A stale/legacy cache can belong to the default workspace and have no
      // identity marker. Before blocking the save, fetch the authoritative
      // document for the selected workspace. _loadFromServer replaces this
      // mismatched cache without merging it, so no cross-workspace data leaks.
      if (!window._workspaceIdentityRepairPending) {
        window._workspaceIdentityRepairPending = true;
        try { await _loadFromServer(); }
        finally { window._workspaceIdentityRepairPending = false; }
      }
      if (String(_db?._workspaceId || '') === activeWorkspaceId) {
        window._workspaceIdentityMismatchWarned = false;
      } else {
      _markServerSyncPending('workspace-data-identity-mismatch');
      if (!window._workspaceIdentityMismatchWarned) {
        window._workspaceIdentityMismatchWarned = true;
        showToast('داده صحیح این میزکار از سرور دریافت نشد؛ ذخیره برای جلوگیری از جابه‌جایی اطلاعات متوقف ماند', 'error');
      }
      console.warn('[Workspace] blocked cross-workspace sync', {
        activeWorkspaceId,
        dataWorkspaceId: _db?._workspaceId || null,
      });
      return null;
      }
    }
    const forceSync = !!window._forceNextSync;
    const localSavedAt = Number(_db?._lastSaved || 0) || 0;
    const localFingerprint = _dataFingerprint(_serverDataSignature(_db));
    if (
      !forceSync &&
      localSavedAt &&
      localSavedAt <= (window._lastServerSyncSavedAt || 0) &&
      localFingerprint === window._lastServerSyncFingerprint
    ) {
      _clearServerSyncPending(localSavedAt);
      return null;
    }
    const syncSavedAt = localSavedAt || Date.now();
    const syncPayload = _serverSafeData(_db);
    const fullRequestPayload = {
      data: syncPayload,
      force: forceSync,
      client_saved_at: syncSavedAt,
      base_etag: window._serverDataEtag || null,
    };
    const documentPatch = forceSync ? null : _buildServerSyncPatch(syncPayload);
    const useDocumentDelta = _preferDocumentDelta(documentPatch, fullRequestPayload);
    const sendFullDocument = async () => {
      const rawRequestSize = JSON.stringify(fullRequestPayload).length;
      if (rawRequestSize > 700 * 1024) {
        return _sendChunkedWorkspacePayload(accId, fullRequestPayload);
      }
      const encodedRequest = await _compressedJsonRequestBody(fullRequestPayload);
      return _apiFetch('/api/data/' + accId + _workspaceQuery(), {
        method: 'PUT',
        body: encodedRequest.body,
        headers: encodedRequest.headers,
      });
    };
    let res;
    if (useDocumentDelta) {
      res = await _apiFetch('/api/data/' + accId + '/delta' + _workspaceQuery(), {
        method: 'POST',
        body: JSON.stringify({
          workspace: _currentAccountId(),
          collections: documentPatch.collections,
          scalars: documentPatch.scalars,
          client_saved_at: syncSavedAt,
          base_etag: window._serverDataEtag || null,
        }),
      });
      let deltaBody = null;
      try { deltaBody = await res.clone().json(); } catch(e) {}
      if (res.status === 404 || res.status === 405 ||
          (res.status === 409 && (deltaBody?.error === 'delta_requires_full_sync' || deltaBody?.error === 'empty_patch'))) {
        res = await sendFullDocument();
      }
    } else {
      res = await sendFullDocument();
    }
    let responseData = null;
    try { responseData = await res.clone().json(); } catch(e) {}

    if (res.status === 409 && responseData?.error === 'todo_id_collision') {
      const serverHighWater = _applyTodoIdHighWater(responseData.todo_id_high_water);
      const collisionIds = Array.isArray(responseData.todo_ids) ? responseData.todo_ids : [];
      let remapped = false;
      if (todoCollisionAttempt < 1 && serverHighWater > 0) {
        const ids = new Set(collisionIds.map(item => String(item?.id ?? item)));
        let serverTodos = null;
        try {
          const currentRes = await _apiFetch('/api/data/' + accId + _workspaceQuery());
          if (currentRes.ok) {
            const currentPayload = await currentRes.json();
            if (Array.isArray(currentPayload?.data?.todos)) serverTodos = currentPayload.data.todos;
          }
        } catch(e) {}
        if (serverTodos) {
          const idRemap = new Map();
          const removeTodos = new Set();
          const todoDate = todo => String(todo?.occurrence_date || todo?.date_jalali || todo?.scheduled_date || todo?.scheduledDate || '');
          const todoRoot = todo => String(todo?.recurrence_parent_id ?? todo?.recurring_parent_id ?? todo?.parent_todo_id ?? todo?.root ?? '');
          const localTodos = _db.todos || [];
          localTodos.forEach(todo => {
            const oldId = String(todo?.id);
            if (!ids.has(oldId)) return;
            // A matching current server id is ambiguous/server-backed; never remap it.
            if (serverTodos.some(serverTodo => String(serverTodo?.id) === oldId)) return;
            const isRecurring = todo?._snapshot === true || todo?.recurrence_parent_id != null ||
              todo?.recurring_parent_id != null || todo?.parent_todo_id != null || todo?.root != null;
            let equivalent = null;
            if (isRecurring && todoRoot(todo) && todoDate(todo)) {
              equivalent = serverTodos.find(serverTodo =>
                String(serverTodo?.id) !== oldId &&
                todoRoot(serverTodo) === todoRoot(todo) &&
                todoDate(serverTodo) === todoDate(todo)
              ) || null;
            }
            if (equivalent) {
              const localState = { ...todo };
              const localEquivalent = localTodos.find(item => item !== todo && String(item?.id) === String(equivalent.id));
              if (localEquivalent) {
                Object.assign(localEquivalent, equivalent, localState, { id: equivalent.id });
                removeTodos.add(todo);
              } else {
                Object.assign(todo, equivalent, localState, { id: equivalent.id });
              }
              idRemap.set(oldId, equivalent.id);
            } else {
              const newId = _allocateTodoId();
              todo.id = newId;
              idRemap.set(oldId, newId);
            }
          });
          if (idRemap.size) {
            _db.todos = localTodos.filter(todo => !removeTodos.has(todo));
            _remapTodoIdReferences(idRemap);
            _syncTodoIdAllocator(_db);
            remapped = true;
          }
        }
      }
      try { _persistDatabaseSnapshot(window._activeDBKey || DB_KEY, _db); } catch(e) {}
      _markServerSyncPending(
        remapped ? 'todo-id-collision-remapped' : 'todo-id-collision-stopped',
        remapped ? {} : {
          todoIds: collisionIds.map(item => String(item?.id ?? item)),
          stoppedFingerprint: _dataFingerprint(_serverDataSignature(_db || {})),
        }
      );
      if (remapped) return _syncToServerOnce(conflictAttempt, todoCollisionAttempt + 1);
      return res;
    }

    if (res.status === 409 && responseData?.error === 'sync_conflict' && responseData.data) {
      if (conflictAttempt < 1) {
        const localPending = _cloneData(_db);
        const serverBaseline = _cloneData(responseData.data);
        _db = _mergeLocalPendingChangesIntoOwnerData(localPending, responseData.data, { teamSafe: !!teamSession });
        _mergeServerTodosIntoLocal(serverBaseline);
        _migrate(_db);
        window._serverDataEtag = responseData.etag || null;
        _writeServerSyncBaseline(serverBaseline, window._serverDataEtag);
        try { _persistDatabaseSnapshot(window._activeDBKey || DB_KEY, _db); } catch(e) {}
        _markServerSyncPending('conflict-merged');
        return _syncToServerOnce(conflictAttempt + 1, todoCollisionAttempt);
      }
      const stoppedFingerprint = _dataFingerprint(_serverDataSignature(_db || {}));
      _markServerSyncPending('conflict-merged-stopped');
      clearTimeout(window._serverSyncRetryTimer);
      window._serverSyncRetryAttempt = 0;
      if (window._fullSyncConflictStoppedWarnedFingerprint !== stoppedFingerprint) {
        window._fullSyncConflictStoppedWarnedFingerprint = stoppedFingerprint;
        showToast('همگام‌سازی کامل پس از تعارض متوقف شد؛ تغییرات روی دستگاه محفوظ است', 'error');
      }
      return res;
    }
    if (res && res.ok) {
      _applyTodoIdHighWater(responseData?.todo_id_high_water);
      if (forceSync) window._forceNextSync = false;
      window._lastServerSyncSavedAt = syncSavedAt;
      window._lastServerSyncFingerprint = _dataFingerprint(_serverDataSignature(syncPayload));
      window._serverDataEtag = responseData?.etag || window._serverDataEtag || null;
      _writeServerSyncBaseline(syncPayload, window._serverDataEtag);
      window._serverSyncRetryAttempt = 0;
      clearTimeout(window._serverSyncRetryTimer);
      _clearServerSyncPending(syncSavedAt);
      if (teamSession) window._teamLastOwnerDataSavedAt = _db._lastSaved || Date.now();
      setTimeout(() => _notifyRecentCreatedTodos(accId), 0);
    }
    if (res && res.status === 403 && teamSession && !window._teamSyncForbiddenWarned) {
      window._teamSyncForbiddenWarned = true;
      showToast('دسترسی هم‌تیمی برای ذخیره روی حساب اصلی تأیید نشد', 'error');
    }
    if (res && res.status === 409 && responseData?.error !== 'todo_id_collision' && !window._destructiveSyncBlockedWarned) {
      window._destructiveSyncBlockedWarned = true;
      showToast('سرور جلوی پاک شدن ناگهانی داده‌ها را گرفت؛ صفحه را رفرش کنید', 'error');
    }
    if (res && res.status === 429) {
      window._rateLimitedUntil = Date.now() + 2 * 60 * 1000;
    }
    if (res && res.status === 413) {
      clearTimeout(window._serverSyncRetryTimer);
      window._serverSyncRetryAttempt = 0;
      _markServerSyncPending('payload-too-large');
      if (!window._serverPayloadTooLargeWarned) {
        window._serverPayloadTooLargeWarned = true;
        showToast('حجم داده از سقف سرور بیشتر است؛ تلاش تکراری متوقف شد تا نسخه به‌روز برنامه بارگذاری شود.', 'error');
      }
      return res;
    }
    if (res && !res.ok && responseData?.error !== 'todo_id_collision') {
      _markServerSyncPending('http-' + res.status);
      _scheduleServerSyncRetry();
      if (!window._serverSyncFailureWarned) {
        window._serverSyncFailureWarned = true;
        showToast('ذخیره روی دستگاه انجام شد؛ ارتباط سرور برقرار شود خودکار دوباره ارسال می‌شود', 'error');
        setTimeout(() => { window._serverSyncFailureWarned = false; }, 30000);
      }
    }
    return res || null;
  } catch(e) {
    console.warn('Server sync failed:', e.message);
    _markServerSyncPending('network-error');
    _scheduleServerSyncRetry();
    if (!window._serverSyncFailureWarned) {
      window._serverSyncFailureWarned = true;
      showToast('اینترنت یا سرور در دسترس نیست؛ داده روی دستگاه محفوظ است و خودکار دوباره ارسال می‌شود', 'error');
      setTimeout(() => { window._serverSyncFailureWarned = false; }, 30000);
    }
    return null;
  }
}

function _syncItemTime(item) {
  const t = Date.parse(item?.updated_at || item?.done_at || item?.created_at || 0);
  return Number.isFinite(t) ? t : 0;
}

function _mergeServerTodosIntoLocal(serverData) {
  if (!serverData || !Array.isArray(serverData.todos)) return false;
  if (!_db.todos) _db.todos = [];
  let changed = false;
  const localById = new Map((_db.todos || []).map(t => [String(t.id), t]));
  serverData.todos.forEach(remote => {
    if (!remote || remote.id == null) return;
    const key = String(remote.id);
    const local = localById.get(key);
    if (!local) {
      _db.todos.push({ ...remote });
      changed = true;
      return;
    }
    const picked = _pickMergedTodo(local, remote);
    if (picked && JSON.stringify(picked) !== JSON.stringify(local)) {
      Object.assign(local, picked);
      changed = true;
    }
    const remoteTime = _syncItemTime(remote);
    const localTime = _syncItemTime(local);
    const localHistoryKeys = new Set((Array.isArray(local.history) ? local.history : []).map(row =>
      [row?.action, row?.created_at, row?.user_id, row?.new_value].map(value => String(value ?? '')).join('|')
    ));
    const remoteStateRows = (Array.isArray(remote.history) ? remote.history : []).filter(row =>
      row?.action === 'completed' || row?.action === 'unchecked'
    );
    const hasNewRemoteState = remoteStateRows.some(row =>
      !localHistoryKeys.has([row?.action, row?.created_at, row?.user_id, row?.new_value]
        .map(value => String(value ?? '')).join('|'))
    );
    if (hasNewRemoteState) {
      ['done', 'status', 'done_at', 'completedAt', 'completed_at', 'completed_by',
       'completed_by_email', 'archived', 'updated_at', 'skipped_at',
       'date_jalali', 'scheduled_date', 'scheduledDate', 'occurrence_date'].forEach(field => {
        if (Object.prototype.hasOwnProperty.call(remote, field)) local[field] = _cloneData(remote[field]);
      });
      local.history = Array.isArray(local.history) ? local.history : [];
      (remote.history || []).forEach(row => {
        const key = [row?.action, row?.created_at, row?.user_id, row?.new_value]
          .map(value => String(value ?? '')).join('|');
        if (!localHistoryKeys.has(key)) {
          local.history.push(_cloneData(row));
          localHistoryKeys.add(key);
        }
      });
      changed = true;
      return;
    }
    if (remoteTime > localTime) {
      Object.assign(local, remote);
      changed = true;
      return;
    }
    // داده‌های قدیمی ممکن است updated_at نداشته باشند؛ برای مشکل تیک‌ها، done_at سرور را جدی بگیر.
    if (remote.done && remote.done_at && !local.done) {
      local.done = true;
      local.done_at = remote.done_at;
      local.archived = !!remote.archived;
      local.updated_at = remote.updated_at || remote.done_at;
      changed = true;
    }
  });
  if (changed) {
    _db._lastSaved = Math.max(_db._lastSaved || 0, serverData._lastSaved || 0);
    _migrate(_db);
    try {
      const key = window._activeDBKey || DB_KEY;
      _persistDatabaseSnapshot(key, _db);
    } catch(e) {}
  }
  return changed;
}

// ── بارگذاری داده از سرور ──────────────────────────────────────────────────
async function _loadFromServer() {
  if (!_sbUser || !_sbSession?.token) return false;
  if (window._rateLimitedUntil && Date.now() < window._rateLimitedUntil) return false;
  try {
    const teamSession = _teamAccessSession();
    const accId = teamSession?.ownerUserId || _sbUser.id;
    // Likewise, an old backend returns the default document even when the
    // workspace query is present. Ignoring it preserves strict isolation.
    if (!teamSession && _currentAccountId() !== 'default' && window._workspaceServerSupported !== true) {
      await _refreshWorkspacesFromServer();
      if (window._workspaceServerSupported !== true) return false;
    }
    if (teamSession && !teamSession.ownerUserId) return false;
    if (!accId) return false;
    const res = await _apiFetch('/api/data/' + accId + _workspaceQuery());
    if (res.status === 429) {
      window._rateLimitedUntil = Date.now() + 2 * 60 * 1000;
      return false;
    }
    if (res.status === 403 && teamSession && !window._teamLoadForbiddenWarned) {
      window._teamLoadForbiddenWarned = true;
      showToast('دسترسی هم‌تیمی به حساب اصلی تأیید نشد؛ لینک دعوت را دوباره باز کن', 'error');
      return false;
    }
    if (!res.ok) return false;
    const ct = res.headers.get('content-type') || '';
    if (!ct.includes('application/json')) return false;
    const payload = await res.json();
    const { data } = payload;
    const activeWorkspaceId = _currentAccountId();
    if (payload.workspace_id && String(payload.workspace_id) !== activeWorkspaceId) {
      console.error('[Workspace] ignored response for a different workspace', {
        activeWorkspaceId,
        responseWorkspaceId: payload.workspace_id,
      });
      return false;
    }
    // A confirmed empty response is authoritative too. Replace any quarantined
    // legacy cache with a genuinely empty, correctly identified workspace.
    if (!data && !teamSession && activeWorkspaceId !== 'default') {
      const empty = _freshData();
      empty._workspaceId = activeWorkspaceId;
      empty._lastSaved = 0;
      _migrate(empty);
      _db = empty;
      window._workspaceDataReady = true;
      window._serverDataEtag = payload.etag || null;
      const key = window._activeDBKey || DB_KEY;
      try { _persistDatabaseSnapshot(key, _db); } catch(e) {}
      _clearServerSyncPending(Infinity);
      _writeServerSyncBaseline(_db, null);
      console.warn('[Workspace] initialized confirmed empty scoped workspace');
      return true;
    }
    if (activeWorkspaceId !== 'default' && data?._workspaceId && String(data._workspaceId) !== activeWorkspaceId) {
      console.error('[Workspace] ignored data carrying a different workspace identity', {
        activeWorkspaceId,
        dataWorkspaceId: data._workspaceId,
      });
      return false;
    }
    const responseHighWater = _todoSafeNumericId(payload.todo_id_high_water);
    if (responseHighWater) {
      if (data && typeof data === 'object') {
        data._nextId = data._nextId || {};
        data._todoIdHighWater = Math.max(_todoSafeNumericId(data._todoIdHighWater), responseHighWater);
        data._nextId.todos = Math.max(_todoSafeNumericId(data._nextId.todos), responseHighWater + 1);
      }
      _applyTodoIdHighWater(responseHighWater);
    }
    window._serverDataEtag = payload.etag || window._serverDataEtag || null;
    if (!data) return false;
    if (activeWorkspaceId !== 'default') data._workspaceId = activeWorkspaceId;
    if (!teamSession && activeWorkspaceId !== 'default') window._workspaceDataReady = true;
    if (_isManualRestoreProtected()) {
      const expectedSig = _getManualRestoreExpectedSignature();
      const localSig = _dataFingerprint(_serverDataSignature(_db));
      const serverSig = _dataFingerprint(_serverDataSignature(data));
      if (serverSig === localSig || (expectedSig && serverSig === expectedSig)) {
        _clearManualRestoreProtection();
      } else {
        _forceNextServerSync();
        clearTimeout(window._serverSyncTimer);
        window._serverSyncTimer = setTimeout(_syncToServer, 50);
        console.warn('[TeamPulse] ignored server data while manual restore is pending');
        return false;
      }
    }
    if (window._impersonating && _looksLikeAdminDataDuringImpersonation(data, window._impersonating.adminDBKey)) {
      console.warn('[Impersonate] ignored admin-like server data during poll');
      window._impersonateServerBlocked = true;
      return false;
    }
    if (teamSession) {
      const { serverTime, localTime } = _serverTimes(data);
      if (serverTime && localTime && serverTime === localTime) {
        window._teamOwnerDataReady = true;
        window._teamLastOwnerDataSavedAt = Math.max(window._teamLastOwnerDataSavedAt || 0, serverTime);
        window._lastServerSyncSavedAt = Math.max(window._lastServerSyncSavedAt || 0, localTime);
        return false;
      }
      if (localTime > serverTime && localTime > (window._teamLastOwnerDataSavedAt || 0)) {
        clearTimeout(window._serverSyncTimer);
        window._serverSyncTimer = setTimeout(_syncToServer, 50);
        return false;
      }
      if (serverTime && localTime && serverTime < localTime) {
        window._teamOwnerDataReady = true;
        window._teamLastOwnerDataSavedAt = Math.max(window._teamLastOwnerDataSavedAt || 0, serverTime);
        return false;
      }
      const pendingSync = _readServerSyncPending();
      if (pendingSync) {
        const pendingSavedAt = Number(pendingSync.savedAt || 0) || 0;
        if (serverTime && serverTime >= pendingSavedAt) {
          _clearServerSyncPending(serverTime);
        } else {
          clearTimeout(window._serverSyncTimer);
          window._serverSyncTimer = setTimeout(_syncToServer, 50);
          console.warn('[TeamPulse] kept team local data while server sync is pending');
          return false;
        }
      }
      const teamLocalHasData = !!(_db.students?.length || _db.todos?.length || _db.instructions?.length || _db.staff?.length);
      const teamLocalDiverged = _localDataDivergedFromServerBaseline();
      if (teamLocalHasData && _serverDataChanged(data, _db) && teamLocalDiverged !== false) {
        const serverSnapshot = _cloneData(data);
        _db = _mergeLocalPendingChangesIntoOwnerData(_cloneData(_db), _cloneData(data), { teamSafe: true });
        _mergeServerTodosIntoLocal(serverSnapshot);
        _migrate(_db);
        const key = window._activeDBKey || _teamActiveDBKey();
        try { _persistDatabaseSnapshot(key, _db); } catch(e) {}
        window._teamOwnerDataReady = true;
        _markServerSyncPending(teamLocalDiverged ? 'team-local-diverged' : 'team-legacy-safe-merge');
        clearTimeout(window._serverSyncTimer);
        window._serverSyncTimer = setTimeout(_syncToServer, 50);
        console.warn('[TeamPulse] prevented team data rollback and merged local changes');
        return true;
      }
      if (!serverTime && !localTime && !_serverDataChanged(data, _db)) return false;
      _db = data;
      _migrate(_db);
      const key = window._activeDBKey || _teamActiveDBKey();
      _persistDatabaseSnapshot(key, _db);
      window._teamOwnerDataReady = true;
      window._teamLastOwnerDataSavedAt = _db._lastSaved || 0;
      window._lastServerSyncSavedAt = Math.max(window._lastServerSyncSavedAt || 0, _db._lastSaved || 0);
      _writeServerSyncBaseline(_db, window._serverDataEtag);
      _teamSyncSessionPermissions();
      console.log('[TeamPulse] Team owner data loaded from server');
      return true;
    }
    // merge: همیشه از سرور load کن اگه داده داشت
    // (اولویت با سرور چون همه دستگاه‌ها sync می‌کنن)
    if (data && Object.keys(data).length > 0) {
      // A secondary workspace created by this app always carries its own id.
      // If the local cache does not, it may be a copy of the default workspace;
      // replace that cache from the workspace-scoped server document instead of
      // merging unrelated personnel and business data into it.
      const localWorkspaceMismatch = activeWorkspaceId !== 'default' &&
        String(_db?._workspaceId || '') !== activeWorkspaceId;
      if (localWorkspaceMismatch) {
        _db = data;
        _migrate(_db);
        const key = window._activeDBKey || DB_KEY;
        _persistDatabaseSnapshot(key, _db);
        window._lastServerSyncSavedAt = Number(_db._lastSaved || 0) || 0;
        _writeServerSyncBaseline(_db, window._serverDataEtag);
        _clearServerSyncPending(_db._lastSaved || Date.now());
        console.warn('[Workspace] replaced mismatched local cache with scoped server data');
        return true;
      }
      const { serverTime, localTime } = _serverTimes(data);
      const pendingSync = _readServerSyncPending();
      if (pendingSync) {
        const pendingSavedAt = Number(pendingSync.savedAt || 0) || 0;
        if (localTime >= serverTime || pendingSavedAt >= serverTime) {
          const mergedTodos = _mergeServerTodosIntoLocal(_cloneData(data));
          clearTimeout(window._serverSyncTimer);
          window._serverSyncTimer = setTimeout(_syncToServer, 50);
          console.warn('[TeamPulse] kept newer local data while server sync is pending');
          return mergedTodos;
        }
        const localPending = _cloneData(_db);
        const serverSnapshot = _cloneData(data);
        const merged = _mergeLocalPendingChangesIntoOwnerData(localPending, data);
        _db = merged;
        _mergeServerTodosIntoLocal(serverSnapshot);
        _migrate(_db);
        const key = window._activeDBKey || DB_KEY;
        _persistDatabaseSnapshot(key, _db);
        _markServerSyncPending('merge-pending-with-server');
        _forceNextServerSync();
        clearTimeout(window._serverSyncTimer);
        window._serverSyncTimer = setTimeout(_syncToServer, 50);
        console.warn('[TeamPulse] merged pending local changes with newer server data');
        return true;
      }
      // زمان دستگاه‌ها قابل اعتماد نیست. اگر داده محلی از آخرین نسخه‌ای که واقعاً
      // با سرور همگام شده متفاوت است، هرگز آن را با پاسخ سرور جایگزین نکن.
      // برای نصب‌های قدیمی که هنوز baseline ندارند نیز در صورت اختلاف، یک‌بار
      // محافظه‌کارانه ادغام می‌کنیم تا هیچ داده‌ای از کاربر از دست نرود.
      const localHasMeaningfulData = !!(
        _db.students?.length || _db.todos?.length || _db.instructions?.length || _db.staff?.length ||
        _db.packages?.length || _db.payments?.length || _db.sessions?.length
      );
      const localDiverged = _localDataDivergedFromServerBaseline();
      if (localHasMeaningfulData && _serverDataChanged(data, _db) && localDiverged !== false) {
        const beforeMergeFingerprint = _dataFingerprint(_serverDataSignature(_db));
        const serverSnapshot = _cloneData(data);
        _db = _mergeLocalPendingChangesIntoOwnerData(_cloneData(_db), _cloneData(data));
        _migrate(_db);
        const serverTodoStateChanged = _mergeServerTodosIntoLocal(serverSnapshot);
        const mergedChanged = beforeMergeFingerprint !== _dataFingerprint(_serverDataSignature(_db));
        const key = window._activeDBKey || DB_KEY;
        try { _persistDatabaseSnapshot(key, _db); } catch(e) {}
        _markServerSyncPending(localDiverged ? 'local-diverged-from-baseline' : 'legacy-safe-merge');
        clearTimeout(window._serverSyncTimer);
        window._serverSyncTimer = setTimeout(_syncToServer, 50);
        console.warn('[TeamPulse] prevented automatic rollback and merged local data with server');
        return mergedChanged || serverTodoStateChanged;
      }
      const localEmpty = !_db.students?.length && !_db.todos?.length && !_db.instructions?.length;
      const memoryDiverged = _localDataDivergedFromServerBaseline();
      // اگه سرور داده داشت و لوکال خالی بود، یا سرور جدیدتر بود
      if ((localEmpty && _serverDataChanged(data, _db)) || (serverTime > localTime)) {
        if (!localEmpty && memoryDiverged) {
          const serverSnapshot = _cloneData(data);
          _db = _mergeLocalPendingChangesIntoOwnerData(_cloneData(_db), _cloneData(data));
          _mergeServerTodosIntoLocal(serverSnapshot);
          _migrate(_db);
          const key = window._activeDBKey || DB_KEY;
          try { _persistDatabaseSnapshot(key, _db); } catch(e) {}
          _markServerSyncPending('unstamped-local-merged-with-newer-server');
          clearTimeout(window._serverSyncTimer);
          window._serverSyncTimer = setTimeout(_syncToServer, 50);
          console.warn('[TeamPulse] merged in-memory local todos with newer server data');
          return true;
        }
        _db = data;
        _migrate(_db);
        const key = window._activeDBKey || 'coaching_reza_v3';
        _persistDatabaseSnapshot(key, _db);
        if (window._impersonating) window._impersonateServerBlocked = false;
        if (teamSession) window._teamOwnerDataReady = true;
        window._lastServerSyncSavedAt = Math.max(window._lastServerSyncSavedAt || 0, _db._lastSaved || 0);
        _writeServerSyncBaseline(_db, window._serverDataEtag);
        console.log('[TeamPulse] Loaded from server');
        return true;
      }
      // لوکال جدیدتره — اول تیک‌های سرور را بگیر، بعد اگر لازم بود بفرست
      if (localTime > serverTime) {
        const merged = _mergeServerTodosIntoLocal(data);
        if (merged) {
          _markServerSyncPending('merged-remote-todos-into-newer-local');
          clearTimeout(window._serverSyncTimer);
          window._serverSyncTimer = setTimeout(_syncToServer, 50);
          return true;
        }
        setTimeout(() => _syncToServer(), 500);
      }
    }
    return false;
  } catch(e) {
    console.warn('[TeamPulse] _loadFromServer error:', e.message);
    return false;
  }
}

async function _pollServerStatus() {
  // Keep the existing full-load conflict protections in charge while a local
  // save is pending; the lightweight shortcut must not make that decision.
  if (_hasServerSyncPending() && !_isTerminalTodoCollisionPending() &&
      !_fullSyncConflictPendingMatchesCurrentData()) return _loadFromServer();
  if (!_sbUser || !_sbSession?.token) return false;
  const teamSession = _teamAccessSession();
  const accId = teamSession?.ownerUserId || _sbUser.id;
  if (!accId) return false;
  try {
    const res = await _apiFetch('/api/data/' + accId + '/status' + _workspaceQuery());
    if (!res.ok) return false;
    const ct = res.headers.get('content-type') || '';
    if (!ct.includes('application/json')) return false;
    const status = await res.json();
    const responseHighWater = _todoSafeNumericId(status.todo_id_high_water);
    if (responseHighWater) _applyTodoIdHighWater(responseHighWater);
    if (status.etag === window._serverDataEtag) return false;
    return _loadFromServer();
  } catch(e) {
    console.warn('[TeamPulse] status poll skipped:', e.message);
    return false;
  }
}

function _refreshUiAfterServerLoad(updated) {
  if (currentPage === 'todolist') {
    if (updated) window._todoListServerRefreshPending = true;
    if (!window._todoListServerRefreshPending || !_canAutoRefresh({ allowTodoList: true })) return;
    const content = document.getElementById('content');
    const scrollTop = content?.scrollTop || 0;
    renderTodoList();
    window._todoListServerRefreshPending = false;
    requestAnimationFrame(() => {
      if (content) content.scrollTop = scrollTop;
    });
    return;
  }
  if (updated && _canAutoRefresh()) renderPage();
}

function _startServerSyncLoops() {
  clearInterval(window._syncInterval);
  clearInterval(window._pollInterval);
  clearTimeout(window._pollInterval);
  _bindAppActivityTracking();
  window._syncInterval = setInterval(_syncToServer, 15000);
  const generation = (window._serverPollGeneration || 0) + 1;
  window._serverPollGeneration = generation;
  const poll = async () => {
    try {
      if (!(window._rateLimitedUntil && Date.now() < window._rateLimitedUntil) && !document.hidden) {
        const updated = await _pollServerStatus();
        _refreshUiAfterServerLoad(updated);
      }
    } finally {
      if (window._serverPollGeneration === generation) {
        window._pollInterval = setTimeout(poll, _nextServerPollDelay());
      }
    }
  };
  window._pollInterval = setTimeout(poll, 8000);
}

function _bindAppActivityTracking() {
  if (window._appActivityTrackingBound) return;
  window._appActivityTrackingBound = true;
  window._lastAppActivityAt = Date.now();
  const mark = () => { window._lastAppActivityAt = Date.now(); };
  ['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach(type => {
    document.addEventListener(type, mark, { passive: true });
  });
  window.addEventListener('focus', mark);
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) mark();
  });
}

function _nextServerPollDelay() {
  if (document.hidden) return 2 * 60 * 1000;
  const idleFor = Date.now() - (window._lastAppActivityAt || Date.now());
  if (idleFor > 5 * 60 * 1000) return 90 * 1000;
  if (idleFor > 90 * 1000) return 45 * 1000;
  return 5 * 1000;
}

async function _syncFromServerOnResume() {
  if (document.hidden || document.visibilityState === 'hidden') return false;
  if (!_sbUser || !_sbSession?.token) return false;
  if (window._resumeServerSyncInFlight) return window._resumeServerSyncInFlight;
  window._lastAppActivityAt = Date.now();
  const run = (async () => {
    const updated = await _pollServerStatus();
    _refreshUiAfterServerLoad(updated);
    return updated;
  })();
  window._resumeServerSyncInFlight = run;
  try { return await run; }
  finally {
    if (window._resumeServerSyncInFlight === run) window._resumeServerSyncInFlight = null;
  }
}

function _scheduleServerResumeSync(delay = 500) {
  if (document.hidden || document.visibilityState === 'hidden') return;
  window._lastAppActivityAt = Date.now();
  clearTimeout(window._resumeServerSyncTimer);
  window._resumeServerSyncTimer = setTimeout(() => {
    window._resumeServerSyncTimer = null;
    void _syncFromServerOnResume();
  }, delay);
}

function _startKeyEventReminderLoop() {
  _checkKeyEventReminders();
  clearInterval(window._keyEventReminderInterval);
  window._keyEventReminderInterval = setInterval(_checkKeyEventReminders, 5 * 60 * 1000);
}

function _flushPendingServerSyncKeepalive() {
  if (!_sbUser?.id || !_sbSession?.token) return;
  const teamSession = _teamAccessSession();
  if (teamSession && !teamSession.ownerUserId) return;
  const diverged = _localDataDivergedFromServerBaseline();
  const pending = _hasServerSyncPending();
  if (!diverged && !pending) return;
  if (diverged) {
    try {
      _db._lastSaved = Math.max(Number(_db._lastSaved || 0), Date.now());
      _persistDatabaseSnapshot(window._activeDBKey || DB_KEY, _db);
      _markServerSyncPending('pagehide-flush');
    } catch(e) {}
  }
  const accId = teamSession?.ownerUserId || _sbUser.id;
  const savedAt = Number(_db?._lastSaved || Date.now()) || Date.now();
  const syncPayload = _serverSafeData(_db);
  const fullBody = {
    data: syncPayload,
    force: !!window._forceNextSync,
    client_saved_at: savedAt,
    base_etag: window._serverDataEtag || null,
  };
  const patch = window._forceNextSync ? null : _buildServerSyncPatch(syncPayload);
  const useDelta = typeof _preferDocumentDelta === 'function' && _preferDocumentDelta(patch, fullBody);
  const payloadObj = useDelta ? {
    workspace: _currentAccountId(),
    collections: patch.collections,
    scalars: patch.scalars,
    client_saved_at: savedAt,
    base_etag: window._serverDataEtag || null,
  } : fullBody;
  const path = useDelta
    ? '/api/data/' + accId + '/delta'
    : '/api/data/' + accId;
  const url = (window.location.origin || '') + path + _workspaceQuery('?');
  const data = JSON.stringify(payloadObj);
  const authHeaders = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + _sbSession.token,
  };
  const keepalivePost = () => {
    fetch(url, { method: 'POST', headers: authHeaders, body: data, keepalive: true, referrerPolicy: 'no-referrer' }).catch(() => {});
  };
  if (navigator.sendBeacon) {
    const beaconBody = JSON.stringify(Object.assign({ token: _sbSession.token }, payloadObj));
    const blob = new Blob([beaconBody], { type: 'text/plain;charset=UTF-8' });
    const sent = navigator.sendBeacon(url, blob);
    if (!sent) keepalivePost();
  } else {
    keepalivePost();
  }
}

function _bindServerSyncLifecycleHandlers() {
  if (window._serverSyncLifecycleBound) return;
  window._serverSyncLifecycleBound = true;
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      clearTimeout(window._serverSyncTimer);
      _flushPendingServerSyncKeepalive();
    } else {
      _refreshReminderPushRegistration();
      _scheduleServerResumeSync();
    }
  });
  window.addEventListener('pagehide', () => {
    clearTimeout(window._serverSyncTimer);
    _flushPendingServerSyncKeepalive();
  });
  window.addEventListener('focus', () => {
    _refreshReminderPushRegistration();
    if ((_db?._lastSaved || 0) > (window._teamLastOwnerDataSavedAt || 0)) {
      clearTimeout(window._serverSyncTimer);
      void _syncToServer();
    }
    _scheduleServerResumeSync();
  });
  window.addEventListener('pageshow', () => _scheduleServerResumeSync());
  window.addEventListener('online', () => _scheduleServerResumeSync());
  _scheduleServerResumeSync(500);
  window.addEventListener('beforeunload', () => {
    clearTimeout(window._serverSyncTimer);
    _adoptManualRestoreFromLocalStorage('beforeunload');
    _flushPendingServerSyncKeepalive();
  });
}

function _showAuthScreen(mode) {
  mode = mode || 'login';
  document.getElementById('app').style.display = 'none';
  const bn = document.querySelector('.bottom-nav');
  if (bn) bn.style.display = 'none';

  let authDiv = document.getElementById('auth-screen');
  if (!authDiv) {
    authDiv = document.createElement('div');
    authDiv.id = 'auth-screen';
    document.body.appendChild(authDiv);
  }
  authDiv.style.cssText = 'display:block;position:fixed;inset:0;z-index:9999;overflow-y:auto;background:var(--bg);-webkit-overflow-scrolling:touch';
  authDiv.innerHTML = _authHTML(mode);
  if (mode === 'login' || mode === 'reset') setTimeout(_authHydrateSavedFields, 80);
  if (mode === 'register') setTimeout(_refreshCaptcha, 50);
}

function _authHydrateSavedFields() {
  const creds = _authLoadCredentials();
  if (!creds) return;
  const email = document.getElementById('auth-email');
  const pass = document.getElementById('auth-pass');
  if (email && creds.email && !email.value) email.value = creds.email;
  if (pass && creds.password && !pass.value) pass.value = creds.password;
  [email, pass].filter(Boolean).forEach(el => {
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  });
}

function _hideAuthScreen() {
  const el = document.getElementById('auth-screen');
  if (el) el.style.display = 'none';
  document.getElementById('app').style.display = '';
  const bn = document.querySelector('.bottom-nav');
  if (bn) bn.style.display = '';
}

