let _captchaAnswer = 0;
function _refreshCaptcha() {
  const a = Math.floor(Math.random() * 9) + 1;  // 1-9
  const b = Math.floor(Math.random() * 9) + 1;  // 1-9
  const ops = [
    { q: a + ' + ' + b, a: a + b },
    { q: (a + b) + ' - ' + b, a: a },
    { q: a + ' + ' + b, a: a + b },
  ];
  const pick = ops[Math.floor(Math.random() * ops.length)];
  _captchaAnswer = pick.a;
  const el = document.getElementById('captcha-question');
  if (el) el.textContent = pick.q;
  const inp = document.getElementById('captcha-answer');
  if (inp) inp.value = '';
}

function _authMsg(text, type) {
  type = type || 'error';
  const el = document.getElementById('auth-msg');
  if (!el) return;
  el.style.display = 'block';
  el.style.background = type === 'error' ? 'rgba(248,113,113,.12)' : 'rgba(62,207,142,.12)';
  el.style.color = type === 'error' ? 'var(--red)' : 'var(--green)';
  el.style.border = '1px solid ' + (type === 'error' ? 'rgba(248,113,113,.3)' : 'rgba(62,207,142,.3)');
  el.textContent = text;
}

function _authLoading(on, mode) {
  const btn = document.getElementById('auth-submit-btn');
  if (!btn) return;
  btn.disabled = on;
  if (on) {
    btn.textContent = '⏳ در حال پردازش...';
  } else {
    btn.textContent = mode === 'login' ? '🔐 ورود' : '✅ ایجاد حساب';
  }
}

async function _doAuth(mode) {
  const email = (document.getElementById('auth-email')?.value || '').trim();
  const pass = document.getElementById('auth-pass')?.value || '';
  const name = (document.getElementById('auth-name')?.value || '').trim();
  const phone = enDigits(document.getElementById('auth-phone')?.value || '').replace(/\s+/g, '');

  if (!email || !pass) { _authMsg('ایمیل و رمز عبور را وارد کنید'); return; }
  if (!email.includes('@')) { _authMsg('ایمیل معتبر نیست'); return; }
  if ((mode === 'register' && pass.length < 8) || (mode === 'login' && pass.length < 6)) {
    _authMsg(mode === 'register' ? 'رمز عبور باید حداقل ۸ کاراکتر باشد' : 'رمز عبور معتبر نیست');
    return;
  }

  if (mode === 'register') {
    if (!name) { _authMsg('نام را وارد کنید'); return; }
    if (!/^09\d{9}$/.test(phone)) { _authMsg('شماره تماس باید ۱۱ رقم و با ۰۹ شروع شود'); return; }
    const pass2 = document.getElementById('auth-pass2')?.value || '';
    if (pass !== pass2) { _authMsg('رمزهای عبور یکسان نیستند'); return; }
    const userAns = parseInt(document.getElementById('captcha-answer')?.value || '');
    if (isNaN(userAns) || userAns !== _captchaAnswer) {
      _authMsg('جواب تأیید امنیتی اشتباه است');
      _refreshCaptcha();
      return;
    }
  }

  _authLoading(true, mode);
  try {
    if (mode === 'login') {
      await _auth.signIn(email, pass);
      await _authOnSuccess();
    } else {
      const data = await _auth.signUp(email, pass, name, phone);
      if (data.token) {
        // ذخیره خودکار منطقه زمانی در اولین ثبت‌نام
        const loc = _detectUserLocale();
        if (!_db.meta) _db.meta = {...DEFAULT_META};
        _db.meta.timezone = _db.meta.timezone || loc.timezone;
        _db.meta.calendarType = _db.meta.calendarType || loc.calendarType;
        _db.meta.language = _db.meta.language || loc.language;
        _save();
        await _authOnSuccess();
      }
    }
  } catch(e) {
    const msg = e.message || '';
    if (msg.includes('already registered') || msg.includes('already exists') || msg.includes('User already')) {
      _authMsg('این ایمیل قبلاً ثبت شده — وارد شو');
    } else if (msg.includes('Invalid login') || msg.includes('invalid_credentials') || msg.includes('Invalid')) {
      _authMsg('ایمیل یا رمز عبور اشتباه است');
    } else if (msg.includes('Email not confirmed')) {
      _authMsg('ایمیل تأیید نشده — صندوق ورودیت رو چک کن');
    } else if (msg.includes('rate limit') || msg.includes('too many')) {
      _authMsg('خیلی زیاد تلاش کردی — چند دقیقه صبر کن');
    } else {
      _authMsg('خطا: ' + msg);
    }
    _authLoading(false, mode);
    if (document.getElementById('captcha-question')) _refreshCaptcha();
  }
}

async function _doReset() {
  const email = (document.getElementById('auth-email')?.value || '').trim();
  if (!email || !email.includes('@')) { _authMsg('ایمیل معتبر وارد کن'); return; }
  try {
    await _auth.resetPassword(email);
    _authMsg('لینک بازیابی به ایمیلت فرستادیم ✓', 'success');
  } catch(e) {
    _authMsg('خطا: ' + e.message);
  }
}

async function _authOnSuccess() {
  const pendingInvite = localStorage.getItem(TEAM_PENDING_INVITE_KEY);
  if (pendingInvite) {
    try { _acceptTeamInviteToken(pendingInvite); }
    catch(e) { localStorage.removeItem(TEAM_PENDING_INVITE_KEY); showToast(e.message || 'دعوت‌نامه معتبر نیست', 'error'); }
  }
  window._teamOwnerDataReady = false;
  const teamSessionAtStart = _teamAccessSession();
  if (teamSessionAtStart && !teamSessionAtStart.ownerUserId) {
    await _ensureTeamAccessOwner();
  } else if (teamSessionAtStart) {
    void _ensureTeamAccessOwner();
  }
  window._activeDBKey = _teamActiveDBKey();
  await _loadPrimaryDatabase();
  let loadedFromServer = false;
  const hasLocalDataAtStart = (_db.students?.length > 0) || (_db.todos?.length > 0) || (_db.instructions?.length > 0) || (_db.staff?.length > 0) || (_db.meta?.jobId) || (_db.meta?.appTitle && _db.meta.appTitle !== 'TeamPulse');

  // کاربر جدید = نه از سرور داده اومد نه لوکال داده داره
  const isNewUser = !hasLocalDataAtStart && !_teamAccessSession();

  if (isNewUser) {
    // واقعاً اولین بار — setup wizard نشون بده
    const emailName = _sbUser.email.split('@')[0];
    _db.meta = { ..._db.meta, appTitle: emailName };
    _setDefaultAccountName(emailName);
    _save(false);
  } else {
    // دستگاه جدید یا موجود — فقط اطمینان از اسم
    // نکته: در دسترسی هم‌تیمی (team access) این «حساب» متعلق به کارفرماست، نه پرسنل.
    // اگر اینجا appTitle را با ایمیل خودِ پرسنل پر کنیم، تا قبل از رسیدن دادهٔ واقعی
    // از سرور، بالای صفحه چند لحظه اسم/ایمیل پرسنل به‌جای نام کسب‌وکار کارفرما نشان داده
    // می‌شود. پس برای دسترسی هم‌تیمی صبر می‌کنیم تا دادهٔ واقعی از سرور برسد.
    if (!_teamAccessSession() && (!_db.meta?.appTitle || _db.meta.appTitle === 'TeamPulse')) {
      const emailName = _sbUser.email.split('@')[0];
      _db.meta = { ..._db.meta, appTitle: emailName };
      _save(false);
    }
  }

  _hideAuthScreen();
  _updateAuthUI();
  await init();
  updateAccountDisplay();

  // داده محلی را فوری نشان می‌دهیم؛ رجیستری میزکار و sync سرور بعد از اولین
  // paint انجام می‌شود تا رفرش صفحه روی درخواست شبکه مکث نکند.
  (async () => {
    if (!_teamAccessSession()) {
      try { await _refreshWorkspacesFromServer(); } catch (e) {}
    }
    for (let attempt = 0; attempt < 3; attempt++) {
      loadedFromServer = await _loadFromServer();
      if (loadedFromServer) break;
      if (attempt < 2) await new Promise(r => setTimeout(r, 800));
    }
    if (loadedFromServer) {
      console.log('[TeamPulse] Data synced from server');
      updateAccountDisplay();
      if (_canAutoRefresh()) renderPage();
      applyMetaToUI();
      return;
    }
    if (_teamAccessSession() && !window._teamOwnerDataReady) {
      window._teamOwnerDataReady = false;
      showToast('داده‌های حساب اصلی هنوز لود نشده؛ برای ذخیره دوباره صفحه را رفرش کن', 'error');
    } else if (_teamAccessSession()) {
      updateAccountDisplay();
      if (_canAutoRefresh()) renderPage();
      applyMetaToUI();
    } else if (isNewUser) {
      setTimeout(() => _showWelcomeTour(), 800);
    }
  })();

  void (async () => {
    try {
      const wRes = await _apiFetch('/api/wallet');
      if (wRes.ok) {
        const ct = wRes.headers.get('content-type') || '';
        if (!ct.includes('application/json')) throw new Error('not json');
        const wData = await wRes.json();
        if (!_db._user_wallet) _db._user_wallet = { balance: 0, daily_cost: 1000, transactions: [] };
        _db._user_wallet.balance = wData.balance;
        _db._user_wallet.daily_cost = wData.daily_cost;
        _db._user_wallet.transactions = (wData.transactions || []).map(t => ({
          id: t.id, type: t.type, amount: t.amount, desc: t.description,
          date: new Date((t.created_at||0)*1000).toISOString()
        }));
        _save(false);
      } else { _initUserWallet(); }
    } catch(e) { _initUserWallet(); }
  })();

  _startServerSyncLoops();
  _startKeyEventReminderLoop();
  _bindServerSyncLifecycleHandlers();

  if (loadedFromServer && _db.meta?.jobId) {
    // کاربر موجود — wizard رو نشون نده، فقط applyMeta
    applyMetaToUI();
  }
}

