// ── راهنمای آیکون «افزودن» روی صفحه شاگردان ──
function _showAddStudentHint() {
  const addBtn = document.querySelector('[data-add-student-btn], .btn-add-student, #add-student-btn');
  // پیدا کردن دکمه افزودن با fallback به onclick pattern
  const candidates = Array.from(document.querySelectorAll('button, a')).filter(el =>
    el.getAttribute('onclick')?.includes('openStudentModal')
  );
  const target = addBtn || candidates[0];

  const entityS = META.entitySingular || 'شاگرد';
  showToast(`👇 برای شروع، از دکمه «+ افزودن ${entityS}» اولین ${entityS} رو اضافه کن`, 'success', 6000);

  if (target) {
    target.style.position = 'relative';
    const pulse = document.createElement('div');
    pulse.id = 'add-student-pulse-hint';
    pulse.style.cssText = `
      position:fixed;z-index:9998;pointer-events:none;
      width:54px;height:54px;border-radius:50%;
      border:2.5px solid var(--accent2);
      animation:tpHintPulse 1.4s ease-out infinite;
    `;
    const rect = target.getBoundingClientRect();
    pulse.style.top = (rect.top + rect.height/2 - 27) + 'px';
    pulse.style.left = (rect.left + rect.width/2 - 27) + 'px';
    document.body.appendChild(pulse);

    if (!document.getElementById('tp-hint-keyframes')) {
      const style = document.createElement('style');
      style.id = 'tp-hint-keyframes';
      style.textContent = `@keyframes tpHintPulse{0%{transform:scale(.8);opacity:1}100%{transform:scale(1.6);opacity:0}}`;
      document.head.appendChild(style);
    }

    setTimeout(() => { const p = document.getElementById('add-student-pulse-hint'); if (p) p.remove(); }, 8000);
    target.addEventListener('click', () => {
      const p = document.getElementById('add-student-pulse-hint'); if (p) p.remove();
    }, { once: true });
  }
}

