// ════════════════════════════════════════════════════════════════════════════
// ADMIN PANEL — پنل مدیریت (فقط برای رضا صفاری)
// ════════════════════════════════════════════════════════════════════════════
let _adminSelectedUsers = new Set();

function _adminSparkline(series) {
  const values=(series||[]).map(x=>Number(x.value)||0);
  const data=values.length ? values : [0,0,0,0,0,0];
  while(data.length<2)data.unshift(0);
  const max=Math.max(1,...data),min=Math.min(...data),range=Math.max(1,max-min);
  const pts=data.map((v,i)=>`${(i/(data.length-1))*92},${42-((v-min)/range)*36}`);
  return `<svg class="admin-spark" viewBox="0 0 92 45" aria-hidden="true"><path class="spark-fill" d="M${pts.join(' L')} L92,45 L0,45 Z"></path><path d="M${pts.join(' L')}"></path></svg>`;
}
function _adminMetricCard({type,title,value,current,previous,series,inverse=false}) {
  const change=previous ? Math.round(((current-previous)/Math.abs(previous))*100) : (current?100:0);
  const good=inverse ? change<0 : change>0;
  const cls=change===0?'neutral':(good?'up':'down');
  const arrow=change>0?'▲':change<0?'▼':'●';
  return `<button type="button" class="admin-stat-card" onclick="_adminApplyStatFilter('${type}')" aria-label="${escapeHtml(title)}؛ ${escapeHtml(String(value))}">
    <span><span class="admin-stat-title">${title}</span><strong class="admin-stat-number">${value}</strong>
      <span class="admin-stat-change ${cls}">${arrow} ${fa(Math.abs(change))}٪</span>
      <span class="admin-stat-compare">در مقایسه با دوره قبل</span></span>${_adminSparkline(series)}
  </button>`;
}
function _adminStatsHtml(d,users) {
  const registrations=d?.series?.registrations||[];
  return `<details class="admin-status-summary"><summary>خلاصه وضعیت</summary><div class="admin-stats-grid">
    ${_adminMetricCard({type:'all',title:'کل کاربران',value:fa(d.totalUsers??users.length),current:d.totalUsers??users.length,previous:d.totalUsersPrevious??0,series:registrations})}
    ${_adminMetricCard({type:'activeToday',title:'فعال امروز',value:fa(d.activeToday||0),current:d.activeToday||0,previous:d.activeYesterday||0,series:d?.series?.activity})}
    ${_adminMetricCard({type:'new',title:'کاربران جدید این ماه',value:fa(d.newThisMonth||0),current:d.newThisMonth||0,previous:d.newPreviousMonth||0,series:registrations})}
    ${_adminMetricCard({type:'inactive',title:'کاربران غیرفعال',value:fa(d.inactiveUsers||0),current:d.inactiveUsers||0,previous:d.inactivePreviousPeriod||0,series:d?.series?.inactive,inverse:true})}
    ${_adminMetricCard({type:'paid',title:'کاربران پلن پولی',value:fa(d.paidUsers||0),current:d.paidUsers||0,previous:d.paidPreviousPeriod||0,series:d?.series?.paid})}
    ${_adminMetricCard({type:'revenue',title:'درآمد ماه',value:`${fa(d.monthlyRevenue||0)} تومان`,current:d.monthlyRevenue||0,previous:d.previousMonthlyRevenue||0,series:d?.series?.revenue})}
  </div></details>`;
}

async function renderAdminPanel() {
  if (!_auth.isAdmin()) {
    setContent('<div class="empty"><span>🚫</span><p>دسترسی ندارید</p></div>');
    return;
  }

  updateTopbarActions('<button class="btn btn-ghost" onclick="renderAdminPanel()">🔄 بروزرسانی</button>');

  // تنظیمات: ترکیب localStorage + _db (اولویت با _db چون آخرین ذخیره است)
  const dbSettings = _db.admin_settings || {};
  const lsSettings = JSON.parse(localStorage.getItem('tp_admin_settings') || '{}');
  const localSettings = { ...lsSettings, ...dbSettings };
  // همیشه sync کن به localStorage
  localStorage.setItem('tp_admin_settings', JSON.stringify(localSettings));
  let allUsers = [];
  let serverOnline = false;
  let dashboard = null;

  try {
    const res = await Promise.race([
      _apiFetch('/api/admin/stats'),
      new Promise((_,r) => setTimeout(() => r(new Error('timeout')), 3000))
    ]);
    if (res && res.ok) {
      const stats = await res.json();
      serverOnline = true;
      allUsers = stats.users || [];
      dashboard = stats.dashboard || null;
      if (stats.settings) Object.assign(localSettings, stats.settings);
    }
  } catch(e) { console.log('Admin API not available'); }

  window._adminAllUsers = allUsers;
  window._adminDashboard = dashboard || {};
  window._adminSettings = localSettings;
  window._adminUsersPage = 1;
  const existingAdminUserIds = new Set(allUsers.map(u => String(u.id)));
  _adminSelectedUsers = new Set([..._adminSelectedUsers].filter(id => existingAdminUserIds.has(String(id))));

  const firstUserPage = allUsers.slice(0, 20);
  const usersHTML = _adminRenderUserList(firstUserPage);

  setContent(`
    <div class="admin-page">
    <div class="admin-content">
      <div class="admin-actions" aria-label="اقدامات اصلی مدیریت">
        <button class="btn btn-primary" onclick="_adminOpenCreateUser()">＋ افزودن کاربر</button>
        <button class="btn btn-ghost" onclick="_adminOpenFinance()">💰 مالی</button>
        <button class="btn btn-ghost" onclick="_adminExportAll()">📊 خروجی Excel</button>
        <button class="btn btn-ghost" onclick="_adminNotifyAll()">🔔 ارسال اعلان</button>
        <button class="btn btn-ghost" onclick="renderAdminPanel()">↻ بروزرسانی اطلاعات</button>
      </div>
      <div style="display:flex;align-items:center;gap:8px;padding:10px 14px;border-radius:10px;
        background:${serverOnline?'rgba(62,207,142,.08)':'rgba(248,113,113,.08)'};
        border:1px solid ${serverOnline?'rgba(62,207,142,.3)':'rgba(248,113,113,.3)'};
        margin-bottom:16px;font-size:12px">
        <span>${serverOnline?'🟢':'🔴'}</span>
        <span>${serverOnline?'سرور متصل است':'سرور در دسترس نیست'}</span>
      </div>
      ${_adminStatsHtml(dashboard||{},allUsers)}

      <div class="detail-section" style="margin-bottom:16px;border:1px solid rgba(124,106,247,.28);background:linear-gradient(135deg,rgba(124,106,247,.07),rgba(96,165,250,.03))">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap">
          <div>
            <h3 style="margin-bottom:5px">💾 مدیریت پشتیبان‌ها</h3>
            <p style="margin:0;color:var(--text3);font-size:11.5px;line-height:1.8">
              دریافت یک فایل جامع از داده‌های تمام ${fa(allUsers.length)} کاربر. پشتیبان هر کاربر نیز از منوی سه‌نقطه همان کاربر در دسترس است.
            </p>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <button class="btn btn-primary" onclick="_adminBackupAllUsers(this)">دریافت پشتیبان کل کاربران</button>
            <button class="btn btn-ghost" onclick="_adminImportAllUsersBackup()">📂 وارد کردن پشتیبان کل کاربران</button>
          </div>
        </div>
      </div>

      ${_adminGetPinnedAccounts().length ? `
      <div class="detail-section" style="margin-bottom:16px;border:1px solid rgba(251,191,36,.3);background:rgba(251,191,36,.05)">
        <h3 style="margin-bottom:10px">📌 حساب‌های پین شده</h3>
        <div style="display:flex;flex-wrap:wrap;gap:8px">
          ${_adminGetPinnedAccounts().map(p =>
            '<div style="display:flex;align-items:center;gap:8px;padding:8px 12px;' +
            'background:var(--bg3);border-radius:10px;border:1px solid rgba(251,191,36,.3)">' +
            '<span style="font-weight:600;font-size:13px">' + escapeHtml(p.name) + '</span>' +
            '<button onclick="_adminImpersonate(' + JSON.stringify(p.id) + ',' + JSON.stringify(p.name) + ')" ' +
            'style="font-size:11px;padding:2px 8px;border-radius:6px;border:1px solid var(--accent2);' +
            'background:rgba(124,106,247,.1);color:var(--accent2);cursor:pointer;font-family:var(--font)">🔑 ورود به‌جای کاربر</button>' +
            '<button class="x-close-sm" onclick="_adminPinAccount(' + JSON.stringify(p.id) + ',' + JSON.stringify(p.name) + ')" ' +
            'title="برداشتن پین">✕</button>' +
            '</div>'
          ).join('')}
        </div>
      </div>` : ''}

      ${serverOnline ? `
      <div class="detail-section" style="margin-bottom:16px">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
          <h3>👥 کاربران</h3>
          <span style="font-size:11px;color:var(--text3)">${fa(allUsers.length)} نفر</span>
        </div>
        <input class="form-input" id="admin-user-search" placeholder="🔍 جستجو در نام یا ایمیل..."
          oninput="_adminFilterUsers(this.value)"
          style="margin-bottom:12px;font-size:13px">
        <div id="admin-bulk-actions">${_adminBulkActionsHtml(firstUserPage)}</div>
        <div id="admin-users-list">${usersHTML}</div>
        <div id="admin-users-pagination">${_adminPaginationHtml(allUsers.length)}</div>
      </div>` : ''}
    </div>
    </div>`);

  setTimeout(() => document.getElementById('admin-user-search')?.focus(), 100);
}

function _adminIsProtectedUser(u) {
  return Boolean(u && u.is_protected);
}

function _adminRenderUserList(users) {
  if (!users.length) return '<p style="font-size:12px;color:var(--text3);padding:12px">کاربری پیدا نشد</p>';
  return users.map(u => {
    const initLetter = escapeHtml(String(u.name||u.email||'?').charAt(0).toUpperCase());
    const uid = u.id;
    const uname = escapeHtml(u.name||u.email||'');
    const isActive = u.is_active;
    const isAdmin = u.role === 'admin';
    const bgColor = isActive ? 'rgba(62,207,142,.15)' : 'rgba(248,113,113,.15)';
    const txtColor = isActive ? 'var(--green)' : 'var(--red)';
    const statusLabel = isActive ? 'فعال' : 'غیرفعال';
    const roleLabel = isAdmin ? '👑 ادمین' : '👤 کاربر';
    const menuId = 'admin-user-menu-' + uid;
    const selected = _adminSelectedUsers.has(String(uid));
    return [
      '<div data-admin-user-id="' + uid + '" data-selected="' + (selected?'true':'false') + '" style="display:flex;align-items:center;gap:10px;padding:10px 12px;',
      'background:var(--bg3);border-radius:10px;margin-bottom:6px;cursor:pointer;',
      'border:1px solid ' + (selected?'var(--accent2)':'transparent') + ';transition:border-color .15s" ',
      'onclick="openAdminUserDetail(\'' + uid + '\')" ',
      'onmouseover="this.style.borderColor=\'var(--accent2)\'" ',
      'onmouseout="this.style.borderColor=\'' + (selected?'var(--accent2)':'transparent') + '\'">',
      '<input type="checkbox" aria-label="انتخاب ' + uname + '" ' + (selected?'checked ':'') +
        'onclick="event.stopPropagation();_adminToggleUserSelection(\'' + uid + '\',this.checked)" ' +
        'style="width:18px;height:18px;accent-color:var(--accent);flex-shrink:0">',
      '<div style="width:36px;height:36px;border-radius:50%;',
        'background:linear-gradient(135deg,var(--accent),var(--accent2));',
        'display:flex;align-items:center;justify-content:center;',
        'color:white;font-weight:700;font-size:14px;flex-shrink:0">',
        initLetter + '</div>',
      '<div style="flex:1;min-width:0">',
        '<div style="font-size:13px;font-weight:600;margin-bottom:2px">' + escapeHtml(u.name||'—') + '</div>',
        '<div style="font-size:11px;color:var(--text3);direction:ltr;text-align:right">' + escapeHtml(u.email||'—') + '</div>',
        '<div style="font-size:11px;color:var(--text3);margin-top:2px">' + roleLabel + ' · ' + fa(u.client_count||0) + ' مشتری</div>',
      '</div>',
      '<div style="display:flex;align-items:center;gap:6px">',
        '<span style="font-size:10px;padding:2px 8px;border-radius:10px;background:' + bgColor + ';color:' + txtColor + '">' + statusLabel + '</span>',
        (!_adminIsProtectedUser(u) ? '<button type="button" class="btn btn-ghost btn-sm" style="min-height:34px;padding:5px 10px" onclick="event.stopPropagation();_adminImpersonate(\'' + uid + '\',this.dataset.uname)" data-uname="' + uname + '" aria-label="ورود به حساب ' + uname + '">🔑 ورود</button>' : ''),
        '<div class="row-menu">' +
          '<button class="row-menu-btn" aria-label="عملیات کاربر" onclick="toggleRowMenu(event,\'' + menuId + '\')">⋮</button>' +
          '<div class="row-menu-panel" id="' + menuId + '" style="min-width:210px">' +
            '<div class="row-menu-item" onclick="event.stopPropagation();openAdminUserDetail(\'' + uid + '\')">👤 مشاهده پروفایل</div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminEditUser(\'' + uid + '\')">✏️ ویرایش</div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminChangeRole(\'' + uid + '\')">🛡 تغییر نقش</div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminChangePlan([\'' + uid + '\'])">💎 تغییر پلن</div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminRenewUser(\'' + uid + '\')">🔄 تمدید اشتراک</div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminShowPayments(\'' + uid + '\')">💳 مشاهده پرداخت‌ها</div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminShowActivity(\'' + uid + '\')">📊 مشاهده فعالیت‌ها</div>' +
            '<div class="row-menu-divider"></div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminBackupUser(\'' + uid + '\',this.dataset.uname)" data-uname="' + uname + '">💾 دریافت پشتیبان</div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminImportUserBackup(\'' + uid + '\',this.dataset.uname)" data-uname="' + uname + '">📂 وارد کردن پشتیبان</div>' +
            '<div class="row-menu-divider"></div>' +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminResetPassword(\'' + uid + '\')">🔐 بازنشانی رمز</div>' +
            (!_adminIsProtectedUser(u) ? '<div class="row-menu-item" onclick="event.stopPropagation();_adminImpersonate(\'' + uid + '\',this.dataset.uname)" data-uname="' + uname + '">🔑 ورود به‌جای کاربر</div>' : '') +
            '<div class="row-menu-item" onclick="event.stopPropagation();_adminToggleStatus(\'' + uid + '\',' + (isActive?0:1) + ')">' + (isActive?'🚫 مسدودکردن':'✅ فعال‌سازی') + '</div>' +
            (!_adminIsProtectedUser(u) ? '<div class="row-menu-divider"></div><div class="row-menu-item danger" onclick="event.stopPropagation();_adminDeleteUser(\'' + uid + '\',this.dataset.uname)" data-uname="' + uname + '">🗑 حذف</div>' : '') +
          '</div>' +
        '</div>',
      '</div></div>'
    ].join('');
  }).join('');
}
const _ADMIN_USERS_PAGE_SIZE = 20;
function _adminGetFilteredUsers() {
  const users = window._adminAllUsers || [];
  const q = String(window._adminUserFilter || '').trim();
  let filtered = q.trim()
    ? users.filter(u => (u.name||'').toLowerCase().includes(q.toLowerCase()) || (u.email||'').toLowerCase().includes(q.toLowerCase()))
    : users;
  const mode=window._adminStatFilter||'all';
  const now=new Date(),monthStart=new Date(now.getFullYear(),now.getMonth(),1);
  const localDate=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
  if(mode==='activeToday')filtered=filtered.filter(u=>u.is_active&&u.updated_at&&localDate(u.updated_at)===localDate(now));
  if(mode==='new')filtered=filtered.filter(u=>u.created_at&&new Date(u.created_at)>=monthStart);
  if(mode==='inactive')filtered=filtered.filter(u=>!u.is_active);
  if(mode==='paid')filtered=filtered.filter(u=>!['','free','رایگان'].includes(String(u.plan||'free').toLowerCase()));
  return filtered;
}
function _adminPaginationHtml(total) {
  const pages=Math.max(1,Math.ceil(total/_ADMIN_USERS_PAGE_SIZE));
  const page=Math.min(Math.max(1,Number(window._adminUsersPage)||1),pages);
  window._adminUsersPage=page;
  if(total<=_ADMIN_USERS_PAGE_SIZE)return total
    ? `<div style="text-align:center;margin-top:12px;font-size:11px;color:var(--text3)">نمایش ${fa(total)} کاربر</div>` : '';
  const start=(page-1)*_ADMIN_USERS_PAGE_SIZE+1;
  const end=Math.min(total,page*_ADMIN_USERS_PAGE_SIZE);
  return `<div style="display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;margin-top:14px;padding-top:12px;border-top:1px solid var(--border)">
    <button class="btn btn-ghost btn-sm" onclick="_adminGoToUsersPage(${page-1})" ${page<=1?'disabled':''}>→ قبلی</button>
    <span style="font-size:11.5px;color:var(--text2);min-width:170px;text-align:center">
      صفحه ${fa(page)} از ${fa(pages)} · کاربران ${fa(start)} تا ${fa(end)} از ${fa(total)}
    </span>
    <button class="btn btn-ghost btn-sm" onclick="_adminGoToUsersPage(${page+1})" ${page>=pages?'disabled':''}>بعدی ←</button>
  </div>`;
}
function _adminRenderUsersPage() {
  const filtered=_adminGetFilteredUsers();
  const pages=Math.max(1,Math.ceil(filtered.length/_ADMIN_USERS_PAGE_SIZE));
  window._adminUsersPage=Math.min(Math.max(1,Number(window._adminUsersPage)||1),pages);
  const start=(window._adminUsersPage-1)*_ADMIN_USERS_PAGE_SIZE;
  const pageUsers=filtered.slice(start,start+_ADMIN_USERS_PAGE_SIZE);
  const el = document.getElementById('admin-users-list');
  if (el) el.innerHTML = _adminRenderUserList(pageUsers);
  const bulk = document.getElementById('admin-bulk-actions');
  if (bulk) bulk.innerHTML = _adminBulkActionsHtml(pageUsers);
  const pagination=document.getElementById('admin-users-pagination');
  if(pagination)pagination.innerHTML=_adminPaginationHtml(filtered.length);
}
function _adminFilterUsers(q,resetPage=true) {
  window._adminUserFilter = q || '';
  if(resetPage)window._adminUsersPage=1;
  _adminRenderUsersPage();
}
function _adminGoToUsersPage(page) {
  window._adminUsersPage=page;
  _adminRenderUsersPage();
  document.getElementById('admin-user-search')?.scrollIntoView({behavior:'smooth',block:'center'});
}
function _adminApplyStatFilter(type){
  if(type==='revenue'){
    const d=window._adminDashboard||{};
    return openModal('💰 درآمد ماه',`<div class="detail-section"><div class="detail-row"><span class="detail-key">ماه جاری</span><span class="detail-val">${fa(d.monthlyRevenue||0)} تومان</span></div><div class="detail-row"><span class="detail-key">ماه قبل</span><span class="detail-val">${fa(d.previousMonthlyRevenue||0)} تومان</span></div></div>`,[{label:'بستن',cls:'btn-ghost',action:'closeModal()'}]);
  }
  window._adminStatFilter=type||'all';
  _adminFilterUsers(window._adminUserFilter||'');
  document.getElementById('admin-user-search')?.scrollIntoView({behavior:'smooth',block:'center'});
}

