async function _adminImpersonate(userId, userName) {
  // جلوگیری از ورود به حساب ادمین توسط هر کس
  if (!_auth.isAdmin()) {
    showToast('فقط مدیر کل می‌تواند وارد حساب‌های دیگر شود', 'error');
    return;
  }
  // جلوگیری از ورود به حساب ادمین اصلی
  if (userId === _sbUser?.id) {
    showToast('شما در حال حاضر در حساب خودتان هستید', 'error');
    return;
  }
  try {
    const res = await _apiFetch('/api/admin/users/' + userId);
    if (!res.ok) { showToast('خطا','error'); return; }
    const { user } = await res.json();
    if (_adminIsProtectedUser(user)) {
      showToast('امکان ورود به حساب مدیر اصلی وجود ندارد', 'error');
      return;
    }

    if (!confirm('وارد حساب «' + userName + '» می‌شوید؟ برای بازگشت از نوار بنفش بالای صفحه استفاده کنید.')) return;

    // ذخیره کامل وضعیت ادمین
    const adminSession = localStorage.getItem('tp_session');
    const adminUser = { ..._sbUser };
    const adminDBKey = window._activeDBKey || _userDBKey();
    // The primary database may already be retired from localStorage after the
    // IndexedDB migration. Keep a lightweight in-memory/session signature so
    // target data can still be checked for accidental admin-data contamination.
    const adminDataSignature = _dataSignatureForIsolation(_db);
    const adminIsolationProbe = _buildDataIsolationProbe(_db);
    localStorage.setItem('tp_admin_backup_session', adminSession);
    localStorage.setItem('tp_admin_backup_user', JSON.stringify(adminUser));
    localStorage.setItem('tp_admin_backup_dbkey', adminDBKey);

    // تنظیم user به کاربر هدف
    _sbUser = { ...user };

    // تنظیم DB key برای کاربر هدف
    const targetKey = 'tp_impersonate_' + userId;
    window._activeDBKey = targetKey;
    window._impersonating = { userId, userName, adminSession, adminUser, adminDBKey, adminDataSignature, adminIsolationProbe };
    window._impersonateServerBlocked = false;
    // ذخیره وضعیت impersonate در localStorage تا با رفرش صفحه از بین نره
    try {
      localStorage.setItem('tp_impersonating_state', JSON.stringify({ userId, userName, adminDBKey, adminDataSignature, adminIsolationProbe }));
      localStorage.setItem('tp_impersonating_user', JSON.stringify(user));
    } catch(e) {}

    // block کردن sync تا داده کاربر هدف load بشه
    window._impersonateLoadPending = true;

    // stop all intervals
    clearInterval(window._syncInterval);
    clearInterval(window._pollInterval);
    clearTimeout(window._serverSyncTimer);

    // فوری _db رو خالی کن
    _db = _freshData();
    _migrate(_db);

    // لود داده کاربر از سرور
    let loaded = false;
    try {
      const dataRes = await _apiFetch('/api/data/' + userId);
      if (dataRes.ok) {
        const ct = dataRes.headers.get('content-type') || '';
        if (ct.includes('application/json')) {
          const json = await dataRes.json();
          if (json.data && Object.keys(json.data).length > 0) {
            if (_looksLikeAdminDataDuringImpersonation(json.data, adminDBKey)) {
              const cleanup = _removeAdminCopiesFromTargetData(json.data, window._impersonating?.adminIsolationProbe);
              console.warn('[Impersonate] removed copied admin records from target account:', cleanup.removed);
              _db = cleanup.data;
              _migrate(_db);
              _cacheImpersonatedData(targetKey, _db);
              window._impersonateServerBlocked = false;
              window._impersonateCleanupPending = cleanup.removed;
              loaded = true;
            } else {
              _db = json.data;
              _migrate(_db);
              _cacheImpersonatedData(targetKey, _db);
              window._impersonateServerBlocked = false;
              loaded = true;
            }
          }
        }
      }
    } catch(e) { console.warn('[Impersonate] fetch error:', e.message); }

    // اگه سرور داده نداد، DB خالی (نه داده ادمین)
    if (!loaded) {
      _db = _freshData();
      _migrate(_db);
      _purgeLegacyImpersonationCaches();
      window._impersonateServerBlocked = true;
      showToast('داده حساب مقصد از سرور دریافت نشد؛ برای جلوگیری از بازنویسی، همگام‌سازی مسدود شد', 'error');
    }

    // حالا sync مجاز است
    window._impersonateLoadPending = false;
    if (window._impersonateCleanupPending > 0) {
      const removed = window._impersonateCleanupPending;
      window._impersonateCleanupPending = 0;
      _forceNextServerSync();
      setTimeout(() => _syncToServer(), 50);
      showToast(`${fa(removed)} رکورد کپی‌شده از حساب مدیر پاک‌سازی شد`, 'success');
    }

    // آپدیت META از _db کاربر هدف
    try {
      META = await window.api.meta.get();
      PKG_TYPES = await window.api.packageTypes.getAll();
      FAMILIES = await window.api.families.getAll();
      applyMetaToUI();
    } catch(e) { console.warn('META reset failed:', e.message); }

    // راه‌اندازی intervaloadPending = false;

    // راه‌اندازی interval های جدید
    _startServerSyncLoops();

    // نمایش نوار بازگشت
    _showImpersonateBar(userName);
    _updateAuthUI();

    showToast('وارد حساب «' + userName + '» شدید', 'success');
    currentPage = 'students';
    allStudents = [];
    renderPage();
  } catch(e) { showToast('خطا: ' + e.message,'error'); }
}

function _showImpersonateBar(name) {
  const bar = document.getElementById('impersonate-bar');
  const nameEl = document.getElementById('impersonate-name');
  if (bar) { bar.style.display = 'flex'; }
  if (nameEl) nameEl.textContent = name;
}

function _hideImpersonateBar() {
  const bar = document.getElementById('impersonate-bar');
  if (bar) bar.style.display = 'none';
}

async function _adminReturnToAdmin() {
  // اگه بعد از رفرش هستیم، window._impersonating نال است — بازسازی از localStorage
  if (!window._impersonating) {
    try {
      const savedState = JSON.parse(localStorage.getItem('tp_impersonating_state') || 'null');
      if (savedState) {
        window._impersonating = {
          userId: savedState.userId,
          userName: savedState.userName,
          adminSession: localStorage.getItem('tp_admin_backup_session'),
          adminUser: JSON.parse(localStorage.getItem('tp_admin_backup_user') || 'null'),
          adminDBKey: savedState.adminDBKey || localStorage.getItem('tp_admin_backup_dbkey'),
          adminDataSignature: savedState.adminDataSignature || '',
          adminIsolationProbe: savedState.adminIsolationProbe || null,
        };
      }
    } catch(e) {}
  }
  if (!window._impersonating) return;
  try {
    const { adminSession, adminUser, adminDBKey, userId } = window._impersonating;

    // پاک کردن داده impersonation از localStorage
    const impKey = 'tp_impersonate_' + userId;
    localStorage.removeItem(impKey);
    void _idbDeleteDatabaseSnapshot(impKey).catch(() => {});
    localStorage.removeItem('tp_impersonating_state');
    localStorage.removeItem('tp_impersonating_user');

    // بازگردانی session ادمین
    if (adminSession) localStorage.setItem('tp_session', adminSession);

    // بازگردانی user ادمین
    _sbUser = adminUser || JSON.parse(localStorage.getItem('tp_admin_backup_user') || 'null');

    // بازگردانی DB key ادمین
    window._activeDBKey = adminDBKey || localStorage.getItem('tp_admin_backup_dbkey') || _userDBKey();

    // پاک کردن وضعیت impersonation
    window._impersonating = null;

    // stop intervals
    clearInterval(window._syncInterval);
    clearInterval(window._pollInterval);
    clearTimeout(window._serverSyncTimer);
    window._impersonateLoadPending = false;

    // بارگذاری نسخه تأییدشده ادمین از IndexedDB با fallback محلی
    await _loadPrimaryDatabase();

    // آپدیت META به حالت ادمین
    try {
      META = await window.api.meta.get();
      PKG_TYPES = await window.api.packageTypes.getAll();
      FAMILIES = await window.api.families.getAll();
      applyMetaToUI();
    } catch(e) {}

    _hideImpersonateBar();
    _updateAuthUI();
    currentPage = 'admin_panel';
    allStudents = [];
    renderPage();
    showToast('به حساب ادمین بازگشتید ✓', 'success');

    // راه‌اندازی interval های ادمین
    _startServerSyncLoops();
  } catch(e) {
    showToast('خطا در بازگشت: ' + e.message, 'error');
  }
}


// ── پین کردن حساب کاربری ──────────────────────────────────────────────────
function _adminPinAccount(userId, userName) {
  let pins = JSON.parse(localStorage.getItem('tp_pinned_accounts') || '[]');
  const exists = pins.find(p => p.id === userId);
  if (exists) {
    pins = pins.filter(p => p.id !== userId);
    showToast('پین برداشته شد', 'success');
  } else {
    pins.unshift({ id: userId, name: userName, pinned_at: Date.now() });
    if (pins.length > 5) pins = pins.slice(0, 5);
    showToast('حساب پین شد 📌', 'success');
  }
  localStorage.setItem('tp_pinned_accounts', JSON.stringify(pins));
  renderAdminPanel();
}

function _adminGetPinnedAccounts() {
  return JSON.parse(localStorage.getItem('tp_pinned_accounts') || '[]');
}


function _renderChargeRequests(reqs) {
  const el = document.getElementById('charge-reqs-list');
  if (!el) return;
  if (!reqs.length) { el.innerHTML = '<p style="font-size:12px;color:var(--text3)">درخواستی موجود نیست</p>'; return; }
  el.innerHTML = reqs.map(r => `
    <div style="padding:10px 12px;background:var(--bg3);border-radius:10px;margin-bottom:6px;border:1px solid ${r.status==='pending'?'var(--amber)':r.status==='approved'?'var(--green)':'var(--red)'}">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
        <span style="font-size:12px;direction:ltr">${escapeHtml(r.email)}</span>
        <span style="font-size:12px;font-weight:700;color:var(--accent2)">${fa(r.amount)} ت</span>
      </div>
      <div style="font-size:11px;color:var(--text3);margin-bottom:6px">${new Date(r.created_at*1000).toLocaleDateString('fa-IR')}</div>
      ${r.receipt_text?`<div style="font-size:11px;color:var(--text2);margin-bottom:6px">${escapeHtml(r.receipt_text)}</div>`:''}
      ${r.status==='pending'?`
        <div style="display:flex;gap:6px">
          <button class="btn btn-primary btn-sm" onclick="_approveCharge(${r.id},${r.user_id},${r.amount})">✓ تأیید</button>
          <button class="btn btn-danger btn-sm" onclick="_rejectCharge(${r.id})">✗ رد</button>
        </div>
      `:`<span style="font-size:11px;font-weight:600;color:${r.status==='approved'?'var(--green)':'var(--red)'}">${r.status==='approved'?'✓ تأیید شد':'✗ رد شد'}</span>`}
    </div>`).join('');
}

async function _approveCharge(reqId, userId, amount) {
  const res = await _apiFetch('/api/admin/charge-requests/'+reqId, {
    method: 'PUT',
    body: JSON.stringify({ status: 'approved', note: 'تأیید شد' })
  });
  if (res.ok) { showToast('شارژ تأیید شد ✓', 'success'); renderAdminPanel(); }
  else showToast('خطا', 'error');
}

async function _rejectCharge(reqId) {
  const note = prompt('دلیل رد (اختیاری):') || '';
  const res = await _apiFetch('/api/admin/charge-requests/'+reqId, {
    method: 'PUT',
    body: JSON.stringify({ status: 'rejected', note })
  });
  if (res.ok) { showToast('رد شد', 'error'); renderAdminPanel(); }
}

async function _saveAdminSettings() {
  const currentSettings=window._adminSettings||{};
  const settings = {
    daily_cost: parseInt(document.getElementById('admin-daily-cost')?.value || '1000'),
    card_number: document.getElementById('admin-card')?.value.trim() || '',
    tutorial_video_url: document.getElementById('admin-video-url')?.value.trim() || currentSettings.tutorial_video_url || '',
  };
  // ۱. ذخیره در localStorage
  localStorage.setItem('tp_admin_settings', JSON.stringify(settings));
  // ۲. ذخیره در _db (persistent با sync سرور)
  if (!_db.admin_settings) _db.admin_settings = {};
  _db.admin_settings = { ..._db.admin_settings, ...settings };
  // ۳. ذخیره _db در localStorage
  _save(true);
  // ۴. ذخیره روی سرور
  try {
    await _apiFetch('/api/admin/settings', { method: 'PUT', body: JSON.stringify(settings) });
  } catch(e) {}
  window._adminSettings={...currentSettings,...settings};
  showToast('تنظیمات ذخیره شد ✓', 'success');
}



function _adminEmailSuggest(q) {
  const suggestions = document.getElementById('email-suggestions');
  if (!suggestions) return;
  const users = window._adminAllUsers || [];
  if (!q || q.length < 2) { suggestions.style.display = 'none'; return; }
  const filtered = users.filter(u => (u.email||'').toLowerCase().includes(q.toLowerCase())).slice(0, 6);
  if (!filtered.length) { suggestions.style.display = 'none'; return; }
  suggestions.innerHTML = filtered.map(u =>
    '<div onclick="_adminSelectEmail(' + escapeAttr(u.email) + ',' + escapeAttr(u.id) + ')" ' +
    'style="padding:8px 12px;cursor:pointer;font-size:12px;direction:ltr;border-bottom:1px solid var(--border)" ' +
    'onmouseover="this.style.background=\'var(--bg3)\'" onmouseout="this.style.background=\'\'"> ' +
    '<span style="color:var(--accent2)">' + escapeHtml(u.email) + '</span>' +
    '<span style="color:var(--text3);font-size:11px;margin-right:8px"> — ' + escapeHtml(u.name||'') + '</span>' +
    '</div>'
  ).join('');
  suggestions.style.display = 'block';
}

function _adminSelectEmail(email, userId) {
  const inp = document.getElementById('charge-email');
  if (inp) inp.value = email;
  const suggestions = document.getElementById('email-suggestions');
  if (suggestions) suggestions.style.display = 'none';
  // نشون دادن اطلاعات کاربر
  const user = (window._adminAllUsers||[]).find(u => u.id === userId);
  const info = document.getElementById('charge-user-info');
  if (info && user) {
    info.style.display = 'block';
    info.innerHTML = '👤 ' + escapeHtml(user.name||'') + ' · ' + fa(user.client_count||0) + ' مشتری';
  }
}

async function _adminChargeWallet() {
  const email = document.getElementById('charge-email')?.value.trim();
  const amount = parseInt(document.getElementById('charge-amount')?.value || '0');
  if (!email || !amount || amount <= 0) { showToast('ایمیل و مبلغ را وارد کنید', 'error'); return; }

  // پیدا کردن کاربر
  const users = window._adminAllUsers || [];
  const targetUser = users.find(u => u.email === email);

  if (!targetUser) {
    showToast('کاربری با این ایمیل پیدا نشد', 'error');
    return;
  }

  try {
    // لود data کاربر از سرور
    const res = await _apiFetch('/api/data/' + targetUser.id);
    let userData = null;
    if (res.ok) {
      const ct = res.headers.get('content-type') || '';
      if (ct.includes('application/json')) {
        const json = await res.json();
        userData = json.data;
      }
    }

    if (!userData) userData = { _user_wallet: null };
    if (!userData._user_wallet) {
      userData._user_wallet = { balance: 0, daily_cost: 1000, transactions: [] };
    }

    userData._user_wallet.balance += amount;
    userData._user_wallet.transactions.unshift({
      id: Date.now(), type: 'charge', amount,
      desc: '💳 شارژ توسط مدیر', date: new Date().toISOString()
    });

    // ذخیره data کاربر روی سرور
    const saveRes = await _apiFetch('/api/data/' + targetUser.id, {
      method: 'PUT',
      body: JSON.stringify({ data: userData })
    });

    if (saveRes.ok) {
      showToast('کیف پول ' + (targetUser.name||email) + ' — ' + fa(amount) + ' تومان شارژ شد ✓', 'success');
      document.getElementById('charge-email').value = '';
      document.getElementById('charge-amount').value = '';
      const info = document.getElementById('charge-user-info');
      if (info) info.style.display = 'none';
      const suggestions = document.getElementById('email-suggestions');
      if (suggestions) suggestions.style.display = 'none';
    } else {
      showToast('خطا در ذخیره کیف پول', 'error');
    }
  } catch(e) {
    showToast('خطا: ' + e.message, 'error');
  }
}

