function _openChargeRequest() {
  openModal('💳 درخواست شارژ', `
    <p style="font-size:13px;color:var(--text2);margin-bottom:16px;line-height:1.7">
      مبلغ را به شماره کارت زیر واریز کن و فیش رو اینجا وارد کن:
    </p>
    <div class="form-group full">
      <label class="form-label">مبلغ (تومان)</label>
      <input class="form-input" id="cr-amount" type="number" placeholder="50000" min="10000" max="10000000">
    </div>
    <div class="form-group full">
      <label class="form-label">توضیح یا شماره پیگیری فیش</label>
      <textarea class="form-input" id="cr-receipt" rows="2" placeholder="مثلاً: واریز به مبلغ ۵۰,۰۰۰ تومان در تاریخ..."></textarea>
    </div>
  `, [
    {label:'ارسال درخواست', cls:'btn-primary', action:'_submitChargeRequest()'},
    {label:'انصراف', cls:'btn-ghost', action:'closeModal()'},
  ]);
}

async function _submitChargeRequest() {
  const amount = parseInt(document.getElementById('cr-amount')?.value || '0');
  const receipt = document.getElementById('cr-receipt')?.value.trim() || '';
  if (!amount || amount < 10000) { showToast('حداقل مبلغ ۱۰,۰۰۰ تومان است', 'error'); return; }
  if (amount > 10000000) { showToast('حداکثر مبلغ ۱۰٬۰۰۰٬۰۰۰ تومان است', 'error'); return; }
  const res = await _apiFetch('/api/wallet/charge-request', {
    method: 'POST',
    body: JSON.stringify({ amount, receipt_text: receipt })
  });
  if (res.ok) {
    closeModal();
    showToast('درخواست شارژ ثبت شد ✓ پس از تأیید مدیر حساب شارژ می‌شود', 'success');
  } else {
    const d = await res.json();
    showToast(d.error || 'خطا', 'error');
  }
}

// ── Web-specific additions ────────────────────────────────────────────────────
// Mobile sidebar
function _updateTopbarHeight(){const tb=document.querySelector('.topbar');if(tb){document.documentElement.style.setProperty('--_topbar-h',tb.offsetHeight+'px');}}
let _sidebarHintPlayed = false;
let _sidebarScrollFadeTimer = null;
function _updateSidebarScrollState() {
  const nav = document.getElementById('sidebar-nav') || document.querySelector('.sidebar-nav');
  const wrap = document.getElementById('sidebar-scroll') || document.querySelector('.sidebar-scroll');
  if (!nav || !wrap) return;
  const max = nav.scrollHeight - nav.clientHeight;
  const hasScroll = max > 2;
  wrap.classList.toggle('no-scrollbar', !hasScroll);
  wrap.classList.toggle('at-bottom', !hasScroll || nav.scrollTop >= max - 8);
  if (hasScroll) {
    const trackTop = 8;
    const trackPadding = 16;
    const trackHeight = Math.max(24, nav.clientHeight - trackPadding);
    const thumbHeight = Math.max(28, Math.round((nav.clientHeight / nav.scrollHeight) * trackHeight));
    const thumbTop = trackTop + Math.round((nav.scrollTop / max) * Math.max(0, trackHeight - thumbHeight));
    wrap.style.setProperty('--sidebar-thumb-height', thumbHeight + 'px');
    wrap.style.setProperty('--sidebar-thumb-top', thumbTop + 'px');
  }
}
function _bindSidebarScrollUX() {
  const nav = document.getElementById('sidebar-nav') || document.querySelector('.sidebar-nav');
  const wrap = document.getElementById('sidebar-scroll') || document.querySelector('.sidebar-scroll');
  if (!nav || nav.dataset.scrollUxReady) return;
  nav.dataset.scrollUxReady = '1';
  nav.addEventListener('scroll', () => {
    wrap && wrap.classList.add('is-scrolling');
    _updateSidebarScrollState();
    clearTimeout(_sidebarScrollFadeTimer);
    _sidebarScrollFadeTimer = setTimeout(() => wrap && wrap.classList.remove('is-scrolling'), 650);
  }, { passive: true });
}
function _playSidebarScrollHint() {
  if (_sidebarHintPlayed) return;
  _sidebarHintPlayed = true;
  const wrap = document.getElementById('sidebar-scroll') || document.querySelector('.sidebar-scroll');
  const nav = document.getElementById('sidebar-nav') || document.querySelector('.sidebar-nav');
  if (!wrap || !nav || nav.scrollHeight <= nav.clientHeight + 24) return;
  wrap.classList.remove('scroll-hint');
  void wrap.offsetWidth;
  wrap.classList.add('scroll-hint');
  setTimeout(() => wrap.classList.remove('scroll-hint'), 650);
}
function openSidebar(){
  _updateTopbarHeight();
  _bindSidebarScrollUX();
  document.getElementById('sidebar').classList.add('open');
  document.getElementById('sidebar-backdrop').classList.add('open');
  document.body.style.overflow='hidden';
  requestAnimationFrame(() => {
    _updateSidebarScrollState();
    setTimeout(_playSidebarScrollHint, 180);
  });
}
function closeSidebar(){document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebar-backdrop').classList.remove('open');document.body.style.overflow='';}
function toggleSidebar(){const sb=document.getElementById('sidebar');if(sb&&sb.classList.contains('open')){closeSidebar();}else{openSidebar();}}

/* ── Swipe-to-close: کشیدن انگشت روی سایدبار (در موبایل) برای بستن آن ── */
(function(){
  const sb = document.getElementById('sidebar');
  if(!sb) return;
  let sx = 0, sy = 0, tracking = false;
  sb.addEventListener('touchstart', function(e){
    if(!e.touches || !e.touches.length) return;
    sx = e.touches[0].clientX; sy = e.touches[0].clientY; tracking = true;
  }, {passive:true});
  sb.addEventListener('touchend', function(e){
    if(!tracking) return;
    tracking = false;
    const t = e.changedTouches && e.changedTouches[0];
    if(!t) return;
    const dx = t.clientX - sx, dy = t.clientY - sy;
    // سایدبار از سمت راست باز می‌شود، پس کشیدن به سمت راست (dx مثبت) آن را می‌بندد
    if(dx > 55 && Math.abs(dx) > Math.abs(dy) * 1.5){ closeSidebar(); }
  }, {passive:true});
})();
function bnNav(el){
  const page=el.dataset.page;if(!page)return;
  // بستن کیبورد iOS قبل از تغییر صفحه — جلوگیری از به‌هم‌ریختگی layout روی iOS Safari
  if (document.activeElement && document.activeElement !== document.body) {
    document.activeElement.blur();
  }
  document.querySelectorAll('.bn-item').forEach(x=>x.classList.remove('active'));
  el.classList.add('active');
  document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));
  currentPage=page;if(currentPage==='students'){_studentsTab='sessions';_keySessionsExpanded=false;}if(currentPage==='todolist')_todoActiveTab='mine';updatePageTitle();renderPage();
}

// Patch nav-items to close sidebar + sync bottom nav on mobile
document.querySelectorAll('.nav-item[data-page]').forEach(el=>{
  el.addEventListener('click',()=>{
    document.querySelectorAll('.bn-item').forEach(x=>x.classList.toggle('active',x.dataset.page===el.dataset.page));
    closeSidebar();
  });
});

// Global fallback: intercept any click on nav-item using event delegation on document
document.addEventListener('click', function(e) {
  const navEl = e.target.closest('a.nav-item[data-page]');
  if (!navEl) return;
  e.preventDefault();
  const page = navEl.dataset.page;
  if (!page) return;
  if (document.activeElement && document.activeElement !== document.body) {
    document.activeElement.blur();
  }
  document.querySelectorAll('.nav-item').forEach(x => x.classList.remove('active'));
  navEl.classList.add('active');
  currentPage = page;
  if (currentPage === 'students') { _studentsTab = 'sessions'; _keySessionsExpanded = false; }
  updatePageTitle();
  renderPage();
}, true); // capture phase

// بستن کیبورد iOS قبل از هر navigation (سایدبار، bottom-nav، دکمه‌های بازگشت)
// جلوگیری از باگ به‌هم‌ریختگی layout روی iOS Safari وقتی input فوکوس‌دار باز می‌مونه
document.addEventListener('click', function(e) {
  const target = e.target.closest('[data-page], .bn-item, [onclick*="renderPage()"], [onclick*="currentPage="]');
  if (!target) return;
  if (document.activeElement && document.activeElement !== document.body &&
      document.activeElement !== target && !target.contains(document.activeElement)) {
    document.activeElement.blur();
  }
}, true); // capture phase — قبل از سایر handler ها اجرا می‌شه

