function _gcalCalendarSelectHtml() {
  const calendars = _db._gcal_calendars || [];
  const selected = _gcal.calendarId();
  const rows = calendars.length ? calendars : [{id:selected,summary:_gcal.calendarName(),primary:selected==='primary',accessRole:''}];
  const options = rows.map(c => {
    const label = `${c.summary || c.id}${c.primary ? ' — اصلی' : ''}${c.accessRole==='writer' ? ' — قابل ویرایش' : ''}`;
    return `<option value="${escapeHtml(c.id)}" ${c.id===selected?'selected':''}>${escapeHtml(label)}</option>`;
  }).join('');
  return `
    <div class="form-group full" style="margin-top:10px;max-width:520px">
      <label>تقویم مقصد برای ثبت و وارد کردن</label>
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
        <select class="form-input" id="gcal-calendar-select" style="flex:1;min-width:220px" onchange="gcalSelectCalendarUI(this.value)">
          ${options}
        </select>
        <button class="btn btn-ghost" onclick="gcalRefreshCalendarsUI()">↻ بروزرسانی لیست</button>
      </div>
    </div>`;
}

