// ── PWA Install Prompt ─────────────────────────────────────────────────────
let _deferredInstallPrompt = null;
const PWA_INSTALLED_KEY = 'tp_pwa_installed';

function _isPWAStandalone() {
  return window.matchMedia('(display-mode: standalone)').matches ||
    window.matchMedia('(display-mode: fullscreen)').matches ||
    navigator.standalone === true;
}
function _markPWAInstalled() {
  try { localStorage.setItem(PWA_INSTALLED_KEY, '1'); } catch(e) {}
}
async function _isPWAInstalled() {
  if (_isPWAStandalone()) {
    _markPWAInstalled();
    return true;
  }
  // Chrome/Edge can detect an installed copy even when this page is opened in a browser tab.
  if (typeof navigator.getInstalledRelatedApps === 'function') {
    try {
      const relatedApps = await navigator.getInstalledRelatedApps();
      if (relatedApps.some(app => app.platform === 'webapp')) {
        _markPWAInstalled();
        return true;
      }
    } catch(e) {}
  }
  // localStorage alone is not proof: the app may have been removed later.
  return false;
}
if (_isPWAStandalone()) _markPWAInstalled();

window.addEventListener('beforeinstallprompt', e => {
  e.preventDefault();
  _deferredInstallPrompt = e;
  setTimeout(_showInstallBanner, 700);
});
window.addEventListener('appinstalled', () => {
  _deferredInstallPrompt = null;
  _markPWAInstalled();
  _hideInstallBanner();
  showToast('✅ TeamPulse با موفقیت نصب شد!', 'success');
});
// iOS and Firefox don't emit beforeinstallprompt, so only those manual-install
// browsers need a delayed fallback. Install-capable Chromium browsers wait for
// beforeinstallprompt; an installed app therefore never receives a false banner.
setTimeout(() => {
  const ua = navigator.userAgent || '';
  const isIOS = /iphone|ipad|ipod/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const isFirefoxAndroid = /android/i.test(ua) && /firefox/i.test(ua);
  if (isIOS || isFirefoxAndroid) _showInstallBanner();
}, 2800);

async function _showInstallBanner() {
  if (await _isPWAInstalled() || document.getElementById('pwa-install-banner')) return;
  try { if (sessionStorage.getItem('tp_install_hidden_session') === '1') return; } catch(e) {}

  const ua = navigator.userAgent;
  const isIOS = /iphone|ipad|ipod/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const isAndroid = /android/i.test(ua);
  const isFirefoxAndroid = isAndroid && /firefox/i.test(ua);
  const isSafari = isIOS && /safari/i.test(ua) && !/crios|fxios|edgios|opios/i.test(ua);
  const banner = document.createElement('div');
  banner.id = 'pwa-install-banner';
  banner.style.cssText = 'position:fixed;bottom:0;right:0;left:0;z-index:9998;background:linear-gradient(135deg,#1e2130,#2a2d45);border-top:1px solid rgba(124,106,247,.3);padding:16px max(16px,env(safe-area-inset-right)) calc(16px + env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left));display:flex;flex-direction:column;gap:12px;box-shadow:0 -8px 32px rgba(0,0,0,.4);animation:slideUpBanner .3s ease';

  const iosInstructions = isIOS && !isSafari
    ? `<div style="background:rgba(255,255,255,.06);border-radius:10px;padding:12px">
        <div style="font-size:12px;color:white;font-weight:700;margin-bottom:7px">📲 نصب روی آیفون و آیپد</div>
        <div style="font-size:11px;color:rgba(255,255,255,.72);line-height:1.9;margin-bottom:10px">برای نصب، این صفحه را با <strong style="color:#60a5fa">Safari</strong> باز کنید؛ سپس Share و <strong style="color:#60a5fa">Add to Home Screen</strong> را انتخاب کنید.</div>
        <button onclick="_copyPWAInstallUrl(this)" style="width:100%;padding:10px;border-radius:10px;background:rgba(96,165,250,.2);color:#60a5fa;border:1px solid rgba(96,165,250,.3);font-family:var(--font);font-weight:700">📋 کپی لینک برای Safari</button>
      </div>`
    : isIOS
      ? `<div style="background:rgba(255,255,255,.06);border-radius:10px;padding:12px">
          <div style="font-size:12px;color:white;font-weight:700;margin-bottom:7px">📲 نصب با Safari</div>
          <div style="font-size:11px;color:rgba(255,255,255,.72);line-height:2">۱. روی دکمه <strong style="color:white">Share</strong> بزنید.<br>۲. گزینه <strong style="color:#60a5fa">Add to Home Screen</strong> را انتخاب کنید.<br>۳. در پایان روی <strong style="color:white">Add</strong> بزنید.</div>
        </div>`
      : '';

  banner.innerHTML = `
    <style>@keyframes slideUpBanner{from{transform:translateY(100%)}to{transform:translateY(0)}}</style>
    <div style="display:flex;align-items:center;gap:12px">
      <img src="/logo.png" alt="" style="width:46px;height:46px;border-radius:12px;flex-shrink:0;mix-blend-mode:screen">
      <div style="flex:1;min-width:0"><div style="color:white;font-weight:800;font-size:14px">${isFirefoxAndroid?'TeamPulse را به صفحه اصلی اضافه کنید':'TeamPulse را نصب کنید'}</div><div style="color:rgba(255,255,255,.65);font-size:12px;margin-top:2px">${isIOS?'دسترسی سریع از صفحه اصلی':(isFirefoxAndroid?'دسترسی سریع از آیکن صفحه اصلی':'اجرای سریع‌تر و تجربه‌ای شبیه اپلیکیشن')}</div></div>
      <button class="x-close-sm x-close-invert" onclick="_hideInstallBanner(true)" aria-label="بعداً" style="font-size:16px">×</button>
    </div>
    ${iosInstructions}
    ${!isIOS ? `<div style="display:flex;gap:8px">
      <button onclick="_installPWA()" style="flex:1;padding:11px;border-radius:10px;background:var(--accent);color:white;border:none;font-family:var(--font);font-size:14px;font-weight:800">📲 ${isFirefoxAndroid?'راهنمای افزودن':(isAndroid?'نصب برنامه':'Install TeamPulse')}</button>
      <button onclick="_hideInstallBanner(true)" style="padding:11px 16px;border-radius:10px;background:rgba(255,255,255,.1);color:white;border:none;font-family:var(--font);font-size:13px">بعداً</button>
    </div>` : `<button onclick="_hideInstallBanner(true)" style="width:100%;padding:10px;border-radius:10px;background:rgba(255,255,255,.1);color:white;border:none;font-family:var(--font);font-size:13px">متوجه شدم</button>`}
  `;
  document.body.appendChild(banner);
}

function _hideInstallBanner(dismiss) {
  const banner = document.getElementById('pwa-install-banner');
  if (banner) {
    banner.style.transition = 'transform .3s ease';
    banner.style.transform = 'translateY(100%)';
    setTimeout(() => banner.remove(), 300);
  }
  if (dismiss) {
    try { sessionStorage.setItem('tp_install_hidden_session', '1'); } catch(e) {}
  }
}

async function _installPWA() {
  // در بعضی مرورگرهای اندروید رویداد نصب کمی بعد از آماده‌شدن SW صادر می‌شود.
  if (!_deferredInstallPrompt && 'serviceWorker' in navigator) {
    try {
      await navigator.serviceWorker.ready;
      await new Promise(resolve => setTimeout(resolve, 700));
    } catch(e) {}
  }
  if (!_deferredInstallPrompt) {
    _showAndroidInstallHelp();
    return;
  }
  _deferredInstallPrompt.prompt();
  const { outcome } = await _deferredInstallPrompt.userChoice;
  _deferredInstallPrompt = null;
  if (outcome === 'accepted') {
    _hideInstallBanner(false);
    // appinstalled is the authoritative success signal and shows the success toast.
    showToast('نصب TeamPulse در حال تکمیل است…', 'info');
  } else {
    showToast('هر زمان آماده بودید، دوباره روی دکمه نصب بزنید', 'info');
  }
}

function _showAndroidInstallHelp() {
  const ua = navigator.userAgent || '';
  const samsung = /SamsungBrowser/i.test(ua);
  const firefox = /Firefox|FxiOS/i.test(ua);
  const browserName = samsung ? 'Samsung Internet' : (firefox ? 'Firefox' : 'مرورگر');
  const steps = samsung
    ? '۱. روی منوی <b>سه‌خط یا سه‌نقطه</b> مرورگر بزنید.<br>۲. گزینه <b>Add page to / افزودن صفحه به</b> را انتخاب کنید.<br>۳. <b>Home screen / صفحه اصلی</b> را بزنید.<br>۴. در پایان <b>Add / افزودن</b> را تأیید کنید.'
    : firefox
      ? '۱. منوی سه‌نقطه Firefox را باز کنید.<br>۲. گزینه <b>Install / نصب</b> را انتخاب کنید.<br>۳. در پنجره <b>Add to Home screen</b>، گزینه <b>Add automatically / افزودن خودکار</b> را بزنید.<br>۴. آیکن TeamPulse روی صفحه اصلی اندروید ایجاد می‌شود.'
      : '۱. منوی سه‌نقطه مرورگر را باز کنید.<br>۲. گزینه <b>Install app / نصب برنامه</b> یا <b>Add to Home screen / افزودن به صفحه اصلی</b> را انتخاب کنید.<br>۳. نصب را تأیید کنید.';
  openModal('📲 نصب TeamPulse روی اندروید', `
    <div class="detail-section" style="line-height:2">
      <div style="font-size:13px;font-weight:800;margin-bottom:8px">روش نصب در ${browserName}</div>
      <div style="font-size:12px;color:var(--text2)">${steps}</div>
    </div>
    ${(samsung || firefox) ? `<div style="font-size:11px;color:var(--text3);line-height:1.8">${firefox?'توجه: Firefox ممکن است TeamPulse را فقط روی صفحه اصلی اضافه کند و آن را در فهرست برنامه‌های نصب‌شده نشان ندهد. برای نصب کامل و نمایش در فهرست Apps، لینک را در Google Chrome باز کنید و «نصب برنامه» را بزنید.':'اگر گزینه «افزودن به صفحه اصلی» نمایش داده نشد، همین آدرس را در Google Chrome باز کنید و از منوی سه‌نقطه «نصب برنامه» را بزنید.'}</div>` : ''}
  `,[
    {label:'متوجه شدم',cls:'btn-primary',action:'closeModal()'},
    {label:'📋 کپی لینک نصب',cls:'btn-ghost',action:'_copyPWAInstallUrl(this)'},
  ]);
}

async function _copyPWAInstallUrl(btn) {
  const url = 'https://teampulse.ir/app';
  try {
    await navigator.clipboard.writeText(url);
    if (btn) {
      const old = btn.textContent;
      btn.textContent = '✅ لینک کپی شد';
      setTimeout(() => { if (btn) btn.textContent = old; }, 2000);
    }
  } catch(e) {
    window.prompt('این لینک را کپی و در Safari باز کنید:', url);
  }
}

// Register Service Worker
const TP_SERVICE_WORKER_URL = '/sw.js?v=team-pulse-static-v83';
let _tpSwRefreshing = false;
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (_tpSwRefreshing) return;
    _tpSwRefreshing = true;
    window.location.reload();
  });
  navigator.serviceWorker.register(TP_SERVICE_WORKER_URL)
    .then(reg => {
      reg.update().catch(() => {});
      if (reg.waiting) reg.waiting.postMessage({ type: 'SKIP_WAITING' });
      reg.addEventListener('updatefound', () => {
        const worker = reg.installing;
        if (!worker) return;
        worker.addEventListener('statechange', () => {
          if (worker.state === 'installed' && navigator.serviceWorker.controller) {
            worker.postMessage({ type: 'SKIP_WAITING' });
          }
        });
      });
    })
    .catch(() => {});
}


// ── محاسبه‌ی یکپارچه‌ی ارتفاع واقعی Viewport (iOS Safari / Android Chrome / PWA) ──
// این تابع تنها منبع حقیقت برای ارتفاع واقعی قابل‌مشاهده در کل اپ است.
// window.innerHeight روی iOS Safari هنگام نمایش/مخفی‌شدن نوار آدرس یا باز شدن
// کیبورد به‌درستی/به‌موقع به‌روزرسانی نمی‌شود؛ visualViewport.height دقیق‌تر و لحظه‌ای است.
window._mobileKeyboardOpen = false;
let _vvBaseHeight = window.visualViewport ? window.visualViewport.height : window.innerHeight;

function _getRealViewportHeight() {
  return window.visualViewport ? window.visualViewport.height : window.innerHeight;
}

function _setRealAppHeight() {
  const vv = window.visualViewport || null;
  const layoutH = window.innerHeight || document.documentElement.clientHeight || _getRealViewportHeight();
  const h = vv ? vv.height : layoutH;
  const vvOffsetTop = vv ? (vv.offsetTop || 0) : 0;
  const vvBottomGap = vv ? Math.max(0, Math.round(layoutH - (vv.height + vvOffsetTop))) : 0;
  document.documentElement.style.setProperty('--app-vh', h + 'px');
  document.documentElement.style.setProperty('--modal-vh', h + 'px');
  document.documentElement.style.setProperty('--vv-height', h + 'px');
  document.documentElement.style.setProperty('--layout-vh', layoutH + 'px');
  document.documentElement.style.setProperty('--vv-offset-top', Math.round(vvOffsetTop) + 'px');
  document.documentElement.style.setProperty('--vv-bottom-gap', vvBottomGap + 'px');

  // تشخیص کیبورد مجازی: اگه ارتفاع بیش از ۱۵۰px نسبت به مقدار پایه کم شده باشه یعنی کیبورد بازه
  const keyboardWasOpen = window._mobileKeyboardOpen;
  window._mobileKeyboardOpen = (h < _vvBaseHeight - 150) || vvBottomGap > 150;
  const hasOpenModal = !!document.querySelector('.modal-overlay.open');
  document.body.classList.toggle('modal-keyboard-open', !!(window._mobileKeyboardOpen && hasOpenModal));

  // ── حفظ موقعیت اسکرول modal-body هنگام باز/بسته‌شدن کیبورد ──
  // وقتی کیبورد باز می‌شود یا بسته می‌شود، scrollTop modal-body را ذخیره و بازیابی می‌کنیم
  // تا هیچ پرشی در محتوا اتفاق نیفتد.
  if (hasOpenModal && keyboardWasOpen !== window._mobileKeyboardOpen) {
    const modalBody = document.querySelector('.modal-overlay.open .modal-body');
    if (modalBody) {
      if (window._mobileKeyboardOpen) {
        // کیبورد باز شد — scrollTop فعلی را ذخیره کن
        modalBody._savedScrollTop = modalBody.scrollTop;
      } else {
        // کیبورد بسته شد — scrollTop ذخیره‌شده را بازگردان
        requestAnimationFrame(() => {
          if (modalBody._savedScrollTop != null) {
            modalBody.scrollTop = modalBody._savedScrollTop;
          }
        });
      }
    }
  }
}
_setRealAppHeight();

// پوشش کامل تغییرات ارتفاع در iOS Safari، Android Chrome و PWA
window.addEventListener('resize', _setRealAppHeight);
window.addEventListener('orientationchange', () => {
  // بعد از چرخش صفحه، iOS با کمی تأخیر ارتفاع نهایی رو گزارش می‌کنه
  setTimeout(() => {
    _vvBaseHeight = _getRealViewportHeight();
    _setRealAppHeight();
  }, 200);
});
if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', _setRealAppHeight);
  window.visualViewport.addEventListener('scroll', _setRealAppHeight);
}

let _modalScrollY = 0;
let _modalScrollLocked = false;

function _lockModalPageScroll() {
  _setRealAppHeight();
  if (_modalScrollLocked) return;
  _modalScrollY = window.scrollY || document.documentElement.scrollTop || 0;
  document.documentElement.style.setProperty('--modal-scroll-y', _modalScrollY + 'px');
  document.body.classList.add('modal-open');
  _modalScrollLocked = true;
}

function _unlockModalPageScroll(force = false) {
  if (!force && document.querySelector('.modal-overlay.open')) return;
  if (!_modalScrollLocked) {
    document.body.classList.remove('modal-open', 'modal-keyboard-open');
    return;
  }
  document.body.classList.remove('modal-open', 'modal-keyboard-open');
  document.documentElement.style.removeProperty('--modal-scroll-y');
  _modalScrollLocked = false;
  const y = _modalScrollY || 0;
  _modalScrollY = 0;
  requestAnimationFrame(() => {
    try { window.scrollTo(0, y); } catch(e) {}
    _setRealAppHeight();
  });
}

function _syncModalScrollLock() {
  const hasOpenModal = !!document.querySelector('.modal-overlay.open');
  if (hasOpenModal) _lockModalPageScroll();
  else _unlockModalPageScroll(true);
}

setTimeout(() => {
  const modalRoot = document.getElementById('modals') || document.body;
  if (!modalRoot || modalRoot._modalScrollObserverReady) return;
  modalRoot._modalScrollObserverReady = true;
  new MutationObserver(() => {
    _setRealAppHeight();
    _syncModalScrollLock();
  }).observe(modalRoot, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
  _syncModalScrollLock();
}, 0);

// ── سرچ جمع‌شونده در topbar روی موبایل (فقط آیکون ذره‌بین، با کلیک باز می‌شه) ──
document.addEventListener('click', function(e) {
  if (window.innerWidth > 768) return; // فقط روی موبایل
  const searchBox = e.target.closest('.topbar-actions .table-search');
  const clickedToggleIcon = !!e.target.closest('.search-toggle-icon');
  if (searchBox && searchBox.classList.contains('tb-search-open') && clickedToggleIcon) {
    searchBox.classList.remove('tb-search-open');
    searchBox.querySelector('input')?.blur();
    e.preventDefault();
    return;
  }
  if (searchBox && !searchBox.classList.contains('tb-search-open')) {
    // بستن سایر سرچ‌های باز
    document.querySelectorAll('.topbar-actions .table-search.tb-search-open').forEach(s => {
      if (s !== searchBox) s.classList.remove('tb-search-open');
    });
    searchBox.classList.add('tb-search-open');
    const input = searchBox.querySelector('input');
    if (input) setTimeout(() => input.focus(), 150);
    return;
  }
  // کلیک بیرون از سرچ باز → ببندش (فقط اگه خالی باشه)
  if (!searchBox) {
    document.querySelectorAll('.topbar-actions .table-search.tb-search-open').forEach(s => {
      const input = s.querySelector('input');
      if (!input || !input.value) s.classList.remove('tb-search-open');
    });
  }
});

// ── تشخیص تکمیلی کیبورد مجازی از طریق focus/blur روی فیلدهای ورودی ──────────
document.addEventListener('focusin', (e) => {
  const tag = e.target?.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA') {
    window._mobileKeyboardOpen = true;
  }
});
document.addEventListener('focusout', (e) => {
  const tag = e.target?.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA') {
    setTimeout(() => {
      if (document.activeElement?.tagName !== 'INPUT' && document.activeElement?.tagName !== 'TEXTAREA') {
        window._mobileKeyboardOpen = false;
      }
    }, 300);
  }
});

// ── نمایش/مخفی‌کردن رمز برای تمام فیلدهای فعلی و مودال‌های پویا ──────────
function _enhancePasswordVisibility(root=document) {
  const fields = root.querySelectorAll?.('input[type="password"]:not([data-password-visibility-ready])') || [];
  fields.forEach(input => {
    input.dataset.passwordVisibilityReady = '1';
    const parent = input.parentElement;
    if (!parent) return;

    let button = Array.from(parent.children).find(el =>
      el.tagName === 'BUTTON' && input.id && String(el.getAttribute('onclick') || '').includes(input.id)
    );
    if (button) {
      button.removeAttribute('onclick');
      button.classList.add('password-visibility-toggle');
    } else {
      const wrapper = document.createElement('div');
      wrapper.className = 'password-field-wrap';
      parent.insertBefore(wrapper, input);
      wrapper.appendChild(input);
      button = document.createElement('button');
      button.className = 'password-visibility-toggle';
      wrapper.appendChild(button);
    }

    button.type = 'button';
    button.textContent = '👁️';
    button.title = 'نمایش رمز عبور';
    button.setAttribute('aria-label', 'نمایش رمز عبور');
    button.setAttribute('aria-pressed', 'false');
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      const revealing = input.type === 'password';
      input.type = revealing ? 'text' : 'password';
      button.textContent = revealing ? '🙈' : '👁️';
      button.title = revealing ? 'مخفی‌کردن رمز عبور' : 'نمایش رمز عبور';
      button.setAttribute('aria-label', button.title);
      button.setAttribute('aria-pressed', revealing ? 'true' : 'false');
      input.focus({ preventScroll:true });
      try { input.setSelectionRange(input.value.length, input.value.length); } catch(e) {}
    });
  });
}

const _passwordVisibilityObserver = new MutationObserver(() => {
  clearTimeout(window._passwordVisibilityTimer);
  window._passwordVisibilityTimer = setTimeout(() => _enhancePasswordVisibility(document), 30);
});
function _initPasswordVisibility() {
  _enhancePasswordVisibility(document);
  _passwordVisibilityObserver.observe(document.body, { childList:true, subtree:true });
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _initPasswordVisibility, { once:true });
else _initPasswordVisibility();

// ── Responsive table → card conversion (mobile) ──────────────────────────
function _applyResponsiveTableLabels() {
  document.querySelectorAll('.table-card').forEach(card => {
    const table = card.querySelector('table');
    if (!table) return;
    const headerCells = table.querySelectorAll('thead th');
    if (!headerCells.length) return;
    const labels = Array.from(headerCells).map(th => th.textContent.trim());

    table.querySelectorAll('tbody tr').forEach(tr => {
      const cells = tr.querySelectorAll('td');
      // ردیف‌های empty-state با colspan رو دست نزن
      if (cells.length === 1 && cells[0].hasAttribute('colspan')) return;
      cells.forEach((td, i) => {
        if (labels[i] !== undefined && !td.hasAttribute('data-label')) {
          td.setAttribute('data-label', labels[i]);
        }
      });
    });
    card.classList.add('tbl-responsive');
  });
}

// اجرا بعد از هر بار رندر شدن محتوای صفحه
const _tableObserver = new MutationObserver(() => {
  clearTimeout(window._tblLabelTimer);
  window._tblLabelTimer = setTimeout(_applyResponsiveTableLabels, 60);
});
function _initResponsiveTableObserver() {
  const contentEl = document.getElementById('content');
  if (contentEl) _tableObserver.observe(contentEl, { childList: true, subtree: true });
  _applyResponsiveTableLabels();
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _initResponsiveTableObserver);
} else {
  _initResponsiveTableObserver();
}

function _startApp() {
  _initAuth().then(authed => {
    if (authed) {
      updateAccountDisplay();
    }
  });
}

// ── MagicBento effect for .stat-card (global, event-delegated) ──────────────
(function() {
  const isMobile = () => window.innerWidth <= 768;
  const PROXIMITY = 90;   // radius*0.5
  const FADE = 135;       // radius*0.75
  const RADIUS = 180;
  let particleTimers = new WeakMap();
  let particleNodes = new WeakMap();

  function spawnParticles(card) {
    if (isMobile()) return;
    if (particleNodes.has(card)) return; // already spawning
    const rect = card.getBoundingClientRect();
    const nodes = [];
    const count = 6;
    for (let i = 0; i < count; i++) {
      const timer = setTimeout(() => {
        if (!card.matches(':hover')) return;
        const p = document.createElement('div');
        p.className = 'sc-particle';
        const x = Math.random() * rect.width;
        const y = Math.random() * rect.height;
        p.style.left = x + 'px';
        p.style.top = y + 'px';
        p.style.opacity = '0';
        card.appendChild(p);
        nodes.push(p);
        requestAnimationFrame(() => {
          p.style.transition = 'opacity .3s ease, transform 2.5s ease-in-out';
          p.style.opacity = '1';
          const dx = (Math.random() - 0.5) * 60;
          const dy = (Math.random() - 0.5) * 60;
          p.style.transform = `translate(${dx}px,${dy}px)`;
        });
      }, i * 120);
    }
    particleNodes.set(card, nodes);
  }

  function clearParticles(card) {
    const nodes = particleNodes.get(card);
    if (nodes) {
      nodes.forEach(p => {
        p.style.transition = 'opacity .3s ease, transform .3s ease';
        p.style.opacity = '0';
        setTimeout(() => p.remove(), 300);
      });
      particleNodes.delete(card);
    }
  }

  document.addEventListener('mouseenter', e => {
    const card = e.target.closest && e.target.closest('.stat-card');
    if (!card || isMobile()) return;
    spawnParticles(card);
  }, true);

  document.addEventListener('mouseleave', e => {
    const card = e.target.closest && e.target.closest('.stat-card');
    if (!card) return;
    card.style.setProperty('--glow-intensity', '0');
    card.style.transform = '';
    clearParticles(card);
  }, true);

  document.addEventListener('mousemove', e => {
    if (isMobile()) return;
    const card = e.target.closest && e.target.closest('.stat-card');
    if (!card) return;
    const rect = card.getBoundingClientRect();
    const relX = ((e.clientX - rect.left) / rect.width) * 100;
    const relY = ((e.clientY - rect.top) / rect.height) * 100;
    card.style.setProperty('--glow-x', relX + '%');
    card.style.setProperty('--glow-y', relY + '%');

    const centerX = rect.width / 2, centerY = rect.height / 2;
    const x = e.clientX - rect.left, y = e.clientY - rect.top;
    const dist = Math.max(0, Math.hypot(x - centerX, y - centerY) - Math.max(rect.width, rect.height) / 2);
    let glow = 0;
    if (dist <= PROXIMITY) glow = 1;
    else if (dist <= FADE) glow = (FADE - dist) / (FADE - PROXIMITY);
    card.style.setProperty('--glow-intensity', glow.toString());

    // tilt (light) + magnetism
    const rotateX = ((y - centerY) / centerY) * -2;
    const rotateY = ((x - centerX) / centerX) * 2;
    const magnetX = (x - centerX) * 0.02;
    const magnetY = (y - centerY) * 0.02;
    card.style.transform = `perspective(600px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translate(${magnetX}px, ${magnetY}px)`;
  });

  document.addEventListener('click', e => {
    if (isMobile()) return;
    const card = e.target.closest && e.target.closest('.stat-card');
    if (!card) return;
    const rect = card.getBoundingClientRect();
    const x = e.clientX - rect.left, y = e.clientY - rect.top;
    const maxDist = Math.max(
      Math.hypot(x, y), Math.hypot(x - rect.width, y),
      Math.hypot(x, y - rect.height), Math.hypot(x - rect.width, y - rect.height)
    );
    const ripple = document.createElement('div');
    ripple.style.cssText = `
      position:absolute;width:${maxDist*2}px;height:${maxDist*2}px;border-radius:50%;
      background:radial-gradient(circle, rgba(124,106,247,.35) 0%, rgba(124,106,247,.15) 30%, transparent 70%);
      left:${x-maxDist}px;top:${y-maxDist}px;pointer-events:none;z-index:5;
      transform:scale(0);opacity:1;transition:transform .7s ease,opacity .7s ease;
    `;
    card.appendChild(ripple);
    requestAnimationFrame(() => { ripple.style.transform = 'scale(1)'; ripple.style.opacity = '0'; });
    setTimeout(() => ripple.remove(), 700);
  });
})();

