    deadline: readCalendarDateField('ach-deadline') || '',
    difficulty: document.getElementById('ach-difficulty')?.value || 'medium',
    status: 'done',
    progress: 100,
    milestones: [],
    notes: '',
    created_at: now,
    completed_at: now,
