async function saveEditHabit(id) {
  const h = (_db.habits||[]).find(x => x.id === id);
  if (!h) return;
  const title = document.getElementById('hab-title')?.value.trim();
  if (!title) { showToast('نام عادت را وارد کنید', 'error'); return; }
  const goalId = document.getElementById('hab-goal')?.value || '';
  const habitTime = document.getElementById('hab-time')?.value || '';
  const remindMin = parseInt(document.getElementById('hab-remind')?.value || '0');
  if (remindMin > 0 && !habitTime) {
    showToast('برای ارسال نوتیفیکیشن، زمان انجام عادت را مشخص کن', 'error');
    return;
  }
  if (remindMin > 0 && !(await _ensureReminderPushEnabled('hab-notif-status'))) return;
  Object.assign(h, {
    title,
    icon: document.getElementById('hab-icon')?.value || '🔥',
    color: document.getElementById('hab-color')?.value || '#fbbf24',
    time: habitTime,
    remind_min: remindMin,
    goal_id: goalId ? +goalId : null,
    desc: document.getElementById('hab-desc')?.value || '',
  });
  _save();
  if (remindMin > 0 && habitTime) _scheduleHabitNotification(id, title, habitTime, remindMin);
  closeModal(); showToast('ذخیره شد ✓', 'success');
  if (currentPage === 'habits') renderHabits();
}

function _requestHabitNotifPermission() {
  _ensureReminderPushEnabled('hab-notif-status');
}

function _scheduleHabitNotification(id, title, habitTime, remindMinutes) {
  if (typeof _isTeamGuest === 'function' && _isTeamGuest()) return;
  if (!('Notification' in window) || Notification.permission !== 'granted') return;
  if (!habitTime || remindMinutes <= 0) return;
  try {
    const [h, m] = habitTime.split(':').map(Number);
    if (isNaN(h) || isNaN(m)) return;
    const now = new Date();
    const today = _appTodayGregorianParts();
    const notifDate = _zonedWallTimeToLocalDate(today.year, today.month, today.day, h, m, 0);
    notifDate.setMinutes(notifDate.getMinutes() - remindMinutes);
    if (notifDate <= now) {
      const tomorrowJ = _addDays(..._todayJalali(), 1);
      const [gy, gm, gd] = jalaliToGregorian(tomorrowJ[0], tomorrowJ[1], tomorrowJ[2]);
      const nextDate = _zonedWallTimeToLocalDate(gy, gm, gd, h, m, 0);
      notifDate.setTime(nextDate.getTime() - remindMinutes * 60000);
    }
    const delay = notifDate.getTime() - now.getTime();
    if (delay > 0 && delay < 48 * 3600 * 1000) {
      setTimeout(() => {
        _notify('🔥 ' + title, {
          body: 'وقت انجام عادتته — TeamPulse',
          icon: '/favicon.png',
          tag: 'habit-' + id,
        });
      }, delay);
    }
  } catch(e) { console.warn('Habit notification schedule failed:', e); }
}

function deleteHabit(id) {
  if (!confirm('این عادت حذف شود؟ این کار قابل بازگشت نیست.')) return;
  _db.habits = (_db.habits||[]).filter(x => x.id !== id);
  _db.habit_logs = (_db.habit_logs||[]).filter(x => x.habit_id !== id);
  _save(); showToast('حذف شد', 'error');
  if (currentPage === 'habits') renderHabits();
}

function openHabitDetail(id) {
  _habitsInit();
  const h = _db.habits.find(x => x.id === id);
  if (!h) return;
  const fa = n => String(n).replace(/[0-9]/g, d => '۰۱۲۳۴۵۶۷۸۹'[+d]);
  const logs = _db.habit_logs || [];
  const todayStr = _todayJalaliStr ? _todayJalaliStr() : '';
  const doneToday = logs.some(l => l.habit_id === id && l.date === todayStr && l.done);
  const streak = _habitStreak(id);
  const bestStreak = _habitBestStreak(id);
  const monthSuccess = _habitMonthSuccess(id);
  const lastDone = _habitLastDone(id);
  const totalDone = logs.filter(l => l.habit_id === id && l.done).length;
  const linkedGoal = h.goal_id ? (_db.goals||[]).find(x => x.id === h.goal_id) : null;
  const color = h.color || 'var(--amber)';

  const statBox = (icon, value, label, c) => `
    <div style="flex:1;background:var(--bg3);border-radius:10px;padding:10px;text-align:center">
      <div style="font-size:16px;font-weight:800;color:${c||'var(--text)'}">${icon} ${value}</div>
      <div style="font-size:9px;color:var(--text3);margin-top:2px">${label}</div>
    </div>`;

  openModal(`${escapeHtml(h.icon || '🔥')} ${escapeHtml(h.title)}`, `
    <div>
      ${h.desc ? `<div style="font-size:13px;color:var(--text2);line-height:1.8;margin-bottom:14px;background:var(--bg3);border-radius:10px;padding:10px 12px">📝 ${escapeHtml(h.desc)}</div>` : ''}

      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px">
        ${h.time ? `<span style="font-size:12px;background:var(--bg3);border-radius:20px;padding:5px 12px;color:var(--text2)">⏰ ${h.time}</span>` : ''}
        ${linkedGoal ? `<span onclick="closeModal();openGoalDetail(${linkedGoal.id})" style="cursor:pointer;font-size:12px;border-radius:20px;padding:5px 12px;background:rgba(124,106,247,.13);color:var(--accent2);font-weight:600">🎯 ${escapeHtml(linkedGoal.title)}</span>` : ''}
        ${h.pinned ? `<span style="font-size:12px;background:var(--bg3);border-radius:20px;padding:5px 12px;color:var(--text2)">📌 پین شده</span>` : ''}
        ${h.archived ? `<span style="font-size:12px;background:var(--bg3);border-radius:20px;padding:5px 12px;color:var(--text2)">🗃 آرشیو شده</span>` : ''}
      </div>

      <div style="display:flex;gap:8px;margin-bottom:10px">
        ${statBox(streak>0?'🔥':'', fa(streak), 'روز استمرار', color)}
        ${statBox('🏆', fa(bestStreak), 'رکورد', 'var(--amber)')}
        ${statBox('📈', fa(monthSuccess)+'٪', 'موفقیت ماه', 'var(--green)')}
      </div>
      <div style="display:flex;gap:8px;margin-bottom:16px">
        ${statBox('✅', fa(totalDone), 'کل دفعات انجام', '#60a5fa')}
        ${statBox('🕐', lastDone || '—', 'آخرین انجام', 'var(--text)')}
      </div>

      <button onclick="closeModal();toggleHabitToday(${id})" style="width:100%;padding:12px;border-radius:10px;border:none;cursor:pointer;
        font-family:var(--font);font-size:14px;font-weight:700;margin-bottom:16px;
        background:${doneToday ? 'var(--bg3)' : 'var(--green)'};color:${doneToday?'var(--text)':'white'}">
        ${doneToday ? '↩️ لغو ثبت امروز' : '✅ ثبت انجام امروز'}
      </button>

      <div style="display:flex;gap:8px">
        <button onclick="closeModal();openHabitHistory(${id})" style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border);background:var(--bg2);color:var(--text);font-family:var(--font);font-size:12px;font-weight:600;cursor:pointer">📊 تاریخچه</button>
        <button onclick="closeModal();openEditHabit(${id})" style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border);background:var(--bg2);color:var(--text);font-family:var(--font);font-size:12px;font-weight:600;cursor:pointer">✏️ ویرایش</button>
        <button onclick="closeModal();toggleArchiveHabit(${id})" style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border);background:var(--bg2);color:var(--text);font-family:var(--font);font-size:12px;font-weight:600;cursor:pointer">${h.archived?'↩️ بازگرداندن':'🗃 آرشیو'}</button>
      </div>
    </div>
  `, [
    { label: '🗑 حذف', cls: 'btn-danger', action: `closeModal();deleteHabit(${id})` },
    { label: 'بستن', cls: 'btn-ghost', action: 'closeModal()' },
  ]);
}

function openHabitMenu(id) {
  _habitsInit();
  const h = _db.habits.find(x => x.id === id);
  if (!h) return;
  const rowBtn = (icon, label, action, danger) => `
    <button onclick="${action}" style="width:100%;display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:10px;
      border:1px solid var(--border);background:var(--bg2);color:${danger ? 'var(--red)' : 'var(--text)'};
      font-size:13px;font-weight:600;cursor:pointer;margin-bottom:8px;font-family:var(--font);text-align:right">
      <span style="font-size:16px">${icon}</span><span>${label}</span>
    </button>`;
  openModal(`${escapeHtml(h.icon || '🔥')} ${escapeHtml(h.title)}`, `
    <div>
      ${rowBtn('✏️', 'ویرایش', `closeModal();openEditHabit(${id})`)}
      ${rowBtn('📊', 'آمار و تاریخچه', `closeModal();openHabitHistory(${id})`)}
      ${rowBtn(h.pinned ? '📌' : '📍', h.pinned ? 'حذف پین' : 'پین کردن بالای لیست', `closeModal();togglePinHabit(${id})`)}
      ${rowBtn('📋', 'کپی کردن این عادت', `closeModal();duplicateHabit(${id})`)}
      ${rowBtn(h.archived ? '↩️' : '🗃', h.archived ? 'بازگرداندن از آرشیو' : 'آرشیو کردن', `closeModal();toggleArchiveHabit(${id})`)}
      ${rowBtn('🗑', 'حذف', `closeModal();deleteHabit(${id})`, true)}
    </div>
  `, [{ label: 'بستن', cls: 'btn-ghost', action: 'closeModal()' }]);
}

function duplicateHabit(id) {
  _habitsInit();
  const h = _db.habits.find(x => x.id === id);
  if (!h) return;
  _db.habits.push({
    ...h,
    id: _db._nextId.habits++,
    title: h.title + ' (کپی)',
    pinned: false,
    archived: false,
    created_at: new Date().toISOString(),
  });
  _save(); showToast('عادت کپی شد ✓', 'success');
  if (currentPage === 'habits') renderHabits();
}

function togglePinHabit(id) {
  _habitsInit();
  const h = _db.habits.find(x => x.id === id);
  if (!h) return;
  h.pinned = !h.pinned;
  _save(); showToast(h.pinned ? 'به بالای لیست پین شد 📌' : 'پین برداشته شد', 'success');
  if (currentPage === 'habits') renderHabits();
}

function toggleArchiveHabit(id) {
  _habitsInit();
  const h = _db.habits.find(x => x.id === id);
  if (!h) return;
  h.archived = !h.archived;
  _save(); showToast(h.archived ? 'آرشیو شد 🗃' : 'از آرشیو خارج شد ↩️', 'success');
  if (currentPage === 'habits') renderHabits();
}

function openHabitHistory(id) {
  _habitsInit();
  const h = _db.habits.find(x => x.id === id);
  if (!h) return;
  const fa = n => String(n).replace(/[0-9]/g, d => '۰۱۲۳۴۵۶۷۸۹'[+d]);
  const doneDates = (_db.habit_logs||[]).filter(l => l.habit_id === id && l.done).map(l => l.date).sort().reverse();
  const rows = doneDates.slice(0, 60).map(d => `
    <div style="display:flex;justify-content:space-between;align-items:center;padding:9px 12px;border-bottom:1px solid var(--border);font-size:12px">
      <span style="color:var(--text)">${d}</span><span style="color:var(--green);font-weight:600">✓ انجام شد</span>
    </div>`).join('') || '<div style="text-align:center;color:var(--text3);font-size:12px;padding:24px">هنوز سابقه‌ای ثبت نشده</div>';
  openModal(`📊 تاریخچه: ${escapeHtml(h.title)}`, `
    <div style="margin-bottom:10px;font-size:12px;color:var(--text2)">مجموع ${fa(doneDates.length)} بار انجام شده</div>
    <div style="max-height:340px;overflow-y:auto;border:1px solid var(--border);border-radius:10px">${rows}</div>
  `, [{ label: 'بستن', cls: 'btn-ghost', action: 'closeModal()' }]);
}


// NOTE: goals/habits routing and titles are now handled natively inside
// renderPage() and updatePageTitle() above — no monkey-patching needed.


// ════════════════════════════════════════════════════════════════════════════
// VOICE TO TEXT — ورودی صوتی سراسری (useSpeechRecognition-style shared module)
// ────────────────────────────────────────────────────────────────────────────
// معماری: تمام منطق تبدیل گفتار پشت یک «موتور» (Engine) قرار دارد.
// موتور Web Speech برای مرورگرهای پشتیبان و موتور MediaRecorder + سرور Whisper
// برای iPhone/Safari و مرورگرهای بدون SpeechRecognition پیاده‌سازی شده است.
// هر موتور دیگری کافی است همین سه متد را پیاده‌سازی کند:
//   isSupported(), start({lang,onInterim,onFinal,onError,onEnd}), stop()
// و بدون هیچ تغییری در UI/دکمه‌ها، جایگزین می‌شود (Feature Flag: VOICE_CONFIG.engine)
// ════════════════════════════════════════════════════════════════════════════

const VOICE_VERSION = '2026-07-voice-debug-v4';
console.log('[voice-version]', VOICE_VERSION);

const VOICE_CONFIG = {
  engine: 'auto' // 'auto' | 'webspeech' | 'media'
};

function _voiceIsIOS() {
  return /iPad|iPhone|iPod/.test(navigator.userAgent) ||
    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
}
function _voiceIsMobile() {
  return _voiceIsIOS() || /Android|Mobile/i.test(navigator.userAgent);
}
function _voiceIsAndroid() {
  return /Android/i.test(navigator.userAgent);
}

let _iosVoiceStream = null;
let _iosVoiceStreamReleaseTimer = null;

function _voiceStopStream(stream) {
  try { stream?.getTracks?.().forEach(t => t.stop()); } catch(e) {}
}

function _voiceStreamIsLive(stream) {
  return !!(stream && stream.getAudioTracks && stream.getAudioTracks().some(t => t.readyState === 'live'));
}

async function _getReusableIOSVoiceStream() {
  if (!_voiceIsIOS()) return null;
  if (_iosVoiceStreamReleaseTimer) {
    clearTimeout(_iosVoiceStreamReleaseTimer);
    _iosVoiceStreamReleaseTimer = null;
  }
  if (_voiceStreamIsLive(_iosVoiceStream)) {
    _iosVoiceStream.getAudioTracks().forEach(t => { t.enabled = true; });
    return _iosVoiceStream;
  }
  _iosVoiceStream = await navigator.mediaDevices.getUserMedia({
    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
  });
  return _iosVoiceStream;
}

function _releaseReusableIOSVoiceStreamSoon() {
  if (!_voiceIsIOS() || !_iosVoiceStream) return;
  _iosVoiceStream.getAudioTracks().forEach(t => { t.enabled = false; });
  clearTimeout(_iosVoiceStreamReleaseTimer);
  _iosVoiceStreamReleaseTimer = setTimeout(() => {
    _voiceStopStream(_iosVoiceStream);
    _iosVoiceStream = null;
    _iosVoiceStreamReleaseTimer = null;
  }, 120000);
}

window.addEventListener('pagehide', () => {
  _voiceStopStream(_iosVoiceStream);
  _iosVoiceStream = null;
});

class WebSpeechVoiceEngine {
  constructor() {
    this.kind = 'webspeech';
    this._recognition = null;
    this._userListening = false;
    this._finalTranscript = '';
    this._interimTranscript = '';
    this._recognitionBaseTranscript = '';
    this._restartTimer = null;
  }
  isSupported() {
    return !!(window.SpeechRecognition || window.webkitSpeechRecognition);
  }
  start({ lang, onInterim, onFinal, onReplace, onError, onEnd, onStatus }) {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { onError && onError('unsupported'); return; }
    this._userListening = true;
    this._finalTranscript = '';
    this._interimTranscript = '';
    this._recognitionBaseTranscript = '';
    clearTimeout(this._restartTimer);
    this._restartTimer = null;

    const mergeSpeech = (base, addition) => {
      base = (base || '').trim();
      addition = (addition || '').trim();
      if (!base) return addition;
      if (!addition) return base;
      if (base === addition || base.endsWith(addition)) return base;
      if (addition.startsWith(base)) return addition;

      const baseWords = base.split(/\s+/).filter(Boolean);
      const addWords = addition.split(/\s+/).filter(Boolean);
      let overlap = 0;
      const max = Math.min(baseWords.length, addWords.length);
      for (let size = max; size > 0; size--) {
        const baseTail = baseWords.slice(baseWords.length - size).join(' ');
        const addHead = addWords.slice(0, size).join(' ');
        if (baseTail === addHead) {
          overlap = size;
          break;
        }
      }
      return [...baseWords, ...addWords.slice(overlap)].join(' ').trim();
    };
    const emitReplace = (commitFinalOnly = false) => {
      const text = commitFinalOnly
        ? this._finalTranscript
        : mergeSpeech(this._finalTranscript, this._interimTranscript);
      if (onReplace) onReplace(text, commitFinalOnly);
      else if (commitFinalOnly && text) onFinal && onFinal(text);
      else if (!commitFinalOnly && this._interimTranscript) onInterim && onInterim(this._interimTranscript);
    };

    const beginRecognition = () => {
      if (!this._userListening) return;
      this._recognitionBaseTranscript = this._finalTranscript;
      const rec = new SR();
      // مهم: rec.lang همیشه باید از تنظیمات برنامه (پارامتر lang) بیاید، نه از
      // navigator.language مرورگر — و باید پیش از rec.start() مقداردهی شده باشد.
      rec.lang = lang || 'fa-IR';
      // iOS با continuous ناپایدار است؛ Android/desktop تا جای ممکن یک جلسه‌ی
      // پیوسته می‌گیرند، و اگر مرورگر خودش onend داد با instance تازه ادامه می‌دهیم.
      rec.continuous = !_voiceIsIOS();
      rec.interimResults = true;
      rec.onstart = () => {
        onStatus && onStatus('در حال ضبط... صحبت کنید');
      };
      rec.onresult = (e) => {
        const finalParts = [];
        const interimParts = [];
        for (let i = 0; i < e.results.length; i++) {
          const result = e.results[i];
          const transcript = (result[0]?.transcript || '').trim();
          if (!transcript) continue;
          if (result.isFinal) {
            finalParts.push(transcript);
          } else {
            interimParts.push(transcript);
          }
        }

        const currentFinal = finalParts.reduce((acc, part) => mergeSpeech(acc, part), '');
        const currentInterim = interimParts.reduce((acc, part) => mergeSpeech(acc, part), '');
        this._finalTranscript = mergeSpeech(this._recognitionBaseTranscript, currentFinal);
        this._interimTranscript = currentInterim;
        emitReplace(false);
      };
      rec.onerror = (e) => {
        if (!this._userListening && e.error === 'aborted') return;
        if (this._userListening && _voiceIsAndroid() && (e.error === 'no-speech' || e.error === 'aborted')) {
          return;
        }
        this._userListening = false;
        onError && onError(e.error);
      };
      rec.onend = () => {
        if (this._recognition === rec) this._recognition = null;
        if (this._userListening) {
          emitReplace(true);
          clearTimeout(this._restartTimer);
          this._restartTimer = setTimeout(() => {
            if (this._userListening) beginRecognition();
          }, _voiceIsAndroid() ? 260 : 120);
          return;
        }
        emitReplace(true);
        onEnd && onEnd();
      };
      try {
        rec.start();
        this._recognition = rec;
      } catch (e) {
        onError && onError('start-failed');
      }
    };

    // نکته‌ی کلیدی رفع باگ موبایل: اگر مستقیم rec.start() صدا زده شود در حالی که
    // Permission هنوز «prompt» است، بعضی مرورگرهای موبایل (به‌خصوص Android/WebView)
    // به‌جای نمایش دیالوگ بومی درخواست دسترسی، بلافاصله خطای not-allowed برمی‌گردانند.
    // راه‌حل: با همان تپ اول کاربر، صریحاً getUserMedia صدا زده می‌شود تا دیالوگ بومی
    // مرورگر نمایش داده شود. اگر Allow شد، ضبط فوراً و بدون تپ دوم شروع می‌شود.
    // اگر Deny شد، همان‌جا پیام مناسب نشان داده می‌شود، نه بعد از یک تلاش ناموفق دیگر.
    const shouldPreflightMic = navigator.mediaDevices && navigator.mediaDevices.getUserMedia && !_voiceIsIOS();
    if (shouldPreflightMic) {
      navigator.mediaDevices.getUserMedia({ audio: true })
        .then((stream) => {
          // این استریم فقط برای گرفتن مجوز بود؛ خودِ SpeechRecognition میکروفون را
          // مستقل مدیریت می‌کند، پس بلافاصله آزادش می‌کنیم.
          stream.getTracks().forEach((t) => t.stop());
          beginRecognition();
        })
        .catch((err) => {
          const name = err && err.name;
          if (name === 'NotAllowedError' || name === 'PermissionDeniedError' || name === 'SecurityError') {
            // بعضی مرورگرهای اندروید/وب‌ویو getUserMedia را رد می‌کنند اما
            // Web Speech خودش می‌تواند prompt دسترسی را نشان دهد. در iPhone
            // این خطا معمولاً یعنی کاربر یا سایت واقعاً میکروفون را بسته است.
            if (_voiceIsAndroid()) beginRecognition();
            else onError && onError('not-allowed');
          } else if (name === 'NotFoundError' || name === 'DevicesNotFoundError') {
            onError && onError('no-mic');
          } else {
            // مرورگرهایی که getUserMedia صریح را درست پیاده‌سازی نکرده‌اند؛
            // بازگشت به رفتار قبلی و اجازه دادن به خودِ SpeechRecognition
            beginRecognition();
          }
        });
    } else {
      beginRecognition();
    }
  }
  stop() {
    this._userListening = false;
    clearTimeout(this._restartTimer);
    this._restartTimer = null;
    if (this._recognition) {
      try { this._recognition.stop(); } catch (e) {}
      this._recognition = null;
    }
  }
}

class MediaRecorderVoiceEngine {
  constructor() {
    this.kind = 'media';
    this._recorder = null;
    this._stream = null;
    this._chunks = [];
  }
  isSupported() {
    return !!(navigator.mediaDevices?.getUserMedia && window.MediaRecorder);
  }
  _mimeType() {
    const types = [
      'audio/mp4',
      'audio/webm;codecs=opus',
      'audio/webm',
      'audio/wav',
    ];
    return types.find(t => MediaRecorder.isTypeSupported?.(t)) || '';
  }
  _fileNameFor(type) {
    if ((type || '').includes('mp4')) return 'audio.m4a';
    if ((type || '').includes('webm')) return 'audio.webm';
    if ((type || '').includes('wav')) return 'audio.wav';
    return 'audio.webm';
  }
  _debugPayload({ blob, fileName, data, res }) {
    return {
      frontend: {
        audioBlobSize: blob?.size ?? null,
        audioBlobType: blob?.type || null,
        fileName: fileName || null,
      },
      authTokenPresent: !!data?._authTokenPresent,
      speechProvider: data?.debug?.speechProvider || null,
      voskModelLoaded: data?.debug?.voskModelLoaded ?? data?.debug?.vosk?.modelLoaded ?? null,
      transcriptionEngine: data?.debug?.transcriptionEngine || null,
      vosk: data?.debug?.vosk || null,
      voskVersion: data?.debug?.voskVersion || data?.debug?.vosk?.voskVersion || null,
      modelLoaded: data?.debug?.modelLoaded ?? data?.debug?.vosk?.modelLoaded ?? null,
      modelPath: data?.debug?.modelPath || data?.debug?.vosk?.modelPath || null,
      modelLoadTime: data?.debug?.modelLoadTime ?? data?.debug?.vosk?.modelLoadTime ?? null,
      openaiStatus: data?.debug?.openaiStatus ?? data?.debug?.openai?.status ?? null,
      backend: data?.debug?.backend || null,
      probe: data?.debug?.probe || null,
      converted: data?.debug?.converted || null,
      transcription: data?.debug?.transcription || null,
      openai: data?.debug?.openai || null,
      response: {
        ok: !!res?.ok,
        status: res?.status || null,
        url: res?.url || null,
        errorCode: data?.error || null,
        message: data?.message || null,
        responseText: data?._responseText || null,
        jsonParseError: data?._jsonParseError || null,
      },
    };
  }
  async start({ lang, onFinal, onError, onEnd, onStatus }) {
    if (!window.isSecureContext && location.hostname !== 'localhost') {
      onError && onError('insecure-context');
      return;
    }
    if (!this.isSupported()) {
      onError && onError('media-unsupported');
      return;
    }
    try {
      if (navigator.permissions?.query) {
        try {
          const p = await navigator.permissions.query({ name: 'microphone' });
          if (p.state === 'denied') {
            onError && onError('permission-denied');
            return;
          }
        } catch(e) {}
      }

      this._stream = _voiceIsIOS()
        ? await _getReusableIOSVoiceStream()
        : await navigator.mediaDevices.getUserMedia({
            audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
          });
      this._chunks = [];
      const mimeType = this._mimeType();
      this._recorder = new MediaRecorder(this._stream, mimeType ? { mimeType } : undefined);
      this._recorder.ondataavailable = (e) => {
        if (e.data && e.data.size > 0) this._chunks.push(e.data);
      };
      this._recorder.onerror = () => {
        if (_voiceIsIOS()) {
          _voiceStopStream(_iosVoiceStream);
          _iosVoiceStream = null;
        }
        onError && onError('recording-failed');
      };
      this._recorder.onstop = async () => {
        try {
          if (_voiceIsIOS()) _releaseReusableIOSVoiceStreamSoon();
          else _voiceStopStream(this._stream);
          this._stream = null;
          const blobType = mimeType || this._chunks[0]?.type || 'audio/webm';
          const blob = new Blob(this._chunks, { type: blobType });
          console.log('[voice] audioBlob.size:', blob.size, 'audioBlob.type:', blob.type, 'chunks:', this._chunks.length);
          if (!blob.size || blob.size < 5000) {
            onError && onError('audio-too-small');
            return;
          }
          onStatus && onStatus('در حال تبدیل صدا به متن...');
          const fd = new FormData();
          const fileName = this._fileNameFor(blobType);
          fd.append('audio', blob, fileName);
          fd.append('language', 'fa');
          const authToken = _getApiAuthToken();
          if (!authToken) {
            const debugPayload = this._debugPayload({
              blob,
              fileName,
              data: {
                error: 'auth_token_missing',
                message: 'برای استفاده از تبدیل صدا باید وارد حساب شوید.',
                _authTokenPresent: false,
              },
              res: { ok: false, status: 0, url: '/api/speech/transcribe' },
            });
            console.warn('[voice-debug] auth token missing', debugPayload);
            onError && onError({ code: 'auth-token-missing', debug: debugPayload });
            return;
          }
          console.log('[voice-upload]', {
            url: '/api/speech/transcribe',
            method: 'POST',
            formField: 'audio',
            fileName,
            blobSize: blob.size,
            blobType: blob.type,
            authTokenPresent: true,
            manualContentType: false,
          });
          let res;
          try {
            res = await _apiFetch('/api/speech/transcribe', {
              method: 'POST',
              body: fd,
              headers: { Authorization: `Bearer ${authToken}` },
            });
          } catch (fetchErr) {
            const debugPayload = this._debugPayload({
              blob,
              fileName,
              data: { error: 'fetch_failed', message: fetchErr?.message || String(fetchErr), _authTokenPresent: true },
              res: { ok: false, status: 0, url: '/api/speech/transcribe' },
            });
            console.error('[voice-debug] fetch failed', debugPayload);
            onError && onError({ code: 'fetch-failed', debug: debugPayload });
            return;
          }
          const responseText = await res.text().catch(e => {
            return `__READ_RESPONSE_TEXT_FAILED__: ${e?.message || e}`;
          });
          let data = {};
          try {
            data = responseText ? JSON.parse(responseText) : {};
          } catch (jsonErr) {
            const isHtmlResponse = /^\s*<!doctype html/i.test(responseText || '') || /^\s*<html[\s>]/i.test(responseText || '');
            data = {
              error: isHtmlResponse ? 'api_html_response' : 'non_json_response',
              message: isHtmlResponse
                ? 'API اشتباه پیکربندی شده و به جای پاسخ JSON، صفحه HTML برگردانده است.'
                : 'Server returned non-JSON response',
              _jsonParseError: jsonErr?.message || String(jsonErr),
            };
          }
          data._authTokenPresent = true;
          data._responseText = responseText;
          const debugPayload = this._debugPayload({ blob, fileName, data, res });
          console.log('[voice-debug]', debugPayload);
          if (!res.ok) {
            const code = data.error || '';
            if (code === 'speech_service_not_configured') onError && onError({ code: 'server-not-configured', debug: debugPayload });
            else if (code === 'unsupported_audio_format') onError && onError({ code: 'unsupported-audio-format', debug: debugPayload });
            else if (code === 'audio_unprocessable') onError && onError({ code: 'audio-unprocessable', debug: debugPayload });
            else if (code === 'audio_tool_missing') onError && onError({ code: 'audio-tool-missing', debug: debugPayload });
            else if (code === 'audio_too_large') onError && onError({ code: 'audio-too-large', debug: debugPayload });
            else if (code === 'audio_upload_failed') onError && onError({ code: 'audio-upload-failed', debug: debugPayload });
            else if (code === 'openai_rate_limit_or_quota') onError && onError({ code: 'openai-rate-limit-or-quota', debug: debugPayload });
            else if (code === 'openai_auth_failed') onError && onError({ code: 'openai-auth-failed', debug: debugPayload });
            else if (code === 'openai_permission_denied') onError && onError({ code: 'openai-permission-denied', debug: debugPayload });
            else if (code === 'openai_server_error') onError && onError({ code: 'openai-server-error', debug: debugPayload });
            else if (code === 'vosk_venv_missing') onError && onError({ code: 'vosk-venv-missing', debug: debugPayload });
            else if (code === 'vosk_model_missing') onError && onError({ code: 'vosk-model-missing', debug: debugPayload });
            else if (code === 'vosk_engine_missing') onError && onError({ code: 'vosk-engine-missing', debug: debugPayload });
            else if (code === 'empty_transcription') onError && onError({ code: 'empty-transcription', debug: debugPayload });
            else if (code === 'speech_provider_not_implemented') onError && onError({ code: 'speech-provider-not-implemented', debug: debugPayload });
            else if (code === 'speech_provider_invalid') onError && onError({ code: 'speech-provider-invalid', debug: debugPayload });
            else if (code === 'api_html_response') onError && onError({ code: 'api-html-response', debug: debugPayload });
            else if (code === 'non_json_response') onError && onError({ code: 'non-json-response', debug: debugPayload });
            else onError && onError({ code: data.message || 'transcription-failed', debug: debugPayload });
            return;
          }
          const text = (data.text || '').trim();
          if (text) onFinal && onFinal(text);
          else {
            console.warn('[voice-debug] debug report', debugPayload);
            onError && onError({ code: 'debug-report', debug: debugPayload });
          }
        } catch(e) {
          onError && onError(e.message || 'transcription-failed');
        } finally {
          onEnd && onEnd();
        }
      };
      this._recorder.start();
      onStatus && onStatus('در حال ضبط... صحبت کنید');
    } catch(e) {
      const name = e && e.name;
      if (_voiceIsIOS() && (name === 'NotAllowedError' || name === 'PermissionDeniedError' || name === 'SecurityError')) {
        _voiceStopStream(_iosVoiceStream);
        _iosVoiceStream = null;
      }
      if (name === 'NotAllowedError' || name === 'PermissionDeniedError' || name === 'SecurityError') onError && onError('permission-denied');
      else if (name === 'NotFoundError' || name === 'DevicesNotFoundError') onError && onError('no-mic');
      else onError && onError(e.message || 'recording-failed');
    }
  }
  stop() {
    if (this._recorder && this._recorder.state !== 'inactive') {
      try { this._recorder.stop(); } catch(e) {}
    } else {
      if (_voiceIsIOS()) _releaseReusableIOSVoiceStreamSoon();
      else _voiceStopStream(this._stream);
      this._stream = null;
    }
  }
}

// نقطه‌ی Feature Flag: هر موتور جدیدی اضافه شد، فقط همین‌جا سوییچ کن
function _createVoiceEngine() {
  if (VOICE_CONFIG.engine === 'media') return new MediaRecorderVoiceEngine();
  if (VOICE_CONFIG.engine === 'webspeech') return new WebSpeechVoiceEngine();
  if (!_voiceIsIOS()) {
    const web = new WebSpeechVoiceEngine();
    if (web.isSupported()) return web;
  }
  const media = new MediaRecorderVoiceEngine();
  if (media.isSupported()) return media;
  switch (VOICE_CONFIG.engine) {
    case 'webspeech':
    default:
      return new WebSpeechVoiceEngine();
  }
}

// ── Single Source of Truth برای «زبان برنامه» ───────────────────────────────
// این تابع تنها مرجع تشخیص زبان برنامه است. تنظیمات عمومی، ویژگی lang صفحه،
// فرمت‌های وابسته و موتور تشخیص گفتار همگی باید از همین‌جا زبان را بخوانند
// تا هیچ‌وقت با هم ناهماهنگ نشوند. هرگز نباید مستقیم
// از navigator.language (زبان مرورگر/سیستم‌عامل کاربر) به‌عنوان زبان برنامه
// استفاده شود، چون ممکن است با زبان واقعی برنامه یکی نباشد.
function _getAppLanguage() {
  if (typeof META !== 'undefined' && META && META.appLanguage) return META.appLanguage;
  if (typeof META !== 'undefined' && META && META.language) return String(META.language).startsWith('en') ? 'en' : 'fa';
  return 'fa';
}

function _getVoiceLangPref() {
  return localStorage.getItem('tp_voice_lang') || 'auto';
}
function saveVoiceLangSetting(val) {
  localStorage.setItem('tp_voice_lang', val);
  showToast('زبان تشخیص گفتار ذخیره شد', 'success');
}
function _voiceLangCode() {
  const pref = _getVoiceLangPref();
  const map = { fa: 'fa-IR', en: 'en-US', ar: 'ar-SA', tr: 'tr-TR' };
  if (pref === 'auto') {
    // «تشخیص خودکار» یعنی: از زبان برنامه (Single Source of Truth) پیروی کن،
    // نه از زبان مرورگر. این خط دقیقاً محل رفع باگ گزارش‌شده است.
    const appLang = _getAppLanguage();
    return map[appLang] || 'fa-IR';
  }
  return map[pref] || 'fa-IR';
}

// یک session فعال به‌ازای هر textarea (اجازه‌ی ضبط هم‌زمان چند فیلد را می‌دهد)
const _voiceSessions = new WeakMap();

const _VOICE_ICON_MIC = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><line x1="12" y1="19" x2="12" y2="23"/><line x1="8" y1="23" x2="16" y2="23"/></svg>';
const _VOICE_ICON_STOP = '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><rect x="5" y="5" width="14" height="14" rx="2"/></svg>';
const _VOICE_ICON_WARN = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>';

function _setVoiceBtnState(btn, statusEl, state, label) {
  btn.classList.remove('voice-recording', 'voice-error');
  if (state === 'recording') { btn.classList.add('voice-recording'); btn.innerHTML = _VOICE_ICON_STOP; btn.title = 'پایان ضبط'; }
  else if (state === 'error') { btn.classList.add('voice-error'); btn.innerHTML = _VOICE_ICON_WARN; btn.title = 'خطا در ورودی صوتی'; }
  else {
    btn.innerHTML = _VOICE_ICON_MIC;
    btn.title = 'ورودی صوتی (تبدیل گفتار به متن)';
  }
  if (statusEl) {
    if (label) {
      statusEl.textContent = label;
      statusEl.style.display = 'inline-block';
      statusEl.classList.toggle('is-error', state === 'error');
    } else {
      statusEl.style.display = 'none';
    }
  }
}

function _voiceDebugVal(v) {
  return (v === undefined || v === null || v === '') ? '—' : String(v);
}
function _voiceDebugRows(debug) {
  return [
    ['voice version', VOICE_VERSION],
    ['authTokenPresent', debug?.authTokenPresent],
    ['speechProvider', debug?.speechProvider],
    ['voskModelLoaded', debug?.voskModelLoaded],
    ['transcriptionEngine', debug?.transcriptionEngine],
    ['voskInstalled', debug?.health?.voskInstalled ?? debug?.vosk?.voskInstalled],
    ['voskVersion', debug?.voskVersion || debug?.health?.voskVersion],
    ['modelLoaded', debug?.modelLoaded ?? debug?.health?.modelLoaded],
    ['modelPath', debug?.modelPath || debug?.health?.modelPath],
    ['modelLoadTime', debug?.modelLoadTime ?? debug?.health?.modelLoadTime],
    ['health ready', debug?.health?.ready],
    ['venvExists', debug?.health?.venvExists],
    ['pythonPath', debug?.health?.pythonPath],
    ['health ffmpeg', debug?.health?.ffmpeg],
    ['health ffprobe', debug?.health?.ffprobe],
    ['frontend audioBlobSize', debug?.frontend?.audioBlobSize],
    ['frontend audioBlobType', debug?.frontend?.audioBlobType],
    ['backend file size', debug?.backend?.size],
    ['backend mimetype', debug?.backend?.mimetype],
    ['ffprobe duration', debug?.probe?.duration],
    ['ffprobe codec', debug?.probe?.codec],
    ['converted file size', debug?.converted?.size],
    ['OpenAI response textLength', debug?.transcription?.textLength],
    ['openaiStatus', debug?.openaiStatus],
    ['OpenAI status', debug?.openai?.status],
    ['OpenAI type', debug?.openai?.type],
    ['OpenAI code', debug?.openai?.code],
    ['OpenAI message', debug?.openai?.message],
    ['page protocol', debug?.ping?.pageProtocol],
    ['page origin', debug?.ping?.pageOrigin],
    ['api ping status', debug?.ping?.status],
    ['api ping responseText', debug?.ping?.responseText],
    ['response status', debug?.response?.status],
    ['errorCode', debug?.response?.errorCode],
    ['responseText', debug?.response?.responseText],
  ];
}
async function _voiceTestSpeechApi(debugEl) {
  const debug = {
    ping: { status: null, responseText: null, error: null, pageOrigin: location.origin, pageProtocol: location.protocol },
    response: { errorCode: null, status: null, responseText: null },
  };
  try {
    const res = await fetch('/api/speech/ping', { method: 'GET', cache: 'no-store' });
    const text = await res.text().catch(e => `__READ_RESPONSE_TEXT_FAILED__: ${e?.message || e}`);
    debug.ping.status = res.status;
    debug.ping.responseText = text;
    debug.response.status = res.status;
    debug.response.responseText = text;
    debug.response.errorCode = res.ok ? null : 'speech_ping_failed';
  } catch (e) {
    debug.ping.status = 0;
    debug.ping.error = e?.message || String(e);
    debug.ping.responseText = debug.ping.error;
    debug.response.status = 0;
    debug.response.errorCode = 'speech_ping_fetch_failed';
    debug.response.responseText = debug.ping.error;
  }
  console.log('[voice-api-ping]', debug);
  _voiceShowDebugPanel(debugEl, debug);
  return debug;
}
async function _voiceTestSpeechHealth(debugEl) {
  const debug = {
    health: null,
    response: { errorCode: null, status: null, responseText: null },
  };
  try {
    const res = await fetch('/api/speech/health', { method: 'GET', cache: 'no-store' });
    const text = await res.text().catch(e => `__READ_RESPONSE_TEXT_FAILED__: ${e?.message || e}`);
    debug.response.status = res.status;
    debug.response.responseText = text;
    debug.response.errorCode = res.ok ? null : 'speech_health_failed';
    try {
      debug.health = text ? JSON.parse(text) : null;
      debug.speechProvider = debug.health?.provider || null;
      debug.voskModelLoaded = debug.health?.modelLoaded ?? null;
      debug.voskVersion = debug.health?.voskVersion || null;
      debug.modelLoaded = debug.health?.modelLoaded ?? null;
      debug.modelPath = debug.health?.modelPath || null;
      debug.modelLoadTime = debug.health?.modelLoadTime ?? null;
      debug.transcriptionEngine = debug.health?.provider === 'vosk' ? 'python-vosk-worker' : debug.health?.provider || null;
    } catch (jsonErr) {
      debug.response.errorCode = 'speech_health_non_json';
    }
  } catch (e) {
    debug.response.status = 0;
    debug.response.errorCode = 'speech_health_fetch_failed';
    debug.response.responseText = e?.message || String(e);
  }
  console.log('[voice-health]', debug);
  _voiceShowDebugPanel(debugEl, debug);
  return debug;
}
function _voicePlayDebugAudio(type) {
  const url = type === 'converted'
    ? '/api/speech/debug-last-audio?type=converted'
    : '/api/speech/debug-last-audio';
  const audio = new Audio(url + (url.includes('?') ? '&' : '?') + '_=' + Date.now());
  audio.play().catch(err => {
    console.warn('[voice-debug] audio playback failed', { type, error: err?.message || err });
    showToast('پخش فایل Debug انجام نشد؛ Console را بررسی کن', 'warning');
  });
}
function _voiceShowDebugPanel(debugEl, debug) {
  if (!debugEl) return;
  const rows = _voiceDebugRows(debug);
  console.table(Object.fromEntries(rows));
  debugEl.innerHTML = `
    <strong>گزارش Debug تبدیل صدا — نسخه ${escapeHtml(VOICE_VERSION)}</strong>
    <div class="voice-debug-grid">
      ${rows.map(([k, v]) => `<div>${k}</div><div>${escapeHtml(_voiceDebugVal(v))}</div>`).join('')}
    </div>
    <div class="voice-debug-actions">
      <button type="button" class="voice-debug-btn" data-voice-debug-health="1">سلامت موتور صدا</button>
      <button type="button" class="voice-debug-btn" data-voice-debug-play="raw">پخش فایل ضبط‌شده</button>
      <button type="button" class="voice-debug-btn" data-voice-debug-play="converted">پخش فایل تبدیل‌شده</button>
    </div>
  `;
  debugEl.style.display = 'block';
}
function _voiceHideDebugPanel(debugEl) {
  if (!debugEl) return;
  debugEl.style.display = 'none';
  debugEl.innerHTML = '';
}

// نمایش زنده‌ی مدت‌زمان ضبط، مثل «۰۰:۱۸» — تجربه‌ای شبیه ChatGPT/Notion AI
function _startVoiceTimer(session, statusEl) {
  session.startedAt = Date.now();
  session.timerId = setInterval(() => {
    const sec = Math.floor((Date.now() - session.startedAt) / 1000);
    const mm = String(Math.floor(sec / 60)).padStart(2, '0');
    const ss = String(sec % 60).padStart(2, '0');
    if (statusEl) { statusEl.textContent = `🔴 ${mm}:${ss}`; statusEl.style.display = 'inline-block'; statusEl.classList.remove('is-error'); }
  }, 500);
}
function _stopVoiceTimer(session) {
  if (session && session.timerId) { clearInterval(session.timerId); session.timerId = null; }
}

// درج زنده‌ی متن دقیقاً در محل مکان‌نما، بدون پاک کردن متن قبلی
function _voiceLiveInsert(el, state, text, isFinal) {
  const before = state.committedValue.slice(0, state.cursor);
  const after = state.committedValue.slice(state.cursor);
  const needsSpace = before && text && !/[\s\n]$/.test(before) && !/^[\s\n.,!?؛،]/.test(text);
  const sep = needsSpace ? ' ' : '';
  el.value = before + sep + text + after;
  if (isFinal) {
    state.committedValue = el.value;
    state.cursor = (before + sep + text).length;
  }
  const caret = (before + sep + text).length;
  el.selectionStart = el.selectionEnd = caret;
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function _voiceReplaceFromRecognition(el, state, text, commitFinalOnly) {
  const before = state.committedValue.slice(0, state.cursor);
  const after = state.committedValue.slice(state.cursor);
  text = (text || '').trim();
  const needsSpace = before && text && !/[\s\n]$/.test(before) && !/^[\s\n.,!?؛،]/.test(text);
  const sep = needsSpace ? ' ' : '';
  el.value = before + sep + text + after;
  const caret = (before + sep + text).length;
  el.selectionStart = el.selectionEnd = caret;
  if (commitFinalOnly) {
    state.committedValue = el.value;
    state.cursor = caret;
  }
  el.dispatchEvent(new Event('input', { bubbles: true }));
}

function _startIOSKeyboardDictation(el, btn, statusEl) {
  try {
    el.focus({ preventScroll: true });
    const pos = typeof el.selectionStart === 'number' ? el.selectionStart : el.value.length;
    el.selectionStart = el.selectionEnd = pos;
  } catch(e) {
    try { el.focus(); } catch(e2) {}
  }
  _setVoiceBtnState(btn, statusEl, 'idle', 'از میکروفون کیبورد آیفون استفاده کن');
  setTimeout(() => _setVoiceBtnState(btn, statusEl, 'idle', null), 6500);
}

function _toggleVoiceInput(el, btn, statusEl, debugEl) {
  const existing = _voiceSessions.get(el);
  if (existing) {
    existing.engine.stop();
    if (existing.engine.kind === 'media') {
      _stopVoiceTimer(existing);
      _setVoiceBtnState(btn, statusEl, 'recording', 'در حال تبدیل صدا به متن...');
      return;
    }
    _stopVoiceTimer(existing);
    _voiceSessions.delete(el);
    _setVoiceBtnState(btn, statusEl, 'idle', null);
    return;
  }

  const engine = _createVoiceEngine();
  if (!engine.isSupported()) {
    const msg = _voiceIsIOS()
      ? 'این مرورگر ضبط داخلی را پشتیبانی نمی‌کند؛ از دیکته کیبورد آیفون استفاده کن'
      : 'مرورگر شما از ضبط یا تشخیص گفتار پشتیبانی نمی‌کند';
    if (_voiceIsIOS()) _startIOSKeyboardDictation(el, btn, statusEl);
    else _setVoiceBtnState(btn, statusEl, 'error', msg);
    setTimeout(() => _setVoiceBtnState(btn, statusEl, 'idle', null), 3500);
    return;
  }

  // متن فعلی و محل مکان‌نما حفظ می‌شود؛ متن جدید دقیقاً همان‌جا اضافه می‌شود
  if (_voiceIsAndroid() && document.activeElement && document.activeElement !== document.body) {
    try { document.activeElement.blur(); } catch(e) {}
  }
  const state = {
    committedValue: el.value,
    cursor: (typeof el.selectionStart === 'number') ? el.selectionStart : el.value.length
  };
  _voiceHideDebugPanel(debugEl);
  const session = { engine, state, timerId: null, debugEl };
  _voiceSessions.set(el, session);
  _setVoiceBtnState(btn, statusEl, 'recording', '🔴 00:00');
  _startVoiceTimer(session, statusEl);

  engine.start({
    lang: _voiceLangCode(),
    onInterim: (t) => _voiceLiveInsert(el, state, t, false),
    onFinal: (t) => _voiceLiveInsert(el, state, t, true),
    onReplace: (t, commitFinalOnly) => _voiceReplaceFromRecognition(el, state, t, commitFinalOnly),
    onStatus: (label) => _setVoiceBtnState(btn, statusEl, 'recording', label),
    onError: (err) => {
      const errCode = (err && typeof err === 'object') ? err.code : err;
      const errDebug = (err && typeof err === 'object') ? err.debug : null;
      const activeSession = _voiceSessions.get(el);
      if (activeSession) activeSession.hadError = true;
      _stopVoiceTimer(activeSession);
      let msg = 'خطا در تشخیص گفتار، دوباره تلاش کن';
      if (errDebug) _voiceShowDebugPanel(activeSession?.debugEl || debugEl, errDebug);
      if (errCode === 'not-allowed' || errCode === 'permission-denied' || errCode === 'service-not-allowed') {
        msg = 'دسترسی میکروفون رد شده است';
      } else if (errCode === 'no-mic') {
        msg = 'میکروفونی پیدا نشد';
      } else if (errCode === 'unsupported') {
        msg = 'تشخیص گفتار داخلی این مرورگر پشتیبانی نمی‌شود';
      } else if (errCode === 'media-unsupported') {
        msg = 'ضبط صدا در این مرورگر پشتیبانی نمی‌شود';
      } else if (errCode === 'insecure-context') {
        msg = 'برای ضبط صدا باید سایت با HTTPS باز شود';
      } else if (errCode === 'server-not-configured') {
        msg = 'سرویس تبدیل صدا روی سرور هنوز تنظیم نشده است';
      } else if (errCode === 'audio-too-small') {
        msg = 'صدای کافی ضبط نشد. دوباره نزدیک‌تر به میکروفون صحبت کنید.';
      } else if (errCode === 'unsupported-audio-format') {
        msg = 'فرمت صدای ضبط‌شده پشتیبانی نشد';
      } else if (errCode === 'audio-unprocessable') {
        msg = 'فایل صوتی قابل پردازش نیست.';
      } else if (errCode === 'audio-tool-missing') {
        msg = 'ابزار پردازش صدا روی سرور نصب نیست';
      } else if (errCode === 'fetch-failed') {
        msg = 'ارسال صدا به سرور انجام نشد؛ اتصال، HTTPS یا CORS را بررسی کن';
      } else if (errCode === 'auth-token-missing') {
        msg = 'برای استفاده از تبدیل صدا باید وارد حساب شوید.';
      } else if (errCode === 'audio-too-large') {
        msg = 'حجم فایل صوتی بیشتر از حد مجاز سرور است';
      } else if (errCode === 'audio-upload-failed') {
        msg = 'آپلود فایل صوتی در سرور ناموفق بود';
      } else if (errCode === 'openai-rate-limit-or-quota') {
        msg = 'محدودیت مصرف یا اعتبار OpenAI API فعال شده است.';
      } else if (errCode === 'openai-auth-failed') {
        msg = 'کلید OpenAI API نامعتبر است یا احراز هویت انجام نشد';
      } else if (errCode === 'openai-permission-denied') {
        msg = 'دسترسی OpenAI API برای این عملیات مجاز نیست';
      } else if (errCode === 'openai-server-error') {
        msg = 'سرویس OpenAI موقتاً خطا داده است';
      } else if (errCode === 'vosk-venv-missing') {
        msg = 'محیط مجازی Python برای تبدیل صدا روی سرور ساخته نشده است';
      } else if (errCode === 'vosk-model-missing') {
        msg = 'مدل تبدیل صدای فارسی روی سرور نصب نشده';
      } else if (errCode === 'vosk-engine-missing') {
        msg = 'موتور Vosk روی سرور نصب نشده است';
      } else if (errCode === 'empty-transcription') {
        msg = 'صدای کافی تشخیص داده نشد';
      } else if (errCode === 'speech-provider-not-implemented') {
        msg = 'موتور انتخاب‌شده برای تبدیل صدا هنوز فعال نشده است';
      } else if (errCode === 'speech-provider-invalid') {
        msg = 'تنظیمات موتور تبدیل صدا معتبر نیست';
      } else if (errCode === 'api-html-response') {
        msg = 'API اشتباه پیکربندی شده و به جای پاسخ JSON، صفحه HTML برگردانده است.';
      } else if (errCode === 'non-json-response') {
        msg = 'پاسخ سرور قابل خواندن نبود؛ status و responseText را در Debug ببین';
      } else if (errCode === 'debug-report') {
        msg = 'گزارش Debug آماده شد؛ فایل‌های صدا را پخش کن';
      }
      _setVoiceBtnState(btn, statusEl, 'error', msg);
      setTimeout(() => { _voiceSessions.delete(el); _setVoiceBtnState(btn, statusEl, 'idle', null); }, errDebug ? 8000 : 3500);
    },
    onEnd: () => {
      const activeSession = _voiceSessions.get(el);
      _stopVoiceTimer(activeSession);
      _voiceSessions.delete(el);
      if (activeSession?.hadError) return;
      _setVoiceBtnState(btn, statusEl, 'idle', null);
    }
  });
}

// ── اتصال خودکار دکمه‌ی میکروفون به هر TextArea موجود در برنامه ──────────────
function _attachVoiceButton(el) {
  if (!el || el.dataset.voiceReady || el.hasAttribute('data-no-voice')) return;
  el.dataset.voiceReady = '1';

  const parent = el.parentElement;
  if (!parent) return;
  if (getComputedStyle(parent).position === 'static') {
    parent.style.position = 'relative';
  }

  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'voice-mic-btn';
  btn.title = 'ورودی صوتی (تبدیل گفتار به متن)';
  btn.innerHTML = _VOICE_ICON_MIC;

  const statusEl = document.createElement('span');
  statusEl.className = 'voice-status-label';
  statusEl.style.display = 'none';

  const debugEl = document.createElement('div');
  debugEl.className = 'voice-debug-panel';
  debugEl.style.display = 'none';
  debugEl.addEventListener('click', (e) => {
    if (e.target?.dataset?.voiceDebugPing) {
      e.preventDefault();
      e.stopPropagation();
      _voiceTestSpeechApi(debugEl);
      return;
    }
    if (e.target?.dataset?.voiceDebugHealth) {
      e.preventDefault();
      e.stopPropagation();
      _voiceTestSpeechHealth(debugEl);
      return;
    }
    const playType = e.target?.dataset?.voiceDebugPlay;
    if (!playType) return;
    e.preventDefault();
    e.stopPropagation();
    _voicePlayDebugAudio(playType);
  });

  btn.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    _toggleVoiceInput(el, btn, statusEl, debugEl);
  });

  parent.appendChild(btn);
  parent.appendChild(statusEl);
  parent.appendChild(debugEl);

  // اگر فیلد از صفحه حذف شد، ضبط در حال اجرا متوقف شود
  el.addEventListener('DOMNodeRemovedFromDocument', () => {
    const s = _voiceSessions.get(el);
    if (s) { s.engine.stop(); _voiceSessions.delete(el); }
  });
}

function _voiceScanAndAttach(root) {
  const scope = root || document;
  const nodes = scope.querySelectorAll ? scope.querySelectorAll('textarea.form-textarea:not([data-voice-ready]):not([data-no-voice])') : [];
  nodes.forEach(_attachVoiceButton);
  // اگر خودِ ریشه یک کادر متن باشد (مثلاً در حالت تمرکز)
  if (scope.matches && scope.matches('textarea.form-textarea:not([data-voice-ready]):not([data-no-voice])')) {
    _attachVoiceButton(scope);
  }
}

// ── Auto-Grow Textarea ──────────────────────────────────────────────────────
// رفع «اسکرول تو در تو»: به‌جای اینکه خودِ Textarea اسکرول داخلی داشته باشد و
// Modal هم دور آن اسکرول کند، ارتفاع Textarea با محتوا رشد می‌کند و فقط یک
// اسکرول (همان محفظهٔ بیرونی) باقی می‌ماند.
function _autoGrowTextarea(el) {
  el.style.overflowY = 'hidden';
  el.style.resize = 'none';
  const resize = () => {
    el.style.height = 'auto';
    el.style.height = (el.scrollHeight + 2) + 'px';
  };
  el.addEventListener('input', resize);
  // اگر Textarea داخل بخشی است که ابتدا بسته/مخفی است (مثل «یادداشت خصوصی» یا Accordionها)،
  // scrollHeight هنگام ساخت صفر است؛ با focus دوباره محاسبه می‌شود.
  el.addEventListener('focus', resize);
  resize();
}
function _autoGrowScanAndAttach(root) {
  const scope = root || document;
  // توجه: textarea.note-content-textarea در موبایل از Auto-Grow کنار گذاشته شده
  // (باعث jump کیبورد iOS می‌شد). در دسکتاپ (min-width:769px) auto-grow فعال است.
  const isDesktop = window.matchMedia && window.matchMedia('(min-width:769px)').matches;
  const noteContentSel = isDesktop ? '' : ':not(.note-content-textarea)';
  const sel = `textarea:not([data-autogrow-ready]):not(#fm-textarea):not(#share-msg-preview)${noteContentSel}`;
  const nodes = scope.querySelectorAll ? scope.querySelectorAll(sel) : [];
  nodes.forEach((el) => { el.dataset.autogrowReady = '1'; _autoGrowTextarea(el); });
  if (scope.matches && scope.matches(sel)) {
    scope.dataset.autogrowReady = '1'; _autoGrowTextarea(scope);
  }
  // در دسکتاپ: auto-grow را مستقیماً به note-content-textarea متصل می‌کنیم اگر هنوز نشده
  if (isDesktop && scope.querySelectorAll) {
    scope.querySelectorAll('textarea.note-content-textarea:not([data-autogrow-ready])').forEach((el) => {
      el.dataset.autogrowReady = '1'; _autoGrowTextarea(el);
    });
  }
}

// ── هوک سراسری مدیریت کیبورد iOS برای تمام مودال‌های برنامه ─────────────────
// این کد یک‌بار اجرا می‌شود و روی همه‌ی فیلدهای متنی داخل مودال‌ها اثر می‌گذارد.
// هدف: جلوگیری از پرش صفحه هنگام فوکوس روی textarea یا input داخل modal در iOS Safari.
(function _initIOSModalKeyboardHook() {
  if (typeof window === 'undefined') return;

  // هنگام focus روی هر input/textarea داخل modal:
  // - از scroll خودکار Safari جلوگیری می‌کنیم
  // - scrollTop modal-body را حفظ می‌کنیم
  document.addEventListener('focus', function(e) {
    const target = e.target;
    if (!target || (target.tagName !== 'INPUT' && target.tagName !== 'TEXTAREA')) return;
    const modalBody = target.closest('.modal-body');
    if (!modalBody) return;

    // scrollTop فعلی را ذخیره کن تا بعد از focus بازگردانیم
    const savedTop = modalBody.scrollTop;

    // در iOS Safari، focus روی input باعث می‌شود مرورگر صفحه را اسکرول کند.
    // با یک rAF کوچک این scroll را خنثی می‌کنیم.
    // نکته مهم: اینجا دیگر window.scrollTo(0,0) صدا زده نمی‌شود — آن خط خودش
    // در iPhone Safari باعث jump می‌شد. فقط scrollTop خودِ modal-body حفظ می‌شود،
    // نه اسکرول کل window/body.
    requestAnimationFrame(() => {
      // اگر modal-body بیشتر از ۵px جابه‌جا شده، برگردانش
      if (Math.abs(modalBody.scrollTop - savedTop) > 5) {
        modalBody.scrollTop = savedTop;
      }
    });
  }, true); // capture phase

  // وقتی کاربر blur می‌کند (کیبورد بسته می‌شود)، scrollTop را بازمی‌گردانیم
  document.addEventListener('blur', function(e) {
    const target = e.target;
    if (!target || (target.tagName !== 'INPUT' && target.tagName !== 'TEXTAREA')) return;
    const modalBody = target.closest('.modal-body');
    if (!modalBody) return;

    // کمی صبر می‌کنیم تا کیبورد واقعاً بسته شود و --modal-vh آپدیت شود
    setTimeout(() => {
      if (modalBody._savedScrollTop != null) {
        modalBody.scrollTop = modalBody._savedScrollTop;
      }
    }, 100);
  }, true);
})();

(function _initVoiceInput() {
  const start = () => {
    _voiceScanAndAttach(document);
    _autoGrowScanAndAttach(document);
    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        m.addedNodes && m.addedNodes.forEach((node) => {
          if (node.nodeType !== 1) return;
          _voiceScanAndAttach(node);
          _autoGrowScanAndAttach(node);
        });
      }
    });
    observer.observe(document.body, { childList: true, subtree: true });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _startApp, { once: true });
} else {
  _startApp();
}
